#!/usr/bin/env python3
"""Read-only evidence reconciliation for multi-site web-hosting handovers.

Requires exported observations from the real incumbent and candidate platforms.
Does not crawl, change infrastructure, or assert regulatory compliance.
"""
import argparse
import csv
import hashlib
import html
import json
import os
import re
import sys
import tempfile
from datetime import datetime, timezone
from pathlib import Path
from urllib.parse import urlsplit

FIELDS = ('agency_id', 'canonical_url', 'export_sha256', 'backup_sha256', 'route_count', 'observed_http_status')
COMPARE = ('canonical_url', 'export_sha256', 'backup_sha256', 'route_count')
SHA256 = re.compile(r'^[0-9a-fA-F]{64}$')


def sha_file(path):
    digest = hashlib.sha256()
    with Path(path).open('rb') as fd:
        for block in iter(lambda: fd.read(1024 * 1024), b''):
            digest.update(block)
    return digest.hexdigest()


def read_manifest(path):
    seen = {}
    with Path(path).open('r', encoding='utf-8-sig', newline='') as fd:
        reader = csv.DictReader(fd)
        if not reader.fieldnames or any(f not in reader.fieldnames for f in FIELDS):
            raise ValueError(f'{path}: CSV must contain {", ".join(FIELDS)}')
        for row_num, row in enumerate(reader, start=2):
            if any(row.get(f) is None for f in FIELDS):
                raise ValueError(f'{path}:{row_num}: incomplete row')
            row = {f: row[f].strip() for f in FIELDS}
            key = row['agency_id']
            if not key or key in seen or any(ch in key for ch in '\r\n\x00'):
                raise ValueError(f'{path}:{row_num}: blank, duplicate or invalid agency_id {key!r}')
            parsed = urlsplit(row['canonical_url'])
            if parsed.scheme != 'https' or not parsed.hostname or parsed.username or parsed.password:
                raise ValueError(f'{path}:{row_num}: canonical_url requires public https host')
            for digest_field in ('export_sha256', 'backup_sha256'):
                if not SHA256.fullmatch(row[digest_field]):
                    raise ValueError(f'{path}:{row_num}: invalid {digest_field}')
                row[digest_field] = row[digest_field].lower()
            try:
                routes = int(row['route_count'])
                status = int(row['observed_http_status'])
            except ValueError as e:
                raise ValueError(f'{path}:{row_num}: route_count and observed_http_status must be integers') from e
            if routes < 0 or not 100 <= status <= 599:
                raise ValueError(f'{path}:{row_num}: invalid route count or HTTP status')
            row['route_count'] = routes
            row['observed_http_status'] = status
            seen[key] = row
    if not seen:
        raise ValueError(f'{path}: no observation rows')
    return seen


def read_approvals(path):
    if not path:
        return {}
    items = {}
    columns = ('agency_id', 'field', 'before', 'after', 'reason', 'approved_by')
    with Path(path).open('r', encoding='utf-8-sig', newline='') as fd:
        reader = csv.DictReader(fd)
        if not reader.fieldnames or any(f not in reader.fieldnames for f in columns):
            raise ValueError(f'{path}: approvals require {", ".join(columns)}')
        for row_num, row in enumerate(reader, start=2):
            row = {key: (row.get(key) or '').strip() for key in columns}
            ident = (row['agency_id'], row['field'])
            if row['field'] not in COMPARE or not row['reason'] or not row['approved_by'] or not row['agency_id'] or ident in items:
                raise ValueError(f'{path}:{row_num}: invalid or duplicate signed approval')
            items[ident] = row
    return items


def audit(before, after, approvals, min_agencies):
    checks = []
    used = set()
    for agency_id in sorted(set(before) | set(after)):
        old = before.get(agency_id)
        new = after.get(agency_id)
        if old is None or new is None:
            checks.append({'agency_id': agency_id, 'field': 'agency_presence', 'before': 'present' if old else 'missing', 'after': 'present' if new else 'missing', 'result': 'FAIL', 'reason': 'Unpaired site; do not silently add/drop an agency'})
            continue
        for field in COMPARE:
            a, b = str(old[field]), str(new[field])
            if a == b:
                continue
            key = (agency_id, field)
            approval = approvals.get(key)
            if approval and approval['before'] == a and approval['after'] == b:
                checks.append({'agency_id': agency_id, 'field': field, 'before': a, 'after': b, 'result': 'APPROVED_CHANGE', 'reason': approval['reason'], 'approved_by': approval['approved_by']})
                used.add(key)
            else:
                checks.append({'agency_id': agency_id, 'field': field, 'before': a, 'after': b, 'result': 'FAIL', 'reason': 'Unapproved change from baseline'})
        if not 200 <= new['observed_http_status'] <= 299:
            checks.append({'agency_id': agency_id, 'field': 'observed_http_status', 'before': str(old['observed_http_status']), 'after': str(new['observed_http_status']), 'result': 'FAIL', 'reason': 'Candidate observation is not HTTP 2xx'})
    if len(before) < min_agencies:
        checks.append({'agency_id': '*', 'field': 'baseline_coverage', 'before': str(len(before)), 'after': str(min_agencies), 'result': 'FAIL', 'reason': 'Baseline covers fewer sites than required'})
    unused = sorted(set(approvals) - used)
    for agency_id, field in unused:
        checks.append({'agency_id': agency_id, 'field': field, 'before': approvals[(agency_id, field)]['before'], 'after': approvals[(agency_id, field)]['after'], 'result': 'INVALID_APPROVAL', 'reason': 'Approval is stale or does not match an observed change'})
    failed = sum(x['result'] in ('FAIL', 'INVALID_APPROVAL') for x in checks)
    return {'status': 'PASS' if failed == 0 else 'FAIL', 'baseline_sites': len(before), 'candidate_sites': len(after), 'matched_sites': len(set(before) & set(after)), 'approved_changes': sum(x['result'] == 'APPROVED_CHANGE' for x in checks), 'blocking_issues': failed, 'checks': checks}


def atomic_write(path, content):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    with tempfile.NamedTemporaryFile('w', encoding='utf-8', dir=path.parent, prefix='.cutover-', delete=False) as fd:
        temp = fd.name
        fd.write(content)
        fd.flush()
        os.fsync(fd.fileno())
    os.replace(temp, path)


def render_html(report):
    def esc(x):
        return html.escape(str(x), quote=True)
    rows = ''.join('<tr><td>' + esc(x['agency_id']) + '</td><td>' + esc(x['field']) + '</td><td class="wrap">' + esc(x['before']) + '</td><td class="wrap">' + esc(x['after']) + '</td><td><strong>' + esc(x['result']) + '</strong></td><td>' + esc(x.get('reason', '')) + '</td></tr>' for x in report['summary']['checks'])
    if not rows:
        rows = '<tr><td colspan="6">No differences or failures in supplied manifests.</td></tr>'
    summary = report['summary']
    return '''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>GovHub Multi-site Cutover Evidence</title><style>:root{font-family:system-ui, sans-serif;color-scheme:light}body{max-width:1180px;margin:36px auto;padding:0 22px;color:#172230;background:#fafbfc}h1{letter-spacing:-.03em}.lede{max-width:770px;color:#485768}.metrics{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:12px;margin:28px 0}.metric{background:white;border:1px solid #dfe5ea;padding:17px;border-radius:12px}.metric b{display:block;font-size:26px;margin-top:6px}.muted{color:#64748b}table{border-collapse:collapse;width:100%;background:white}th,td{border-bottom:1px solid #e5e9ef;padding:11px;text-align:left;vertical-align:top;font-size:13px}th{background:#eaf0f4}td.wrap{overflow-wrap:anywhere;max-width:260px}.foot{font-size:13px;color:#64748b;margin-top:22px}</style></head><body><p class="muted">READ-ONLY ACCEPTANCE EVIDENCE · ORIGINAL OPERATOR EXPORTS</p><h1>Multi-site cutover reconciliation</h1><p class="lede">Strict comparisons of separately supplied baseline and candidate agency manifests. No live endpoint is contacted; no hosting, uptime, accessibility, or regulatory certification is implied.</p><div class="metrics"><div class="metric">Decision<b>''' + esc(summary['status']) + '''</b></div><div class="metric">Baseline sites<b>''' + esc(summary['baseline_sites']) + '''</b></div><div class="metric">Matched sites<b>''' + esc(summary['matched_sites']) + '''</b></div><div class="metric">Blocking issues<b>''' + esc(summary['blocking_issues']) + '''</b></div><div class="metric">Approved changes<b>''' + esc(summary['approved_changes']) + '''</b></div></div><h2>Difference ledger</h2><table><thead><tr><th>Agency</th><th>Field</th><th>Baseline</th><th>Candidate</th><th>Disposition</th><th>Reason</th></tr></thead><tbody>''' + rows + '''</tbody></table><p class="foot">Manifest SHA-256: baseline ''' + esc(report['inputs']['baseline_sha256']) + ''', candidate ''' + esc(report['inputs']['candidate_sha256']) + '''. Generated ''' + esc(report['generated_at']) + '''. Full structured ledger: report.json.</p></body></html>'''


def main():
    p = argparse.ArgumentParser(description='Source-exported multi-site cutover acceptance, offline only')
    p.add_argument('--before', required=True, help='Baseline export CSV')
    p.add_argument('--after', required=True, help='Candidate export CSV')
    p.add_argument('--approvals', help='Optional exact field change approvals CSV')
    p.add_argument('--out', required=True, help='Output directory for report.json/report.html')
    p.add_argument('--min-agencies', type=int, default=1, help='Minimum number of baseline agencies, default 1')
    args = p.parse_args()
    if args.min_agencies < 1:
        p.error('--min-agencies must be >= 1')
    try:
        old, new = read_manifest(args.before), read_manifest(args.after)
        approvals = read_approvals(args.approvals)
        summary = audit(old, new, approvals, args.min_agencies)
        report = {'tool': 'multi-site-cutover-evidence/1.0', 'generated_at': datetime.now(timezone.utc).isoformat(), 'inputs': {'baseline_sha256': sha_file(args.before), 'candidate_sha256': sha_file(args.after), 'approvals_sha256': sha_file(args.approvals) if args.approvals else None}, 'summary': summary, 'limits': ['Operator-supplied exported evidence only', 'No network probes or customer access', 'Not a security, hosting, or regulatory compliance certification']}
        atomic_write(Path(args.out) / 'report.json', json.dumps(report, indent=2, ensure_ascii=False) + '\n')
        atomic_write(Path(args.out) / 'report.html', render_html(report))
        print(json.dumps({k: summary[k] for k in ('status', 'baseline_sites', 'matched_sites', 'blocking_issues', 'approved_changes')}))
        return 2 if summary['blocking_issues'] else 0
    except (OSError, ValueError, UnicodeError) as exc:
        print(f'INPUT_ERROR: {exc}', file=sys.stderr)
        return 3


if __name__ == '__main__':
    sys.exit(main())

"""Selected native Castor tasks in the existing GovHub operation.
Apache-2.0. Castor remains the task engine; all source and native outputs stay
in the original private Session. See CASTOR_NATIVE.md for the exact contract.
"""
from __future__ import annotations

import hashlib
import json
import os
from pathlib import Path
import re
import shutil
import tempfile
import time

VERSION = "govhub-castor/v1"
CASTOR_COMMIT = "058feddafd0b977eebf33364d02cd553ae26854a"
RUNTIME_FIELDS = {"site_root", "castor_path", "php_path", "git_path", "docker_path"}
KINDS = {"CAPTURE": "capture", "BACKUP_CREATE": "backup", "PREVIEW": "preview",
         "REHEARSAL": "restore", "CUTOVER": "release", "ROLLBACK": "rollback"}
LABELS = {"capture": "Capture complete selected Castor project",
          "backup": "Run the selected native backup task",
          "preview": "Run the selected nonproduction task",
          "restore": "Rehearse the selected native restore",
          "release": "Apply the selected reviewed release task",
          "rollback": "Run the selected reviewed recovery task"}


def _api():
    import native_adapter
    return native_adapter


def _json(value):
    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"))


def _digest(value):
    return hashlib.sha256(_json(value).encode()).hexdigest()


def _name(value, label):
    if not isinstance(value, str) or not value or len(value) > 512 or any(
            c in value for c in ("\x00", "\r", "\n")):
        raise ValueError("Select the actual " + label + ".")
    return value


def _relative(value):
    value = _name(value, "project-relative path")
    if "\\" in value or Path(value).is_absolute() or any(p in {"", ".", ".."} for p in value.split("/")):
        raise ValueError("Use an ordinary project-relative path.")
    return value


def _under(root, relative, *, exists=True):
    relative = _relative(relative)
    root = Path(root).resolve()
    path = root.joinpath(*relative.split("/"))
    current = root
    for part in relative.split("/"):
        current /= part
        if current.is_symlink():
            raise ValueError("An explicitly selected project path is a symlink: " + relative)
    if exists and not path.exists():
        raise ValueError("The selected native project member is absent: " + relative)
    if not path.resolve().is_relative_to(root):
        raise ValueError("A selected project member escaped its original root.")
    return path


def _array(p, key):
    value = p.get(key, "[]")
    if not isinstance(value, str):
        raise ValueError(key + " must retain its explicit JSON text.")
    result = json.loads(value)
    if not isinstance(result, list) or len(result) > 10000:
        raise ValueError(key + " must be a bounded JSON array.")
    return result


def provider_schema():
    def f(name, label, required=False, **extra):
        return {"name": name, "label": label, "type": "text", "required": required, **extra}
    return {"value": "castor", "label": "Castor on-premise application",
            "runtime_fields": sorted(RUNTIME_FIELDS), "fields": [
        f("environment_id", "Existing deployment identity", True),
        f("site_root", "Existing native project directory", True),
        f("castor_path", "Existing Castor or repacked executable", True),
        f("php_path", "Existing PHP launcher for a PHAR",
          help="Optional. The installed Castor release determines its PHP requirement."),
        f("git_path", "Existing Git executable"),
        f("docker_path", "Existing Docker executable"),
        f("docker_context", "Selected native Docker context", True),
        f("castor_file", "Project-relative Castor entrypoint",
          help="Empty for a repacked executable; otherwise the actual root PHP file."),
        f("castor_context", "Selected native Castor context",
          help="Leave empty only when the original application defines no named contexts."),
        f("compose_project", "Existing Compose project name", True),
        f("compose_files_json", "Complete ordered Compose files", True, type="textarea",
          help="JSON array of original project-relative file names."),
        f("source_revision", "Reviewed full Git commit",
          help="Capture first to receive the actual full commit; mutations require it."),
        f("task_name", "Selected existing native task"),
        f("task_args_json", "Exact task argument tokens", type="textarea", default="[]"),
        f("verify_task_name", "Existing native verification task"),
        f("verify_args_json", "Exact verification argument tokens", type="textarea", default="[]"),
        f("verify_source", "Verification JSON source", default="stdout",
          help="stdout or file. The original task must actually provide this JSON."),
        f("verify_output_path", "Project-relative verification JSON file"),
        f("verification_checks_json", "Native verification comparisons", type="textarea", default="[]",
          help='JSON array of {"pointer":"/actual/path","equals":<actual expected value>} objects.'),
        f("task_outputs_json", "Complete task output selection", type="textarea", default="[]",
          help='JSON array of {"path":"relative","role":"database|files|...","kind":"file|directory"}.'),
        f("backup_inputs_json", "Reviewed original recovery input files", type="textarea", default="[]",
          help='JSON array of {"path":"relative","role":"...","kind":"file|directory","sha256":"original file or directory-manifest SHA256"}.'),
        f("release_files_json", "Complete release executables and configuration", type="textarea", default="[]"),
        f("source_images_json", "Selected immutable image IDs or digests", type="textarea", default="[]",
          help="Empty selects the complete current native Compose image cohort."),
        f("timeout_seconds", "Native command timeout, seconds", type="integer", default=900,
          minimum=10, maximum=86400),
        f("max_artifact_bytes", "Maximum retained individual file bytes", type="integer",
          default=2147483648, minimum=1048576),
    ]}


def profile(config, runtime_bindings=None):
    if not isinstance(config, dict) or config.get("source_kind") != "castor":
        raise ValueError("Select the original Castor application profile.")
    allowed = {"source_kind", "target_fingerprint"} | {v["name"] for v in provider_schema()["fields"]}
    if set(config) - allowed:
        raise ValueError("Unsupported Castor profile fields: " + ", ".join(sorted(set(config) - allowed)))
    p = dict(config)
    if runtime_bindings:
        if not isinstance(runtime_bindings, dict) or set(runtime_bindings) - RUNTIME_FIELDS:
            raise ValueError("Only the original native host paths can be rebound.")
        p.update(runtime_bindings)
    _name(p.get("environment_id"), "deployment identity")
    root = Path(p.get("site_root", "")).expanduser()
    if not root.is_absolute() or root.is_symlink() or not root.is_dir():
        raise ValueError("Select the original absolute native project directory.")
    p["site_root"] = str(root.resolve())
    for key, default in (("castor_path", None), ("git_path", "git"), ("docker_path", "docker")):
        selected = p.get(key) or default
        p[key] = _api()._binary(selected, executable=not (key == "castor_path" and p.get("php_path")))
    if p.get("php_path"):
        p["php_path"] = _api()._binary(p["php_path"])
    if p.get("castor_file"):
        _under(root, p["castor_file"])
    for key in ("docker_context", "compose_project"):
        _name(p.get(key), key)
    if not re.fullmatch(r"[a-z0-9][a-z0-9_-]*", p["compose_project"]):
        raise ValueError("Select the actual native Compose project name.")
    if p.get("castor_context"):
        _name(p["castor_context"], "Castor context")
    for key, default, lower, upper in (("timeout_seconds", 900, 10, 86400),
                                      ("max_artifact_bytes", 2147483648, 1048576, 2**53 - 1)):
        value = p.get(key, default)
        if type(value) is not int or not lower <= value <= upper:
            raise ValueError("Invalid " + key + ".")
        p[key] = value
    if p.get("source_revision") and not re.fullmatch(r"[a-f0-9]{40}|[a-f0-9]{64}", p["source_revision"]):
        raise ValueError("Select the original complete Git commit.")
    for key in ("compose_files_json", "release_files_json"):
        values = _array(p, key)
        if key == "compose_files_json" and not values:
            raise ValueError("Select every original Compose file in its native order.")
        for value in values:
            _under(root, value)
        if len(values) != len(set(values)):
            raise ValueError("An original selected file is repeated.")
    for key in ("task_args_json", "verify_args_json"):
        _arguments(_array(p, key))
    for key in ("task_outputs_json", "backup_inputs_json"):
        paths = []
        for item in _array(p, key):
            if not isinstance(item, dict):
                raise ValueError("Select complete original " + key + " records.")
            _relative(item.get("path"))
            _name(item.get("role"), "output role")
            paths.append(item["path"])
            if key == "task_outputs_json":
                if item.get("kind") not in {"file", "directory"} or set(item) != {"path", "role", "kind"}:
                    raise ValueError("Declare each task output's exact path, role and kind.")
            elif (set(item) not in ({"path", "role", "sha256"}, {"path", "role", "kind", "sha256"})
                    or item.get("kind", "file") not in {"file", "directory"}
                    or not re.fullmatch(r"[a-f0-9]{64}", str(item.get("sha256", "")))):
                raise ValueError("Select each original recovery file or directory's complete SHA256 identity.")
        if len(paths) != len(set(paths)):
            raise ValueError("An original output/input is selected twice.")
    for image in _array(p, "source_images_json"):
        if not isinstance(image, str) or not re.fullmatch(r"(?:sha256:[a-f0-9]{64}|[^\s]+@sha256:[a-f0-9]{64})", image):
            raise ValueError("Select immutable native image IDs or repository digests.")
    for name in ("task_name", "verify_task_name"):
        if p.get(name):
            _task_name(p[name])
    if p.get("verify_source", "stdout") not in {"stdout", "file"}:
        raise ValueError("Choose original verification stdout or file.")
    if p.get("verify_output_path"):
        _relative(p["verify_output_path"])
    for check in _array(p, "verification_checks_json"):
        if not isinstance(check, dict) or set(check) != {"pointer", "equals"} or not isinstance(check["pointer"], str) or (
                check["pointer"] and not check["pointer"].startswith("/")):
            raise ValueError("Declare native JSON pointer/expected-value comparisons.")
    return p


def _task_name(value):
    if not isinstance(value, str) or not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9:_.-]{0,511}", value):
        raise ValueError("Select an exact original named Castor task.")
    if value in {"list", "help", "execute", "repack", "compile", "composer", "self-update"} or value.startswith("castor:"):
        raise ValueError("Select the application's own named task; keep build/tool maintenance separate.")
    return value


def _arguments(value):
    for item in value:
        if not isinstance(item, str) or "\x00" in item or len(item) > 65536:
            raise ValueError("Native arguments must remain complete string tokens.")
        if item.startswith("-c") and not item.startswith("--"):
            raise ValueError("Task arguments cannot override the original context shortcut.")
        if item.split("=", 1)[0] in {"--context", "-c", "--castor-file", "--working-dir", "--interactive",
                                    "--update-remotes", "--no-remote"}:
            raise ValueError("Task arguments cannot replace the bound native root/context/import selection.")
    return value


def provider_context(p):
    return {"source_kind": "castor", "environment_id": p["environment_id"],
            "compose_project": p["compose_project"], "docker_context": p["docker_context"],
            "castor_context": p.get("castor_context", ""), "castor_file": p.get("castor_file", "")}


def actions_for(kind):
    action = KINDS.get(kind)
    if not action:
        return []
    required = [] if action == "capture" else ["source_revision", "task_name", "verify_task_name", "verification_checks_json"]
    if action == "backup":
        required.append("task_outputs_json")
    if action in {"restore", "rollback"}:
        required.append("backup_inputs_json")
    return [{"value": "castor-" + action, "label": LABELS[action], "required_profile_fields": required}]


def pollable(resume):
    # Local native tasks have no separate provider job queue. An unknown exit
    # stays attached to its original process/journal, never becomes a new task.
    return False


def resume_fields(operation, payload, reason):
    if not str(operation.get("native_action", "")).startswith("castor-"):
        raise ValueError("Continue the original Castor operation.")
    value = {}
    if "runtime_bindings" in payload:
        selected = profile(operation["profile"]["config"], payload["runtime_bindings"])
        value["runtime_bindings"] = {k: selected.get(k, "") for k in payload["runtime_bindings"]}
    if payload.get("castor_command_receipt"):
        path = Path(payload["castor_command_receipt"]).expanduser()
        if not path.is_absolute() or path.is_symlink() or not path.is_file():
            raise ValueError("Select the actual original completed Session command receipt.")
        pending = operation.get("resume_checkpoint") or {}
        if not pending.get("pending_command") and pending.get("phase") not in {"native_interrupted", "dispatching"}:
            raise ValueError("This original operation has no uncertain native command to reconcile.")
        value["castor_command_receipt"] = {"path": str(path.resolve()), "reason": str(reason),
                                           "request_sha256": pending.get("request_sha256")}
    return value


def _retain(s, path, role, **extra):
    item = s.add(path, role, **extra)
    rows = s.state.setdefault("retained_artifacts", [])
    old = next((x for x in rows if x["path"] == item["path"]), None)
    if old and (old["sha256"], old["size"]) != (item["sha256"], item["size"]):
        raise ValueError("An original retained artifact was modified.")
    if old is None:
        rows.append(item)
    return item


def _record(s, name, value, role):
    path = s.out / name
    if path.exists() and json.loads(path.read_bytes()) != value:
        path = path.with_name(path.stem + "-" + _digest(value) + path.suffix)
    if not path.exists():
        _api()._atomic(path, value)
    return _retain(s, path, role)


def _state_checkpoint(s):
    """Keep the complete original state privately; bound UI checkpoints by identity."""
    raw = (json.dumps(s.state, sort_keys=True, ensure_ascii=False, indent=2) + "\n").encode("utf-8")
    sha = hashlib.sha256(raw).hexdigest()
    path = s.out / ("castor-state-" + sha + ".json")
    if path.exists():
        if path.is_symlink() or path.read_bytes() != raw:
            raise ValueError("An original complete Castor checkpoint changed.")
    else:
        _api()._atomic(path, s.state)
    fields = ("provider", "phase", "intent_sha256", "request_sha256",
              "pending_command", "command_record", "mutation_started", "launch_failed")
    value = {key: s.state[key] for key in fields if key in s.state}
    value["native_state"] = {"path": str(path), "bytes": len(raw), "sha256": sha}
    return value


def _receive_state(s, value):
    reference = value.get("native_state") if isinstance(value, dict) else None
    if not reference:
        return value
    path = Path(s.private_path(reference["path"]))
    if (path.parent != s.out or path.name != "castor-state-" + reference["sha256"] + ".json"
            or path.is_symlink() or not path.is_file()):
        raise ValueError("Receive the complete original private Castor state member.")
    raw = path.read_bytes()
    if len(raw) != reference["bytes"] or hashlib.sha256(raw).hexdigest() != reference["sha256"]:
        raise ValueError("The original complete Castor state member changed.")
    return json.loads(raw)


def _bounded_result(s, status, observations=None, message=None):
    checkpoint = _state_checkpoint(s)
    s.add(checkpoint["native_state"]["path"], "original_native_state")
    result = s.result(status, observations, message)
    result.update(checkpoint=checkpoint, resume_checkpoint=checkpoint)
    return result


def _load(s, supplied=None):
    path = s.out / "native-state.json"
    saved = s.read_private_json(path) if path.exists() else supplied or {}
    saved = saved.get("resume_checkpoint", saved.get("state", saved))
    saved = _receive_state(s, saved)
    s.state = dict(s.resolve_private(saved))
    if s.out.is_relative_to(Path(s.p["site_root"])):
        raise ValueError("Keep the receiving Session outside its selected source project tree.")
    if s.state.get("provider") not in (None, "castor"):
        raise ValueError("This original Session belongs to another provider.")
    s.state["provider"] = "castor"
    original_notify = s.notify

    def notify(value):
        checkpoint = _state_checkpoint(s)
        original_notify({**value, "state": checkpoint, "resume_checkpoint": checkpoint})

    s.notify = notify


def _bind(s, operation_id, action, original_config):
    value = {"operation_id": operation_id, "action": action, "target": provider_context(s.p),
             "profile": {k: v for k, v in original_config.items() if k not in RUNTIME_FIELDS}}
    digest = _digest(value)
    if s.state.get("intent_sha256") not in (None, digest):
        raise ValueError("The retained Castor instruction belongs to another original operation.")
    s.state.update(intent=value, intent_sha256=digest)
    s.save_state()


def _command(s, label, argv, *, mutating=False):
    path = s.out / (label + ".command.json")
    # Reopen completed commands as their exact original native invocation, even
    # on a receiving host with explicit new executable locations.
    previous = s.read_private_json(path) if path.exists() else None
    if previous and previous.get("phase") == "complete":
        argv = previous["argv"]
    try:
        result = s.command(label, argv, mutating=mutating)
    except _api().NativeWaiting:
        if path.exists():
            retained = s.read_private_json(path)
            if retained.get("phase") not in {"complete", "not_started"}:
                s.state.update(phase="native_interrupted", pending_command=label, command_record=str(path))
                s.save_state()
        raise
    for role in ("stdout", "stderr"):
        _retain(s, result[role]["path"], "native_" + role)
    _retain(s, path, "native_command")
    return result


def _bytes(record, role="stdout"):
    path = Path(record[role]["path"])
    raw = path.read_bytes()
    if len(raw) != record[role]["size"] or hashlib.sha256(raw).hexdigest() != record[role]["sha256"]:
        raise ValueError("An original native command output changed.")
    return raw


def _parsed(record):
    try:
        return json.loads(_bytes(record))
    except (UnicodeDecodeError, ValueError) as exc:
        raise ValueError("The selected native command did not return complete JSON; inspect its unchanged stdout.") from exc


def _castor(p, task, args=None, *, context=True):
    result = ([p["php_path"]] if p.get("php_path") else []) + [p["castor_path"]]
    if p.get("castor_file"):
        result.append("--castor-file=" + str(_under(p["site_root"], p["castor_file"])))
    result.extend(["--no-interaction", "--no-ansi"])
    if context and p.get("castor_context"):
        result.append("--context=" + p["castor_context"])
    return result + [task] + (args or [])


def _compose(p):
    result = [p["docker_path"], "--context", p["docker_context"], "compose",
              "--project-directory", p["site_root"], "--project-name", p["compose_project"]]
    for item in _array(p, "compose_files_json"):
        result.extend(["--file", str(_under(p["site_root"], item))])
    return result



def _file_identity(path):
    digest = hashlib.sha256()
    size = 0
    with Path(path).open("rb") as stream:
        before = os.fstat(stream.fileno())
        for block in iter(lambda: stream.read(1048576), b""):
            digest.update(block)
            size += len(block)
        after = os.fstat(stream.fileno())
    if (before.st_dev, before.st_ino, before.st_size, before.st_mtime_ns) != (
            after.st_dev, after.st_ino, after.st_size, after.st_mtime_ns) or size != before.st_size:
        raise ValueError("An original native file changed while its complete bytes were received.")
    return {"bytes": size, "sha256": digest.hexdigest()}


def _working_tree(s, label, root=None, depth=0):
    """Hash actual Git-selected files, index entries and nested worktrees."""
    if depth > 30:
        raise ValueError("The selected original submodule nesting is excessive.")
    root = Path(root or s.p["site_root"])
    command = [s.p["git_path"], "-C", str(root)]
    tracked = _bytes(_command(s, label + "-index", command + ["ls-files", "--stage", "-z"]))
    other = _bytes(_command(s, label + "-untracked", command + ["ls-files", "--others", "--exclude-standard", "-z"]))
    entries = {}
    for row in tracked.split(b"\x00"):
        if not row:
            continue
        metadata, raw_path = row.split(b"\t", 1)
        mode, blob, stage = metadata.decode("ascii").split(" ")
        relative = raw_path.decode("utf-8", "strict")
        _relative(relative)
        if stage != "0":
            raise ValueError("Resolve the original native source's Git index conflict before commissioning.")
        entries[relative] = {"path": relative, "git_mode": mode, "git_blob": blob}
    for raw_path in other.split(b"\x00"):
        if raw_path:
            relative = raw_path.decode("utf-8", "strict")
            _relative(relative)
            entries[relative] = {"path": relative, "git_mode": None, "git_blob": None}
    result = []
    for relative, entry in sorted(entries.items()):
        path = root / relative
        # A tracked symlink is observed as its link value, never followed.
        if path.is_symlink():
            entry.update(kind="symlink", target=os.readlink(path))
        elif not path.exists():
            entry["kind"] = "absent"
        elif entry["git_mode"] == "160000":
            if not path.is_dir() or not (path / ".git").exists():
                raise ValueError("Initialize the original selected submodule before complete source capture.")
            prefix = label + "-sub-" + hashlib.sha256(relative.encode()).hexdigest()[:20]
            nested = _working_tree(s, prefix, path, depth + 1)
            head = _bytes(_command(s, prefix + "-head", command[:1] + ["-C", str(path), "rev-parse", "HEAD"])).decode().strip()
            entry.update(kind="submodule", head_commit=head, source=nested)
        elif path.is_file():
            before = path.stat()
            identity = _file_identity(path)
            after = path.stat()
            if (before.st_size, before.st_mtime_ns, before.st_ino) != (after.st_size, after.st_mtime_ns, after.st_ino):
                raise ValueError("An original source member changed while its identity was read.")
            entry.update(kind="file", mode=after.st_mode & 0o777, **identity)
        else:
            raise ValueError("An original Git-selected member is not an ordinary source file.")
        result.append(entry)
    return {"members": result, "sha256": _digest(result)}


def _inventory(s, label, *, selected=True):
    p = s.p
    head_record = _command(s, label + "-head", [p["git_path"], "rev-parse", "--verify", "HEAD"])
    head = _bytes(head_record).decode().strip()
    if not re.fullmatch(r"[a-f0-9]{40}|[a-f0-9]{64}", head):
        raise ValueError("Native Git did not identify the complete current commit.")
    status = _command(s, label + "-git-status", [p["git_path"], "status", "--porcelain=v1", "-z", "--untracked-files=all"])
    version = _command(s, label + "-version", _castor(p, "--version", context=False))
    listing = _command(s, label + "-tasks", _castor(p, "list", ["--format=json"], context=False))
    catalog = _parsed(listing)
    if not isinstance(catalog, dict) or not isinstance(catalog.get("commands"), list):
        raise ValueError("The installed Castor list did not return its native command catalogue.")
    help_rows = {}
    if selected:
        for key in ("task_name", "verify_task_name"):
            if p.get(key):
                help_result = _command(s, label + "-" + key + "-help",
                    _castor(p, "help", [p[key], "--format=json"]))
                help_rows[key] = _parsed(help_result)
                if help_rows[key].get("name") != p[key]:
                    raise ValueError("Native task help resolved to a different original task.")
                options = help_rows[key].get("definition", {}).get("options", {})
                context_option = options.get("context") if isinstance(options, dict) else next((x for x in options if x.get("name") == "--context"), None)
                if context_option and not p.get("castor_context"):
                    raise ValueError("Select the actual named native context before this task can run.")
    engine = _parsed(_command(s, label + "-engine",
        [p["docker_path"], "--context", p["docker_context"], "info", "--format", "{{json .}}"]))
    if not isinstance(engine, dict) or not engine.get("ID"):
        raise ValueError("Native Docker did not return the selected engine identity.")
    compose = _parsed(_command(s, label + "-compose-config", _compose(p) + ["config", "--format", "json"]))
    ps_raw = _bytes(_command(s, label + "-compose-ps", _compose(p) + ["ps", "--all", "--format", "json"]))
    try:
        containers = json.loads(ps_raw or b"[]")
        if isinstance(containers, dict):
            containers = [containers]
    except ValueError:
        containers = [json.loads(line) for line in ps_raw.splitlines() if line.strip()]
    if not isinstance(containers, list):
        raise ValueError("The native Compose container census is not a complete array.")
    images_raw = _bytes(_command(s, label + "-compose-images", _compose(p) + ["images", "--format", "json"]))
    try:
        images = json.loads(images_raw or b"[]")
        if isinstance(images, dict):
            images = [images]
    except ValueError:
        images = [json.loads(line) for line in images_raw.splitlines() if line.strip()]
    working_tree = _working_tree(s, label + "-source")
    bindings = {}
    for relative in _array(p, "compose_files_json") + _array(p, "release_files_json") + ([p["castor_file"]] if p.get("castor_file") else []):
        path = _under(p["site_root"], relative)
        if not path.is_file():
            raise ValueError("Select ordinary native release/configuration files.")
        bindings[relative] = _file_identity(path)
    return {"project": provider_context(p), "head_commit": head, "git_status_sha256": status["stdout"]["sha256"],
            "castor_version": _bytes(version).decode("utf-8", "strict").strip(),
            "native_executables": {key: _file_identity(p[key]) for key in ("castor_path", "php_path") if p.get(key)},
            "tasks": catalog["commands"], "task_definitions": help_rows,
            "docker_engine": engine, "compose_config": compose, "containers": containers, "images": images,
            "selected_files": bindings, "working_tree": working_tree, "observed_at": _api()._now()}


def _binding(inventory):
    return {"project": inventory["project"], "head_commit": inventory["head_commit"],
            "git_status_sha256": inventory["git_status_sha256"],
            "working_tree_sha256": inventory["working_tree"]["sha256"],
            "engine_id": inventory["docker_engine"]["ID"],
            "castor_version": inventory["castor_version"], "native_executables": inventory["native_executables"],
            "selected_files": inventory["selected_files"], "compose_config": inventory["compose_config"],
            "images": sorted(inventory["images"], key=_json),
            "task_definitions": inventory["task_definitions"]}


def _source(s, inventory, phase):
    import castor_source
    selected = dict(s.p)
    selected["source_revision"] = inventory["head_commit"]
    selected["capture_phase"] = phase
    if phase == "before":
        # These files are produced by the selected task. A pre-task capture
        # retains existing members, but may legitimately precede their creation.
        selected["allow_missing_task_outputs"] = True
    result = castor_source.capture_source(s, inventory, selected)
    for item in list(s.artifacts):
        current = _retain(s, item["path"], item["role"], **{k: v for k, v in item.items() if k not in {"path", "role", "sha256", "size"}})
        if current["sha256"] != item["sha256"] or current["size"] != item["size"]:
            raise ValueError("An original helper source artifact changed before completion.")
    s.state.setdefault("source_captures", {})[phase] = result
    s.save_state()
    return result


def _directory_members(path):
    members = []
    for member in sorted(path.rglob("*")):
        if member.is_symlink():
            raise ValueError("A declared native directory contains a symlink.")
        if member.is_file():
            members.append({"path": member.relative_to(path).as_posix(), **_file_identity(member)})
        elif not member.is_dir():
            raise ValueError("A declared native directory contains a nonordinary member.")
    return members


def _inputs(s):
    result = []
    for selected in _array(s.p, "backup_inputs_json"):
        path = _under(s.p["site_root"], selected["path"])
        kind = selected.get("kind", "file")
        if kind == "file":
            if not path.is_file():
                raise ValueError("The reviewed recovery input must be an ordinary complete file.")
            identity = _file_identity(path)
        else:
            if not path.is_dir():
                raise ValueError("The reviewed recovery input must be its original complete directory.")
            members = _directory_members(path)
            identity = {"members": members, "sha256": _digest(members)}
        if identity["sha256"] != selected["sha256"]:
            raise ValueError("An original reviewed recovery input has changed.")
        result.append({**selected, "kind": kind, **identity})
    return result


def _outputs(s, *, required):
    result = []
    for selected in _array(s.p, "task_outputs_json"):
        path = _under(s.p["site_root"], selected["path"], exists=required)
        if not path.exists():
            result.append({**selected, "present": False})
            continue
        if selected["kind"] == "file":
            if not path.is_file():
                raise ValueError("The selected native output is not an ordinary file.")
            result.append({**selected, "present": True, **_file_identity(path)})
        else:
            if not path.is_dir():
                raise ValueError("The selected native output is not a directory.")
            members = _directory_members(path)
            result.append({**selected, "present": True, "members": members, "manifest_sha256": _digest(members)})
    return result


def _pointer(value, pointer):
    for raw in pointer.split("/")[1:] if pointer else []:
        if re.search(r"~(?![01])", raw):
            raise ValueError("Invalid native JSON pointer escape.")
        key = raw.replace("~1", "/").replace("~0", "~")
        if isinstance(value, list):
            if not re.fullmatch(r"0|[1-9][0-9]*", key):
                raise ValueError("Select an actual array position in the native report.")
            value = value[int(key)]
        elif isinstance(value, dict):
            value = value[key]
        else:
            raise ValueError("A native verification pointer crosses a scalar value.")
    return value


def _verify(s):
    p = s.p
    result = _command(s, "verify-task", _castor(p, p["verify_task_name"], _array(p, "verify_args_json")), mutating=True)
    retained = s.state.get("verification_report")
    if retained:
        raw = Path(s.private_path(retained["path"])).read_bytes()
        if hashlib.sha256(raw).hexdigest() != retained["sha256"] or len(raw) != retained["size"]:
            raise ValueError("The original native verification bytes changed.")
    else:
        if p.get("verify_source", "stdout") == "file":
            original = _under(p["site_root"], p["verify_output_path"])
            raw = original.read_bytes()
        else:
            raw = _bytes(result)
        if len(raw) > p["max_artifact_bytes"]:
            raise ValueError("The native verification report exceeds the selected intake bound.")
        saved = s.out / ("verification-report-" + hashlib.sha256(raw).hexdigest() + ".json")
        if not saved.exists():
            with saved.open("xb") as output:
                output.write(raw)
                output.flush()
                os.fsync(output.fileno())
        s.state["verification_report"] = _retain(s, saved, "native_verification_report")
        s.save_state()
    if len(raw) > p["max_artifact_bytes"]:
        raise ValueError("The native verification report exceeds the selected intake bound.")
    actual = json.loads(raw)
    checks = []
    for selected in _array(p, "verification_checks_json"):
        observed = _pointer(actual, selected["pointer"])
        matched = _json(observed) == _json(selected["equals"])
        checks.append({**selected, "observed": observed, "matched": matched})
    outcome = {"checks": checks, "report_sha256": hashlib.sha256(raw).hexdigest(),
               "passed": bool(checks) and all(row["matched"] for row in checks)}
    _record(s, "native-verification.json", outcome, "native_verification")
    if not outcome["passed"]:
        raise ValueError("The actual native verification did not satisfy all reviewed comparisons.")
    s.state["verification"] = outcome
    s.save_state()
    return outcome


def _recover_receipt(s, operation):
    incoming = operation.get("castor_command_receipt")
    if not incoming:
        return
    accepted = s.state.setdefault("received_command_receipts", {})
    for item in accepted.values():
        if item.get("selection") == incoming:
            return
    if incoming.get("request_sha256") != s.state.get("request_sha256"):
        raise ValueError("The selected command receipt belongs to another original request.")
    source = Path(s.private_path(incoming["path"]))
    raw = source.read_bytes()
    receipt_hash = hashlib.sha256(raw).hexdigest()
    if any(item["sha256"] == receipt_hash for item in accepted.values()):
        return
    label = s.state.get("pending_command")
    if not label or not re.fullmatch(r"[A-Za-z0-9_.-]+", label):
        raise ValueError("No original native command is awaiting its completion; retain the already accepted receipt.")
    if label in accepted:
        raise ValueError("The already accepted original native receipt cannot be replaced.")
    original_path = s.out / (label + ".command.json")
    preimage = s.out / (label + "-before-receiving.json")
    original = s.read_private_json(preimage if preimage.exists() else original_path)
    retained = s.out / ("received-command-receipt-" + receipt_hash + ".json")
    if not retained.exists():
        with retained.open("xb") as output:
            output.write(raw)
            output.flush()
            os.fsync(output.fileno())
    _retain(s, retained, "original_native_receipt")
    # Compare both receipts in the same receiving-workspace view while the
    # complete incoming bytes remain unchanged in retained custody.
    completed = s.resolve_private(json.loads(raw))
    for key in ("argv", "cwd", "started_at", "mutating", "stdin"):
        if completed.get(key) != original.get(key):
            raise ValueError("The native receipt does not match the exact original command " + key + ".")
    if original.get("pid") is not None and completed.get("pid") != original["pid"]:
        raise ValueError("The completion names a different original process.")
    if completed.get("phase") != "complete" or type(completed.get("returncode")) is not int or not completed.get("completed_at"):
        raise ValueError("Select the native observed exit receipt, not an inferred task outcome.")
    for role in ("stdout", "stderr"):
        item = completed[role]
        path = Path(item["path"])
        copied = s.out / (label + ".received-" + receipt_hash + "." + role)
        if copied.exists():
            observed = _api()._file(copied, role)
            if observed["sha256"] != item["sha256"] or observed["size"] != item["size"]:
                raise ValueError("A retained received output changed.")
        else:
            if not path.is_absolute() or path.is_symlink() or not path.is_file():
                raise ValueError("The native receipt must include complete original output files.")
            observed = _api()._file(path, role)
            if observed["sha256"] != item["sha256"] or observed["size"] != item["size"]:
                raise ValueError("The selected native output does not match its receipt.")
            shutil.copyfile(path, copied)
            received = _api()._file(copied, role)
            if received["sha256"] != item["sha256"] or received["size"] != item["size"]:
                raise ValueError("The original native output changed while being received.")
        completed[role] = _api()._file(copied, role)
    _record(s, label + "-before-receiving.json", original, "original_interrupted_command")
    _api()._atomic(original_path, completed)
    s.state.setdefault("completed_commands", {})[label] = completed
    s.state.update(phase="native_prepared" if completed["returncode"] == 0 else "native_failed", pending_command=None)
    s.state["received_command_receipts"][label] = {"sha256": receipt_hash, "reason": incoming["reason"],
        "label": label, "request_sha256": s.state.get("request_sha256"), "selection": incoming,
        "retained_path": str(retained)}
    s.save_state()


def _finish(s, observations):
    value = {"schema": VERSION, "intent_sha256": s.state["intent_sha256"],
             "provider_context": provider_context(s.p), "observations": observations,
             "artifacts": list(s.state.get("retained_artifacts", []))}
    path = s.out / "castor-completed-operation.json"
    if path.exists() and json.loads(path.read_bytes()) != value:
        raise ValueError("The original completed Castor outcome cannot be replaced.")
    _api()._atomic(path, value)
    s.state.update(phase="completed", completion=str(path))
    s.save_state()
    return _completed(s, value)


def _completed(s, value):
    if value.get("intent_sha256") != s.state["intent_sha256"]:
        raise ValueError("This original completed outcome belongs to another instruction.")
    s.artifacts = []
    for item in value["artifacts"]:
        path = s.private_path(item["path"])
        observed = _api()._file(path, item["role"])
        if observed["sha256"] != item["sha256"] or observed["size"] != item["size"]:
            raise ValueError("A retained complete Castor artifact changed.")
        s.add(path, item["role"])
    s.add(s.out / "castor-completed-operation.json", "restored_native_status")
    return _bounded_result(s, "COMPLETE", value["observations"])


def _failure(s, exc):
    waiting = isinstance(exc, _api().NativeWaiting) or s.state.get("phase") in {"native_interrupted", "dispatching"}
    status = "WAITING_NATIVE" if waiting else "CANCELLED" if isinstance(exc, _api().NativeCancelled) else "FAILED"
    s.artifacts = list(s.state.get("retained_artifacts", []))
    result = _bounded_result(s, status, message=str(exc))
    label = s.state.get("pending_command")
    record = None
    if label and (s.out / (label + ".command.json")).exists():
        record = s.read_private_json(s.out / (label + ".command.json"))
    result["native_resume"] = {"provider": "castor", "phase": s.state.get("phase"),
        "request_sha256": s.state.get("request_sha256"), "command_label": label,
        "command_record": str(s.out / (label + ".command.json")) if label else None,
        "original_process": {k: record.get(k) for k in ("pid", "started_at", "phase", "returncode")} if record else None}
    result["safe_to_retry"] = not waiting
    return result


def discover_capabilities(config, runtime_bindings=None):
    value = {"ready": False, "actions": [], "configuration": dict(config), "current_config": dict(config)}
    try:
        p = profile(config, runtime_bindings)
        with tempfile.TemporaryDirectory(prefix="govhub-castor-capabilities-") as folder:
            s = _api().Session(p, folder)
            _load(s)
            inventory = _inventory(s, "capability")
            value.update(ready=True, target_fingerprint=_digest(provider_context(p)),
                native_inventory=inventory,
                native_status={"head_commit": inventory["head_commit"], "castor_version": inventory["castor_version"],
                    "docker_engine_id": inventory["docker_engine"]["ID"], "compose_project": p["compose_project"],
                    "task_count": len(inventory["tasks"]), "containers": inventory["containers"]},
                actions=[row for kind in KINDS for row in actions_for(kind)])
    except Exception as exc:
        value["error"] = str(exc)
    return value


def capture(config, context, checkpoint=None, cancelled=None):
    p = profile(config, context.get("runtime_bindings"))
    s = _api().Session(p, context["output_dir"], checkpoint, cancelled, context.get("workspace_relocations"))
    try:
        _load(s, context.get("checkpoint"))
        expected = context.get("target_fingerprint") or config.get("target_fingerprint")
        if expected and expected != _digest(provider_context(p)):
            raise ValueError("The original capture target fingerprint changed.")
        _bind(s, context.get("operation_id"), "capture", config)
        completed = s.out / "castor-completed-operation.json"
        if completed.exists():
            return _completed(s, s.read_private_json(completed))
        _recover_receipt(s, context)
        inventory = s.state.get("capture_inventory")
        if inventory is None:
            inventory = _inventory(s, "capture")
            s.state["capture_inventory"] = inventory
            s.save_state()
        if p.get("source_revision") and p["source_revision"] != inventory["head_commit"]:
            raise ValueError("The original selected Git revision changed.")
        source = _source(s, inventory, "capture")
        following = _inventory(s, "capture-following")
        if _binding(following) != _binding(inventory):
            raise ValueError("The native source/engine/configuration changed during full capture.")
        return _finish(s, {"native_action": "castor-capture", "native_inventory": inventory,
                          "following_inventory": following, "source": source,
                          "consistency": "original native task/source outputs; no database/files transaction is inferred"})
    except Exception as exc:
        return _failure(s, exc)


def execute(operation, config, source_paths, checkpoint=None, cancelled=None):
    p = profile(config, operation.get("runtime_bindings"))
    s = _api().Session(p, source_paths["output_dir"], checkpoint, cancelled, source_paths.get("workspace_relocations"))
    try:
        _load(s, source_paths.get("checkpoint") or operation.get("resume_checkpoint"))
        action = str(operation.get("native_action", "")).removeprefix("castor-")
        if action == "capture" or KINDS.get(operation.get("type")) != action:
            raise ValueError("Select the exact native task purpose from the original reviewed operation.")
        if action == "preview" and operation.get("environment", {}).get("data", {}).get("purpose") not in {"Candidate", "Rehearsal"}:
            raise ValueError("Select the explicitly designated nonproduction environment for a preview task.")
        if operation.get("provider_environment_id") != p["environment_id"]:
            raise ValueError("The original native operation names a different deployment.")
        expected = operation.get("target_fingerprint") or config.get("target_fingerprint")
        if expected and expected != _digest(provider_context(p)):
            raise ValueError("The original native target identity changed.")
        _bind(s, operation["id"], action, config)
        completed = s.out / "castor-completed-operation.json"
        if completed.exists():
            return _completed(s, s.read_private_json(completed))
        _recover_receipt(s, operation)
        if not p.get("source_revision") or not p.get("task_name") or not p.get("verify_task_name") or not _array(p, "verification_checks_json"):
            raise ValueError("Select the original source commit, native task and complete verification comparisons.")
        if p.get("verify_source", "stdout") == "file" and not p.get("verify_output_path"):
            raise ValueError("Select the actual native verification report path.")
        if action == "backup" and not _array(p, "task_outputs_json"):
            raise ValueError("Select the complete actual database/files backup outputs.")
        if action in {"restore", "rollback"} and not _array(p, "backup_inputs_json"):
            raise ValueError("Select the original hash-bound recovery input files.")
        original = s.state.get("before")
        if original is None:
            original = _inventory(s, "before")
            if original["head_commit"] != p["source_revision"]:
                raise ValueError("The current source differs from the reviewed commit.")
            s.state.update(before=original, backup_inputs=_inputs(s), before_outputs=_outputs(s, required=False))
            s.save_state()
        argv = _castor(p, p["task_name"], _array(p, "task_args_json"))
        request = {"task": p["task_name"], "args": _array(p, "task_args_json"),
                   "context": provider_context(p), "source": _binding(original),
                   "backup_inputs": s.state["backup_inputs"], "verification": {
                       k: p.get(k) for k in ("verify_task_name", "verify_args_json", "verify_source",
                                             "verify_output_path", "verification_checks_json")}}
        request_sha = _digest(request)
        if s.state.get("request_sha256") not in (None, request_sha):
            raise ValueError("The retained original native request changed.")
        s.state.update(request=request, request_sha256=request_sha)
        s.save_state()
        task_record = s.out / "application-task.command.json"
        dispatched = task_record.exists() and s.read_private_json(task_record).get("phase") not in {"not_started", "prepared"}
        if not dispatched and not s.state.get("task_completed"):
            if not s.state.get("before_source"):
                s.state["before_source"] = _source(s, original, "before")
                s.save_state()
            fresh = _inventory(s, "dispatch-" + str(time.time_ns()))
            if _binding(fresh) != _binding(original) or _inputs(s) != s.state["backup_inputs"]:
                raise ValueError("The original source/configuration/engine/recovery inputs changed before dispatch.")
        native = _command(s, "application-task", argv, mutating=True)
        s.state["task_completed"] = {"returncode": native["returncode"], "completed_at": native["completed_at"]}
        s.save_state()
        verification = s.state.get("verification") or _verify(s)
        outputs = s.state.get("after_outputs")
        if outputs is None:
            outputs = _outputs(s, required=True)
            s.state["after_outputs"] = outputs
            s.save_state()
        elif outputs != _outputs(s, required=True):
            raise ValueError("The completed native task outputs changed before full receiving.")
        following = s.state.get("after_inventory")
        if following is None:
            following = _inventory(s, "after")
            if following["docker_engine"]["ID"] != original["docker_engine"]["ID"]:
                raise ValueError("The native task continued on another Docker engine.")
            s.state["after_inventory"] = following
            s.save_state()
        source = s.state.get("after_source")
        if source is None:
            source = _source(s, following, "after")
            final_inventory = _inventory(s, "source-after-" + str(time.time_ns()))
            if _binding(final_inventory) != _binding(following):
                raise ValueError("The actual post-task source/engine/configuration changed during receiving.")
            if outputs != _outputs(s, required=True):
                raise ValueError("The original task outputs changed during complete source capture.")
            s.state["after_source"] = source
            s.save_state()
        return _finish(s, {"native_action": "castor-" + action, "native_inventory": following,
            "before_inventory": original, "source": source, "before_source": s.state["before_source"],
            "task_result": s.state["task_completed"], "verification": verification,
            "task_outputs": outputs, "backup_inputs": s.state["backup_inputs"],
            "request_sha256": request_sha, "native_result": "verified",
            "consistency": "actual selected task and original verification report; no inferred transactional snapshot"})
    except Exception as exc:
        return _failure(s, exc)

#!/usr/bin/env python3
"""Receive a complete selected Castor operating course in the existing GovHub project.

Copyright 2026 Token Junkie Labs contributors. Apache-2.0; see ../LICENSE.
Actual provider work, current plan review, native commands, files and private backup
remain with the original GovHub engines. This programme retains the whole course.
"""
from __future__ import annotations

import argparse
from datetime import datetime
import hashlib
import json
import os
from pathlib import Path
import re
import shutil
import sys
import time

from pantheon_receive import (Commands, add_workspace, atomic, directory, identity,
                              lease, opened, read_json, request_payload, utc)
from tugboat_receive import arguments, copy_intake, receive_application
import castor_adapter

SCHEMA = "govhub-castor-native-receiving/v1"
CONTINUATION = "govhub-castor-native-continuation/v1"


def digest(value):
    return hashlib.sha256(json.dumps(value, sort_keys=True, separators=(",", ":"),
                                    ensure_ascii=False, allow_nan=False).encode()).hexdigest()


def save(path, value):
    atomic(path, value)
    return value


def native_checkpoint(operation):
    value = operation.get("resume_checkpoint") or operation.get("checkpoint") or {}
    return value.get("resume_checkpoint", value.get("state", value))


def source_pointer(value, pointer, json_value=False):
    if not isinstance(pointer, str) or not pointer.startswith("/"):
        raise ValueError("Select an explicit JSON pointer into the complete original operation.")
    for raw in pointer.split("/")[1:]:
        if re.search(r"~(?![01])", raw):
            raise ValueError("Use the original valid JSON pointer escaping.")
        key = raw.replace("~1", "/").replace("~0", "~")
        if isinstance(value, list):
            if not re.fullmatch(r"0|[1-9][0-9]*", key):
                raise ValueError("A source pointer must select an actual original list item.")
            value = value[int(key)]
        elif isinstance(value, dict):
            value = value[key]
        else:
            raise ValueError("The selected source pointer does not name an original value.")
    if json_value:
        return json.dumps(value, sort_keys=True, separators=(",", ":"), ensure_ascii=False, allow_nan=False)
    if not isinstance(value, (str, int, bool)) or isinstance(value, float):
        raise ValueError("A profile source selection must resolve to its native scalar value.")
    return value


class Receiving:
    def __init__(self, request_path, continuation_path=None):
        self.request, self.original = request_payload(request_path)
        if self.request.get("schema") != SCHEMA:
            raise ValueError("Use the complete original Castor receiving request.")
        if not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9_.:-]{2,159}", self.request.get("operation_id", "")):
            raise ValueError("Supply the original whole-course operation identifier.")
        self.root = directory(self.request["work_directory"], True)
        self.state_file = self.root / "receiving.json"
        self.state = read_json(self.state_file) if self.state_file.exists() else {
            "schema": SCHEMA, "operation_id": self.request["operation_id"],
            "request_sha256": self.original["sha256"], "phase": "prepared", "steps": {},
        }
        if self.state.get("request_sha256") != self.original["sha256"]:
            raise ValueError("This receiving directory belongs to another original request.")
        self.args = arguments(self.request["workspace"])
        self.workspace, self.actor = opened(self.args)
        self.steps = self.request.get("steps")
        if not isinstance(self.steps, list) or not 1 <= len(self.steps) <= 64:
            raise ValueError("Select between one and 64 complete native operating steps.")
        ids = []
        for step in self.steps:
            if not isinstance(step, dict) or not re.fullmatch(r"[a-z0-9][a-z0-9-]{0,79}", step.get("id", "")):
                raise ValueError("Each selected native step needs a unique plain identifier.")
            if step["id"] in ids:
                raise ValueError("Each native step identifier must be unique.")
            ids.append(step["id"])
            kind = step.get("type")
            actions = castor_adapter.actions_for(kind)
            if step.get("native_action") not in {row["value"] for row in actions}:
                raise ValueError("Select an actual Castor action for each existing operation purpose.")
            if not isinstance(step.get("profile"), dict) or step["profile"].get("source_kind") != "castor":
                raise ValueError("Retain the selected complete Castor profile for every step.")
            if not step.get("environment_id"):
                raise ValueError("Select the existing local environment record for every native step.")
            for source in list(step.get("profile_sources", [])) + list(step.get("backup_sources", [])):
                if source.get("step") not in ids[:-1]:
                    raise ValueError("A profile source must select an earlier completed course step.")
        self.continuation = {}
        self.continuation_identity = None
        if continuation_path:
            value, original = request_payload(continuation_path)
            if value.get("schema") != CONTINUATION or value.get("request_sha256") != self.original["sha256"]:
                raise ValueError("Continuation must name this immutable original course request.")
            if not isinstance(value.get("operations", {}), dict):
                raise ValueError("Continuation operations must be keyed by their original operation IDs.")
            source_commands = value.get("source_commands", {})
            if not isinstance(source_commands, dict) or any(
                    not isinstance(key, str) or not re.fullmatch(r"0|[1-9][0-9]*", key)
                    or not isinstance(receipt, str) or not Path(receipt).is_absolute()
                    for key, receipt in source_commands.items()):
                raise ValueError("Source command receipts must bind an export index to its actual absolute receipt path.")
            self.continuation = value
            self.continuation_identity = original

    def reload(self):
        if self.state_file.exists():
            current = read_json(self.state_file)
            if current.get("request_sha256") != self.original["sha256"]:
                raise ValueError("The saved receiving state belongs to another original request.")
            self.state = current

    def persist(self):
        save(self.state_file, self.state)

    def retained(self, label, value):
        path = self.root / (label + "-" + digest(value) + ".json")
        if not path.exists():
            save(path, value)
        elif read_json(path) != value:
            raise ValueError("A retained original receiving result changed.")
        return identity(path)

    def key(self, label):
        return self.request["operation_id"] + "/" + label

    def original_operation(self, step_id):
        step = self.state["steps"].get(step_id) or {}
        if step.get("phase") != "COMPLETE" or not step.get("operation_id"):
            raise ValueError("The selected earlier native source operation is not complete.")
        result = self.workspace.dispatch("operations.get", {"operation_id": step["operation_id"]}, self.actor)
        if result["operation"]["state"] != "COMPLETE":
            raise ValueError("The selected earlier original operation no longer has a complete outcome.")
        return result["operation"]

    def profile(self, step):
        selected = dict(step["profile"])
        schema = castor_adapter.provider_schema()
        allowed = {field["name"] for field in schema["fields"]}
        host_fields = {field if isinstance(field, str) else field["name"]
                       for field in schema.get("runtime_fields", [])}
        bindings = []
        for source in step.get("profile_sources", []):
            name = source.get("field")
            if name not in allowed or name.endswith("_env") or name in host_fields:
                raise ValueError("Only native source selections may be received from a prior operation.")
            original = self.original_operation(source["step"])
            encoding = source.get("encoding", "scalar")
            if encoding not in {"scalar", "json"} or (encoding == "json" and not name.endswith("_json")):
                raise ValueError("Use JSON encoding only for an original provider JSON selection.")
            value = source_pointer(original, source.get("pointer"), encoding == "json")
            selected[name] = value
            bindings.append({"field": name, "step": source["step"], "operation_id": original["id"],
                             "operation_revision": original["revision"], "pointer": source["pointer"], "encoding": encoding,
                             "value": value, "original_sha256": digest(original)})
        if step.get("backup_sources"):
            if any(row.get("field") == "backup_inputs_json" for row in step.get("profile_sources", [])):
                raise ValueError("Choose one explicit original backup input binding for this step.")
            inputs = []
            seen = set()
            for source in step["backup_sources"]:
                if not isinstance(source, dict) or set(source) - {"step", "path", "target_path"}:
                    raise ValueError("Select the previous backup step, actual output path and optional original target path.")
                original = self.original_operation(source["step"])
                outputs = ((original.get("native_result") or {}).get("observations") or {}).get("task_outputs") or []
                matches = [row for row in outputs if row.get("path") == source.get("path") and row.get("present") is True]
                if len(matches) != 1:
                    raise ValueError("The backup selection must identify one complete original task output.")
                output = matches[0]
                kind = output.get("kind", "file")
                sha = output.get("sha256") if kind == "file" else output.get("manifest_sha256")
                if kind not in {"file", "directory"} or not re.fullmatch(r"[0-9a-f]{64}", sha or ""):
                    raise ValueError("The selected original backup lacks its complete native file or directory identity.")
                path = source.get("target_path") or output["path"]
                if not isinstance(path, str) or path.startswith("/") or "\\" in path or any(
                        part in {"", ".", ".."} for part in path.split("/")):
                    raise ValueError("Select an explicit original project-relative backup input path.")
                if path in seen:
                    raise ValueError("Select each original receiving backup input once.")
                seen.add(path)
                item = {"path": path, "role": output["role"], "kind": kind, "sha256": sha}
                inputs.append(item)
                bindings.append({"field": "backup_inputs_json", "step": source["step"],
                    "operation_id": original["id"], "operation_revision": original["revision"],
                    "original_sha256": digest(original), "original_output": output, "selected_input": item})
            selected["backup_inputs_json"] = json.dumps(inputs, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
        castor_adapter.profile(selected)
        return selected, bindings

    def configure(self, step, retained):
        if "profile" not in retained:
            selected, bindings = self.profile(step)
            retained.update(profile=selected, profile_sources=bindings)
            self.persist()
        selected = retained["profile"]
        before = self.workspace.dispatch("operations.capabilities",
                    {"environment_id": step["environment_id"]}, self.actor)
        environment = before["environment"]
        if environment["data"].get("provider_resource_id") != selected["environment_id"]:
            raise ValueError("The actual provider identity differs from the selected environment record.")
        if before.get("current_config") != selected:
            request = {"environment_id": environment["id"], "expected_revision": environment["revision"],
                       "config": selected}
            retained["configuration_request"] = self.retained(step["id"] + "-configuration-request", request)
            self.persist()
            result = self.workspace.dispatch("operations.configure", request, self.actor)
            retained["configuration_result"] = self.retained(step["id"] + "-configuration-result", result)
            self.persist()
            before = self.workspace.dispatch("operations.capabilities",
                      {"environment_id": environment["id"]}, self.actor)
        return before

    def queue(self, step, retained, capability):
        if "request" not in retained:
            request = {"request_key": self.key(step["id"]),
                "environment_id": step["environment_id"],
                "environment_revision": capability["environment"]["revision"],
                "config_sha256": capability["profile"]["revision"],
                "authorization_reference": step.get("authorization_reference") or self.request["authorization_reference"],
                "target_fingerprint": capability.get("capabilities", {}).get("target_fingerprint", ""),
                "native_action": step["native_action"]}
            if step["type"] != "CAPTURE":
                request["type"] = step["type"]
            if step["type"] not in {"CAPTURE", "PREVIEW", "BACKUP_CREATE", "BACKUP_DOWNLOAD"}:
                if not step.get("plan_id") or not step.get("expected_plan_revision"):
                    raise ValueError("Reviewed cohort operations require the selected original plan and revision.")
                request.update(plan_id=step["plan_id"], expected_revision=step["expected_plan_revision"])
                if "agency_ids" in step:
                    request["agency_ids"] = step["agency_ids"]
                if step.get("backup_sha256"):
                    request["backup_sha256"] = step["backup_sha256"]
            retained.update(method="sources.capture" if step["type"] == "CAPTURE" else "operations.create",
                            request=request, phase="PREPARED")
            self.persist()
        if not retained.get("operation_id"):
            result = self.workspace.dispatch(retained["method"], retained["request"], self.actor)
            retained.update(operation_id=result["operation"]["id"], phase=result["operation"]["state"],
                            queued=self.retained(step["id"] + "-queued", result))
            self.persist()

    def continue_operation(self, step, operation):
        selected = self.continuation.get("operations", {}).get(operation["id"], {})
        if selected and not isinstance(selected, dict):
            raise ValueError("A continuation must retain the selected original operation controls.")
        unknown = set(selected) - {"castor_command_receipt", "runtime_bindings", "restored_snapshot_id",
                                  "reason", "resume_cancelled"}
        if unknown:
            raise ValueError("Unsupported original continuation fields: " + ", ".join(sorted(unknown)))
        if operation["state"] in {"COMPLETE", "QUEUED", "RUNNING"}:
            return
        if (operation.get("native_result") or {}).get("status") == "COMPLETE":
            snapshot_id = selected.get("restored_snapshot_id") or step.get("restored_snapshot_id")
            if snapshot_id:
                request = {"operation_id": operation["id"], "expected_revision": operation["revision"],
                    "capture_file_id": operation["native_capture_file_id"],
                    "restored_snapshot_id": snapshot_id,
                    "notes": selected.get("reason") or step.get("observation_notes") or
                             "Original selected restored inventory received through the complete native course"}
                result = self.workspace.dispatch("operations.observe", request, self.actor)
                self.retained(step["id"] + "-observed", {"request": request, "result": result})
            return
        native = native_checkpoint(operation)
        deadline = max(float(native.get("provider_not_before", 0)),
                       float(native.get("provider_request_not_before", 0)),
                       float(native.get("not_before", 0)))
        if operation.get("next_poll_at"):
            original_poll = datetime.fromisoformat(operation["next_poll_at"].replace("Z", "+00:00"))
            if original_poll.tzinfo is None:
                raise ValueError("The original operation poll deadline must include its timezone.")
            deadline = max(deadline, original_poll.timestamp())
        if time.time() < deadline:
            return
        cancelled = operation.get("cancel_requested") or operation["state"] == "CANCELLED"
        if cancelled and not selected.get("resume_cancelled"):
            return
        ambiguous = native.get("phase") in {"dispatching", "native_interrupted"} or bool(native.get("pending_command"))
        associated = bool(selected.get("castor_command_receipt"))
        explicit = bool(selected.get("runtime_bindings") or selected.get("resume_cancelled"))
        recoverable = operation["state"] in {"PAUSED", "WAITING_NATIVE"} and not ambiguous and not castor_adapter.pollable(native)
        if ambiguous and not associated:
            return
        if not associated and not explicit and not recoverable:
            return
        request = {"request_key": self.key(step["id"] + "-resume-" + str(operation["revision"]) + "-" + digest(selected)),
            "operation_id": operation["id"], "expected_revision": operation["revision"],
            "reason": selected.get("reason") or "Continue the same original native course after its receiving condition"}
        for key in ("castor_command_receipt", "runtime_bindings"):
            if key in selected:
                request[key] = selected[key]
        self.retained(step["id"] + "-resume-request", request)
        result = self.workspace.dispatch("operations.resume", request, self.actor)
        self.retained(step["id"] + "-resume-result", result)

    def run_step(self, step):
        retained = self.state["steps"].setdefault(step["id"], {"phase": "PREPARED"})
        if retained.get("phase") == "COMPLETE":
            self.original_operation(step["id"])
            return True
        if not retained.get("operation_id"):
            capability = self.configure(step, retained)
            self.queue(step, retained, capability)
        result = self.workspace.dispatch("operations.get", {"operation_id": retained["operation_id"]}, self.actor)
        self.continue_operation(step, result["operation"])
        from cli import run_worker
        run_worker(self.workspace, True)
        result = self.workspace.dispatch("operations.get", {"operation_id": retained["operation_id"]}, self.actor)
        # A newly completed provider mutation may now be joined to its actual
        # already-retained RESTORED inventory by the original comparison engine.
        if result["operation"]["state"] != "COMPLETE":
            self.continue_operation(step, result["operation"])
            result = self.workspace.dispatch("operations.get", {"operation_id": retained["operation_id"]}, self.actor)
        retained.update(phase=result["operation"]["state"], result=self.retained(step["id"] + "-result", result))
        self.persist()
        if retained["phase"] != "COMPLETE":
            self.state.update(phase="attention", current_step=step["id"])
            self.persist()
            return False
        return True

    def run(self):
        with lease(self.root, "receiving.lock"):
            self.reload()
            self.retained("original-request", self.request)
            if self.continuation_identity:
                self.retained("original-continuation", self.continuation)
            if self.state["phase"] == "complete":
                for step in self.steps:
                    self.original_operation(step["id"])
                return self.status()
            for step in self.steps:
                if not self.run_step(step):
                    return self.status()
            self.state.update(phase="complete", completed_at=utc())
            self.state.pop("current_step", None)
            self.persist()
            return self.status()

    def status(self):
        self.reload()
        return {"schema": SCHEMA, "state": self.state["phase"],
            "operation_id": self.state["operation_id"], "request_sha256": self.original["sha256"],
            "workspace": str(self.workspace.root), "current_step": self.state.get("current_step"),
            "steps": {key: {"state": row["phase"], "operation_id": row.get("operation_id")}
                      for key, row in self.state["steps"].items()},
            "result": identity(self.state_file) if self.state_file.exists() else None}

    def receive_sources(self, target, selected, handover, state_path):
        """Receive original complete packages and reopen their actual Git sources."""
        import castor_source
        from native_adapter import Session, _binary
        exports = selected.get("source_exports")
        if not isinstance(exports, list) or not exports:
            raise ValueError("Select the actual complete source artifact from each source-capture step.")
        required = {step["id"] for step in self.steps if step["type"] == "CAPTURE"}
        if not required.issubset({row.get("step") for row in exports if isinstance(row, dict)}):
            raise ValueError("Include every completed source-capture step in independent native receiving.")
        seen = set()
        for index, selection in enumerate(exports):
            if not isinstance(selection, dict) or set(selection) - {"step", "file_name", "runtime_bindings"}:
                raise ValueError("Select the original step, complete file name and actual local runtime bindings.")
            key = (selection.get("step"), selection.get("file_name"))
            if key in seen:
                raise ValueError("Receive each original source artifact once in this handover.")
            seen.add(key)
            operation = handover["operation_cohort"][selection["step"]]
            item = self.workspace.operation_file(operation["id"], selection["file_name"])
            slot = directory(target / ("native-source-" + str(index).zfill(2)), True)
            archive = slot / "original-source.zip"
            expected = {"bytes": item.get("size", item.get("bytes")), "sha256": item["sha256"]}
            if not archive.exists():
                partial = slot / "original-source.zip.receiving"
                if partial.is_symlink():
                    raise ValueError("The original source receiving path cannot be a link.")
                with Path(item["path"]).open("rb") as source, partial.open("wb") as output:
                    shutil.copyfileobj(source, output, 1024 * 1024)
                    output.flush()
                    os.fsync(output.fileno())
                actual = identity(partial)
                if any(actual[name] != expected[name] for name in expected):
                    raise ValueError("The complete retained source package changed while receiving.")
                os.replace(partial, archive)
            actual = identity(archive)
            if any(actual[name] != expected[name] for name in expected):
                raise ValueError("The original received source package changed.")
            original_config = operation["profile"]["config"]
            maximum = original_config.get("max_artifact_bytes", 1073741824)
            manifest = castor_source.verify_source(archive, maximum)
            native_target = manifest.get("target") or {}
            expected_selection = {
                "environment_id": original_config["environment_id"],
                "castor_file": original_config.get("castor_file", ""),
                "docker_context": original_config.get("docker_context", ""),
                "castor_context": original_config.get("castor_context", ""),
                "compose_project": original_config.get("compose_project", ""),
                "compose_files": json.loads(original_config.get("compose_files_json") or "[]"),
                "release_files": json.loads(original_config.get("release_files_json") or "[]"),
                "task_outputs": json.loads(original_config.get("task_outputs_json") or "[]"),
            }
            if any(native_target.get(name) != value for name, value in expected_selection.items()):
                raise ValueError("The source artifact belongs to another original application/context/Compose/file selection.")
            inputs = json.loads(original_config.get("backup_inputs_json") or "[]")
            original_inputs = native_target.get("backup_inputs") or []
            normalized = lambda entries: sorted(
                [{"path": row["path"], "role": row["role"], "kind": row.get("kind", "file"),
                  "sha256": row["sha256"]} for row in entries], key=lambda row: row["path"])
            if normalized(inputs) != normalized(original_inputs):
                raise ValueError("The source artifact carries another original backup input selection.")
            observations = (operation.get("native_result") or {}).get("observations") or {}
            phase = native_target.get("capture_phase")
            actual_inventory = observations.get("before_inventory" if phase == "before" else "native_inventory") or {}
            expected_head = actual_inventory.get("head_commit")
            if phase in {"before", "capture"} and original_config.get("source_revision") and original_config["source_revision"] != expected_head:
                raise ValueError("The original pre-task source differs from its reviewed source revision.")
            if not expected_head or manifest.get("source_revision") != expected_head or native_target.get("source_revision") != expected_head:
                raise ValueError("The source package differs from the selected or actually observed original commit.")
            images = native_target.get("image_ids")
            if not isinstance(images, list) or any(not isinstance(value, str) for value in images) or len(images) != len(set(images)):
                raise ValueError("The complete source package must retain its actual unique native image identities.")
            original_source = observations.get("before_source" if phase == "before" else "source") or {}
            if original_source.get("target") != native_target:
                raise ValueError("The native source manifest differs from its complete original operation source selection.")
            if original_source.get("source_revision") != manifest.get("source_revision"):
                raise ValueError("The native package revision differs from its retained original source result.")
            if native_target.get("capture_phase") not in {"capture", "before", "after"}:
                raise ValueError("The source package has no explicit original capture phase.")
            received = castor_source.receive_source(archive, slot / "members", maximum)
            host = directory(slot / "host", True)
            bindings = dict(selection.get("runtime_bindings") or {})
            if set(bindings) - castor_adapter.RUNTIME_FIELDS:
                raise ValueError("Only original declared native host paths may be supplied during source receiving.")
            if "site_root" in bindings and Path(bindings["site_root"]).resolve() != host:
                raise ValueError("The source reopening host directory is this original private handover slot.")
            bindings["site_root"] = str(host)
            # This read-only source receiver has no application checkout yet.
            # Native task profile validation applies after the full checkout exists.
            # The helper invokes only this receiving Session's original Git executable.
            source_profile = {**original_config, **bindings}
            source_profile["git_path"] = _binary(source_profile.get("git_path") or "git")
            source_profile.setdefault("timeout_seconds", 900)
            source_profile.setdefault("max_artifact_bytes", 2147483648)
            session = Session(source_profile, slot / "native-reopen")
            saved = session.out / "native-state.json"
            if saved.exists():
                session.state = session.read_private_json(saved)
            source_receipt = (self.continuation.get("source_commands") or {}).get(str(index))
            if source_receipt:
                castor_source.receive_command_receipt(session, source_receipt)
            reopened = castor_source.reopen_source(session, slot / "members", slot / "checkout")
            receipt = {"step": selection["step"], "operation_id": operation["id"],
                       "file_name": selection["file_name"], "archive": actual,
                       "received": received, "reopened": reopened,
                       "native_output": str(session.out)}
            handover.setdefault("source_exports", {})[str(index)] = receipt
            save(state_path, handover)
        return handover["source_exports"]

    def handover(self, selected):
        with lease(self.root, "receiving.lock"):
            self.reload()
            if self.state["phase"] != "complete":
                raise ValueError("Complete the selected original native course before the full receiving handover.")
            target = Path(selected["destination"]).expanduser()
            if not target.is_absolute() or target.is_symlink():
                raise ValueError("Use the original absolute private receiving directory.")
            target = target.resolve(strict=False)
            for original in (self.root, self.workspace.root, Path(self.args.source_root)):
                original = original.resolve()
                if target == original or target.is_relative_to(original) or original.is_relative_to(target):
                    raise ValueError("Keep full receiving separate from the original input and project directories.")
            target.mkdir(mode=0o700, parents=True, exist_ok=True)
            path = self.root / "handover.json"
            handover = read_json(path) if path.exists() else {
                "schema": SCHEMA, "binding": digest(selected), "phase": "prepared", "destination": str(target)}
            if handover["binding"] != digest(selected):
                raise ValueError("Continue the same original whole handover selection.")
            if "operation_cohort" not in handover:
                # Freeze the complete original course before any backup or source
                # receiving. Later source revisions never rewrite this handover.
                handover["operation_cohort"] = {
                    step["id"]: self.original_operation(step["id"]) for step in self.steps}
                handover["original_course"] = {"request": self.request, "receiving": self.state}
                handover["cohort_sha256"] = digest(handover["operation_cohort"])
                save(path, handover)
            if digest(handover["operation_cohort"]) != handover["cohort_sha256"]:
                raise ValueError("The retained original handover operation cohort changed.")
            if set(handover["operation_cohort"]) != {step["id"] for step in self.steps}:
                raise ValueError("The retained handover differs from its original course selection.")
            save(path, handover)
            if handover.get("phase") == "complete":
                application = handover["application"]["archive"]
                if identity(application["path"])["sha256"] != application["sha256"]:
                    raise ValueError("The original received application archive changed.")
                if read_json(target / "original-course.json") != handover["original_course"]:
                    raise ValueError("The completed original course changed after receiving.")
                return {"state": "RECEIVED", "workspace": handover["reopened"]["workspace"],
                        "operation_count": len(handover["reopened"]["operations"]),
                        "destination": str(target), "receiver": str(target / "application" /
                        "govhub-operations" / "workspace" / "castor_receive.py"), "result": identity(path)}
            if not handover.get("intake_received"):
                handover["intake_received"] = copy_intake(Path(self.args.source_root), target / "original-inputs", handover, path)
                save(path, handover)
            if not handover.get("application"):
                handover["application"] = receive_application(Path(selected["application_zip"]),
                    selected["application_sha256"], target)
                save(path, handover)
            self.receive_sources(target, selected, handover, path)
            backup = target / "private-workspace"
            if not handover.get("backup"):
                if backup.exists():
                    if (backup / "BACKUP_INCOMPLETE").exists() or not (backup / "backup.json").is_file():
                        prior = target / ("incomplete-private-workspace-" + str(time.time_ns()))
                        os.rename(backup, prior)
                        handover.setdefault("retained_partial_backups", []).append(str(prior))
                        save(path, handover)
                    else:
                        metadata = read_json(backup / "backup.json")
                        if metadata["workspace"] != self.workspace.snapshot().get("workspace"):
                            raise ValueError("The retained backup belongs to another original workspace.")
                        handover["backup"] = {"directory": str(backup), **metadata}
                if not handover.get("backup"):
                    handover["backup"] = self.workspace.dispatch("workspace.backup",
                        {"destination": str(backup)}, self.actor)
                save(path, handover)
            receiver = target / "application" / "govhub-operations" / "workspace" / "castor_receive.py"
            if not receiver.is_file():
                raise ValueError("The complete original application package is missing its Castor receiver.")
            received_args = arguments({**self.request["workspace"], "workspace": str(backup),
                                       "source_root": str(target / "original-inputs")})
            received_workspace, _ = opened(received_args)
            original = received_workspace.snapshot()
            saved_operations = {row["id"]: row for row in original["govhub"]["operations"]}
            for step in self.steps:
                source_operation = handover["operation_cohort"][step["id"]]
                if saved_operations.get(source_operation["id"]) != source_operation:
                    raise ValueError("The coherent private backup does not contain the completed original course.")
            selection_path = target / "original-course.json"
            if not selection_path.exists():
                save(selection_path, handover["original_course"])
            elif read_json(selection_path) != handover["original_course"]:
                raise ValueError("The received original course differs from its completed source.")
            commands = Commands(self.root / "cold-reopen", 600)
            receipt = commands.run("original-project-reopen", [
                sys.executable, str(receiver), "inspect", "--workspace", str(backup),
                "--source-root", str(target / "original-inputs"),
                "--assessment-core", str(receiver.parent / "vendor" / "assessment-core"),
                "--username", self.args.username, "--password-env", self.args.password_env])
            reopened = Commands.json_output(receipt)
            expected = {row["id"]: row for row in original["govhub"]["operations"]}
            actual = {row["id"]: row for row in reopened["operations"]}
            if original.get("workspace") != reopened.get("workspace") or expected != actual:
                raise ValueError("Independent receiving changed the original workspace or native operation population.")
            handover.update(phase="complete", reopened=reopened, cold_command=receipt,
                            receiving_state=handover["original_course"]["receiving"], completed_at=utc())
            save(path, handover)
            return {"state": "RECEIVED", "workspace": reopened["workspace"],
                    "operation_count": len(actual), "destination": str(target),
                    "receiver": str(receiver), "result": identity(path)}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    commands = parser.add_subparsers(dest="command", required=True)
    for name in ("run", "status", "handover"):
        item = commands.add_parser(name)
        item.add_argument("--request", required=True)
        item.add_argument("--continuation")
        if name == "handover":
            item.add_argument("--selection", required=True)
    inspect = commands.add_parser("inspect")
    add_workspace(inspect)
    args = parser.parse_args()
    os.umask(0o077)
    try:
        if args.command == "inspect":
            workspace, actor = opened(args)
            snapshot = workspace.snapshot()
            result = {"workspace": snapshot.get("workspace"),
                "actor": {"name": actor["name"], "role": actor["role"]},
                "operations": snapshot["govhub"]["operations"],
                "summary": snapshot["govhub"]["summary"]}
        else:
            receiving = Receiving(args.request, args.continuation)
            if args.command == "run":
                result = receiving.run()
            elif args.command == "status":
                result = receiving.status()
            else:
                selection, _ = request_payload(args.selection)
                result = receiving.handover(selection)
        print(json.dumps(result, ensure_ascii=False, allow_nan=False), flush=True)
        return 2 if result.get("state") == "attention" else 0
    except Exception as exc:
        print(json.dumps({"ok": False, "type": type(exc).__name__, "message": str(exc)}), file=sys.stderr)
        return 1


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
# SPDX-License-Identifier: Apache-2.0
"""Complete native Castor source capture and independent private receiving.

Native task execution remains owned by castor_adapter and the original Session.
This module retains selected native source, deployment images and backup outputs.
"""
from __future__ import annotations

import argparse
from datetime import datetime, timezone
import hashlib
import json
import os
from pathlib import Path, PurePosixPath
import re
import shutil
import stat
import subprocess
import sys
import tarfile
import tempfile
import zipfile

SCHEMA = "govhub-castor-source/v1"
CHUNK = 1024 * 1024


def _now():
    return datetime.now(timezone.utc).isoformat().replace("+00:00", "Z")


def _bytes(value):
    return (json.dumps(value, ensure_ascii=False, sort_keys=True, indent=2) + "\n").encode("utf-8")


def _digest(value):
    return hashlib.sha256(value).hexdigest()


def _atomic(path, value):
    path = Path(path)
    path.parent.mkdir(mode=0o700, parents=True, exist_ok=True)
    if path.is_symlink():
        raise ValueError("A native source journal cannot be a link.")
    fd, name = tempfile.mkstemp(prefix=path.name + ".part-", dir=path.parent)
    try:
        with os.fdopen(fd, "wb") as stream:
            os.fchmod(stream.fileno(), 0o600)
            stream.write(_bytes(value))
            stream.flush()
            os.fsync(stream.fileno())
        os.replace(name, path)
    finally:
        if os.path.exists(name):
            os.unlink(name)


def _file(path):
    path = Path(path)
    if path.is_symlink() or not path.is_file():
        raise ValueError("The original ordinary source file is unavailable: " + str(path))
    a = path.stat()
    digest = hashlib.sha256()
    size = 0
    with path.open("rb") as stream:
        for data in iter(lambda: stream.read(CHUNK), b""):
            digest.update(data)
            size += len(data)
    b = path.stat()
    if (a.st_dev, a.st_ino, a.st_size, a.st_mtime_ns) != (
            b.st_dev, b.st_ino, b.st_size, b.st_mtime_ns) or size != a.st_size:
        raise ValueError("A native source file changed while it was being retained.")
    return {"bytes": size, "sha256": digest.hexdigest()}


def _relative(value):
    if (not isinstance(value, str) or not value or "\\" in value or "\0" in value
            or value.startswith("/") or any(x in ("", ".", "..") for x in value.split("/"))):
        raise ValueError("Use an ordinary package-relative native path.")
    value.encode("utf-8", errors="strict")
    return value


def _selector(value, name):
    if (not isinstance(value, str) or not value or "\0" in value or "\n" in value
            or value.startswith("-")):
        raise ValueError("Select the actual native " + name + ".")
    return value


def _executable(value):
    value = _selector(value, "executable")
    selected = shutil.which(value)
    if not selected or not os.access(selected, os.X_OK):
        raise ValueError("The selected original native executable is unavailable: " + value)
    return str(Path(selected).resolve())


def _load(path):
    return json.loads(Path(path).read_bytes().decode("utf-8"))


def _stable_file(path, content):
    path = Path(path)
    if path.exists():
        if path.read_bytes() != content:
            raise ValueError("The retained original source input differs: " + str(path))
    else:
        path.parent.mkdir(mode=0o700, parents=True, exist_ok=True)
        with path.open("xb") as stream:
            os.chmod(path, 0o600)
            stream.write(content)
            stream.flush()
            os.fsync(stream.fileno())


def _tar_files(path, base, names):
    """Capture exact selected worktree nodes; links remain links, never followed."""
    path, base = Path(path), Path(base)
    staging = path.with_suffix(path.suffix + ".partial")
    if staging.exists():
        staging.unlink()
    entries = []
    with tarfile.open(staging, "w", format=tarfile.PAX_FORMAT, dereference=False) as archive:
        for name in sorted(set(names)):
            _relative(name)
            node = base / name
            if not node.exists() and not node.is_symlink():
                entries.append({"path": name, "kind": "deleted"})
                continue
            info = archive.gettarinfo(str(node), arcname=name)
            if not (info.isfile() or info.isdir() or info.issym()):
                raise ValueError("A selected source node needs explicit native handling: " + name)
            row = {"path": name, "mode": info.mode, "kind": "symlink" if info.issym()
                   else "directory" if info.isdir() else "file"}
            if info.issym():
                row["link_target"] = info.linkname
                archive.addfile(info)
            elif info.isfile():
                before = _file(node)
                if info.size != before["bytes"]:
                    raise ValueError("A native file changed before its archive read: " + name)
                with node.open("rb") as stream:
                    archive.addfile(info, stream)
                if _file(node) != before:
                    raise ValueError("The native source changed during its capture: " + name)
                row.update(before)
            else:
                archive.addfile(info)
            entries.append(row)
    os.chmod(staging, 0o600)
    os.replace(staging, path)
    return entries


def _tree_names(root):
    names = []
    for parent, directories, files in os.walk(root, followlinks=False):
        for name in list(directories):
            path = Path(parent) / name
            names.append(path.relative_to(root).as_posix())
            if path.is_symlink():
                directories.remove(name)
        names.extend((Path(parent) / name).relative_to(root).as_posix() for name in files)
    return names



def _canonical(value):
    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"))


def _array(profile, key):
    value = profile.get(key, "[]")
    value = json.loads(value) if isinstance(value, str) else value
    if not isinstance(value, list) or len(value) > 10000:
        raise ValueError(key + " must be the complete bounded native selection array.")
    return value


def _under(root, relative, required=True):
    relative = _relative(relative)
    current = Path(root)
    for component in relative.split("/"):
        current = current / component
        if current.is_symlink():
            raise ValueError("Explicit selected files cannot traverse a link: " + relative)
    if required and not current.exists():
        raise ValueError("The selected native source is unavailable: " + relative)
    return current


def _rows(raw):
    try:
        value = json.loads(raw or b"[]")
        value = [value] if isinstance(value, dict) else value
    except ValueError:
        value = [json.loads(line) for line in raw.splitlines() if line.strip()]
    if not isinstance(value, list) or any(not isinstance(row, dict) for row in value):
        raise ValueError("The native census is not a complete JSON object array.")
    return value


def _directory_identity(path):
    members = []
    for member in sorted(path.rglob("*")):
        if member.is_symlink():
            raise ValueError("A selected backup/output directory contains a link.")
        if member.is_file():
            members.append({"path": member.relative_to(path).as_posix(), **_file(member)})
        elif not member.is_dir():
            raise ValueError("A selected backup/output contains a special filesystem node.")
    return {"members": members, "sha256": _digest(_canonical(members).encode("utf-8"))}


def _selected_identity(root, row, allow_missing=False):
    path = _under(root, row["path"], required=not allow_missing)
    if not path.exists():
        return {**row, "present": False}
    if row["kind"] == "file":
        if not path.is_file():
            raise ValueError("The selected original file is no longer a file.")
        identity = _file(path)
    elif row["kind"] == "directory":
        if not path.is_dir():
            raise ValueError("The selected original directory is no longer a directory.")
        identity = _directory_identity(path)
    else:
        raise ValueError("Declare each actual selected file/directory kind.")
    if row.get("sha256") and row["sha256"] != identity["sha256"]:
        raise ValueError("The selected original recovery input differs from its reviewed hash.")
    return {**row, **identity, "present": True}


def _current_tree(root, git, run, label, depth=0):
    """Match the provider's actual complete index/worktree fingerprint."""
    if depth > 30:
        raise ValueError("Native submodule nesting exceeds the source intake limit.")
    prefix = [git, "-C", str(root)]
    tracked = run(label + "-index", prefix + ["ls-files", "--stage", "-z"])
    other = run(label + "-untracked", prefix + ["ls-files", "--others", "--exclude-standard", "-z"])
    entries = {}
    for row in tracked.split(b"\0"):
        if not row:
            continue
        metadata, raw_path = row.split(b"\t", 1)
        mode, blob, stage = metadata.decode("ascii").split()
        relative = _relative(raw_path.decode("utf-8", "strict"))
        if stage != "0":
            raise ValueError("Resolve original native Git index conflicts before source capture.")
        entries[relative] = {"path": relative, "git_mode": mode, "git_blob": blob}
    for raw_path in other.split(b"\0"):
        if raw_path:
            relative = _relative(raw_path.decode("utf-8", "strict"))
            entries[relative] = {"path": relative, "git_mode": None, "git_blob": None}
    result = []
    for relative, entry in sorted(entries.items()):
        path = root / relative
        if path.is_symlink():
            entry.update(kind="symlink", target=os.readlink(path))
        elif not path.exists():
            entry["kind"] = "absent"
        elif entry["git_mode"] == "160000":
            if not path.is_dir():
                raise ValueError("The selected original submodule is unavailable.")
            tag = label + "-sub-" + _digest(relative.encode())[:20]
            nested = _current_tree(path, git, run, tag, depth + 1)
            head = run(tag + "-head", [git, "-C", str(path), "rev-parse", "HEAD"]).decode().strip()
            entry.update(kind="submodule", head_commit=head, source=nested)
        elif path.is_file():
            entry.update(kind="file", mode=path.stat().st_mode & 0o777, **_file(path))
        else:
            raise ValueError("An original Git-selected member is not an ordinary file.")
        result.append(entry)
    return {"members": result, "sha256": _digest(_canonical(result).encode("utf-8"))}


def _copy_original(source, destination, expected=None):
    source, destination = Path(source), Path(destination)
    identity = _file(source)
    if expected is not None and identity != expected:
        raise ValueError("The actual selected source changed before copying.")
    if destination.exists():
        if _file(destination) != identity:
            raise ValueError("The retained original copied source differs.")
        return identity
    temporary = destination.with_name(destination.name + ".partial")
    destination.parent.mkdir(mode=0o700, parents=True, exist_ok=True)
    with source.open("rb") as incoming, temporary.open("wb") as output:
        os.chmod(temporary, 0o600)
        shutil.copyfileobj(incoming, output, CHUNK)
        output.flush()
        os.fsync(output.fileno())
    if _file(source) != identity or _file(temporary) != identity:
        raise ValueError("Native source changed or was truncated while copied.")
    os.replace(temporary, destination)
    return identity



def _native_command(s, label, argv, mutating=False):
    """Keep helper commands on the original Session's receipt-recovery path."""
    from native_adapter import NativeWaiting
    path = s.out / (label + ".command.json")
    previous = s.read_private_json(path) if path.exists() else None
    if previous and previous.get("phase") == "complete":
        # The phase selection/destination is already bound by the helper journal.
        # A moved runtime reopens the exact completed original command.
        argv = previous["argv"]
    try:
        result = s.command(label, argv, mutating=mutating)
    except NativeWaiting:
        if path.exists():
            record = s.read_private_json(path)
            if record.get("phase") not in {"complete", "not_started"}:
                s.state.update(phase="native_interrupted", pending_command=label,
                               command_record=str(path))
                s.save_state()
        raise
    if s.state.get("pending_command") == label:
        s.state["pending_command"] = None
        s.save_state()
    return result


def capture_source(session, provider_inventory, selection):
    """Retain one complete source phase without dispatching any native task."""
    s, p = session, selection
    root = Path(s.private_path(p["site_root"])).resolve(strict=True)
    revision = p.get("source_revision", "")
    if not re.fullmatch(r"[0-9a-f]{40}|[0-9a-f]{64}", revision):
        raise ValueError("Select the actual complete original Git revision.")
    phase = p.get("capture_phase", "capture")
    if phase not in {"capture", "before", "after"}:
        raise ValueError("Select the original capture, before or after phase.")
    allow_missing = p.get("allow_missing_task_outputs", False)
    if type(allow_missing) is not bool or (allow_missing and phase != "before"):
        raise ValueError("Only a before-task capture may retain not-yet-created outputs.")
    compose_files = [_relative(value) for value in _array(p, "compose_files_json")]
    release_files = [_relative(value) for value in _array(p, "release_files_json")]
    if not compose_files or len(set(compose_files)) != len(compose_files) or len(set(release_files)) != len(release_files):
        raise ValueError("Retain the original unique ordered Compose/release selection.")
    outputs = _array(p, "task_outputs_json")
    inputs = [{**row, "kind": row.get("kind", "file")} for row in _array(p, "backup_inputs_json")]
    for rows in (outputs, inputs):
        if len({row["path"] for row in rows}) != len(rows):
            raise ValueError("Select each original task input/output once.")
        for row in rows:
            _relative(row["path"])
            _selector(row["role"], "file role")
            if row["kind"] not in {"file", "directory"}:
                raise ValueError("Declare each selected native file or directory.")
    image_selection = _array(p, "source_images_json")
    for selected in image_selection:
        if not isinstance(selected, str) or not re.fullmatch(
                r"(?:sha256:[a-f0-9]{64}|[^\s]+@sha256:[a-f0-9]{64})", selected):
            raise ValueError("Explicit image selection requires an immutable full ID or repository digest.")
    requested = {"environment_id": _selector(p["environment_id"], "deployment identity"),
        "source_revision": revision, "capture_phase": phase,
        "castor_file": p.get("castor_file") or "", "castor_context": p.get("castor_context") or "",
        "docker_context": _selector(p["docker_context"], "Docker context"),
        "compose_project": _selector(p["compose_project"], "Compose project"),
        "compose_files": compose_files, "release_files": release_files,
        "task_outputs": outputs, "backup_inputs": inputs, "image_selection": image_selection}
    if requested["castor_file"]:
        _relative(requested["castor_file"])
    key = _digest(_bytes(requested))[:24]
    directory = s.out / ("castor-source-" + key)
    directory.mkdir(mode=0o700, parents=True, exist_ok=True)
    if root == directory or root in directory.parents:
        raise ValueError("Keep the original capture outside the native Git/source tree.")
    state_path = directory / "capture.json"
    if state_path.exists():
        state = s.read_private_json(state_path)
        if state.get("selection") != requested:
            raise ValueError("Continue the exact original source phase and target selection.")
    else:
        state = {"schema": SCHEMA, "selection": requested, "state": "RUNNING",
                 "started_at": _now(), "commands": {}, "parts": {}, "attempt": 0}
        _atomic(state_path, state)

    def save():
        state["updated_at"] = _now()
        _atomic(state_path, state)
        s.state.setdefault("castor_source", {})[key] = {
            "state": state["state"], "directory": str(directory), "selection": requested}
        s.save_state()

    def publish(result):
        s.add(directory / "castor-source.zip", "castor_complete_source",
              source_revision=revision, capture_phase=phase)
        s.add(directory / "MANIFEST.json", "castor_source_manifest",
              source_revision=revision, capture_phase=phase)
        # Complete command stdout/stderr/receipts are also members of the ZIP.
        # Explicit artifact admission keeps them visible in the native handover.
        for path in sorted((directory / "commands").glob("*")):
            if path.is_file():
                s.add(path, "castor_source_command", capture_phase=phase)
        return {**result, "archive": str(directory / "castor-source.zip"),
                "manifest": str(directory / "MANIFEST.json")}

    if state["state"] == "COMPLETE":
        for name, identity in state["published"].items():
            if _file(directory / name) != identity:
                raise ValueError("A complete original Castor source artifact changed.")
        return publish(state["result"])

    state["attempt"] += 1
    attempt = state["attempt"]
    save()
    inventory_path = directory / "provider-inventory.json"
    if not inventory_path.exists():
        _atomic(inventory_path, provider_inventory)
    inventory = _load(inventory_path)
    if inventory.get("head_commit") != revision:
        raise ValueError("The source selection differs from the retained native inventory head.")
    expected_project = {key: requested[key] for key in (
        "environment_id", "castor_file", "castor_context", "docker_context", "compose_project")}
    if any(inventory.get("project", {}).get(k) != v for k, v in expected_project.items()):
        raise ValueError("The native inventory describes a different selected Castor project.")
    tools = {name: _executable(p.get(name + "_path") or name) for name in ("git", "docker")}

    def run(name, argv):
        record = _native_command(s, "castor-source-" + key + "-" + name, argv)
        stored = directory / "commands"
        stored.mkdir(mode=0o700, exist_ok=True)
        paths = {}
        for field in ("stdout", "stderr"):
            original = Path(s.private_path(record[field]["path"]))
            destination = stored / (name + "." + field)
            _copy_original(original, destination)
            paths[field] = destination.relative_to(directory).as_posix()
        command_path = stored / (name + ".json")
        if command_path.exists():
            if s.resolve_private(_load(command_path)) != record:
                raise ValueError("The original native command outcome changed after relocation.")
        else:
            _stable_file(command_path, _bytes(record))
        state["commands"][name] = {"argv": argv, "record": command_path.relative_to(directory).as_posix(), **paths}
        save()
        return (directory / paths["stdout"]).read_bytes()

    def git(name, where, args):
        return run(name, [tools["git"], "-C", str(where), *args])

    def docker(name, args):
        return run(name, [tools["docker"], "--context", requested["docker_context"], *args])

    def fresh(name, argv):
        return run("observe-" + str(attempt) + "-" + name, argv)

    compose = [tools["docker"], "--context", requested["docker_context"], "compose",
               "--project-directory", str(root), "--project-name", requested["compose_project"]]
    for name in compose_files:
        compose += ["--file", str(_under(root, name))]

    def observe_images(label):
        rows = _rows(fresh(label, compose + ["images", "--format", "json"]))
        return rows

    def inspect_image(label, selected):
        raw = docker(label, ["image", "inspect", selected])
        rows = _rows(raw)
        if len(rows) != 1 or not re.fullmatch(r"sha256:[a-f0-9]{64}", str(rows[0].get("Id", ""))):
            raise ValueError("Native image inspection did not resolve one complete immutable image ID.")
        image = rows[0]
        if "@sha256:" in selected and selected not in (image.get("RepoDigests") or []):
            raise ValueError("Native image inspection did not preserve the selected repository digest.")
        if selected.startswith("sha256:") and len(selected) == 71 and selected != image["Id"]:
            raise ValueError("Native image inspection changed the selected full image ID.")
        return image

    try:
        observed_tree = _current_tree(root, tools["git"], fresh, "worktree-before")
        if observed_tree != inventory.get("working_tree"):
            raise ValueError("The native Git/index/worktree differs from the reviewed complete inventory.")
        current_head = fresh("head-before", [tools["git"], "-C", str(root), "rev-parse", "HEAD"]).decode().strip()
        if current_head != revision:
            raise ValueError("The selected native Git HEAD changed before capture.")
        engine = json.loads(fresh("engine-before", [tools["docker"], "--context", requested["docker_context"],
            "info", "--format", "{{json .}}"]))
        if engine.get("ID") != inventory.get("docker_engine", {}).get("ID"):
            raise ValueError("The original selected Docker engine changed.")
        observed_images = observe_images("compose-images-before")
        if sorted(map(_canonical, observed_images)) != sorted(map(_canonical, inventory.get("images", []))):
            raise ValueError("The native Compose image cohort changed since the original inventory.")
        compose_config = json.loads(fresh("compose-config-before", compose + ["config", "--format", "json"]))
        if compose_config != inventory.get("compose_config"):
            raise ValueError("The selected Compose configuration differs from the original inventory.")
        image_rows = []
        candidates = [(value, None) for value in image_selection]
        if not candidates:
            for row in inventory.get("images", []):
                value = row.get("ID") or row.get("Id") or row.get("id")
                if not isinstance(value, str) or not re.fullmatch(r"(?:sha256:)?[a-f0-9]{12,64}", value):
                    raise ValueError("Native Compose must supply an actual image ID for exact resolution.")
                candidates.append((value, row))
        for index, (selected, original_row) in enumerate(candidates):
            image = inspect_image("image-" + str(index) + "-inspect", selected)
            image_rows.append({"selected": selected, "original_compose_row": original_row,
                "image_id": image["Id"], "repo_digests": image.get("RepoDigests") or [],
                "repo_tags": image.get("RepoTags") or [], "inspection": image})
        image_ids = sorted({row["image_id"] for row in image_rows})
        target = {**requested, "image_ids": image_ids}
        if state.get("target") is not None and state["target"] != target:
            raise ValueError("The retained original image/source target changed.")
        state["target"] = target
        state["parts"]["images"] = {"selection": image_selection, "original_compose_rows": inventory.get("images", []),
            "resolved": image_rows, "image_ids": image_ids, "docker_engine_id": engine["ID"]}
        save()
        repos = state.get("repositories")
        if repos is None:
            repos = [{"path": "", "parent": None, "gitlink": None}]
            state["repositories"] = repos
            save()
        index = 0
        while index < len(repos):
            s.check()
            repository = repos[index]
            where = root / repository["path"]
            tag = "git-" + str(index)
            repo_dir = directory / "repositories" / str(index)
            repo_dir.mkdir(mode=0o700, parents=True, exist_ok=True)
            actual_root = git(tag + "-root", where, ["rev-parse", "--show-toplevel"]).decode().strip()
            if Path(actual_root).resolve() != where.resolve():
                raise ValueError("A native submodule is uninitialized or the selected Git root differs.")
            head = git(tag + "-head", where, ["rev-parse", "--verify", "HEAD"]).decode().strip()
            if index == 0 and head != revision:
                raise ValueError("Local Git HEAD differs from the reviewed Castor revision.")
            # Preserve actual submodule HEAD independently from the parent index gitlink.
            repository["head"] = head
            listing = git(tag + "-index", where, ["ls-files", "--stage", "-z"])
            selected_files, gitlinks = [], []
            for row in listing.split(b"\0"):
                if not row:
                    continue
                metadata, raw_name = row.split(b"\t", 1)
                mode, object_id, stage = metadata.decode("ascii").split()
                name = _relative(os.fsdecode(raw_name))
                if stage != "0":
                    raise ValueError("Resolve native Git index conflicts before source capture.")
                if mode == "160000":
                    gitlinks.append((name, object_id))
                else:
                    selected_files.append(name)
            # Include HEAD files removed from the current index, so staged
            # deletions also remove their original working copy on reopening.
            head_tree = git(tag + "-head-tree", where, ["ls-tree", "-r", "-z", "--full-tree", head])
            for row in head_tree.split(b"\0"):
                if not row:
                    continue
                metadata, raw_name = row.split(b"\t", 1)
                mode, object_type, object_id = metadata.decode("ascii").split()
                if object_type == "blob":
                    selected_files.append(_relative(os.fsdecode(raw_name)))
            untracked = git(tag + "-untracked", where, ["ls-files", "--others", "--exclude-standard", "-z"])
            selected_files += [os.fsdecode(x) for x in untracked.split(b"\0") if x]
            git(tag + "-ignored", where, ["ls-files", "--others", "--ignored", "--exclude-standard", "-z"])
            staged = git(tag + "-staged", where, ["diff", "--cached", "--binary", "--full-index", "--no-ext-diff"])
            unstaged = git(tag + "-unstaged", where, ["diff", "--binary", "--full-index", "--no-ext-diff"])
            git(tag + "-status", where, ["status", "--porcelain=v1", "-z", "--untracked-files=all"])
            for filename, content in (("staged.patch", staged), ("unstaged.patch", unstaged)):
                _stable_file(repo_dir / filename, content)
            bundle = repo_dir / "repository.bundle"
            git(tag + "-bundle", where, ["bundle", "create", str(bundle), "--all", "HEAD"])
            git(tag + "-verify", where, ["bundle", "verify", str(bundle)])
            git(tag + "-archive", where, ["archive", "--format=tar", "--output", str(repo_dir / "tracked.tar"), head])
            git(tag + "-refs", where, ["show-ref", "--head"])
            entries_path = repo_dir / "worktree.json"
            if entries_path.exists():
                entries = _load(entries_path)
            else:
                entries = _tar_files(repo_dir / "worktree.tar", where, selected_files)
                _atomic(entries_path, entries)
            # Compare native working patches again after the complete byte capture.
            if git(tag + "-staged-after", where, ["diff", "--cached", "--binary", "--full-index", "--no-ext-diff"]) != staged:
                raise ValueError("Native staged changes changed during source capture.")
            if git(tag + "-unstaged-after", where, ["diff", "--binary", "--full-index", "--no-ext-diff"]) != unstaged:
                raise ValueError("Native worktree changed during source capture.")
            if git(tag + "-head-after", where, ["rev-parse", "--verify", "HEAD"]).decode().strip() != head:
                raise ValueError("Native Git HEAD changed during its complete source capture.")
            if git(tag + "-index-after", where, ["ls-files", "--stage", "-z"]) != listing:
                raise ValueError("Native Git index changed during its complete source capture.")
            repository["directory"] = repo_dir.relative_to(directory).as_posix()
            repository["worktree_entries"] = len(entries)
            for name, oid in gitlinks:
                relative = (PurePosixPath(repository["path"]) / name).as_posix()
                if not any(row["path"] == relative for row in repos):
                    repos.append({"path": relative, "parent": index, "gitlink": oid})
            save()
            index += 1


        # Explicit selections retain ignored release/backup bytes as well as the
        # Git-selected tree. No host credentials/cache are copied implicitly.
        selected_rows = [{"path": value, "role": "compose", "kind": "file"} for value in compose_files]
        selected_rows += [{"path": value, "role": "release", "kind": "file"} for value in release_files]
        if requested["castor_file"]:
            selected_rows.append({"path": requested["castor_file"], "role": "castor_entrypoint", "kind": "file"})
        selected_rows += [{**row, "selection": "task_output"} for row in outputs]
        selected_rows += [{**row, "selection": "backup_input"} for row in inputs]
        original_rows, selected_names = [], []
        for row in selected_rows:
            observed = _selected_identity(root, row,
                allow_missing=allow_missing and row.get("selection") == "task_output")
            expected = inventory.get("selected_files", {}).get(row["path"])
            if expected and observed.get("present") and {k: observed[k] for k in ("bytes", "sha256")} != expected:
                raise ValueError("The selected native release/configuration source changed.")
            original_rows.append(observed)
            if observed["present"]:
                selected_names.append(row["path"])
                if row["kind"] == "directory":
                    selected_names += [(PurePosixPath(row["path"]) / name).as_posix()
                                       for name in _tree_names(root / row["path"])]
        _stable_file(directory / "selected-selection.json", _bytes(original_rows))
        selected_archive = directory / "selected-files.tar"
        selected_manifest = directory / "selected-files.json"
        if selected_manifest.exists():
            selected_entries = _load(selected_manifest)
        else:
            selected_entries = _tar_files(selected_archive, root, selected_names)
            _atomic(selected_manifest, selected_entries)
        for row in original_rows:
            current = _selected_identity(root, row,
                allow_missing=allow_missing and row.get("selection") == "task_output")
            if current != row:
                raise ValueError("An original selected native output/input changed across its capture.")
        for entry in selected_entries:
            path = root / entry["path"]
            if entry["kind"] == "file" and _file(path) != {k: entry[k] for k in ("bytes", "sha256")}:
                raise ValueError("The retained selected source archive differs from current original bytes.")
            if entry["kind"] == "directory" and not path.is_dir():
                raise ValueError("The retained selected source directory changed.")
        state["parts"]["selected_files"] = {"archive": selected_archive.name,
            "entries": selected_manifest.name, "selection": original_rows, **_file(selected_archive)}

        executable = Path(p["castor_path"]).resolve(strict=True)
        executable_identity = _file(executable)
        if executable_identity != inventory.get("native_executables", {}).get("castor_path"):
            raise ValueError("The selected original Castor/PHAR executable changed.")
        executable_copy = directory / "executables" / executable.name
        _copy_original(executable, executable_copy, executable_identity)
        state["parts"]["castor_executable"] = {"original_path": str(executable),
            "path": executable_copy.relative_to(directory).as_posix(), "mode": executable.stat().st_mode & 0o777,
            **executable_identity}
        image_archive = directory / "docker-images.tar"
        if image_ids:
            docker("image-save", ["image", "save", "--output", str(image_archive), *image_ids])
            if not image_archive.is_file() or not image_archive.stat().st_size:
                raise ValueError("Native Docker did not retain the complete selected image archive.")
            state["parts"]["images"].update(archive=image_archive.name, **_file(image_archive))
            # A complete native tar stream is parsed without extracting or loading it.
            with tarfile.open(image_archive, "r:") as native_archive:
                if not native_archive.getmembers():
                    raise ValueError("Native Docker returned an empty image archive.")
        else:
            state["parts"]["images"]["archive"] = None
        for index, row in enumerate(image_rows):
            after = inspect_image("image-" + str(index) + "-after", row["image_id"])
            if after["Id"] != row["image_id"]:
                raise ValueError("The retained native image identity changed during save.")
        if sorted(map(_canonical, observe_images("compose-images-after"))) != sorted(map(_canonical, observed_images)):
            raise ValueError("The selected native Compose image cohort changed during capture.")
        engine_after = json.loads(fresh("engine-after", [tools["docker"], "--context", requested["docker_context"],
            "info", "--format", "{{json .}}"]))
        if engine_after.get("ID") != engine["ID"]:
            raise ValueError("The selected native Docker engine changed during capture.")
        final_tree = _current_tree(root, tools["git"], fresh, "worktree-after")
        if final_tree != observed_tree:
            raise ValueError("The actual Git/index/untracked bytes changed during full source capture.")
        if fresh("head-after", [tools["git"], "-C", str(root), "rev-parse", "HEAD"]).decode().strip() != revision:
            raise ValueError("The selected original Git head changed during capture.")
        # Recheck every ordinary archived file against its retained bytes, including
        # untracked files whose content is not represented in a native Git diff.
        for repository in repos:
            where = root / repository["path"]
            repo_data = directory / repository["directory"]
            for entry in _load(repo_data / "worktree.json"):
                path = where / entry["path"]
                if entry["kind"] == "file" and _file(path) != {k: entry[k] for k in ("bytes", "sha256")}:
                    raise ValueError("A retained original worktree file changed.")
                if entry["kind"] == "symlink" and (not path.is_symlink() or os.readlink(path) != entry["link_target"]):
                    raise ValueError("A retained original worktree link changed.")
                if entry["kind"] == "deleted" and (path.exists() or path.is_symlink()):
                    raise ValueError("A retained source deletion changed.")
        state["state"] = "PACKAGING"
        save()
        members = []
        for path in sorted(directory.rglob("*")):
            if not path.is_file() or path.is_symlink():
                continue
            relative = path.relative_to(directory).as_posix()
            if relative in {"capture.json", "MANIFEST.json", "castor-source.zip"} or relative.endswith(".partial"):
                continue
            members.append({"path": relative, "mode": path.stat().st_mode & 0o777, **_file(path)})
        total = sum(row["bytes"] for row in members)
        if total > p["max_artifact_bytes"]:
            raise ValueError("Complete native source exceeds the original configured archive intake limit.")
        manifest = {"schema": SCHEMA, "target": target, "source_revision": revision,
            "started_at": state["started_at"], "completed_at": _now(),
            "capture_consistency": "selected_native_files_and_image_save; application_consistency_depends_on_original_task_verification",
            "repositories": repos, "parts": state["parts"], "commands": state["commands"],
            "working_tree": observed_tree, "native_inventory": "provider-inventory.json",
            "ignored_source_policy": "Ignored files are listed; only explicit selected release, backup and task-output paths are copied.",
            "members": members, "member_bytes": total}
        _atomic(directory / "MANIFEST.json", manifest)
        archive_path = directory / "castor-source.zip"
        temporary = directory / "castor-source.zip.partial"
        with zipfile.ZipFile(temporary, "w", compression=zipfile.ZIP_STORED, allowZip64=True) as archive:
            archive.write(directory / "MANIFEST.json", "MANIFEST.json")
            for member in members:
                archive.write(directory / member["path"], member["path"])
        verify_source(temporary, p["max_artifact_bytes"])
        if temporary.stat().st_size > p["max_artifact_bytes"]:
            raise ValueError("The complete archive including manifest/ZIP headers exceeds its selected bound.")
        os.chmod(temporary, 0o600)
        os.replace(temporary, archive_path)
        result = {"schema": SCHEMA, "state": "COMPLETE", "source_revision": revision,
            "target": target, "capture_consistency": manifest["capture_consistency"],
            "repositories": repos, "parts": state["parts"], "files": members,
            "archive": str(archive_path), "manifest": str(directory / "MANIFEST.json"),
            "archive_identity": _file(archive_path)}
        state["result"] = result
        state["published"] = {name: _file(directory / name) for name in ("castor-source.zip", "MANIFEST.json")}
        state["state"] = "COMPLETE"
        save()
        return publish(result)
    except BaseException as error:
        state["state"] = "ATTENTION"
        state["error"] = {"type": type(error).__name__, "message": str(error), "at": _now()}
        save()
        raise


def verify_source(archive_path, max_bytes=8 * 1024**3):
    """Verify every complete package member without extracting any filesystem node."""
    if _file(archive_path)["bytes"] > max_bytes:
        raise ValueError("The complete original source archive exceeds the receiving bound.")
    with zipfile.ZipFile(archive_path) as archive:
        infos = archive.infolist()
        names = [info.filename for info in infos]
        if len(names) != len(set(names)) or "MANIFEST.json" not in names:
            raise ValueError("The complete original source archive has duplicate or missing members.")
        if sum(info.file_size for info in infos) > max_bytes + 16 * CHUNK:
            raise ValueError("The complete native package exceeds the selected receiving limit.")
        manifest_info = archive.getinfo("MANIFEST.json")
        if manifest_info.file_size > 16 * CHUNK:
            raise ValueError("The original native source manifest exceeds its receiving limit.")
        manifest = json.loads(archive.read("MANIFEST.json").decode("utf-8"))
        if manifest.get("schema") != SCHEMA or not isinstance(manifest.get("members"), list):
            raise ValueError("Use the original complete Castor source package.")
        expected = {}
        for member in manifest["members"]:
            name = _relative(member["path"])
            if name in expected or name == "MANIFEST.json":
                raise ValueError("The original manifest repeats a source member.")
            expected[name] = member
        if set(names) != set(expected) | {"MANIFEST.json"}:
            raise ValueError("The archive differs from its complete original source manifest.")
        for info in infos:
            _relative(info.filename)
            if info.is_dir() or stat.S_ISLNK(info.external_attr >> 16) or info.flag_bits & 1:
                raise ValueError("The outer source package requires ordinary unencrypted files.")
            if info.filename == "MANIFEST.json":
                continue
            digest = hashlib.sha256()
            size = 0
            with archive.open(info) as stream:
                for data in iter(lambda: stream.read(CHUNK), b""):
                    digest.update(data)
                    size += len(data)
            if {"bytes": size, "sha256": digest.hexdigest()} != {
                    key: expected[info.filename][key] for key in ("bytes", "sha256")}:
                raise ValueError("A complete original source member differs: " + info.filename)
        return manifest


def receive_source(archive_path, destination, max_bytes=8 * 1024**3):
    """Resume private exact-byte receipt; never overwrite another receiving identity."""
    archive_path = Path(archive_path).resolve(strict=True)
    destination = Path(destination).absolute()
    identity = _file(archive_path)
    manifest = verify_source(archive_path, max_bytes)
    if destination.is_symlink() or any(parent.is_symlink() for parent in destination.parents):
        raise ValueError("Use an ordinary original private receiving directory.")
    destination.mkdir(mode=0o700, parents=True, exist_ok=True)
    state_path = destination / "RECEIVING.json"
    if state_path.exists():
        state = _load(state_path)
        if state.get("archive") != identity:
            raise ValueError("Continue the same original complete source package.")
    else:
        if any(destination.iterdir()):
            raise ValueError("Start source receipt in an empty original private directory.")
        state = {"schema": "govhub.castor.source-receiving.v1", "archive": identity,
                 "state": "RECEIVING", "started_at": _now()}
        _atomic(state_path, state)
    with zipfile.ZipFile(archive_path) as archive:
        for name in archive.namelist():
            path = destination / _relative(name)
            path.parent.mkdir(mode=0o700, parents=True, exist_ok=True)
            if any(parent.is_symlink() for parent in path.parents) or path.is_symlink():
                raise ValueError("The native receiving path contains a link.")
            member = next((x for x in manifest["members"] if x["path"] == name), None)
            expected = ({"bytes": len(archive.read(name)), "sha256": _digest(archive.read(name))}
                        if name == "MANIFEST.json" else {k: member[k] for k in ("bytes", "sha256")})
            if path.exists():
                if _file(path) != expected:
                    raise ValueError("A received original source member changed: " + name)
                continue
            temporary = path.with_name(path.name + ".receiving-partial")
            with archive.open(name) as source, temporary.open("wb") as output:
                os.chmod(temporary, 0o600)
                shutil.copyfileobj(source, output, CHUNK)
                output.flush()
                os.fsync(output.fileno())
            if _file(temporary) != expected:
                raise ValueError("Incomplete native receiving member.")
            os.replace(temporary, path)
    state.update(state="COMPLETE", completed_at=_now(), source_revision=manifest["source_revision"],
                 target=manifest["target"], destination=str(destination))
    _atomic(state_path, state)
    return state



def _restore_worktree(archive_path, destination, entries):
    """Restore only reviewed native members, preserving literal symlink targets."""
    destination = Path(destination)
    expected = {entry["path"]: entry for entry in entries}
    with tarfile.open(archive_path, "r:") as archive:
        names = archive.getnames()
        retained = {name for name, item in expected.items() if item["kind"] != "deleted"}
        if len(names) != len(set(names)) or set(names) != retained:
            raise ValueError("The original worktree archive differs from its node manifest.")
        # No member may traverse a retained symlink, regardless of archive order.
        links = {name for name, item in expected.items() if item["kind"] == "symlink"}
        for name in expected:
            _relative(name)
            if any(parent.as_posix() in links for parent in PurePosixPath(name).parents):
                raise ValueError("A native archive writes through a link; retain it for explicit review.")
        for name, entry in expected.items():
            target = destination / name
            for parent in target.parents:
                if parent == destination:
                    break
                if parent.is_symlink():
                    raise ValueError("The receiving tree has an unexpected linked parent.")
            if entry["kind"] == "deleted":
                if target.is_symlink() or target.is_file():
                    target.unlink()
                elif target.exists():
                    raise ValueError("A deleted native file was replaced by a local directory.")
                continue
            info = archive.getmember(name)
            target.parent.mkdir(mode=0o700, parents=True, exist_ok=True)
            if entry["kind"] == "directory":
                if not info.isdir() or target.is_symlink():
                    raise ValueError("Native directory type differs.")
                target.mkdir(mode=0o700, exist_ok=True)
                continue
            if entry["kind"] == "symlink":
                if not info.issym() or info.linkname != entry["link_target"]:
                    raise ValueError("Native link identity differs.")
                if target.is_symlink():
                    if os.readlink(target) == info.linkname:
                        continue
                    target.unlink()
                elif target.is_file():
                    target.unlink()
                elif target.exists():
                    raise ValueError("The native link destination contains a directory.")
                target.symlink_to(info.linkname)
                continue
            if not info.isfile() or info.size != entry["bytes"]:
                raise ValueError("Native file type or length differs.")
            if target.is_symlink():
                target.unlink()
            if target.exists() and not target.is_file():
                raise ValueError("The native file destination is not an ordinary file.")
            fd, temporary = tempfile.mkstemp(prefix=target.name + ".source-", dir=target.parent)
            try:
                with os.fdopen(fd, "wb") as output, archive.extractfile(info) as source:
                    os.fchmod(output.fileno(), 0o600)
                    shutil.copyfileobj(source, output, CHUNK)
                    output.flush()
                    os.fsync(output.fileno())
                if _file(temporary) != {key: entry[key] for key in ("bytes", "sha256")}:
                    raise ValueError("The original worktree bytes differ.")
                os.chmod(temporary, entry["mode"] & 0o777)
                os.replace(temporary, target)
                os.utime(target, (info.mtime, info.mtime))
            finally:
                if os.path.exists(temporary):
                    os.unlink(temporary)
        for name, entry in sorted(expected.items(), key=lambda row: row[0].count("/"), reverse=True):
            if entry["kind"] == "directory":
                os.chmod(destination / name, entry["mode"] & 0o777)



def receive_command_receipt(session, receipt_path):
    """Adopt a real completed command from this original private Git reopen.

    This only reconciles the existing command; it never launches another process.
    The enclosing source receiver retains its original operation lock.
    """
    s = session
    from native_adapter import _file as artifact
    incoming_path = Path(receipt_path)
    accepted = s.state.setdefault("source_received_command_receipts", {})
    selected_path = str(incoming_path)
    for prior in accepted.values():
        if prior.get("selected_path") == selected_path:
            retained = Path(s.private_path(prior["retained_path"]))
            if _file(retained)["sha256"] != prior["sha256"]:
                raise ValueError("The already received original native receipt changed.")
            for item in prior["outputs"].values():
                if _file(s.private_path(item["path"])) != {"bytes": item["size"], "sha256": item["sha256"]}:
                    raise ValueError("An accepted original command output changed.")
            return prior
    if not incoming_path.is_absolute() or incoming_path.is_symlink() or not incoming_path.is_file():
        raise ValueError("Select the actual complete original native Git command receipt.")
    raw = incoming_path.read_bytes()
    receipt_sha256 = _digest(raw)
    previous = next((row for row in accepted.values() if row["sha256"] == receipt_sha256), None)
    if previous is not None:
        return previous
    label = s.state.get("pending_command")
    if not isinstance(label, str) or not re.fullmatch(r"castor-reopen-[A-Za-z0-9_.-]+", label):
        raise ValueError("This private source Session has no original Git command awaiting a receipt.")
    if label in accepted:
        raise ValueError("Preserve the already accepted original Git command receipt.")
    original_path = s.out / (label + ".command.json")
    original_raw = original_path.read_bytes()
    directory = s.out / "received-source-commands"
    directory.mkdir(mode=0o700, exist_ok=True)
    prior_path = directory / (label + ".original.json")
    if prior_path.exists():
        original_raw = prior_path.read_bytes()
    original = json.loads(original_raw)
    retained = directory / (receipt_sha256 + ".json")
    _stable_file(retained, raw)
    completed = json.loads(raw)
    for field in ("argv", "cwd", "started_at", "mutating", "stdin"):
        if completed.get(field) != original.get(field):
            raise ValueError("The received native completion differs from original " + field + ".")
    if original.get("pid") is not None and completed.get("pid") != original["pid"]:
        raise ValueError("The completed receipt names another original native process.")
    if (completed.get("phase") != "complete" or type(completed.get("returncode")) is not int
            or not completed.get("completed_at") or not isinstance(completed.get("pid"), int)):
        raise ValueError("The native receipt must retain the actual observed command exit.")
    outputs = {}
    for role in ("stdout", "stderr"):
        descriptor = completed.get(role)
        if not isinstance(descriptor, dict):
            raise ValueError("The complete native command output descriptor is missing.")
        path = Path(descriptor["path"])
        if not path.is_absolute():
            raise ValueError("The actual original command output path must be absolute.")
        expected = {"bytes": descriptor["size"], "sha256": descriptor["sha256"]}
        destination = directory / (receipt_sha256 + "." + role)
        if destination.exists():
            if _file(destination) != expected:
                raise ValueError("A retained original command output changed.")
        else:
            _copy_original(path, destination, expected)
        outputs[role] = artifact(destination, role)
    _stable_file(directory / (label + ".original.json"), original_raw)
    completed.update(outputs)
    _atomic(original_path, completed)
    outcome = {"label": label, "sha256": receipt_sha256, "selected_path": selected_path,
               "retained_path": str(retained),
               "received_at": _now(), "returncode": completed["returncode"],
               "outputs": outputs}
    accepted[label] = outcome
    s.state.setdefault("completed_commands", {})[label] = completed
    s.state.update(phase="native_prepared" if completed["returncode"] == 0 else "native_failed",
                   pending_command=None)
    s.save_state()
    s.add(retained, "castor_source_original_command_receipt")
    for role in ("stdout", "stderr"):
        s.add(outputs[role]["path"], "castor_source_received_" + role)
    return outcome


def reopen_source(session, received_directory, checkout_directory):
    """Reopen original Git/index/local work in an independently received project.

    The caller supplies its existing Session and original operation lock. Local
    Git writes use that same retained native command admission. Missing mutation
    outcomes stay on Session's original uncertain-command recovery path.
    Selected backup/output bytes and saved images remain private original inputs.
    This never loads Docker images, starts containers or executes a native task.
    """
    s = session
    received = Path(s.private_path(str(received_directory))).resolve(strict=True)
    manifest = _load(received / "MANIFEST.json")
    if manifest.get("schema") != SCHEMA:
        raise ValueError("Select the complete original received source.")
    for member in manifest["members"]:
        path = received / _relative(member["path"])
        if _file(path) != {key: member[key] for key in ("bytes", "sha256")}:
            raise ValueError("A retained original source member changed.")
    destination = Path(s.private_path(str(checkout_directory))).absolute()
    if destination.is_symlink() or any(parent.is_symlink() for parent in destination.parents):
        raise ValueError("Select an ordinary new private source checkout.")
    control = s.out / "castor-source-reopen.json"
    binding = {"manifest_sha256": _file(received / "MANIFEST.json")["sha256"],
               "destination": str(destination)}
    if control.exists():
        state = s.read_private_json(control)
        if state.get("binding") != binding:
            raise ValueError("Continue the original source reopening destination.")
    else:
        if destination.exists() and any(destination.iterdir()):
            raise ValueError("Initial source reopening requires an empty private destination.")
        state = {"schema": "govhub.castor.source-reopen.v1", "binding": binding,
                 "state": "RUNNING", "repositories": [], "started_at": _now()}
        _atomic(control, state)
    if state["state"] == "COMPLETE":
        # The receiving engineer's later edits remain theirs. Do not overwrite.
        return {**state, "reused": True}
    destination.mkdir(mode=0o700, parents=True, exist_ok=True)
    git = _executable(s.p.get("git_path") or "git")
    for index, repository in enumerate(manifest["repositories"]):
        relative = repository["path"]
        if relative:
            _relative(relative)
        where = destination / relative
        where.mkdir(mode=0o700, parents=True, exist_ok=True)
        data = received / _relative(repository["directory"])
        label = "castor-reopen-" + str(index)

        def command(name, args, mutating=False):
            result = _native_command(s, label + "-" + name, [git, "-C", str(where), *args], mutating=mutating)
            return Path(s.private_path(result["stdout"]["path"])).read_bytes()

        command("init", ["init"], True)
        command("bundle-verify", ["bundle", "verify", str(data / "repository.bundle")])
        command("head-fetch", ["fetch", str(data / "repository.bundle"), "HEAD"], True)
        command("checkout", ["checkout", "--detach", "--force", repository["head"]], True)
        # Fetch original heads only after leaving init's current branch.
        command("refs-after-detach", ["fetch", "--force", str(data / "repository.bundle"), "+refs/*:refs/*"], True)
        if (data / "staged.patch").stat().st_size:
            command("index", ["apply", "--cached", "--binary", str(data / "staged.patch")], True)
        entries = _load(data / "worktree.json")
        _restore_worktree(data / "worktree.tar", where, entries)
        row = {"path": relative, "head": repository["head"], "state": "RECONSTRUCTED"}
        if row not in state["repositories"]:
            state["repositories"].append(row)
        _atomic(control, state)
    # Parent diffs include native submodule working status. Reopen every original
    # child before comparing any parent's final index, patches and untracked set.
    for index, repository in enumerate(manifest["repositories"]):
        where = destination / repository["path"]
        data = received / repository["directory"]
        checks = [
            ("index", ["ls-files", "--stage", "-z"], received / manifest["commands"]["git-" + str(index) + "-index"]["stdout"]),
            ("status", ["status", "--porcelain=v1", "-z", "--untracked-files=all"], received / manifest["commands"]["git-" + str(index) + "-status"]["stdout"]),
            ("staged", ["diff", "--cached", "--binary", "--full-index", "--no-ext-diff"], data / "staged.patch"),
            ("unstaged", ["diff", "--binary", "--full-index", "--no-ext-diff"], data / "unstaged.patch"),
        ]
        for name, arguments, original in checks:
            record = _native_command(s, "castor-reopen-final-" + str(index) + "-" + name,
                                     [git, "-C", str(where), *arguments])
            observed = Path(s.private_path(record["stdout"]["path"])).read_bytes()
            if observed != original.read_bytes():
                raise ValueError("Independent native Git " + name + " differs from the original.")
    selected = manifest["parts"]["selected_files"]
    _restore_worktree(received / _relative(selected["archive"]), destination,
                      _load(received / _relative(selected["entries"])))
    restored = []
    for row in selected["selection"]:
        current = _selected_identity(destination, row, allow_missing=not row["present"])
        if current != row:
            raise ValueError("The independently received selected source/output differs.")
        restored.append({**row, "receiving_path": str(destination / row["path"]) if row["present"] else None})
    state.update(state="COMPLETE", completed_at=_now(), source_revision=manifest["source_revision"],
                 original_target=manifest["target"], selected_files=restored,
                 images=manifest["parts"]["images"], image_load_performed=False,
                 native_task_performed=False, received_directory=str(received))
    _atomic(control, state)
    s.add(control, "castor_source_reopen")
    return state


def _main():
    parser = argparse.ArgumentParser(description=__doc__)
    sub = parser.add_subparsers(dest="action", required=True)
    verify = sub.add_parser("verify")
    verify.add_argument("--archive", required=True)
    verify.add_argument("--max-bytes", type=int, default=8 * 1024**3)
    receive = sub.add_parser("receive")
    receive.add_argument("--archive", required=True)
    receive.add_argument("--destination", required=True)
    receive.add_argument("--max-bytes", type=int, default=8 * 1024**3)
    args = parser.parse_args()
    if args.action == "verify":
        value = verify_source(args.archive, args.max_bytes)
    else:
        value = receive_source(args.archive, args.destination, args.max_bytes)
    print(json.dumps(value, ensure_ascii=False, indent=2))


if __name__ == "__main__":
    _main()

"""Compile reviewed source projections to native Drupal migration definitions."""
from copy import deepcopy
import re
from pathlib import PurePosixPath
from urllib.parse import urlsplit

from govhub import GovHubError, digest, packed, text
from .model import MISSING, at, issue

ID = re.compile(r"^govhub_[a-z0-9_]{1,49}$")
FIELD = re.compile(r"^[A-Za-z_][A-Za-z0-9_]*$")


def ordered_migrations(migrations):
    by_id = {item["id"]: item for item in migrations}
    result, visiting, visited = [], set(), set()
    def visit(identity):
        if identity in visiting:
            raise GovHubError("MIGRATION_CYCLE", "Native migration dependencies contain a cycle at " + identity + ".")
        if identity in visited:
            return
        if identity not in by_id:
            raise GovHubError("MIGRATION_DEPENDENCY", "The complete plan must include native dependency " + identity + ".")
        visiting.add(identity)
        dependencies = by_id[identity].get("migration_dependencies", {})
        for key in ("required", "optional"):
            for parent in dependencies.get(key, []):
                if key == "required" or parent in by_id:
                    visit(parent)
        visiting.remove(identity)
        visited.add(identity)
        result.append(by_id[identity])
    for identity in by_id:
        visit(identity)
    return result


NATIVE_PROCESS_PLUGINS = {
    "get", "default_value", "concat", "extract", "static_map", "skip_on_empty",
    "migration_lookup", "sub_process", "file_copy", "format_date", "explode",
    "flatten", "urlencode", "null_coalesce",
}


def process_steps(value):
    return value if isinstance(value, list) else [value]


def copies_original_file(process):
    return any(isinstance(step, dict) and step.get("plugin") == "file_copy"
               for value in process.values() for step in process_steps(value))


def validate_process(value, ids, location="process", *, destination_plugin="", nested=False):
    problems = []
    if isinstance(value, list):
        if not value:
            problems.append(issue("NATIVE_PROCESS", "A native process pipeline must contain a source property or process step.", property=location))
        for n, part in enumerate(value):
            problems.extend(validate_process(part, ids, location + "/" + str(n),
                destination_plugin=destination_plugin, nested=nested))
    elif isinstance(value, dict):
        plugin = value.get("plugin")
        if not isinstance(plugin, str) or plugin not in NATIVE_PROCESS_PLUGINS:
            problems.append(issue("NATIVE_PROCESS_PLUGIN", "Select a supported installed Drupal core process plugin.", property=location, plugin=plugin))
        if plugin == "migration_lookup":
            selected = value.get("migration", [])
            selected = [selected] if isinstance(selected, str) else selected
            if not isinstance(selected, list) or not selected or any(not isinstance(x, str) or x not in ids for x in selected):
                problems.append(issue("LOOKUP_MIGRATION", "A relationship lookup must select declared native migrations.", property=location))
            if value.get("no_stub") is not True:
                problems.append(issue("LOOKUP_STUB", "Set no_stub: true and explicitly handle missing relationships in the native pipeline.", property=location))
        if plugin == "sub_process":
            inner = value.get("process", {})
            if not isinstance(inner, dict):
                problems.append(issue("NATIVE_PROCESS", "A sub_process needs its native destination-property mapping.", property=location))
            else:
                for field, definition in inner.items():
                    problems.extend(validate_process(definition, ids, location + "/" + str(field),
                        destination_plugin=destination_plugin, nested=True))
        if plugin == "file_copy":
            if nested or destination_plugin != "entity:file":
                problems.append(issue("MEDIA_COPY_LOCATION", "Copy original bytes in a separately bound entity:file migration at the top process level; map multi-value media through migration_lookup.", property=location))
            source = value.get("source")
            if not isinstance(source, list) or len(source) != 2 or source[0] != "_govhub_source_path" or not isinstance(source[1], str):
                problems.append(issue("MEDIA_COPY_SOURCE", "file_copy must select [_govhub_source_path, destination source property] from this row's reviewed original-file binding.", property=location))
            if value.get("move"):
                problems.append(issue("MEDIA_COPY_MOVE", "Retain original source files and select move: false.", property=location))
            if value.get("file_exists") not in ("use existing", "replace"):
                problems.append(issue("MEDIA_COPY_EXISTING", "Select the native file_copy policy use existing or replace.", property=location))
    elif not isinstance(value, str):
        problems.append(issue("NATIVE_PROCESS", "A mapped field needs a native source-property string or process plugin definition.", property=location))
    return problems


def compile_mapping(family, mapping, editions, retained_files):
    selected = mapping.get("migrations")
    if not isinstance(selected, list) or not selected:
        raise GovHubError("CONTENT_MAPPING", "Add the selected source-to-Drupal migrations.")
    ids = [item.get("id") for item in selected if isinstance(item, dict)]
    if len(ids) != len(selected) or any(not isinstance(i, str) or not ID.fullmatch(i) for i in ids) or len(set(ids)) != len(ids):
        raise GovHubError("MIGRATION_ID", "Use distinct stable native migration IDs beginning with govhub_ and containing at most 56 lowercase letters, digits, or underscores.")
    problems, migrations, lineage, source_refs, seen_uuids = [], [], [], {}, {}
    policies = set()
    for entry in selected:
        identity = entry["id"]
        edition = editions.get(entry.get("edition_id"))
        if not edition or edition["family_id"] != family["id"]:
            raise GovHubError("MAPPING_EDITION", "Choose a retained original source edition from this consolidation.")
        for file in edition["files"]:
            source_refs[file["id"]] = {"file_id": file["id"], "sha256": file["sha256"], "bytes": file["bytes"], "observed_at": edition["observed_at"], "label": edition["label"]}
        destination = deepcopy(entry.get("destination", {}))
        if not isinstance(destination, dict) or not re.fullmatch(r"entity:[a-z][a-z0-9_]*", destination.get("plugin", "")):
            raise GovHubError("CONTENT_DESTINATION", "Select the installed Drupal content-entity destination, for example entity:node.")
        if destination.get("default_bundle") and not FIELD.fullmatch(destination["default_bundle"]):
            raise GovHubError("CONTENT_BUNDLE", "Select the exact native machine name for the content bundle.")
        process = deepcopy(entry.get("process", {}))
        if not isinstance(process, dict) or not process:
            raise GovHubError("CONTENT_PROCESS", "Map the selected fields using Drupal's original process definitions.")
        process_order = entry.get("process_order", list(process))
        if not isinstance(process_order, list) or len(process_order) != len(process) or set(process_order) != set(process):
            raise GovHubError("PROCESS_ORDER", "Retain each native destination property once in its original processing order.")
        for field, definition in process.items():
            problems.extend(dict(p, migration_id=identity) for p in validate_process(definition, set(ids), field, destination_plugin=destination["plugin"]))
        policy = entry.get("existing_target_policy", "CREATE_ONLY")
        if policy not in {"CREATE_ONLY", "REVIEWED_FIELD_UPDATE", "REUSE_SELECTED"}:
            raise GovHubError("CONTENT_UPDATE_POLICY", "Select the existing-target policy for each native migration.")
        policies.add(policy)
        if policy == "REUSE_SELECTED":
            destination["overwrite_properties"] = []
        if policy == "REVIEWED_FIELD_UPDATE" and not destination.get("overwrite_properties"):
            problems.append(issue("UPDATE_FIELDS", "Name the exact native destination fields that may update existing target records.", migration_id=identity))
        removal = entry.get("removal_policy", "RETAIN_TARGET")
        if removal != "RETAIN_TARGET":
            problems.append(issue("REMOVAL_INSTRUCTION", "Source refresh retains missing target rows. Use a separately reviewed native rollback for selected migration-owned records.", migration_id=identity))
        projection = entry.get("projection", {})
        if not isinstance(projection, dict) or any(not isinstance(k, str) or not FIELD.fullmatch(k) or not isinstance(v, str) for k, v in projection.items()):
            raise GovHubError("CONTENT_PROJECTION", "Map native source-property names to original literal fields or JSON pointers.")
        key_names = entry.get("source_ids") or ["source_id" if len(edition["record_keys"]) == 1 else "source_id_" + str(i + 1) for i in range(len(edition["record_keys"]))]
        if not isinstance(key_names, list) or len(key_names) != len(edition["record_keys"]) or len(set(key_names)) != len(key_names) or any(not isinstance(k, str) or not FIELD.fullmatch(k) for k in key_names):
            raise GovHubError("CONTENT_SOURCE_IDS", "Name one native source ID property for each original key field, in the same order.")
        choose = entry.get("selected_keys")
        if choose is not None and (not isinstance(choose, list) or any(not isinstance(k, list) or len(k) != len(key_names) or any(not isinstance(v, str) for v in k) for k in choose)):
            raise GovHubError("CONTENT_SELECTION", "Select complete original source-key arrays, preserving their order and exact strings.")
        chosen = {packed(v) for v in choose} if choose is not None else None
        for problem in edition["issues"]:
            # An explicit subset can leave other retained source rows for a
            # later mapping. Whole-feed completeness issues still apply.
            if chosen is not None:
                if "keys" in problem and packed(problem["keys"]) not in chosen:
                    continue
                if "row" in problem:
                    row = edition["rows"][problem["row"] - 1]
                    if packed(row["keys"]) not in chosen:
                        continue
            problems.append(dict(problem, migration_id=identity, edition_id=edition["id"]))
        selected_bindings = entry.get("file_bindings", [])
        if not isinstance(selected_bindings, list):
            raise GovHubError("CONTENT_FILE_BINDINGS", "Map original source-key arrays to retained original file IDs.")
        bound_files = {}
        for binding in selected_bindings:
            if not isinstance(binding, dict):
                raise GovHubError("CONTENT_FILE_BINDINGS", "Each file binding selects original source_ids and one retained file_id.")
            source_ids = binding.get("source_ids")
            file_id = binding.get("file_id")
            if not isinstance(source_ids, list) or len(source_ids) != len(key_names) or any(not isinstance(v, str) or not v for v in source_ids) or not isinstance(file_id, str) or not file_id:
                raise GovHubError("CONTENT_FILE_BINDINGS", "Retain each complete original source-key array and one actual retained file ID.")
            key = packed(source_ids)
            if key in bound_files:
                raise GovHubError("CONTENT_FILE_BINDINGS", "Each original source-key array has one reviewed file binding.")
            bound_files[key] = file_id
            if file_id not in retained_files:
                problems.append(issue("MEDIA_BINDING", "Retain this original media file before reviewing the mapping.", migration_id=identity, keys=source_ids, file_id=file_id))
        copies_file = copies_original_file(process)
        rows, found = [], set()
        for original in edition["rows"]:
            source_key = packed(original["keys"])
            if chosen is not None and source_key not in chosen:
                continue
            found.add(source_key)
            if not original["keys"]:
                continue
            row = deepcopy(original["data"]) if not projection else {}
            for field, path in projection.items():
                value = at(original["data"], path)
                if value is MISSING:
                    problems.append(issue("SOURCE_PROPERTY", "The selected source property is absent from this original row.", migration_id=identity, keys=original["keys"], property=path))
                else:
                    row[field] = deepcopy(value)
            for name, value in zip(key_names, original["keys"]):
                row[name] = value
            if source_key in bound_files:
                if row.get("_govhub_file_id") and row["_govhub_file_id"] != bound_files[source_key]:
                    problems.append(issue("MEDIA_BINDING_CONFLICT", "The projected source row and reviewed binding select different retained media files.", migration_id=identity, keys=original["keys"]))
                row["_govhub_file_id"] = bound_files[source_key]
            if "_govhub_source_path" in row or "_govhub_file_sha256" in row:
                problems.append(issue("MEDIA_RUNTIME_PROPERTY", "Native source paths and hashes come from the verified retained-file binding. Exclude runtime helper properties from the source projection.", migration_id=identity, keys=original["keys"]))
            if copies_file and (not isinstance(row.get("_govhub_file_id"), str) or not row.get("_govhub_file_id")):
                problems.append(issue("MEDIA_ROW_BINDING", "Every selected file-copy row needs its reviewed retained-file binding.", migration_id=identity, keys=original["keys"]))
            for required in entry.get("required_source_fields", []):
                value = at(row, required)
                if value is MISSING or value is None or value == "" or value == []:
                    problems.append(issue("REQUIRED_SOURCE", "Supply the required source value before migration.", migration_id=identity, keys=original["keys"], property=required))
            if row.get("_govhub_file_id") and (not isinstance(row["_govhub_file_id"], str) or row["_govhub_file_id"] not in retained_files):
                problems.append(issue("MEDIA_BINDING", "The selected media row needs its complete retained original file.", migration_id=identity, keys=original["keys"], file_id=row["_govhub_file_id"]))
            uuid_source = process.get("uuid")
            uuid_value = at(row, uuid_source) if isinstance(uuid_source, str) else MISSING
            if uuid_value is not MISSING and uuid_value:
                target = (destination["plugin"], str(uuid_value), str(row.get("langcode", "")))
                if target in seen_uuids:
                    problems.append(issue("DUPLICATE_TARGET_UUID", "Two selected source records map to the same target UUID and language.", migration_id=identity, keys=original["keys"], previous=seen_uuids[target]))
                seen_uuids[target] = {"migration_id": identity, "keys": original["keys"]}
            rows.append(row)
            lineage.append({"migration_id": identity, "source_ids": original["keys"], "edition_id": edition["id"], "file_id": original["file_id"], "source_row": original["source_row"], "original_row_sha256": original["row_sha256"], **{k: original[k] for k in ("source_line_start", "source_line_end") if k in original}})
        for absent in sorted(set(bound_files) - found):
            problems.append(issue("MEDIA_BINDING_SOURCE", "The reviewed media binding must select a source key included in this migration.", migration_id=identity, keys=absent, file_id=bound_files[absent]))
        if chosen is not None:
            for absent in sorted(chosen - found):
                problems.append(issue("SELECTED_KEY_MISSING", "The selected original key is missing from this source edition.", migration_id=identity, keys=absent))
        migration = {"id": identity, "label": text(entry.get("label", identity), 500, True), "source": {"id_order": key_names, "ids": {name: {"type": "string"} for name in key_names}, "fields": {name: name for name in sorted({key for row in rows for key in row})}, "rows": rows}, "process": process, "process_order": process_order, "destination": destination, "existing_target_policy": policy, "migration_dependencies": deepcopy(entry.get("migration_dependencies", {"required": [], "optional": []})), "receiving": deepcopy(entry.get("receiving") or {"fields": list(dict.fromkeys(field.split("/")[0] for field in process if not field.startswith("_")))})}
        if not migration["receiving"].get("fields"):
            migration["receiving"]["fields"] = list(dict.fromkeys(field.split("/")[0] for field in process if not field.startswith("_")))
        migrations.append(migration)
    migrations = ordered_migrations(migrations)
    files, file_ids, paths = [], set(), set()
    for binding in mapping.get("files", []):
        item = retained_files.get(binding.get("file_id"))
        if not item:
            raise GovHubError("CONTENT_FILE", "Select an original retained media or source file.")
        relative = text(binding.get("relative_path", item["filename"]), 2000, True)
        path = PurePosixPath(relative)
        if path.is_absolute() or ".." in path.parts or "\\" in relative or relative in paths or item["id"] in file_ids:
            raise GovHubError("CONTENT_FILE_PATH", "Each selected file needs one unique relative delivery path without traversal.")
        file_ids.add(item["id"]); paths.add(relative)
        files.append({"file_id": item["id"], "sha256": item["sha256"], "bytes": item["bytes"], "relative_path": relative, "media_type": text(binding.get("media_type", ""), 500), "license": text(binding.get("license", ""), 8000), "source_url": text(binding.get("source_url", ""), 4000)})
    for migration in migrations:
        for row in migration["source"]["rows"]:
            if row.get("_govhub_file_id") and (not isinstance(row["_govhub_file_id"], str) or row["_govhub_file_id"] not in file_ids):
                problems.append(issue("MEDIA_FILE_SELECTION", "Include this row's original bytes in the plan's selected files.", migration_id=migration["id"], file_id=row["_govhub_file_id"]))
    routes = deepcopy(mapping.get("routes", []))
    for route in routes:
        if route.get("migration_id") not in ids or not isinstance(route.get("source_ids"), list) or any(not isinstance(v, str) for v in route["source_ids"]):
            raise GovHubError("CONTENT_ROUTE", "Each selected route must identify its original migration and source keys.")
        for name in ("old_url", "new_url"):
            parsed = urlsplit(route.get(name, ""))
            if parsed.scheme not in {"http", "https"} or not parsed.hostname or parsed.username or parsed.password:
                raise GovHubError("CONTENT_ROUTE", "Retain the complete original HTTP route and selected canonical URL.")
    scope = family.get("limits", {})
    counts = {"migrations": len(migrations), "records": sum(len(m["source"]["rows"]) for m in migrations), "files": len(files), "file_bytes": sum(f["bytes"] for f in files), "routes": len(routes)}
    for name, total in counts.items():
        if scope.get(name) is not None and total > scope[name]:
            problems.append(issue("SELECTED_SCOPE", "The selected content exceeds this consolidation's agreed " + name + " scope.", selected=total, agreed=scope[name]))
    fingerprint = digest(packed({"migrations": migrations, "files": files, "routes": routes}))
    return {"migrations": migrations, "source_refs": list(source_refs.values()), "files": files, "routes": routes, "lineage": lineage, "issues": problems, "counts": counts, "definition_sha256": fingerprint, "allow_existing_updates": "REVIEWED_FIELD_UPDATE" in policies}

"""Complete content editions, native results and editable receiving joins."""
import html
import json

from govhub import GovHubError, SOURCE, csv_bytes, now, packed, text


class ContentDeliveryMixin:
    def _handover_capture(self, db, payload, actor):
        families = payload.get("content_family_ids", [])
        if not families:
            return super()._handover_capture(db, payload, actor)
        if not isinstance(families, list) or len(set(families)) != len(families) or any(not isinstance(f, str) for f in families):
            raise GovHubError("CONTENT_HANDOVER_SCOPE", "Select each complete content consolidation once.")
        if not isinstance(payload.get("include_sources"), bool):
            raise GovHubError("HANDOVER_SOURCE_OPTION", "Select whether the receiving handover includes the original source bytes.")
        if payload.get("plan_ids") or payload.get("visitor_edition_ids"):
            capture = super()._handover_capture(db, payload, actor)
        else:
            meta = self.meta(db)
            capture = {"format": "govhub-cutover-handover/1", "name": text(payload.get("name", ""), 500, True), "observed_at": now(), "author": actor["name"], "workspace": meta["workspace"], "workspace_head": meta["head"], "source": SOURCE, "settings": self._setting(db, "settings"), "core_sources": self.core_sources, "auditor_sha256": self.auditor_sha256, "include_sources": payload["include_sources"], "plan_ids": [], "plans": [], "snapshots": [], "operations": [], "records": {"sites": [], "environments": [], "migration_issues": []}, "record_history": [], "sources": []}
        source_ids = {f["id"] for f in capture["sources"]}
        if capture["settings"].get("scope_file_id"):
            source_ids.add(capture["settings"]["scope_file_id"])
        content, targets, comparisons = [], set(), set()
        for family_id in sorted(families):
            family = self._content_family(db, family_id)
            editions = self._objects(db, "content_edition", family_id)
            mappings = self._objects(db, "content_mapping", family_id)
            reviews = self._objects(db, "content_review", family_id)
            plans = self._objects(db, "content_plan", family_id)
            content.append({"family": family, "versions": self._objects(db, "content_family_version", family_id), "editions": editions, "mappings": mappings, "reviews": reviews, "plans": plans})
            targets.add(family["environment_id"])
            if family["comparison_id"]:
                comparisons.add(family["comparison_id"])
            for edition in editions:
                source_ids.update(f["id"] for f in edition["files"])
            for mapping in mappings:
                source_ids.update(f["file_id"] for f in mapping["compiled"]["files"])
            for review in reviews:
                if review.get("backup_ref"):
                    source_ids.add(review["backup_ref"]["file_id"])
        included_operations = {o["operation"]["id"] for o in capture["operations"]}
        all_operations = [json.loads(r[0]) for r in db.execute("SELECT data FROM govhub_operations ORDER BY rowid")]
        for operation in all_operations:
            if operation.get("content_family_id") not in families or operation["id"] in included_operations:
                continue
            files = self._output_list(db, "operation", operation["id"])
            capture["operations"].append({"operation": operation, "events": self._objects(db, "operation_event", operation["id"]), "observations": self._objects(db, "operation_observation", operation["id"]), "files": files})
            source_ids.update(f["file_id"] for f in files)
        existing_records = {(r["kind"], r["id"]) for rows in capture["records"].values() for r in rows}
        for row in db.execute("SELECT * FROM entities ORDER BY kind,id"):
            record = self._core.view_record(row)
            selected = record["kind"] == "environments" and record["id"] in targets or record["kind"] == "sites" and record["data"]["comparison_id"] in comparisons
            if selected and (record["kind"], record["id"]) not in existing_records:
                capture["records"][record["kind"]].append(record)
                existing_records.add((record["kind"], record["id"]))
        previous_revisions = {r["revision"] for r in capture["record_history"]}
        for row in db.execute("SELECT * FROM revisions ORDER BY rowid"):
            if (row["kind"], row["id"]) in existing_records and row["revision"] not in previous_revisions:
                retained = dict(row)
                retained["data"], retained["origin"] = json.loads(row["data"]), json.loads(row["origin"])
                capture["record_history"].append(retained)
        capture["sources"] = [self._file_row(db, f) for f in sorted(source_ids)]
        capture["content_family_ids"] = sorted(families)
        capture["content_consolidation"] = {"schema": "govhub.content-consolidation.handover.v1", "families": content}
        return capture

    def _exports_compare(self, payload):
        result = super()._exports_compare(payload)
        with self.connect(snapshot=True) as db:
            before = self._get(db, "export", payload.get("before_id"))
            after = self._get(db, "export", payload.get("after_id"))
            a = self._get(db, "export_intent", before["intent_id"])["capture"]
            b = self._get(db, "export_intent", after["intent_id"])["capture"]
        if not (a.get("content_consolidation") or b.get("content_consolidation")):
            return result
        def components(capture):
            groups = {name: [] for name in ("families", "source_editions", "mappings", "reviews", "native_plans")}
            for bundle in capture.get("content_consolidation", {}).get("families", []):
                groups["families"].append(bundle["family"])
                for edition in bundle["editions"]:
                    groups["source_editions"].append({k: v for k, v in edition.items() if k != "rows"})
                for mapping in bundle["mappings"]:
                    groups["mappings"].append({k: v for k, v in mapping.items() if k not in {"compiled", "definition"}})
                groups["reviews"].extend(bundle["reviews"])
                for plan in bundle["plans"]:
                    groups["native_plans"].append({k: v for k, v in plan.items() if k not in {"native", "lineage"}})
            return groups
        left, right = components(a), components(b)
        result["content_consolidation"] = {name: self._compare_objects(left[name], right[name]) for name in left}
        return result

    def _content_export_files(self, capture, write):
        content = capture.get("content_consolidation")
        if not content:
            return
        write("content-consolidation.json", (packed(content) + "\n").encode("utf-8"))
        rows, lineage, definitions = [], [], []
        for bundle in content["families"]:
            family = bundle["family"]
            for edition in bundle["editions"]:
                for row in edition["rows"]:
                    rows.append({"family_id": family["id"], "source_id": edition["source_id"], "edition_id": edition["id"], "observed_at": edition["observed_at"], "keys": packed(row["keys"]), "file_id": row["file_id"], "source_row": row["source_row"], "row_sha256": row["row_sha256"], "original_record": packed(row["data"]), "source_line_start": row.get("source_line_start", ""), "source_line_end": row.get("source_line_end", "")})
            for plan in bundle["plans"]:
                definitions.append(plan["native"])
                lineage.extend({"plan_id": plan["id"], **entry, "source_ids": packed(entry["source_ids"])} for entry in plan["lineage"])
        write("content-source-records.csv", csv_bytes(rows, ("family_id", "source_id", "edition_id", "observed_at", "keys", "file_id", "source_row", "row_sha256", "original_record", "source_line_start", "source_line_end")))
        write("content-native-migrations.json", (packed(definitions) + "\n").encode("utf-8"))
        write("content-lineage.csv", csv_bytes(lineage, ("plan_id", "migration_id", "source_ids", "edition_id", "file_id", "source_row", "original_row_sha256", "source_line_start", "source_line_end")))
        write("CONTENT_RECEIVING.md", ("# Content consolidation receiving\n\nOpen handover.html for the operator report and content-consolidation.json for every original feed edition, mapping, decision and native plan. content-source-records.csv preserves the complete selected records. content-lineage.csv connects the original source rows to the selected native migration/source IDs. New CSV editions retain their exact delimiter, quoting and per-file header order in content-consolidation.json; their source_line_start/source_line_end columns locate records that span physical lines. Those columns remain empty for earlier editions and JSON sources. operations.json and the retained original native artifacts contain Drupal's actual ID maps, messages and JSON:API responses. source-manifest.json identifies every included original source and media file.\n\nThe separate full workspace backup includes the database, current staff accounts, original file store and native operation journals. Open that complete backup with this same application and review Content consolidation. Compare the retained first and corrected source editions; open their native operations and original artifacts; create a new source-inclusive handover. Use the original target/profile and migration IDs for any continuation. Native selected-row rollback is separate from whole-site recovery. The consolidation record retains its operating recovery instruction.\n").encode("utf-8"))

    def _handover_html(self, capture):
        rendered = super()._handover_html(capture)
        content = capture.get("content_consolidation")
        if not content:
            return rendered
        e = lambda x: html.escape(str(x if x is not None else ""), quote=True)
        blocks = ["<h2>Content consolidation</h2>"]
        for bundle in content["families"]:
            family = bundle["family"]
            blocks.append("<h3>" + e(family["label"]) + "</h3><p>" + e(family["notes"]) + "</p><dl><dt>Owner</dt><dd>" + e(family["owner"]) + "</dd><dt>Recovery instruction</dt><dd>" + e(family["recovery_instruction"]) + "</dd></dl>")
            blocks.append("<table><thead><tr><th>Original feed edition</th><th>Observation</th><th>Records and original sources</th></tr></thead><tbody>")
            for edition in bundle["editions"]:
                blocks.append("<tr><td>" + e(edition["source_id"]) + "<br>" + e(edition["label"]) + "<br>" + e(edition["id"]) + "</td><td>" + e(edition["observed_at"]) + "</td><td>" + e(edition["row_count"]) + " records<br>" + e(len(edition["files"])) + " original files<br>" + e(len(edition["issues"])) + " source issues</td></tr>")
            blocks.append("</tbody></table><h4>Mapping and review history</h4><table><thead><tr><th>Mapping</th><th>Native migration</th><th>Source edition and selected destination</th></tr></thead><tbody>")
            for mapping in bundle["mappings"]:
                for migration in mapping["definition"]["migrations"]:
                    blocks.append("<tr><td>" + e(mapping["label"]) + "<br>" + e(mapping["id"]) + "</td><td>" + e(migration["id"]) + "</td><td>" + e(migration["edition_id"]) + "<br>" + e(packed(migration["destination"])) + "</td></tr>")
            blocks.append("</tbody></table>")
            for review in bundle["reviews"]:
                blocks.append("<p><strong>" + e(review["decision"]) + "</strong> · " + e(review["author"]) + " · " + e(review["created_at"]) + "<br>" + e(review["reason"]) + "<br>Mapping " + e(review["mapping_id"]) + "</p>")
        return rendered.replace(b"</main>", ("".join(blocks) + "</main>").encode("utf-8"))

"""GovHub native adapter ABI for reviewed Drupal content migrations."""
from __future__ import annotations

import hashlib
import json
import os
import re
import shutil
from pathlib import Path

import native_adapter as base
from .install import module_inventory
from .receiving import receive

SCHEMA = "govhub.content-consolidation.drupal-plan.v1"
ACTIONS = {
    "drupal-content-import": "import",
    "drupal-content-rollback": "rollback",
    "drupal-content-status": "status",
    "drupal-content-receive": "receive",
}


def _hash(path):
    digest = hashlib.sha256()
    with Path(path).open("rb") as stream:
        for chunk in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def _verified(descriptor):
    path = Path(descriptor["path"])
    if not path.is_absolute() or path.is_symlink() or not path.is_file():
        raise ValueError("Use the original regular file retained in the private content workspace.")
    expected_size = descriptor.get("bytes", descriptor.get("size"))
    if path.stat().st_size != expected_size or _hash(path) != descriptor["sha256"]:
        raise ValueError("The original retained source bytes changed: " + str(descriptor.get("file_id", path.name)))
    return path


def _read_result(descriptor):
    return json.loads(_verified(descriptor).read_bytes())


def _write_once(path, content):
    data = content if isinstance(content, bytes) else (
        json.dumps(content, ensure_ascii=False, sort_keys=True, separators=(",", ":"), allow_nan=False) + "\n"
    ).encode()
    if path.exists():
        if path.read_bytes() != data:
            raise ValueError("The original retained native request has different bytes: " + path.name)
    else:
        temporary = path.with_name(path.name + ".writing")
        with temporary.open("xb") as stream:
            stream.write(data)
            stream.flush()
            os.fsync(stream.fileno())
        os.replace(temporary, path)
    return base._file(path, "retained_native_input")


def _collect_artifacts(session):
    # The original GovHub file store captures these exact bytes. Large native
    # row and HTTP payloads remain in files, never in the 1 MiB checkpoint.
    known = {item["path"] for item in session.artifacts}
    for path in sorted(session.out.rglob("*")):
        if not path.is_file() or path.is_symlink() or str(path) in known:
            continue
        if path.name.endswith((".writing", ".govhub-writing")) or path.name == "native-state.json":
            continue
        if path.name.startswith("event-") and path.suffix == ".json":
            continue
        if "relocated-originals" in path.parts:
            role = "original_relocation_record"
        elif path.name.endswith(".command.json"):
            role = "native_command"
        elif path.suffix in (".stdout", ".stderr"):
            role = "native_command_output"
        elif path.name == "native-events.ndjson":
            role = "native_row_events"
        elif path.parent.name == "receiving":
            role = "native_http_response" if path.suffix == ".json" else "native_http_body"
        else:
            role = "native_content_artifact"
        session.add(path, role)
        known.add(str(path))


def _source_bindings(plan, source_paths):
    bindings = {}
    for item in source_paths.get("content_files", []):
        if item.get("file_id") in bindings:
            raise ValueError("Each original content file ID has one retained byte binding.")
        path = _verified(item)
        bindings[item["file_id"]] = {**item, "path": str(path.resolve()), "bytes": path.stat().st_size}
    selected = [*plan.get("source_refs", []), *plan.get("files", [])]
    if plan.get("review", {}).get("backup_ref"):
        selected.append(plan["review"]["backup_ref"])
    for item in selected:
        binding = bindings.get(item["file_id"])
        if not binding or any(binding[key] != item[key] for key in ("sha256", "bytes")):
            raise ValueError("An original reviewed source, media file or recovery point is missing: " + item["file_id"])
    return list(bindings.values())


def _ensure_module(profile):
    root, inventory, digest = module_inventory()
    installed = Path(profile["site_root"]) / "modules" / "custom" / "govhub_consolidation"
    missing = []
    for name, item in inventory.items():
        path = installed / name
        if not path.is_file() or _hash(path) != item["sha256"]:
            missing.append(name)
    if missing:
        raise ValueError("Install this exact supplied govhub_consolidation edition into the selected Drupal project with "
                         "python3 -m content_consolidation.drupal.install; missing or different files: " + ", ".join(missing))
    return digest


def _resume_state(session, source_paths, operation, intent):
    path = session.out / "native-state.json"
    supplied = source_paths.get("checkpoint") or operation.get("resume_checkpoint") or {}
    supplied = supplied.get("resume_checkpoint", supplied.get("state", supplied))
    state = session.read_private_json(path) if path.exists() else session.resolve_private(supplied)
    if state and state.get("intent_sha256") != base._digest(intent):
        raise ValueError("The original native operation selects another target, source edition, or rollback selection.")
    session.state = dict(state or {
        "intent_sha256": base._digest(intent), "intent": intent, "phase": "prepared",
        "mutation_started": False, "attempt": 0, "receiving_attempt": 0, "output_dir": str(session.out)
    })
    session.save_state()


def _command_reconciliation(session):
    pending = session.state.get("pending_command")
    if not pending:
        return False
    record_path = session.out / (pending + ".command.json")
    if not record_path.is_file():
        raise base.NativeWaiting("The original native command was dispatched without its retained command record; recover that same record before continuation.")
    record = session.read_private_json(record_path)
    if record.get("phase") == "not_started":
        session.state.update(pending_command=None, phase="native_prepared")
        session.save_state()
        return False
    if record.get("phase") == "complete" or record.get("phase") == "interrupted" and record.get("owned_process_reaped") is True:
        session.state["reconciled_command"] = {"path": str(record_path), "sha256": _hash(record_path),
                                                "phase": record["phase"], "owned_process_reaped": True}
        session.state.update(pending_command=None, phase="native_reconciled")
        session.save_state()
        return True
    raise base.NativeWaiting("This original mutating command has no retained completion or owned-process reaping; reconcile its same process and output before continuing.")


def _recover_native_result(session, operation, plan_ref, action):
    """Adopt the original finished output after a lost parent checkpoint."""
    selected = session.state.get("current_result_path")
    request_ref = session.state.get("current_request")
    if not selected or not request_ref:
        return None
    path = Path(selected)
    if path.parent != session.out or not path.name.endswith(".result.json"):
        raise ValueError("The retained result must belong to this original private operation.")
    if not path.is_file():
        return None
    request = _read_result(request_ref)
    operation_id = operation.get("id") or operation.get("operation_id")
    if (request.get("operation_id") != operation_id or request.get("plan_sha256") != plan_ref["sha256"]
            or request.get("action") != action or Path(request.get("result_path", "")) != path
            or request.get("selection", []) != operation.get("content_selection", [])):
        raise ValueError("The retained native request differs from this operation and source.")
    label = path.name.removesuffix(".result.json")
    record_path = session.out / (label + ".command.json")
    if not record_path.is_file():
        raise base.NativeWaiting("Recover the original command record before adopting its native output.")
    record = session.read_private_json(record_path)
    complete = record.get("phase") == "complete" and record.get("returncode") == 0
    reaped = record.get("phase") == "interrupted" and record.get("owned_process_reaped") is True
    if not (complete or reaped):
        raise base.NativeWaiting("Reconcile the original native process before adopting its retained output.")
    for role in ("stdout", "stderr"):
        if record.get(role):
            _verified(record[role])
    descriptor = base._file(path, "native_content_result")
    result = _read_result(descriptor)
    if (result.get("schema") != "govhub.content-consolidation.drupal-result.v1"
            or result.get("operation_id") != operation_id or result.get("plan_sha256") != plan_ref["sha256"]
            or result.get("action") != action):
        raise ValueError("The original native result differs from its retained operation and source.")
    session.state.update(native_result_ref=descriptor, phase="native_complete",
                         pending_command=None, completed_commands={})
    session.save_state()
    return result


def _native_attempt(session, operation, plan_ref, files, action, *, reconciled=False):
    attempt = int(session.state.get("attempt", 0)) + 1
    label = f"content-native-{attempt:04d}"
    result_path = session.out / f"{label}.result.json"
    request_path = session.out / f"{label}.request.json"
    operation_id = operation.get("id") or operation.get("operation_id")
    if not isinstance(operation_id, str) or not operation_id:
        raise ValueError("Retain the original GovHub operation ID.")
    payload = {
        "schema": "govhub.content-consolidation.native-request.v1", "operation_id": operation_id,
        "action": action, "plan_path": plan_ref["path"], "plan_sha256": plan_ref["sha256"],
        "files": files, "selection": operation.get("content_selection", []),
        "output_dir": str(session.out), "result_path": str(result_path),
        "resume_reconciled": bool(reconciled),
        "row_limit": int(operation.get("content_row_limit", 0)),
        "time_budget_seconds": max(1, session.p["timeout_seconds"] - 10),
    }
    if payload["row_limit"] < 0:
        raise ValueError("The native row limit cannot be negative.")
    request_ref = _write_once(request_path, payload)
    script = Path(__file__).resolve().parent / "run.php"
    script_copy = session.out / "content-run.php"
    _write_once(script_copy, script.read_bytes())
    argv = base._prefix(session.p) + ["php:script", "content-run",
            "--script-path=" + str(session.out), "--", str(request_path)]
    session.state.update(attempt=attempt, current_request=request_ref, current_result_path=str(result_path),
                         phase="native_prepared", native_action=action)
    session.save_state()
    record = session.command(label, argv, mutating=action in {"import", "rollback"})
    result_ref = base._file(result_path, "native_content_result")
    result = _read_result(result_ref)
    if (result.get("schema") != "govhub.content-consolidation.drupal-result.v1"
            or result.get("operation_id") != operation_id or result.get("plan_sha256") != plan_ref["sha256"]):
        raise ValueError("The original native result differs from its retained operation and source.")
    session.state.update(native_result_ref=result_ref, phase="native_complete",
                         pending_command=None, completed_commands={})
    session.save_state()
    return result


def execute(operation, config, source_paths, checkpoint=None, cancelled=None):
    """Run through the original GovHub private native worker and result envelope."""
    profile = base._profile(config)
    if profile["source_kind"] != "drush":
        raise ValueError("Content Migrate execution uses the existing equipped Drupal / Drush profile.")
    session = base.Session(profile, source_paths["output_dir"], checkpoint, cancelled, source_paths.get("workspace_relocations"))
    source_paths = session.resolve_private(source_paths)
    observations = {}
    try:
        native_action = operation.get("native_action", operation.get("action"))
        action = ACTIONS.get(native_action)
        if action is None:
            raise ValueError("Select one of the original Drupal content native actions.")
        environment = operation.get("provider_environment_id", operation.get("environment_id"))
        if environment != profile["environment_id"]:
            raise ValueError("The operation must select this exact configured Drupal environment.")
        plan = source_paths.get("content_plan")
        if not isinstance(plan, dict) or plan.get("schema") != SCHEMA:
            raise ValueError("Use the original frozen Drupal content plan v1.")
        files = _source_bindings(plan, source_paths)
        plan_ref = _write_once(session.out / "content-plan.json", plan)
        selection = operation.get("content_selection", [])
        if action == "rollback" and not selection:
            raise ValueError("Select the exact original migration/source-ID rows to roll back.")
        intent = {"action": native_action, "target": base._context(profile), "plan_sha256": plan_ref["sha256"],
                  "selection": selection, "operation_id": operation.get("id") or operation.get("operation_id")}
        _resume_state(session, source_paths, operation, intent)
        if session.state.get("phase") == "completed" and session.state.get("observations_ref"):
            observations = _read_result(session.state["observations_ref"])
            _collect_artifacts(session)
            return session.result("COMPLETE", observations)
        module_sha = _ensure_module(profile)
        native_status, commands, native_fingerprint = base._drush_info(session, fresh=True)
        if "php:script" not in commands:
            raise ValueError("The selected installed Drush does not expose php:script.")
        expected_fingerprint = operation.get("target_fingerprint") or config.get("target_fingerprint")
        if expected_fingerprint:
            actual = base._drush_fingerprint(profile, native_status, commands)
            if actual != expected_fingerprint:
                raise ValueError("The selected native target differs from the original configured fingerprint.")
        reconciled = _command_reconciliation(session)
        result = None
        ref = session.state.get("native_result_ref")
        candidate = _read_result(ref) if ref else _recover_native_result(session, operation, plan_ref, action)
        if candidate:
            if candidate.get("status") == "complete":
                result = candidate
            elif candidate.get("status") in {"failed", "incomplete"}:
                reconciled = True
        if result is None:
            result = _native_attempt(session, operation, plan_ref, files, action, reconciled=reconciled)
        observations = {**result, "native_action": native_action, "target": base._context(profile),
                        "native_status": native_status, "module_source_sha256": module_sha,
                        "plan_file": plan_ref, "native_result_file": session.state.get("native_result_ref")}
        if result.get("status") == "incomplete":
            path = session.out / f"observations-{session.state['attempt']:04d}.json"
            base._atomic(path, observations)
            session.state.update(phase="native_paused", observations_ref=base._file(path, "content_observations"))
            session.save_state()
            _collect_artifacts(session)
            return session.result("WAITING_NATIVE", observations, "The core Migrate engine paused with its original ID maps; resume this same operation.")
        if result.get("status") != "complete":
            session.state.update(phase="native_failed")
            session.save_state()
            _collect_artifacts(session)
            return session.result("FAILED", observations, (result.get("error") or {}).get("message", "The original migration has failed, ignored or unmapped selected rows; its native maps and messages are retained."))
        if action != "status":
            pass_number = int(session.state.get("receiving_attempt", 0)) + 1
            session.state.update(receiving_attempt=pass_number, phase="receiving")
            session.save_state()
            receiving = receive(session, config, result, plan, pass_number)
            observations["receiving"] = receiving
        else:
            receiving = {"status": "COMPLETE"}
        final_path = session.out / f"content-observations-{int(session.state['receiving_attempt']):04d}.json"
        base._atomic(final_path, observations)
        status = "COMPLETE" if receiving["status"] == "COMPLETE" else "FAILED"
        session.state.update(phase="completed" if status == "COMPLETE" else "receiving_failed",
                             observations_ref=base._file(final_path, "content_observations"), completed_commands={})
        session.save_state()
        _collect_artifacts(session)
        return session.result(status, observations, None if status == "COMPLETE" else "The native import is retained; resolve the recorded target receiving response and resume this operation.")
    except base.NativeCancelled as exc:
        _collect_artifacts(session)
        return session.result("WAITING_NATIVE" if session.state.get("mutation_started") else "CANCELLED", observations, str(exc))
    except base.NativeWaiting as exc:
        _collect_artifacts(session)
        return session.result("WAITING_NATIVE", observations, str(exc))
    except Exception as exc:
        _collect_artifacts(session)
        status = "WAITING_NATIVE" if session.state.get("phase") == "native_interrupted" else "FAILED"
        return session.result(status, observations, str(exc))

"""Install the supplied module into one selected, already equipped Drupal site.

Run from the maintained GovHub workspace:
  python3 -m content_consolidation.drupal.install --config profile.json --output /private/install
"""
from __future__ import annotations

import argparse
import hashlib
import json
import os
import shutil
from pathlib import Path

import native_adapter as base


def module_inventory():
    root = Path(__file__).resolve().parent / "govhub_consolidation"
    files = {}
    for path in sorted(root.rglob("*")):
        if path.is_file():
            relative = path.relative_to(root).as_posix()
            files[relative] = {"sha256": hashlib.sha256(path.read_bytes()).hexdigest(), "bytes": path.stat().st_size}
    if not files or "src/Runner.php" not in files:
        raise ValueError("The complete supplied Drupal module is required.")
    digest = hashlib.sha256(json.dumps(files, sort_keys=True, separators=(",", ":")).encode()).hexdigest()
    return root, files, digest


def install_module(config, output_dir, checkpoint=None, cancelled=None):
    profile = base._profile(config)
    if profile["source_kind"] != "drush":
        raise ValueError("Select the equipped Drupal / Drush site for module installation.")
    session = base.Session(profile, output_dir, checkpoint, cancelled)
    root, files, source_sha = module_inventory()
    target = Path(profile["site_root"]) / "modules" / "custom" / "govhub_consolidation"
    marker = target / ".govhub-source.json"
    intent = {"target": base._context(profile), "module_directory": str(target), "source_sha256": source_sha}
    state_path = session.out / "native-state.json"
    session.state = session.read_private_json(state_path) if state_path.exists() else {
        "intent_sha256": base._digest(intent), "intent": intent, "phase": "prepared", "mutation_started": False
    }
    if session.state["intent_sha256"] != base._digest(intent):
        raise ValueError("This original installation operation selects another target or module edition.")
    try:
        native, commands, native_fingerprint = base._drush_info(session, fresh=True)
        if not {"php:script", "pm:enable", "cache:rebuild"} <= commands:
            raise ValueError("The selected installed Drush must supply php:script, pm:enable, and cache:rebuild.")
        if target.is_symlink() or any(parent.is_symlink() for parent in (target.parent, target.parent.parent)):
            raise ValueError("The selected custom-module directory must be an ordinary directory in this Drupal root.")
        previous = json.loads(marker.read_text()) if marker.exists() else None
        if target.exists() and not previous:
            changed = [name for name, item in files.items()
                       if (target / name).exists() and hashlib.sha256((target / name).read_bytes()).hexdigest() != item["sha256"]]
            if changed:
                raise ValueError("An existing unmanifested module has different source at: " + ", ".join(changed))
        if previous:
            for name, item in previous["files"].items():
                path = target / name
                allowed = {item["sha256"]}
                if session.state.get("mutation_started") and name in files:
                    allowed.add(files[name]["sha256"])
                if path.is_file() and hashlib.sha256(path.read_bytes()).hexdigest() not in allowed:
                    raise ValueError("The installed module has local edits to compose before its update: " + name)
        session.state.update(phase="native_prepared", mutation_started=True)
        session.save_state()
        before = session.out / "module-before"
        for name, expected in files.items():
            session.check()
            source, destination = root / name, target / name
            if destination.is_file() and hashlib.sha256(destination.read_bytes()).hexdigest() == expected["sha256"]:
                continue
            if destination.exists():
                retained = before / name
                retained.parent.mkdir(parents=True, exist_ok=True)
                if retained.exists() and retained.read_bytes() != destination.read_bytes():
                    raise ValueError("The retained original module file differs from this continuation.")
                shutil.copyfile(destination, retained)
            destination.parent.mkdir(parents=True, exist_ok=True)
            temporary = destination.with_name(destination.name + ".govhub-writing")
            with temporary.open("wb") as stream:
                stream.write(source.read_bytes())
                stream.flush()
                os.fsync(stream.fileno())
            os.chmod(temporary, 0o644)
            os.replace(temporary, destination)
        base._atomic(marker, {"schema": "govhub.content-module-source.v1", "sha256": source_sha, "files": files})
        enabled = session.command("content-module-enable", base._prefix(profile) + ["pm:enable", "govhub_consolidation", "--yes"], mutating=True)
        rebuilt = session.command("content-module-cache", base._prefix(profile) + ["cache:rebuild"], mutating=True)
        for name, expected in files.items():
            if hashlib.sha256((target / name).read_bytes()).hexdigest() != expected["sha256"]:
                raise ValueError("Installed source readback changed: " + name)
        result = {"schema": "govhub.content-module-install.v1", "target": base._context(profile),
                  "native_status": native, "source_sha256": source_sha, "module_directory": str(target), "files": files}
        result_path = session.out / "installed-module.json"
        base._atomic(result_path, result)
        session.add(result_path, "installed_content_module")
        session.add(enabled["stdout"]["path"], "native_module_enable")
        session.add(rebuilt["stdout"]["path"], "native_module_cache")
        session.state.update(phase="completed", observations=result)
        session.save_state()
        return session.result("COMPLETE", result)
    except base.NativeCancelled as error:
        return session.result("WAITING_NATIVE" if session.state.get("mutation_started") else "CANCELLED", message=str(error))
    except base.NativeWaiting as error:
        return session.result("WAITING_NATIVE", message=str(error))
    except Exception as error:
        return session.result("WAITING_NATIVE" if session.state.get("phase") == "native_interrupted" else "FAILED", message=str(error))


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--config", required=True, help="Existing private Drush profile JSON.")
    parser.add_argument("--output", required=True, help="Retained private installation operation directory.")
    args = parser.parse_args()
    result = install_module(json.loads(Path(args.config).read_text()), args.output)
    print(json.dumps(result, ensure_ascii=False, indent=2))
    raise SystemExit(0 if result["status"] == "COMPLETE" else 1)


if __name__ == "__main__":
    main()

"""Original HTTP receiving for native Drupal UUIDs, files, and selected routes."""
from __future__ import annotations

import hashlib
import json
import os
import re
import time
from pathlib import Path
from urllib import error, parse, request

import native_adapter as base


def _url(value):
    parts = parse.urlsplit(value)
    if parts.scheme not in ("http", "https") or not parts.hostname or parts.username or parts.password:
        raise ValueError("Receiving requires an original HTTP(S) URL without embedded credentials.")
    return value


def _origin(value):
    url = parse.urlsplit(value)
    return url.scheme.lower(), url.hostname.lower(), url.port or (443 if url.scheme == "https" else 80)


def _headers(config, target_uri, url, accept):
    headers = {"Accept": accept, "User-Agent": "GovHub-Content-Receiving/1.0"}
    if _origin(url) != _origin(target_uri):
        return headers
    for field, name, prefix in (("jsonapi_bearer_env", "Authorization", "Bearer "),
                                ("jsonapi_cookie_env", "Cookie", "")):
        reference = config.get(field)
        if reference:
            if not re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", reference):
                raise ValueError("Configure the name of the existing private receiving environment variable.")
            value = os.environ.get(reference)
            if not value or "\r" in value or "\n" in value:
                raise ValueError("The configured private receiving environment variable is unavailable or invalid: " + reference)
            headers[name] = prefix + value
    return headers


class Redirects(request.HTTPRedirectHandler):
    def __init__(self):
        self.chain = []

    def redirect_request(self, original, fp, code, message, headers, newurl):
        _url(newurl)
        self.chain.append({"status": code, "from": original.full_url, "to": newurl})
        result = super().redirect_request(original, fp, code, message, headers, newurl)
        if result and _origin(original.full_url) != _origin(newurl):
            for key in ("Authorization", "Cookie"):
                result.remove_header(key)
        return result


def fetch(session, config, label, url, *, accept="application/vnd.api+json", max_bytes=16777216):
    url = _url(url)
    output = session.out / "receiving"
    output.mkdir(exist_ok=True)
    record_path = output / (label + ".response.json")
    body_path = output / (label + ".body")
    redirect = Redirects()
    started = base._now()
    status, final_url, response_headers, failure, count = None, url, {}, None, 0
    digest = hashlib.sha256()
    temporary = body_path.with_name(body_path.name + ".partial")
    try:
        session.check()
        client = request.build_opener(redirect)
        req = request.Request(url, headers=_headers(config, session.p["uri"], url, accept), method="GET")
        try:
            response = client.open(req, timeout=min(30, session.p["timeout_seconds"]))
        except error.HTTPError as actual:
            response = actual
        with response:
            status, final_url = response.code, response.geturl()
            response_headers = {key.lower(): value for key, value in response.headers.items()
                                if key.lower() in {"content-type", "content-length", "etag", "last-modified", "location", "date", "content-language"}}
            with temporary.open("wb") as stream:
                while True:
                    session.check()
                    chunk = response.read(1024 * 1024)
                    if not chunk:
                        break
                    if count + len(chunk) > max_bytes:
                        raise ValueError("This original receiving body exceeds its selected byte limit.")
                    stream.write(chunk)
                    digest.update(chunk)
                    count += len(chunk)
                stream.flush()
                os.fsync(stream.fileno())
        os.replace(temporary, body_path)
    except base.NativeCancelled:
        raise
    except Exception as exc:
        failure = {"class": type(exc).__name__, "message": str(exc)}
    result = {"schema": "govhub.content-http-response.v1", "method": "GET", "url": url,
              "status": status, "final_url": final_url, "redirects": redirect.chain, "headers": response_headers,
              "started_at": started, "finished_at": base._now(), "error": failure}
    if body_path.is_file() and failure is None:
        result["body"] = {"path": str(body_path), "sha256": digest.hexdigest(), "bytes": count}
        session.add(body_path, "native_http_body", requested_url=url, status=status, content_type=response_headers.get("content-type"))
    elif temporary.is_file():
        result["partial_body"] = base._file(temporary, "incomplete_http_body")
        session.add(temporary, "incomplete_http_body", requested_url=url, status=status)
    base._atomic(record_path, result)
    session.add(record_path, "native_http_response")
    return result


def _row_key(value):
    return value.get("migration_id"), tuple(value.get("source_ids") or [])


def _same_place(left, right, *, query=True):
    a, b = parse.urlsplit(left), parse.urlsplit(right)
    return (_origin(left) == _origin(right)
            and parse.unquote(a.path or "/") == parse.unquote(b.path or "/")
            and (not query or a.query == b.query))


def _native_path_url(uri, path):
    if (not isinstance(path, str) or not path.startswith("/") or path.startswith("//")
            or parse.urlsplit(path).query or parse.urlsplit(path).fragment):
        raise ValueError("The original native alias and canonical path must be ordinary site paths.")
    site = parse.urlsplit(uri)
    root = parse.urlunsplit((site.scheme, site.netloc, site.path.rstrip("/") + "/", "", ""))
    return _url(parse.urljoin(root, parse.quote(path.lstrip("/"), safe="/:@-._~!$&'()*+,;=%")))


def _alias_snapshot(target, observation=None):
    if (not target or target.get("exists") is not True or not target.get("uuid")
            or not target.get("destination_ids")):
        raise ValueError("The selected native alias has no retained existing UUID.")
    fields = target.get("native_fields") or {}
    def field(name, fallback):
        values = fields.get(name)
        if isinstance(values, list) and len(values) == 1 and isinstance(values[0], dict):
            return values[0].get("value")
        return (observation or {}).get(fallback)
    return {key: target.get(key) for key in
            ("migration_id", "source_ids", "destination_ids", "uuid", "langcode")} | {
                "alias": field("alias", "native_alias"), "path": field("path", "native_path")}


def _receive_alias(session, config, native, route, migration, attempt, index):
    """Receive one original alias row through its native identity and real URL."""
    key = _row_key(route)
    observed = next((item for item in native.get("route_observations", [])
                     if item.get("mapping") == route), {})
    target = next((item for item in native.get("targets", []) if _row_key(item) == key), None)
    rollback = next((item for item in native.get("rollback", []) if _row_key(item) == key), None)
    rollback = rollback if native.get("action") == "rollback" else None
    result = {"mapping": route, "matched": False, "observation": "alias_resolution",
              "native_route": observed, "expected_present": not rollback or rollback.get("action") == "PRESERVE"}
    try:
        if migration.get("destination", {}).get("plugin") != "entity:path_alias":
            raise ValueError("The selected route is not bound to its original alias migration.")
        old = _url(parse.urljoin(session.p["uri"].rstrip("/") + "/", route["old_url"]))
        expected = _url(parse.urljoin(session.p["uri"].rstrip("/") + "/", route["new_url"]))
        result["expected_target_url"] = expected
        selected_action = rollback.get("action") if rollback else None
        if rollback:
            result["rollback_action"] = selected_action
            result["native_rollback"] = rollback
            target = rollback.get("before")
        if selected_action in {"ALREADY_UNMAPPED", "REMOVE_FAILED_MAP"} and not target:
            if rollback.get("destination_ids") or observed.get("kind") == "alias":
                raise ValueError("The original unmapped result still contains a mapped alias destination.")
            if selected_action == "ALREADY_UNMAPPED" and rollback.get("native_map_before") is not None:
                raise ValueError("The original already-unmapped result still contains a source map.")
            if _origin(old) != _origin(session.p["uri"]):
                raise ValueError("The selected removed alias URL belongs to another native site.")
            result["observation"] = "alias_unmapped"
        else:
            if not target or _row_key(target) != key or target.get("entity_type") != "path_alias":
                raise ValueError("The selected native alias row is missing from the original result.")
            snapshot = _alias_snapshot(target, observed if not rollback else None)
            for field in migration.get("receiving", {}).get("fields", []):
                if field not in (target.get("native_fields") or {}):
                    raise ValueError("The original native alias field is unavailable: " + field)
            alias_url = _native_path_url(session.p["uri"], snapshot["alias"])
            canonical_url = _native_path_url(session.p["uri"], snapshot["path"])
            result.update(native_alias=snapshot, canonical_url=canonical_url)
            if not _same_place(old, alias_url, query=False):
                raise ValueError("The selected old URL differs from the native alias's original site path.")
            if not any(_same_place(expected, candidate, query=False) for candidate in (alias_url, canonical_url)):
                raise ValueError("The selected target URL differs from the native alias or its canonical path.")
            if route.get("langcode") and route["langcode"] != snapshot["langcode"]:
                raise ValueError("The selected alias language differs from its native row.")
            if rollback:
                after = rollback.get("after")
                if not isinstance(after, dict) or any(after.get(field) != target.get(field)
                    for field in ("migration_id", "source_ids", "destination_ids", "entity_type")):
                    raise ValueError("The original rollback after-state does not identify this same alias row.")
                if selected_action == "DELETE":
                    if after.get("exists") is not False or after.get("entity_exists"):
                        raise ValueError("The selected native rollback did not remove its original alias entity.")
                    result["observation"] = "alias_removed"
                elif selected_action == "PRESERVE":
                    if _alias_snapshot(after) != snapshot:
                        raise ValueError("The selected preserved alias changed its native UUID, path or identity.")
                    result["observation"] = "alias_preserved"
                else:
                    raise ValueError("The original alias rollback has no supported retained outcome.")
            elif (observed.get("kind") != "alias"
                  or any(observed.get(field) != snapshot[value] for field, value in
                         (("native_uuid", "uuid"), ("native_alias", "alias"),
                          ("native_path", "path"), ("native_langcode", "langcode")))):
                raise ValueError("The original alias map and route observation identify different native destinations.")
        response = fetch(session, config, f"pass-{attempt:04d}-alias-{index:05d}", old,
                         accept="text/html,application/xhtml+xml,application/json;q=0.8,*/*;q=0.5")
        result["http"] = response
        if result["expected_present"]:
            allowed = (old, expected, result["canonical_url"])
            matched = (response["status"] == 200 and not response.get("error")
                       and any(_same_place(response["final_url"], value) for value in allowed))
        else:
            matched = (response["status"] in (404, 410) and not response.get("error")
                       and _same_place(response["final_url"], old))
        result["matched"] = matched
        if not matched:
            result["issue"] = ("The original alias did not resolve to its retained native target."
                               if result["expected_present"] else
                               "The selected removed or unmapped alias still resolves, or its original HTTP result is unavailable.")
    except base.NativeCancelled:
        raise
    except (ValueError, TypeError, KeyError) as exc:
        result["issue"] = str(exc)
    result["status"] = "COMPLETE" if result["matched"] else "FAILED"
    return result


def receive(session, config, native, plan, attempt):
    items, routes, problems = [], [], []
    cache = {}
    action = native.get("action")
    alias_migrations = {item["id"]: item for item in plan.get("migrations", [])
                        if item.get("destination", {}).get("plugin") == "entity:path_alias"}
    alias_routes = {_row_key(route) for route in plan.get("routes", [])
                    if route.get("migration_id") in alias_migrations}
    targets = list(native.get("targets", [])) if action != "rollback" else []
    if action == "rollback":
        for item in native.get("rollback", []):
            before = item.get("before")
            if before and (before.get("jsonapi", {}).get("available") or before.get("entity_type") == "path_alias"):
                targets.append({**before, "expected_present": item["action"] == "PRESERVE",
                                "rollback_action": item["action"], "after": item.get("after")})
    serial = 0
    network_failed = False
    for target in targets:
        session.check()
        selected = {key: target.get(key) for key in ("migration_id", "source_ids", "destination_ids", "entity_type", "bundle", "uuid", "langcode")}
        if target.get("entity_type") == "path_alias" and _row_key(target) in alias_routes:
            # The original native alias and actual route are received below,
            # independently of the account's JSON:API alias administration access.
            continue
        if not target.get("exists"):
            selected.update(status="FAILED", issue="The native mapped entity or selected translation is missing.")
            items.append(selected)
            problems.append(selected)
            continue
        if target.get("field_errors"):
            problems.append({**selected, "issue": "Selected native fields are unavailable.", "fields": target["field_errors"]})
        api = target.get("jsonapi") or {}
        if not api.get("available"):
            # Alias/redirect entities are received through the selected real route.
            route_bound = any(route.get("migration_id") == target["migration_id"]
                              and route.get("source_ids") == target["source_ids"] for route in plan.get("routes", []))
            if target["entity_type"] in ("path_alias", "redirect") and route_bound:
                selected.update(status="ROUTE_RECEIVING", detail=api.get("reason"))
            else:
                selected.update(status="FAILED", issue=api.get("reason", "The target has no installed JSON:API route."))
                problems.append(selected)
            items.append(selected)
            continue
        if network_failed:
            selected.update(status="PENDING", issue="Receiving stopped after the original target connection failed.")
            items.append(selected)
            problems.append(selected)
            continue
        url = api["url"]
        if url not in cache:
            serial += 1
            cache[url] = fetch(session, config, f"pass-{attempt:04d}-entity-{serial:05d}", url)
        response = cache[url]
        selected["http"] = response
        expected_present = target.get("expected_present", True)
        valid = False
        if not response.get("error") and response["status"] == 200 and response.get("body"):
            try:
                body = json.loads(Path(response["body"]["path"]).read_bytes())
                data = body.get("data")
                identity_matches = isinstance(data, dict) and data.get("id") == api["uuid"] and data.get("type") == api["type"]
                language_field = api.get("langcode_field")
                language_matches = not language_field or (identity_matches and data.get("attributes", {}).get(language_field) == target.get("langcode"))
                valid = expected_present and identity_matches and language_matches
                translation_fallback = (not expected_present and identity_matches and language_field
                                        and target.get("after", {}).get("missing_translation") == target.get("langcode")
                                        and data.get("attributes", {}).get(language_field) != target.get("langcode"))
                if translation_fallback:
                    valid = True
                    selected["translation_outcome"] = "The selected translation is removed; the actual endpoint returns another language."
                if valid:
                    selected["received"] = {"id": data["id"], "type": data["type"],
                                            "attributes": data.get("attributes", {}), "relationships": data.get("relationships", {})}
                    for native_field, public_field in api.get("field_names", {}).items():
                        if public_field not in data.get("attributes", {}) and public_field not in data.get("relationships", {}) and public_field != "id":
                            problems.append({**selected, "issue": "The original JSON:API body omitted the selected field.", "field": native_field, "public_field": public_field})
                            valid = False
                    if expected_present:
                        for native_field, references in target.get("relationships", {}).items():
                            public_field = api.get("field_names", {}).get(native_field)
                            relation = data.get("relationships", {}).get(public_field, {}).get("data")
                            linked = relation if isinstance(relation, list) else [relation] if isinstance(relation, dict) else []
                            received_ids = [item.get("id") for item in linked]
                            expected_ids = [item["uuid"] for item in references]
                            if received_ids != expected_ids:
                                problems.append({**selected, "issue": "The original JSON:API relationship differs from the native referenced UUID order.",
                                                 "field": native_field, "expected_uuids": expected_ids, "received_uuids": received_ids})
                                valid = False
                else:
                    selected["issue"] = "The original JSON:API resource identity differs from the native destination UUID/type."
            except (ValueError, TypeError) as exc:
                selected["issue"] = "The original receiving body is not a JSON:API resource: " + str(exc)
        elif not expected_present and response["status"] in (404, 410) and not response.get("error"):
            valid = True
        selected["status"] = "COMPLETE" if valid else "FAILED"
        if not valid:
            selected.setdefault("issue", "The selected native UUID did not return its expected original JSON:API response.")
            problems.append(selected)
        if response.get("error") and response.get("status") is None:
            network_failed = True
        file = target.get("file")
        if expected_present and file:
            if file.get("source_matches") is False or not file.get("exists"):
                selected["status"] = "FAILED"
                problems.append({**selected, "issue": "Native media bytes differ from the retained original file.", "file": file})
            elif not network_failed:
                file_url = file["url"]
                if file_url not in cache:
                    serial += 1
                    cache[file_url] = fetch(session, config, f"pass-{attempt:04d}-file-{serial:05d}", file_url,
                                            accept="*/*", max_bytes=min(session.p["max_artifact_bytes"], file["bytes"] + 1))
                file_response = cache[file_url]
                matched = file_response["status"] == 200 and not file_response.get("error") and file_response.get("body", {}).get("sha256") == file["sha256"]
                selected["file_receiving"] = {"matched": matched, "http": file_response, "expected_sha256": file["sha256"], "source_file_id": file.get("source_file_id")}
                if not matched:
                    selected["status"] = "FAILED"
                    problems.append({**selected, "issue": "The original HTTP media response differs from the native file bytes."})
        items.append(selected)
    for index, route in enumerate(plan.get("routes", []), 1):
        if route.get("migration_id") in alias_migrations:
            received = _receive_alias(session, config, native, route,
                                      alias_migrations[route["migration_id"]], attempt, index)
            routes.append(received)
            identity = received.get("native_alias") or {
                "migration_id": route.get("migration_id"), "source_ids": route.get("source_ids")}
            items.append({**identity, "entity_type": "path_alias", "status": received["status"],
                          "route_index": index, "observation": received["observation"],
                          "expected_present": received["expected_present"],
                          **({"issue": received["issue"]} if received.get("issue") else {})})
            if not received["matched"]:
                problems.append(received)
            continue
        if action == "rollback":
            continue
        session.check()
        old = _url(parse.urljoin(session.p["uri"].rstrip("/") + "/", route["old_url"]))
        expected = _url(parse.urljoin(session.p["uri"].rstrip("/") + "/", route["new_url"]))
        response = fetch(session, config, f"pass-{attempt:04d}-route-{index:05d}", old, accept="text/html,application/xhtml+xml,application/json;q=0.8,*/*;q=0.5")
        final = parse.urldefrag(response["final_url"])[0]
        native_route = next((item for item in native.get("route_observations", []) if item.get("mapping") == route), {})
        alias_matches = (native_route.get("kind") == "alias" and _origin(old) == _origin(session.p["uri"])
                         and parse.unquote(parse.urlsplit(old).path) == native_route.get("native_alias")
                         and parse.unquote(parse.urlsplit(expected).path) == native_route.get("native_path")
                         and _origin(expected) == _origin(session.p["uri"])
                         and final in (parse.urldefrag(old)[0], parse.urldefrag(expected)[0]))
        matched = response["status"] == 200 and not response.get("error") and (alias_matches or final == parse.urldefrag(expected)[0])
        item = {"mapping": route, "expected_target_url": expected, "matched": matched, "http": response,
                "native_route": native_route, "observation": "alias_resolution" if alias_matches else "http_final_url"}
        routes.append(item)
        if not matched:
            problems.append({"issue": "The selected old URL did not resolve to its exact mapped target.", **item})
    result = {"schema": "govhub.content-consolidation.receiving.v1", "observed_at": base._now(),
              "status": "COMPLETE" if not problems else "FAILED", "items": items, "routes": routes,
              "problems": problems, "counts": {"resources": len(items), "routes": len(routes), "problems": len(problems)}}
    path = session.out / f"receiving-{attempt:04d}.json"
    base._atomic(path, result)
    session.add(path, "content_receiving")
    return result

"""Original source editions, stable keys, and exact source-change comparison."""
import io
from copy import deepcopy
from urllib.parse import urljoin

from govhub import GovHubError, digest, instant, json_bytes, packed, text
from .tabular import CsvSource, csv_options

MISSING = object()


def at(value, path):
    """Literal top-level field or RFC 6901 JSON pointer; never guess dot notation."""
    if not isinstance(path, str):
        return MISSING
    if isinstance(value, dict) and path in value:
        return value[path]
    if path == "":
        return value
    if not path.startswith("/"):
        return MISSING
    result = value
    for token in path[1:].split("/"):
        token = token.replace("~1", "/").replace("~0", "~")
        if isinstance(result, dict):
            result = result.get(token, MISSING)
        elif isinstance(result, list) and token.isdecimal() and int(token) < len(result):
            result = result[int(token)]
        else:
            return MISSING
    return result


def issue(code, message, **context):
    return dict(code=code, message=message, **context)


def keys_for(row, fields, encoding="string"):
    values = []
    for field in fields:
        value = at(row, field)
        if isinstance(value, int) and not isinstance(value, bool) and encoding == "decimal":
            value = str(value)
        if not isinstance(value, str) or not value or any(ord(c) < 32 for c in value):
            raise GovHubError("SOURCE_KEY", "Each source key must be a nonempty exact string. Select decimal encoding explicitly for original integer keys.", fields={field: "Supply the original string key or select decimal integer encoding."})
        values.append(value)
    return values


def parse_edition(descriptor, originals):
    """Retain every selected source row, including actionable duplicate-key rows."""
    format_ = descriptor.get("format", "JSON").upper()
    if format_ not in {"CSV", "JSON", "JSON_API"}:
        raise GovHubError("CONTENT_FORMAT", "Select CSV, JSON, or original JSON:API pages.")
    keys = descriptor.get("record_keys", [])
    if not isinstance(keys, list) or not keys or len(set(keys)) != len(keys) or any(not isinstance(k, str) or not k for k in keys):
        raise GovHubError("CONTENT_KEYS", "Select the original unique key fields in their original order.")
    encoding = descriptor.get("key_encoding", "string")
    if encoding not in {"string", "decimal"}:
        raise GovHubError("CONTENT_KEYS", "Choose string or explicit decimal integer source keys.")
    if not originals:
        raise GovHubError("CONTENT_SOURCE", "Select the original source file or all original source pages.")
    rows, problems, fields, seen = [], [], set(), {}
    selected_csv = csv_options(descriptor) if format_ == "CSV" else None
    csv_headers = []
    for page_index, original in enumerate(originals):
        file, content = original["file"], original["bytes"]
        request_url = original.get("request_url", "")
        if format_ == "CSV":
            try:
                source_rows = CsvSource(io.StringIO(content.decode("utf-8-sig"), newline=""), selected_csv)
            except UnicodeError as exc:
                raise GovHubError("CONTENT_CSV", "Read the complete UTF-8 CSV source: " + str(exc)) from exc
            csv_headers.append({"file_id": file["id"], "file_sha256": file["sha256"], "headers": source_rows.headers, "header_line_end": source_rows.header_line_end})
        else:
            source = json_bytes(content)
            source_rows = at(source, descriptor.get("records_pointer", "/data" if format_ == "JSON_API" else ""))
            if not isinstance(source_rows, list):
                raise GovHubError("CONTENT_ROWS", "The selected JSON pointer must identify the original complete row array.")
            if format_ == "JSON_API":
                links = source.get("links", {}) if isinstance(source, dict) else {}
                next_url = links.get("next") if isinstance(links, dict) else None
                if isinstance(next_url, dict):
                    next_url = next_url.get("href")
                actual_next = urljoin(request_url, next_url) if isinstance(next_url, str) and next_url else None
                supplied_next = originals[page_index + 1].get("request_url") if page_index + 1 < len(originals) else None
                if actual_next != (supplied_next or None):
                    problems.append(issue("PAGE_SEQUENCE", "Retain the next original JSON:API page at its exact request URL, or end at the native terminal page.", file_id=file["id"], next_url=actual_next, supplied_next=supplied_next))
        for ordinal, source_row in enumerate(source_rows, 1):
            value = source_row["data"] if format_ == "CSV" else source_row
            if not isinstance(value, dict):
                raise GovHubError("CONTENT_ROW", "Each selected record must be an original JSON object or CSV row.")
            fields.update(value)
            entry = {"row": len(rows) + 1, "file_id": file["id"], "file_sha256": file["sha256"], "source_row": ordinal, "data": deepcopy(value), "row_sha256": digest(packed(value))}
            if format_ == "CSV":
                entry.update(source_line_start=source_row["source_line_start"], source_line_end=source_row["source_line_end"])
            try:
                entry["keys"] = keys_for(value, keys, encoding)
                identity = packed(entry["keys"])
                if identity in seen:
                    problems.append(issue("DUPLICATE_SOURCE_KEY", "This source key occurs more than once in the selected edition.", keys=entry["keys"], rows=[seen[identity], entry["row"]]))
                else:
                    seen[identity] = entry["row"]
            except GovHubError as exc:
                entry["keys"] = []
                problems.append(issue(exc.code, exc.message, row=entry["row"], fields=exc.fields))
            rows.append(entry)
    expected = descriptor.get("expected_records")
    if expected is not None and (isinstance(expected, bool) or not isinstance(expected, int) or expected < 0):
        raise GovHubError("CONTENT_COUNT", "The source's declared record count must be a nonnegative integer.")
    if expected is not None and expected != len(rows):
        problems.append(issue("SOURCE_COUNT", "The retained source count differs from the supplied original declaration.", expected=expected, retained=len(rows)))
    result = {"source_id": text(descriptor.get("source_id", ""), 240, True), "label": text(descriptor.get("label", ""), 500, True), "observed_at": instant(descriptor.get("observed_at", ""), True), "format": format_, "record_keys": keys, "key_encoding": encoding, "records_pointer": descriptor.get("records_pointer", ""), "source_url": text(descriptor.get("source_url", ""), 4000), "source_owner": text(descriptor.get("source_owner", ""), 500), "license_reference": text(descriptor.get("license_reference", ""), 4000), "retention_instruction": text(descriptor.get("retention_instruction", ""), 8000), "files": [{**item["file"], "request_url": item.get("request_url", "")} for item in originals], "rows": rows, "row_count": len(rows), "fields": sorted(fields), "issues": problems, "source_sha256": digest(packed([{k: r[k] for k in ("keys", "row_sha256")} for r in rows]))}
    if format_ == "CSV":
        result.update(csv_options=selected_csv, csv_headers=csv_headers)
    return result


def compare_editions(before, after):
    if before["source_id"] != after["source_id"] or before["record_keys"] != after["record_keys"]:
        raise GovHubError("CONTENT_COMPARISON", "Compare editions of the same original feed and key fields.")
    def index(edition):
        result = {}
        for row in edition["rows"]:
            key = packed(row["keys"])
            if not row["keys"] or key in result:
                raise GovHubError("CONTENT_COMPARISON", "Resolve missing or duplicate keys before comparing this edition.")
            result[key] = row
        return result
    a, b = index(before), index(after)
    changed, unchanged = [], []
    for identity in sorted(set(a) & set(b)):
        old, new = a[identity], b[identity]
        if old["row_sha256"] == new["row_sha256"]:
            unchanged.append(new["keys"])
        else:
            names = sorted(set(old["data"]) | set(new["data"]))
            changed.append({"keys": new["keys"], "before": old, "after": new, "fields": [{"field": name, "before_present": name in old["data"], "after_present": name in new["data"], "before": old["data"].get(name), "after": new["data"].get(name)} for name in names if (name in old["data"], old["data"].get(name)) != (name in new["data"], new["data"].get(name))]})
    return {"before_id": before["id"], "after_id": after["id"], "source_id": before["source_id"], "added": [b[k] for k in sorted(set(b) - set(a))], "removed": [a[k] for k in sorted(set(a) - set(b))], "changed": changed, "unchanged": unchanged}

"""Content consolidation in GovHub's existing store, worker and receiving carrier."""
from copy import deepcopy
from pathlib import Path
import json
import re

from govhub import GovHubError, digest, ident, now, packed, text
from .model import compare_editions, parse_edition
from .tabular import csv_options, inspect_csv
from .compiler import compile_mapping
from .delivery import ContentDeliveryMixin

CONTENT_TYPES = {"CONTENT_IMPORT", "CONTENT_ROLLBACK", "CONTENT_STATUS", "CONTENT_RECEIVE"}
ACTIONS = {"CONTENT_IMPORT": "drupal-content-import", "CONTENT_ROLLBACK": "drupal-content-rollback", "CONTENT_STATUS": "drupal-content-status", "CONTENT_RECEIVE": "drupal-content-receive"}


class NativeFacade:
    def __init__(self, original):
        self.original = original

    def __getattr__(self, name):
        return getattr(self.original, name)

    def configuration_schema(self):
        schema = deepcopy(self.original.configuration_schema())
        for provider in schema["providers"]:
            if provider["value"] == "drush":
                provider["fields"].extend([
                    {"name": "jsonapi_bearer_env", "label": "JSON:API bearer environment variable", "type": "text", "required": False},
                    {"name": "jsonapi_cookie_env", "label": "JSON:API cookie environment variable", "type": "text", "required": False},
                ])
        return schema

    @staticmethod
    def _original_config(config):
        return {k: v for k, v in config.items() if k not in {"jsonapi_bearer_env", "jsonapi_cookie_env"}}

    def discover_capabilities(self, config, **options):
        return self.original.discover_capabilities(self._original_config(config), **options)

    def capture(self, config, context, checkpoint=None, cancelled=None):
        return self.original.capture(self._original_config(config), context, checkpoint=checkpoint, cancelled=cancelled)

    def execute(self, operation, config, source_paths, checkpoint=None, cancelled=None):
        if operation.get("type") in CONTENT_TYPES:
            from .drupal.adapter import execute
            return execute(operation, config, source_paths, checkpoint=checkpoint, cancelled=cancelled)
        return self.original.execute(operation, self._original_config(config), source_paths, checkpoint=checkpoint, cancelled=cancelled)


class ContentMixin(ContentDeliveryMixin):
    def _operations_configure(self, payload, actor):
        config = payload.get("config")
        if isinstance(config, dict):
            for name in ("jsonapi_bearer_env", "jsonapi_cookie_env"):
                if config.get(name) and (not isinstance(config[name], str) or not re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", config[name])):
                    raise GovHubError("JSONAPI_ENV_REFERENCE", "Supply only the name of the existing private JSON:API environment variable.", fields={name: "Use an environment-variable name, not a credential value."})
        return super()._operations_configure(payload, actor)

    def _native(self):
        return NativeFacade(super()._native())

    def _content_family(self, db, identity):
        family = self._get(db, "content_family", identity)
        versions = self._objects(db, "content_family_version", identity)
        return dict(family, **versions[-1]["data"], revision=versions[-1]["id"]) if versions else dict(family, revision=family["id"])

    def _content_summary(self, db):
        families = []
        for stored in self._objects(db, "content_family"):
            family = self._content_family(db, stored["id"])
            editions = self._objects(db, "content_edition", family["id"])
            mappings = self._objects(db, "content_mapping", family["id"])
            reviews = self._objects(db, "content_review", family["id"])
            family.update(source_count=len({e["source_id"] for e in editions}), edition_count=len(editions), latest_mapping_id=mappings[-1]["id"] if mappings else "", latest_review=reviews[-1] if reviews else None)
            families.append(family)
        return {"families": families, "observed_at": now()}

    def _content_compile(self, db, family, definition):
        editions = {e["id"]: e for e in self._objects(db, "content_edition", family["id"])}
        files = {row["id"]: dict(row) for row in db.execute("SELECT * FROM files")}
        result = compile_mapping(family, definition, editions, files)
        selected = {m["id"] for m in result["migrations"]}
        for other in self._objects(db, "content_mapping"):
            if other["family_id"] != family["id"] and self._content_family(db, other["family_id"])["environment_id"] == family["environment_id"]:
                overlap = selected & {m["id"] for m in other["definition"].get("migrations", [])}
                if overlap:
                    raise GovHubError("MIGRATION_OWNERSHIP", "These native migration IDs already belong to another consolidation: " + ", ".join(sorted(overlap)), 409)
        return result

    def _content_family_save(self, payload, actor):
        with self.connect(write=True) as db:
            key, fingerprint, prior = self._request(db, payload, actor)
            if prior:
                return prior
            environment = self._record_db(db, "environments", payload.get("environment_id"))
            if environment["archived"]:
                raise GovHubError("CONTENT_TARGET", "Select an active original target environment.")
            limits = payload.get("limits", {})
            if not isinstance(limits, dict) or set(limits) - {"migrations", "records", "files", "file_bytes", "routes"} or any(isinstance(v, bool) or not isinstance(v, int) or v < 0 for v in limits.values()):
                raise GovHubError("CONTENT_SCOPE", "Retain the agreed nonnegative whole-number scope quantities.")
            data = {"label": text(payload.get("label", ""), 500, True), "environment_id": environment["id"], "owner": text(payload.get("owner", actor["name"]), 500, True), "notes": text(payload.get("notes", ""), 16000), "comparison_id": text(payload.get("comparison_id", ""), 240), "limits": limits, "recovery_instruction": text(payload.get("recovery_instruction", ""), 16000)}
            if payload.get("family_id"):
                current = self._content_family(db, payload["family_id"])
                if current["revision"] != payload.get("expected_revision"):
                    raise GovHubError("CONTENT_REVISION", "Reopen the current consolidation before changing its scope.", 409)
                if data["environment_id"] != current["environment_id"]:
                    raise GovHubError("CONTENT_TARGET", "A consolidation retains its original target. Create a distinct consolidation for a different target.", 409)
                self._object(db, "content_family_version", {"family_id": current["id"], "data": data}, parent=current["id"], actor=actor["name"])
                family = self._content_family(db, current["id"])
            else:
                family = self._object(db, "content_family", data, actor=actor["name"], object_id=ident("content-"))
                family["revision"] = family["id"]
            result = {"family": family}
            self._remember(db, key, fingerprint, result, actor)
            self._changed(db, actor, "Content consolidation scope saved", "content_family", family["id"])
            return result

    def _content_source_inspect(self, payload, actor):
        options = csv_options(payload)
        descriptors = payload.get("files", [])
        if not isinstance(descriptors, list) or not descriptors:
            raise GovHubError("CONTENT_SOURCE", "Choose the retained original CSV files.")
        offset, limit = payload.get("offset", 0), payload.get("limit", 25)
        if isinstance(offset, bool) or not isinstance(offset, int) or offset < 0:
            raise GovHubError("CONTENT_SOURCE_PAGE", "The source offset must be a nonnegative record number.")
        if isinstance(limit, bool) or not isinstance(limit, int) or not 1 <= limit <= 250:
            raise GovHubError("CONTENT_SOURCE_PAGE", "Choose between 1 and 250 displayed original records.")
        result = {"format": "CSV", "csv_options": options, "files": [], "rows": [], "issues": [], "headers": [], "offset": offset, "limit": limit, "complete": True, "row_count": 0, "observed_records": 0}
        seen, known_headers = set(), set()
        with self.connect(snapshot=True) as db:
            for descriptor in descriptors:
                if isinstance(descriptor, str):
                    descriptor = {"file_id": descriptor}
                if not isinstance(descriptor, dict):
                    raise GovHubError("CONTENT_SOURCE", "Choose a retained source file identifier.")
                file = self._file_row(db, descriptor.get("file_id"))
                if file["id"] in seen:
                    raise GovHubError("CONTENT_SOURCE", "Include each retained original CSV once.")
                seen.add(file["id"])
                if file["bytes"] > 128 * 1024 * 1024:
                    raise GovHubError("CONTENT_SOURCE_SIZE", "Select a source export within the existing 128 MiB row-intake limit.")
                path = self._verify_file(file)
                remaining = max(0, limit - len(result["rows"]))
                local_offset = max(0, offset - result["observed_records"])
                try:
                    with path.open("r", encoding="utf-8-sig", newline="") as stream:
                        observed = inspect_csv(stream, options, local_offset, remaining)
                except GovHubError as exc:
                    observed = {"headers": [], "complete": False, "row_count": None, "observed_records": 0, "rows": [], "issues": [{"code": exc.code, "message": exc.message}]}
                for header in observed["headers"]:
                    if header not in known_headers:
                        known_headers.add(header)
                        result["headers"].append(header)
                start = result["observed_records"]
                result["rows"].extend({**row, "row": start + row["source_row"], "file_id": file["id"], "file_sha256": file["sha256"]} for row in observed["rows"])
                result["issues"].extend({**item, "file_id": file["id"]} for item in observed["issues"])
                result["files"].append({**file, **{k: v for k, v in observed.items() if k not in {"rows", "issues"}}})
                result["observed_records"] += observed["observed_records"]
                result["complete"] = result["complete"] and observed["complete"]
        result["row_count"] = result["observed_records"] if result["complete"] else None
        return result

    def _content_edition_create(self, payload, actor):
        with self.connect(write=True) as db:
            key, fingerprint, prior = self._request(db, payload, actor)
            if prior:
                return prior
            family = self._content_family(db, payload.get("family_id"))
            descriptors = payload.get("files", [])
            if not isinstance(descriptors, list) or not descriptors:
                raise GovHubError("CONTENT_SOURCE", "Choose the original source file or all original API pages.")
            originals, ids = [], set()
            for descriptor in descriptors:
                if isinstance(descriptor, str):
                    descriptor = {"file_id": descriptor}
                file = self._file_row(db, descriptor.get("file_id"))
                if file["id"] in ids:
                    raise GovHubError("CONTENT_SOURCE", "Include each original source page once.")
                ids.add(file["id"])
                if file["bytes"] > 128 * 1024 * 1024:
                    raise GovHubError("CONTENT_SOURCE_SIZE", "Select a source export within the existing 128 MiB row-intake limit; retain large media through source-file bindings.")
                originals.append({"file": file, "bytes": self._verify_file(file).read_bytes(), "request_url": text(descriptor.get("request_url", ""), 8000)})
            parsed = parse_edition(payload, originals)
            previous = [e for e in self._objects(db, "content_edition", family["id"]) if e["source_id"] == parsed["source_id"]]
            if previous and previous[-1]["record_keys"] != parsed["record_keys"]:
                raise GovHubError("CONTENT_KEYS_CHANGED", "An existing feed keeps its original key fields. Use a new source namespace for a different identity scheme.")
            edition = self._object(db, "content_edition", dict(parsed, family_id=family["id"], previous_edition_id=previous[-1]["id"] if previous else ""), parent=family["id"], actor=actor["name"])
            result = {"edition": self._content_edition_summary(edition)}
            self._remember(db, key, fingerprint, result, actor)
            self._changed(db, actor, "Complete original content edition retained", "content_edition", edition["id"], {"rows": edition["row_count"], "issues": len(edition["issues"])})
            return result

    @staticmethod
    def _content_edition_summary(edition):
        return {k: v for k, v in edition.items() if k != "rows"}

    def _content_mapping_save(self, payload, actor):
        definition = deepcopy(payload.get("definition"))
        if not isinstance(definition, dict):
            raise GovHubError("CONTENT_MAPPING", "Supply the complete native mapping definition.")
        for migration in definition.get("migrations", []):
            if isinstance(migration, dict) and isinstance(migration.get("process"), dict):
                migration.setdefault("process_order", list(migration["process"]))
        with self.connect(write=True) as db:
            key, fingerprint, prior = self._request(db, dict(payload, definition=definition), actor)
            if prior:
                return prior
            family = self._content_family(db, payload.get("family_id"))
            versions = self._objects(db, "content_mapping", family["id"])
            latest = versions[-1]["id"] if versions else ""
            if payload.get("expected_mapping_id", "") != latest:
                raise GovHubError("CONTENT_MAPPING_REVISION", "A newer mapping was saved. Reopen it before preparing the next complete edition.", 409)
            compiled = self._content_compile(db, family, definition)
            mapping = self._object(db, "content_mapping", {"family_id": family["id"], "family_revision": family["revision"], "label": text(payload.get("label", ""), 500, True), "definition": definition, "previous_mapping_id": latest, "compiled": compiled}, parent=family["id"], actor=actor["name"])
            result = {"mapping": mapping}
            self._remember(db, key, fingerprint, result, actor)
            self._changed(db, actor, "Complete content mapping edition saved", "content_mapping", mapping["id"], {"issues": len(compiled["issues"]), **compiled["counts"]})
            return result

    def _content_review_save(self, payload, actor):
        self._authorize(actor, "reviewer")
        if payload.get("decision") not in {"APPROVE", "RETURN"}:
            raise GovHubError("CONTENT_REVIEW", "Approve this mapping edition or return it for correction.")
        with self.connect(write=True) as db:
            key, fingerprint, prior = self._request(db, payload, actor)
            if prior:
                return prior
            mapping = self._get(db, "content_mapping", payload.get("mapping_id"))
            family = self._content_family(db, mapping["family_id"])
            if payload.get("mapping_sha256") != mapping["sha256"]:
                raise GovHubError("CONTENT_REVIEW_REVISION", "Review the exact retained mapping edition displayed here.", 409)
            compiled = self._content_compile(db, family, mapping["definition"])
            approve = payload["decision"] == "APPROVE"
            if approve and compiled["issues"]:
                raise GovHubError("CONTENT_REVIEW_ISSUES", "Resolve this edition's source and mapping issues before approving its import.", fields={"mapping": str(len(compiled["issues"])) + " retained source or mapping issues."})
            backup = None
            if payload.get("backup_file_id"):
                file = self._file_row(db, payload["backup_file_id"])
                self._verify_file(file)
                backup = {"file_id": file["id"], "sha256": file["sha256"], "bytes": file["bytes"]}
            if approve and compiled["allow_existing_updates"] and not backup:
                raise GovHubError("CONTENT_UPDATE_BACKUP", "Select the original target backup for this reviewed existing-record update.")
            review = self._object(db, "content_review", {"family_id": family["id"], "mapping_id": mapping["id"], "mapping_sha256": mapping["sha256"], "family_revision": family["revision"], "definition_sha256": compiled["definition_sha256"], "decision": payload["decision"], "reason": text(payload.get("reason", ""), 16000, True), "backup_ref": backup}, parent=family["id"], actor=actor["name"])
            plan = None
            if approve:
                editions = sorted({m["edition_id"] for m in mapping["definition"]["migrations"]})
                profile = self._config(db, family["environment_id"])
                native = {"schema": "govhub.content-consolidation.drupal-plan.v1", "id": ident("content-plan-"), "family_id": family["id"], "edition_id": mapping["id"], "label": mapping["label"], "source_refs": compiled["source_refs"], "migrations": compiled["migrations"], "files": compiled["files"], "routes": compiled["routes"], "review": {"id": review["id"], "actor": actor["name"], "at": review["created_at"], "note": review["reason"], "allow_existing_updates": compiled["allow_existing_updates"], "backup_ref": backup}}
                plan = self._object(db, "content_plan", {"id": native["id"], "family_id": family["id"], "family_revision": family["revision"], "mapping_id": mapping["id"], "mapping_sha256": mapping["sha256"], "review_id": review["id"], "edition_ids": editions, "profile_revision": profile["revision"], "native": native, "lineage": compiled["lineage"], "definition_sha256": compiled["definition_sha256"]}, parent=family["id"], actor=actor["name"])
            result = {"review": review, "plan": plan}
            self._remember(db, key, fingerprint, result, actor)
            self._changed(db, actor, "Exact content mapping review retained", "content_review", review["id"], {"decision": review["decision"]})
            return result

    def _content_operation_create(self, payload, actor):
        type_ = payload.get("type", "CONTENT_IMPORT")
        if type_ not in CONTENT_TYPES:
            raise GovHubError("CONTENT_OPERATION", "Select native import, rollback, status, or receiving.")
        with self.connect(write=True) as db:
            key, fingerprint, prior = self._request(db, payload, actor)
            if prior:
                return prior
            plan = self._get(db, "content_plan", payload.get("content_plan_id"))
            if payload.get("plan_sha256") != plan["sha256"]:
                raise GovHubError("CONTENT_PLAN_REVISION", "Choose the exact reviewed native plan edition.", 409)
            family = self._content_family(db, plan["family_id"])
            reviews = [r for r in self._objects(db, "content_review", family["id"]) if r["mapping_id"] == plan["mapping_id"]]
            if not reviews or reviews[-1]["id"] != plan["review_id"] or reviews[-1]["decision"] != "APPROVE" or family["revision"] != plan["family_revision"]:
                raise GovHubError("CONTENT_CURRENT_REVIEW", "Review this exact native plan against the current consolidation scope and decision.", 409)
            environment = self._record_db(db, "environments", family["environment_id"])
            profile = self._config(db, environment["id"])
            if environment["archived"] or environment["data"]["provider_resource_id"] != profile["config"]["environment_id"] or profile["revision"] != plan["profile_revision"] or environment["data"]["native_profile"] != profile["revision"]:
                raise GovHubError("CONTENT_NATIVE_TARGET", "The selected target/profile changed. Review the mapping against its current original configuration.", 409)
            if profile["config"].get("source_kind") != "drush":
                raise GovHubError("CONTENT_NATIVE_PROFILE", "Select the original Drush profile for the Drupal project; its Acquia hosting identity remains in the environment register.")
            if not environment["data"]["authorization_reference"]:
                raise GovHubError("CONTENT_TARGET_AUTHORITY", "Retain the original operating instruction in this target environment.")
            reason = text(payload.get("reason", ""), 16000, True)
            timestamp = now()
            value = {"id": ident("operation-"), "type": type_, "native_action": ACTIONS[type_], "state": "QUEUED", "plan_id": "", "plan_revision": plan["mapping_id"], "plan": None, "audit_id": None, "review_id": plan["review_id"], "environment_id": environment["id"], "environment": environment, "profile": profile, "provider_environment_id": profile["config"]["environment_id"], "source_snapshot_id": "", "source_snapshot": None, "source_snapshot_sha256": "", "authorization_reference": environment["data"]["authorization_reference"], "agency_ids": [family["comparison_id"]] if family["comparison_id"] else [], "content_family_id": family["id"], "content_plan_id": plan["id"], "content_plan_sha256": plan["sha256"], "content_reason": reason, "created_at": timestamp, "updated_at": timestamp, "author": actor["name"], "progress": {"completed": 0, "total": 1, "stage": "QUEUED", "detail": "Queued for the original Drupal migration engine"}, "error": None, "cancel_requested": False, "native_attempted": False, "checkpoint": None, "resume_checkpoint": None, "native_capture_file_id": None, "native_result": None, "result_snapshot_id": None, "actual_started_at": None, "actual_finished_at": None}
            if "content_row_limit" in payload:
                row_limit = payload["content_row_limit"]
                if isinstance(row_limit, bool) or not isinstance(row_limit, int) or row_limit < 0:
                    raise GovHubError("CONTENT_ROW_LIMIT", "Use zero for the full native pass or a positive native row count per continuation.")
                if type_ != "CONTENT_IMPORT" and row_limit:
                    raise GovHubError("CONTENT_ROW_LIMIT", "Native row continuation applies to content import.")
                value["content_row_limit"] = row_limit
            if type_ == "CONTENT_ROLLBACK":
                selection = payload.get("content_selection")
                if not isinstance(selection, list) or not selection:
                    raise GovHubError("CONTENT_ROLLBACK_SELECTION", "Select the original native migration/source IDs to roll back.")
                value["content_selection"] = deepcopy(selection)
            operation = self._write_operation(db, value, actor, "Reviewed native content work queued", {"content_plan_id": plan["id"], "definition_sha256": plan["definition_sha256"]})
            result = {"operation": operation}
            self._remember(db, key, fingerprint, result, actor)
        self._worker_wake.set()
        return result

    def _operation_sources(self, value, output_dir):
        if value.get("type") not in CONTENT_TYPES:
            return super()._operation_sources(value, output_dir)
        with self.connect(snapshot=True) as db:
            plan = self._get(db, "content_plan", value["content_plan_id"])
            if plan["sha256"] != value["content_plan_sha256"]:
                raise GovHubError("CONTENT_PLAN_CHANGED", "The original retained native plan changed.", 409)
            bindings = []
            ids = {item["file_id"] for item in plan["native"]["source_refs"]}
            ids.update(item["file_id"] for item in plan["native"]["files"])
            backup = plan["native"]["review"].get("backup_ref")
            if backup:
                ids.add(backup["file_id"])
            expected = {item["file_id"]: item for item in [*plan["native"]["source_refs"], *plan["native"]["files"], *([backup] if backup else [])]}
            for file_id in sorted(ids):
                item = self._file_row(db, file_id)
                if any(item[name] != expected[file_id][name] for name in ("sha256", "bytes")):
                    raise GovHubError("CONTENT_SOURCE_IDENTITY", "The retained original file differs from the reviewed native plan.", 409)
                path = self._verify_file(item)
                selected = next((f for f in plan["native"]["files"] if f["file_id"] == file_id), {})
                bindings.append({"file_id": file_id, "path": str(path), "sha256": item["sha256"], "bytes": item["bytes"], "relative_path": selected.get("relative_path", item["filename"])})
        return {"content_plan": deepcopy(plan["native"]), "content_files": bindings, "output_dir": str(output_dir), "checkpoint": value.get("resume_checkpoint") or value.get("checkpoint"), "workspace_relocations": self._workspace_relocations(), "snapshot_id": "", "snapshot_sha256": "", "rows": [], "bindings": []}

    def _content_native_completion(self, current, native_result):
        if current.get("type") in CONTENT_TYPES and native_result.get("status") == "COMPLETE":
            current["state"] = "COMPLETE"
            current["progress"] = {"completed": 1, "total": 1, "stage": "COMPLETE", "detail": "Original Drupal migration and selected receiving result retained"}

    def _content_dispatch(self, action, payload, actor):
        if action == "sources.inspect":
            return self._content_source_inspect(payload, actor)
        handlers = {"families.save": self._content_family_save, "editions.create": self._content_edition_create, "mappings.save": self._content_mapping_save, "reviews.save": self._content_review_save, "operations.create": self._content_operation_create}
        if action in handlers:
            return handlers[action](payload, actor)
        with self.connect(snapshot=True) as db:
            if action == "families.list":
                return self._content_summary(db)
            if action == "families.get":
                family = self._content_family(db, payload.get("family_id"))
                return {"family": family, "editions": [self._content_edition_summary(e) for e in self._objects(db, "content_edition", family["id"])], "mappings": [{k: v for k, v in m.items() if k not in {"compiled", "definition"}} for m in self._objects(db, "content_mapping", family["id"])], "reviews": self._objects(db, "content_review", family["id"]), "plans": [{k: v for k, v in p.items() if k not in {"native", "lineage"}} for p in self._objects(db, "content_plan", family["id"])], "operations": [self._operation_summary(o) for o in [json.loads(row[0]) for row in db.execute("SELECT data FROM govhub_operations ORDER BY rowid")] if o.get("content_family_id") == family["id"]]}
            if action == "editions.get":
                edition = self._get(db, "content_edition", payload.get("edition_id"))
                offset = max(0, int(payload.get("offset", 0)))
                limit = min(250, max(1, int(payload.get("limit", 50))))
                query = text(payload.get("query", ""), 2000).casefold()
                rows = [r for r in edition["rows"] if not query or query in packed(r).casefold()]
                return {"edition": self._content_edition_summary(edition), "rows": rows[offset:offset + limit], "offset": offset, "limit": limit, "total": len(rows)}
            if action == "editions.compare":
                return compare_editions(self._get(db, "content_edition", payload.get("before_id")), self._get(db, "content_edition", payload.get("after_id")))
            if action == "mappings.get":
                return {"mapping": self._get(db, "content_mapping", payload.get("mapping_id"))}
            if action == "mappings.preview":
                family = self._content_family(db, payload.get("family_id"))
                return {"compiled": self._content_compile(db, family, payload.get("definition", {}))}
            if action == "plans.get":
                return {"plan": self._get(db, "content_plan", payload.get("content_plan_id"))}
        raise GovHubError("CONTENT_ACTION", "This content-consolidation action does not exist.", 404)

"""Explicit CSV interpretation for retained source inspection and editions.

The original bytes remain in GovHub's source store. This module never sniffs a
dialect, normalizes a header, converts an identifier, or writes source files.
"""
import csv

from govhub import GovHubError


CSV_DEFAULTS = {"delimiter": ",", "quotechar": '"', "escapechar": None, "doublequote": True}


def csv_options(descriptor):
    raw = descriptor.get("csv_options", {})
    if raw is None:
        raw = {}
    if not isinstance(raw, dict) or set(raw) - set(CSV_DEFAULTS):
        raise GovHubError("CONTENT_CSV_OPTIONS", "Choose the CSV delimiter, quote character, escape character and doubled-quote setting.")
    selected = dict(CSV_DEFAULTS, **raw)
    for name in ("delimiter", "quotechar", "escapechar"):
        value = selected[name]
        if name != "delimiter" and value is None:
            continue
        if not isinstance(value, str) or len(value) != 1 or value in "\r\n\0":
            raise GovHubError("CONTENT_CSV_OPTIONS", name + " must be one original character" + (" or null." if name != "delimiter" else "."))
    if not isinstance(selected["doublequote"], bool):
        raise GovHubError("CONTENT_CSV_OPTIONS", "Choose whether the source doubles its quote character.")
    if selected["delimiter"] in {selected["quotechar"], selected["escapechar"]}:
        raise GovHubError("CONTENT_CSV_OPTIONS", "The delimiter must differ from the quote and escape characters.")
    if selected["quotechar"] is not None and selected["quotechar"] == selected["escapechar"]:
        raise GovHubError("CONTENT_CSV_OPTIONS", "Use distinct quote and escape characters; doubled quotes have their own setting.")
    return selected


class CsvSource:
    """One complete UTF-8 CSV reader with exact original headers and line spans."""

    def __init__(self, stream, options):
        self.reader = csv.reader(
            stream, delimiter=options["delimiter"], quotechar=options["quotechar"],
            escapechar=options["escapechar"], doublequote=options["doublequote"],
            quoting=csv.QUOTE_NONE if options["quotechar"] is None else csv.QUOTE_MINIMAL,
            skipinitialspace=False, strict=True,
        )
        try:
            self.headers = next(self.reader)
        except StopIteration as exc:
            raise GovHubError("CONTENT_CSV", "The retained CSV is empty; an original header is required.") from exc
        except (UnicodeError, csv.Error) as exc:
            raise GovHubError("CONTENT_CSV", "Read the original UTF-8 CSV header: " + str(exc)) from exc
        if not self.headers or any(not h for h in self.headers) or len(set(self.headers)) != len(self.headers):
            raise GovHubError("CONTENT_CSV", "Every original CSV header must be nonempty and unique.")
        self.header_line_end = self.reader.line_num

    def __iter__(self):
        ordinal = 0
        while True:
            line_start = self.reader.line_num + 1
            try:
                values = next(self.reader)
            except StopIteration:
                return
            except (UnicodeError, csv.Error) as exc:
                raise GovHubError("CONTENT_CSV", "Read original CSV record " + str(ordinal + 1) + " at line " + str(line_start) + ": " + str(exc)) from exc
            ordinal += 1
            if len(values) != len(self.headers):
                raise GovHubError("CONTENT_CSV", "Original CSV record " + str(ordinal) + " at line " + str(line_start) + " has " + str(len(values)) + " fields; its header has " + str(len(self.headers)) + ". Check the selected delimiter and quoting.")
            yield {
                "source_row": ordinal, "source_line_start": line_start,
                "source_line_end": self.reader.line_num,
                "data": dict(zip(self.headers, values)),
            }


def inspect_csv(stream, options, offset=0, limit=25):
    """Scan the complete selected file while retaining only the requested rows."""
    source = CsvSource(stream, options)
    rows, count = [], 0
    try:
        for row in source:
            if offset <= count < offset + limit:
                rows.append(row)
            count += 1
    except GovHubError as exc:
        return {
            "headers": source.headers, "header_line_end": source.header_line_end,
            "complete": False, "row_count": None, "observed_records": count,
            "rows": rows, "issues": [{"code": exc.code, "message": exc.message}],
        }
    return {
        "headers": source.headers, "header_line_end": source.header_line_end,
        "complete": True, "row_count": count, "observed_records": count,
        "rows": rows, "issues": [],
    }

/* Complete content-consolidation workflow in the retained GovHub shell. */
'use strict';
const contentState={family:null,mapping:null,plan:null,operation:null,dirty:false};
const contentApi=(action,payload={})=>ops('content.'+action,payload);
const contentFamilies=()=>state.snapshot?.content_consolidation?.families||[];
const contentName=id=>contentFamilies().find(f=>f.id===id)?.label||id||'Content consolidation';
const contentJson=value=>JSON.stringify(value,null,2);
function contentObject(form,name,fallback={}){const value=form.elements.namedItem(name)?.value||'';try{return value.trim()?JSON.parse(value):fallback;}catch{throw Error('Enter complete JSON in '+name.replaceAll('_',' ')+'.');}}
function contentCrumbs(f){return `<div class="breadcrumbs">${link('Content consolidation','content')}${f?'<span>'+link(f.label,'content-family',{id:f.id})+'</span>':''}</div>`;}
