async function contentSubmit(form,submitter){const kind=form.dataset.form,v=Object.fromEntries(new FormData(form)),request_key=form.dataset.requestKey||(form.dataset.requestKey=newKey());
 if(kind==='content-family'){const limits={};for(const key of ['migrations','records','files','file_bytes','routes'])if(v['limit_'+key]!=='')limits[key]=Number(v['limit_'+key]);const r=await contentApi('families.save',{label:v.label,environment_id:v.environment_id,owner:v.owner,comparison_id:v.comparison_id,notes:v.notes,recovery_instruction:v.recovery_instruction,limits,request_key,...(form.dataset.id?{family_id:form.dataset.id,expected_revision:form.dataset.revision}:{})});await reload();await go('content-family',{id:r.family.id});return;}
 if(kind==='content-edition'){const files=[...form.querySelectorAll('.content-source-page')].map(p=>({file_id:p.querySelector('[name=file_id]').value,request_url:p.querySelector('[name=request_url]').value}));const payload={family_id:form.dataset.family,source_id:v.source_id,label:v.label,format:v.format,observed_at:v.observed_at,record_keys:contentRecordKeys(form),key_encoding:v.key_encoding,source_url:v.source_url,source_owner:v.source_owner,license_reference:v.license_reference,retention_instruction:v.retention_instruction,files,request_key};if(v.format==='CSV')payload.csv_options=contentCsvOptions(form);if(v.records_pointer)payload.records_pointer=v.records_pointer;if(v.expected_records!=='')payload.expected_records=Number(v.expected_records);const r=await contentApi('editions.create',payload);await reload();await go('content-source',{id:r.edition.id});return;}
 if(kind==='content-record-search'){await go('content-source',{id:v.edition_id,q:v.q});return;}
 if(kind==='content-compare'){await go('content-compare',{before_id:v.before_id,after_id:v.after_id});return;}
 if(kind==='content-mapping'){const definition=contentMappingDefinition(form);if(submitter?.value==='preview'){const r=await contentApi('mappings.preview',{family_id:form.dataset.family,definition});document.querySelector('#content-preview').innerHTML=card('Complete native preview',definitionDisplay({id:'Current unsaved draft',created_at:iso(),author:state.user.name,sha256:r.compiled.definition_sha256,compiled:r.compiled})+contentIssues(r.compiled.issues)+rawDetails('Native definitions and complete original source lineage',r.compiled));return;}const r=await contentApi('mappings.save',{family_id:form.dataset.family,label:v.label,definition,expected_mapping_id:form.dataset.expected,request_key});await reload();await go('content-mapping',{family_id:form.dataset.family,mapping_id:r.mapping.id});notice('The complete mapping edition and original source selection are retained.');return;}
 if(kind==='content-review'){const r=await contentApi('reviews.save',{mapping_id:form.dataset.id,mapping_sha256:form.dataset.sha,decision:v.decision,reason:v.reason,backup_file_id:v.backup_file_id,request_key});await reload();if(r.plan)await go('content-plan',{family_id:r.plan.family_id,plan_id:r.plan.id});else await go('content-family',{id:r.review.family_id});return;}
 if(kind==='content-native'){const payload={content_plan_id:v.content_plan_id,plan_sha256:v.plan_sha256,type:v.type,reason:v.reason,request_key};if(v.type==='CONTENT_ROLLBACK')payload.content_selection=contentObject(form,'content_selection',[]);const r=await contentApi('operations.create',payload);await reload();await go('content-operation',{id:r.operation.id});return;}
 if(kind==='content-operation-control'){const o=contentState.operation;await ops('operations.'+submitter.value,{operation_id:o.id,expected_revision:o.revision,reason:v.reason,request_key});await reload();await renderContentOperation();return;}
 if(kind==='content-export'){const r=await ops('exports.create',{name:v.name,plan_ids:[],content_family_ids:[form.dataset.family],include_sources:form.elements.include_sources.checked,request_key});await reload();await go('export',{id:r.export.id});return;}
}
async function contentAction(action,target){
 const form=target.closest('form[data-form="content-edition"]');
 if(action==='content-inspect-csv'){await contentInspectCsv(form);return;}
 if(action==='content-csv-previous'||action==='content-csv-next'){const view=contentCsvViews.get(form);if(!view)return;await contentInspectCsv(form,Math.max(0,view.result.offset+(action==='content-csv-next'?view.result.limit:-view.result.limit)));return;}
 if(['content-key-add','content-key-up','content-key-down','content-key-remove'].includes(action)){
  const keys=contentRecordKeys(form);
  if(action==='content-key-add'){const field=form.elements.namedItem('csv_key_field').value;if(!field)throw Error('Choose an original header.');if(keys.includes(field))throw Error('This original field is already selected.');keys.push(field);}
  else {const index=Number(target.dataset.index);if(!Number.isInteger(index)||index<0||index>=keys.length)throw Error('Reopen the current ordered keys.');if(action==='content-key-remove')keys.splice(index,1);else {const destination=index+(action==='content-key-up'?-1:1);if(destination<0||destination>=keys.length)return;[keys[index],keys[destination]]=[keys[destination],keys[index]];}}
  form.elements.namedItem('record_keys').value=JSON.stringify(keys);delete form.dataset.requestKey;contentState.dirty=true;contentRenderKeys(form);return;
 }

 if(action==='content-add-page'){document.querySelector('#content-pages').insertAdjacentHTML('beforeend',contentPageRow());contentInvalidateCsv(form);return;}
 if(action==='content-remove-page'){target.closest('.content-source-page').remove();contentInvalidateCsv(form);return;}
 if(action==='content-add-migration'){const box=document.querySelector('#content-migrations');box.insertAdjacentHTML('beforeend',contentMigrationRow({},box.children.length));return;}
 if(action==='content-remove-migration'){target.closest('.content-migration').remove();return;}
 if(action==='content-add-field'){const box=target.closest('.content-migration'),row=target.closest('.content-direct-field'),value=name=>row.querySelector('[name='+name+']').value.trim(),original=value('field_original'),source=value('field_source'),destination=value('field_destination');if(!original||!source||!destination)throw Error('Choose the original field, native source property and destination property.');const projection=JSON.parse(box.querySelector('[name=projection]').value||'{}'),process=JSON.parse(box.querySelector('[name=process]').value||'{}');projection[source]=original;process[destination]=source;box.querySelector('[name=projection]').value=contentJson(projection);box.querySelector('[name=process]').value=contentJson(process);}
}
document.addEventListener('input',event=>{if(event.target.closest('form[data-form^="content-"]')){contentState.dirty=true;delete event.target.closest('form').dataset.requestKey;}});
setInterval(()=>{if(state.view==='content-operation'&&!state.busy&&!contentState.dirty&&contentState.operation&&!['COMPLETE','FAILED','CANCELLED'].includes(contentState.operation.state))renderContentOperation().catch(e=>notice(e.message,true));},5000);

document.addEventListener('change',event=>{
 const form=event.target.closest('form[data-form="content-edition"]');
 if(!form)return;
 if(event.target.name==='format'||event.target.closest('.content-source-page')||event.target.name?.startsWith('csv_')&&event.target.name!=='csv_key_field')contentInvalidateCsv(form);
});
document.addEventListener('input',event=>{
 const form=event.target.closest('form[data-form="content-edition"]');
 if(!form)return;
 if(event.target.name==='record_keys')contentRenderKeys(form);
 else if(event.target.closest('.content-source-page')||event.target.name?.startsWith('csv_')&&event.target.name!=='csv_key_field')contentInvalidateCsv(form);
});

#!/usr/bin/env node
/** Inspect the actual saved receiving case through its original operator UI. */
import fs from 'node:fs/promises';
import path from 'node:path';
import {createRequire} from 'node:module';
import {fileURLToPath} from 'node:url';
const require=createRequire(import.meta.url);

export async function receiveContentBrowser(options){
 const {base_url,family_id,credentials,output_dir,chromium_executable,visual=false}=options;
 if(!base_url||!family_id||!credentials?.name||!credentials?.password||!output_dir)throw Error('Supply the existing operator URL, family ID, retained credentials and private output directory.');
 const {chromium}=require(require.resolve('playwright',{paths:[process.env.CODEX_PRIMARY_RUNTIME_NODE_MODULES||path.dirname(fileURLToPath(import.meta.url)),process.cwd()]}));
 await fs.mkdir(output_dir,{recursive:true,mode:0o700});
 const browser=await chromium.launch({headless:true,...(chromium_executable?{executablePath:chromium_executable}:{}),args:['--no-sandbox','--disable-dev-shm-usage']});
 const result={schema:'govhub.content-consolidation.browser-receiving.v1',family_id,started_at:new Date().toISOString(),views:[],page_errors:[],request_failures:[],http_errors:[]};
 try{
  const context=await browser.newContext({viewport:{width:1440,height:1000},acceptDownloads:true});
  const page=await context.newPage();
  page.on('pageerror',error=>result.page_errors.push(error.message));
  page.on('requestfailed',request=>{if(!String(request.failure()?.errorText).includes('ERR_ABORTED'))result.request_failures.push({url:new URL(request.url()).pathname,error:request.failure()?.errorText});});
  page.on('response',response=>{if(response.url().startsWith(new URL(base_url).origin)&&response.status()>=400)result.http_errors.push({path:new URL(response.url()).pathname,status:response.status()});});
  await page.goto(base_url,{waitUntil:'networkidle'});
  await page.locator('[data-form=login] [name=name]').fill(credentials.name);
  await page.locator('[data-form=login] [name=password]').fill(credentials.password);
  await page.locator('[data-form=login] button').click();
  await page.locator('#navigation a[href="#content"]').waitFor();
  const domain=async(action,payload)=>page.evaluate(async({action,payload})=>{
   const response=await fetch('/api/govhub/content/'+action,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});
   const value=await response.json();if(!response.ok)throw Error(value.error||'The original content read failed.');return value;
  },{action,payload});
  const family=await domain('families.get',{family_id});
  result.family_revision=family.family.revision;
  result.edition_ids=family.editions.map(e=>e.id);
  result.mapping_ids=family.mappings.map(m=>m.id);
  result.operation_ids=family.operations.map(o=>o.id);
  const routes=[['Content consolidations','content',{}],['Original family','content-family',{id:family_id}]];
  for(const edition of family.editions)routes.push(['Original source '+edition.label,'content-source',{id:edition.id}]);
  for(const mapping of family.mappings)routes.push(['Mapping '+mapping.label,'content-mapping',{family_id,mapping_id:mapping.id}]);
  for(const plan of family.plans)routes.push(['Reviewed native plan','content-plan',{family_id,plan_id:plan.id}]);
  for(const operation of family.operations)routes.push(['Original native '+operation.type,'content-operation',{id:operation.id}]);
  for(const source of new Set(family.editions.map(e=>e.source_id))){const editions=family.editions.filter(e=>e.source_id===source);if(editions.length>1)routes.push(['Original source refresh '+source,'content-compare',{before_id:editions[0].id,after_id:editions.at(-1).id}]);}
  for(const width of [1440,390]){
   await page.setViewportSize({width,height:1000});
   for(const [label,view,params] of routes){
    const hash='#'+view+'?'+new URLSearchParams(params);
    await page.goto(new URL(hash,base_url).href,{waitUntil:'networkidle'});
    await page.locator('#main h1').waitFor();
    await page.waitForFunction(()=>document.querySelector('#main').getAttribute('aria-busy')!=='true');
    const observed=await page.evaluate(()=>({title:document.querySelector('#main h1')?.textContent,viewport:innerWidth,document_width:document.documentElement.scrollWidth,notice:document.querySelector('#notice')?.hidden?'':document.querySelector('#notice')?.textContent,forms:[...document.querySelectorAll('#main form')].map(f=>f.dataset.form),rows:document.querySelectorAll('#main tbody tr').length}));
    result.views.push({label,view,params,width,...observed});
    if(visual&&view==='content-family')await page.screenshot({path:path.join(output_dir,'content-family-'+width+'.png'),fullPage:true});
    if(observed.document_width>observed.viewport+1)throw Error(label+' extends to '+observed.document_width+'px at the '+width+'px viewport.');
    if(observed.notice)throw Error(label+': '+observed.notice);
   }
  }
  if(options.export_id){
   await page.goto(new URL('#export?id='+encodeURIComponent(options.export_id),base_url).href,{waitUntil:'networkidle'});
   const link=page.locator('a[href="/api/exports/'+encodeURIComponent(options.export_id)+'/handover.zip"]');
   const downloaded=page.waitForEvent('download');await link.click();const download=await downloaded;
   const destination=path.join(output_dir,'browser-received-handover.zip');await download.saveAs(destination);
   const {createHash}=await import('node:crypto');const bytes=await fs.readFile(destination);
   result.download={filename:download.suggestedFilename(),bytes:bytes.length,sha256:createHash('sha256').update(bytes).digest('hex')};
  }
  if(result.page_errors.length||result.request_failures.length||result.http_errors.length)throw Error('The original browser receiving recorded page or native HTTP failures.');
  result.status='COMPLETE';
 }catch(error){result.status='FAILED';result.error=error.message;}
 finally{result.finished_at=new Date().toISOString();await browser.close();await fs.writeFile(path.join(output_dir,'content-browser-receiving.json'),JSON.stringify(result,null,2)+'\n',{mode:0o600});}
 if(result.status!=='COMPLETE')throw Object.assign(Error(result.error),{result});
 return result;
}
if(process.argv[1]&&path.resolve(process.argv[1])===fileURLToPath(import.meta.url)){
 try{
  const chunks=[];for await(const chunk of process.stdin)chunks.push(chunk);const options=JSON.parse(Buffer.concat(chunks).toString('utf8'));
  if(options.credentials_file){options.credentials=JSON.parse(await fs.readFile(options.credentials_file,'utf8'));delete options.credentials_file;}
  const result=await receiveContentBrowser(options);
  process.stdout.write(JSON.stringify({status:result.status,family_id:result.family_id,views:result.views.length,download:result.download||null})+'\n');
 }catch(error){process.stderr.write(JSON.stringify({status:'FAILED',error:error.message})+'\n');process.exitCode=1;}
}

"""Complete content-package history in GovHub's existing handover and backup."""
import html
import json

from govhub import GovHubError, SOURCE, csv_bytes, now, packed, text


class PackageDeliveryMixin:
    def _handover_capture(self, db, payload, actor):
        ids = payload.get("package_family_ids", [])
        if not ids:
            return super()._handover_capture(db, payload, actor)
        if not isinstance(ids, list) or any(not isinstance(value, str) for value in ids) or len(ids) != len(set(ids)):
            raise GovHubError("PACKAGE_HANDOVER_SCOPE", "Select each complete content-package workshare once.")
        if not isinstance(payload.get("include_sources"), bool):
            raise GovHubError("HANDOVER_SOURCE_OPTION", "Choose whether the handover includes the original source archive and native output bytes.")
        families = [self._package_family(db, value) for value in sorted(ids)]
        selected = dict(payload)
        selected["plan_ids"] = sorted(set(selected.get("plan_ids", [])) | {plan for family in families for plan in family["plan_ids"]})
        if selected.get("plan_ids") or selected.get("content_family_ids") or selected.get("visitor_edition_ids") or selected.get("pots_project_ids") or selected.get("playbook_version_ids"):
            capture = super()._handover_capture(db, selected, actor)
        else:
            meta = self.meta(db)
            capture = {
                "format": "govhub-cutover-handover/1", "name": text(payload.get("name", ""), 500, True),
                "observed_at": now(), "author": actor["name"], "workspace": meta["workspace"],
                "workspace_head": meta["head"], "source": SOURCE, "settings": self._setting(db, "settings"),
                "core_sources": self.core_sources, "auditor_sha256": self.auditor_sha256,
                "include_sources": payload["include_sources"], "plan_ids": [], "plans": [], "snapshots": [],
                "operations": [], "records": {"sites": [], "environments": [], "migration_issues": []},
                "record_history": [], "sources": [],
            }
        source_ids = {item["id"] for item in capture["sources"]}
        if capture["settings"].get("scope_file_id"):
            source_ids.add(capture["settings"]["scope_file_id"])
        bundles, targets, comparisons = [], set(), set()
        for family in families:
            editions = self._objects(db, "package_edition", family["id"])
            reviews = self._objects(db, "package_review", family["id"])
            bundles.append({"family": family, "versions": self._objects(db, "package_family_version", family["id"]), "editions": editions, "reviews": reviews, "comparisons": self._objects(db, "package_comparison", family["id"])})
            targets.update(value for value in (family["environment_id"], family["source_environment_id"]) if value)
            if family["comparison_id"]:
                comparisons.add(family["comparison_id"])
            source_ids.update(edition["file_id"] for edition in editions)
            source_ids.update(review["preview_file_id"] for review in reviews)
            for comparison in self._objects(db, "package_comparison", family["id"]):
                source_ids.update((comparison["baseline_preview_file_id"], comparison["candidate_preview_file_id"]))
        included = {item["operation"]["id"] for item in capture["operations"]}
        for row in db.execute("SELECT data FROM govhub_operations ORDER BY rowid"):
            operation = json.loads(row[0])
            if operation.get("package_family_id") not in ids or operation["id"] in included:
                continue
            files = self._output_list(db, "operation", operation["id"])
            capture["operations"].append({"operation": operation, "events": self._objects(db, "operation_event", operation["id"]), "observations": self._objects(db, "operation_observation", operation["id"]), "files": files})
            source_ids.update(file["file_id"] for file in files)
        records = {(record["kind"], record["id"]) for values in capture["records"].values() for record in values}
        for row in db.execute("SELECT * FROM entities ORDER BY kind,id"):
            record = self._core.view_record(row)
            selected_record = (record["kind"] == "environments" and record["id"] in targets) or (record["kind"] == "sites" and record["data"]["comparison_id"] in comparisons)
            if selected_record and (record["kind"], record["id"]) not in records:
                capture["records"][record["kind"]].append(record)
                records.add((record["kind"], record["id"]))
        previous_revisions = {item["revision"] for item in capture["record_history"]}
        for row in db.execute("SELECT * FROM revisions ORDER BY rowid"):
            if (row["kind"], row["id"]) in records and row["revision"] not in previous_revisions:
                item = dict(row)
                item["data"], item["origin"] = json.loads(row["data"]), json.loads(row["origin"])
                capture["record_history"].append(item)
        capture["sources"] = [self._file_row(db, file_id) for file_id in sorted(source_ids)]
        capture["package_family_ids"] = sorted(ids)
        capture["content_packages"] = {"schema": "govhub.content-packages.handover.v1", "families": bundles}
        return capture

    def _content_export_files(self, capture, write):
        super()._content_export_files(capture, write)
        packages = capture.get("content_packages")
        if not packages:
            return
        write("content-packages.json", (packed(packages) + "\n").encode("utf-8"))
        archives, reviews, operations = [], [], []
        for bundle in packages["families"]:
            for edition in bundle["editions"]:
                archives.append({name: edition.get(name, "") for name in ("id", "family_id", "label", "file_id", "filename", "archive_sha256", "archive_bytes", "previous_edition_id", "created_at", "author")})
            for review in bundle["reviews"]:
                reviews.append({name: review.get(name, "") for name in ("id", "family_id", "edition_id", "preview_operation_id", "preview_sha256", "target_sha256", "before_sha256", "decision", "reason", "created_at", "author")})
        for item in capture["operations"]:
            operation = item["operation"]
            if operation.get("package_family_id") in capture["package_family_ids"]:
                operations.append({"id": operation["id"], "family_id": operation["package_family_id"], "edition_id": operation.get("package_edition_id", ""), "type": operation["type"], "state": operation["state"], "environment_id": operation["environment_id"], "intent_sha256": operation["package_intent_sha256"], "created_at": operation["created_at"], "actual_finished_at": operation.get("actual_finished_at", "")})
        write("package-archive-editions.csv", csv_bytes(archives, ("id", "family_id", "label", "file_id", "filename", "archive_sha256", "archive_bytes", "previous_edition_id", "created_at", "author")))
        write("package-editor-decisions.csv", csv_bytes(reviews, ("id", "family_id", "edition_id", "preview_operation_id", "preview_sha256", "target_sha256", "before_sha256", "decision", "reason", "created_at", "author")))
        write("package-native-operations.csv", csv_bytes(operations, ("id", "family_id", "edition_id", "type", "state", "environment_id", "intent_sha256", "created_at", "actual_finished_at")))
        guide = """# Content package receiving

Open handover.html for the retained workshare, original archives and review decisions. content-packages.json contains every original and corrected archive edition and saved review. package-archive-editions.csv identifies the exact source bytes; package-editor-decisions.csv binds each decision to its native preview and destination state.

operations.json contains the complete original native operations, state and history. Each operation's retained files include the native archive verification, exact package and asset preview, import receipt and receiving readback. source-manifest.json maps each source ID and digest to its included original file. When sources were selected, handover.zip includes every listed archive and native result.

Open the separate complete workspace backup with the maintained GovHub application to continue this same workshare. The backup preserves staff records, decisions, source files and original native command journals. Use packages.families.get, packages.operations.get and packages.receiving.create through the existing CLI or HTTP action dispatcher. A receiving operation reads the original import identity; it does not create another import. Reopen or resume the original interrupted operation before making a new import decision.

GovHub's graph export explicitly selects the native unpublished mode by default: its packages create new content as drafts and preserve existing destination publication. An externally supplied archive retains its original publication mode; the native preview shows that source and its planned effect before review. Use Drupal's native editor and scheduler for destination publication. Correct the original Drupal source and retain its next native export as a new archive edition, then preview and review that edition against the current destination. Absence from a candidate archive is a review difference; native Content Packages does not delete omitted destination entities.

An interrupted native import rolls back its database changes and original receipt together. Unmanaged asset files copied by Drupal can remain after a database rollback; their original native asset plan and files stay retained for the same-operation continuation. Whole-site recovery uses the workshare's included original GovHub cutover and rollback plans and selected backups. Open their native operations and complete original source files. An earlier content package upsert is a new content change; the retained site backup supplies the full rollback path.
"""
        write("PACKAGE_RECEIVING.md", guide.encode("utf-8"))

    def _handover_html(self, capture):
        rendered = super()._handover_html(capture)
        packages = capture.get("content_packages")
        if not packages:
            return rendered
        escape = lambda value: html.escape(str(value if value is not None else ""), quote=True)
        blocks = ["<h2>Content packages</h2>"]
        for bundle in packages["families"]:
            family = bundle["family"]
            blocks.append("<h3>" + escape(family["label"]) + "</h3><p>" + escape(family["notes"]) + "</p><dl><dt>Receiving engineer</dt><dd>" + escape(family["owner"]) + "</dd><dt>Recovery instruction</dt><dd>" + escape(family["recovery_instruction"]) + "</dd></dl>")
            blocks.append("<table><thead><tr><th>Archive edition</th><th>Original bytes</th><th>Source and history</th></tr></thead><tbody>")
            for edition in bundle["editions"]:
                blocks.append("<tr><td>" + escape(edition["label"]) + "<br>" + escape(edition["id"]) + "</td><td>" + escape(edition["filename"]) + "<br>" + escape(edition["archive_bytes"]) + " bytes<br>" + escape(edition["archive_sha256"]) + "</td><td>" + escape(edition["created_at"]) + "<br>" + escape(edition["notes"]) + "</td></tr>")
            blocks.append("</tbody></table><h4>Editor decisions</h4>")
            for review in bundle["reviews"]:
                blocks.append("<p><strong>" + escape(review["decision"]) + "</strong> · " + escape(review["author"]) + " · " + escape(review["created_at"]) + "<br>" + escape(review["reason"]) + "<br>Native preview " + escape(review["preview_operation_id"]) + "</p>")
            blocks.append("<h4>Native operations</h4><table><thead><tr><th>Operation</th><th>Outcome</th><th>Original edition</th></tr></thead><tbody>")
            for item in capture["operations"]:
                operation = item["operation"]
                if operation.get("package_family_id") == family["id"]:
                    blocks.append("<tr><td>" + escape(operation["type"]) + "<br>" + escape(operation["id"]) + "</td><td>" + escape(operation["state"]) + "<br>" + escape(operation["progress"]["detail"]) + "</td><td>" + escape(operation.get("package_edition_id", "")) + "</td></tr>")
            blocks.append("</tbody></table>")
        return rendered.replace(b"</main>", ("".join(blocks) + "</main>").encode("utf-8"))

    def _exports_compare(self, payload):
        result = super()._exports_compare(payload)
        with self.connect(snapshot=True) as db:
            before = self._get(db, "export", payload.get("before_id"))
            after = self._get(db, "export", payload.get("after_id"))
            left = self._get(db, "export_intent", before["intent_id"])["capture"]
            right = self._get(db, "export_intent", after["intent_id"])["capture"]
        def flatten(capture):
            groups = {"families": [], "editions": [], "reviews": [], "comparisons": []}
            for bundle in capture.get("content_packages", {}).get("families", []):
                groups["families"].append(bundle["family"])
                groups["editions"].extend(bundle["editions"])
                groups["reviews"].extend(bundle["reviews"])
                groups["comparisons"].extend(bundle.get("comparisons", []))
            return groups
        if left.get("content_packages") or right.get("content_packages"):
            a, b = flatten(left), flatten(right)
            result["content_packages"] = {name: self._compare_objects(a[name], b[name]) for name in a}
        return result

"""Shared content-package input shapes; Drupal owns content interpretation."""
from copy import deepcopy
import re

SCHEMA = "govhub.content-packages/v1"
NATIVE_REQUEST = "govhub.content-packages.native-request.v1"
NATIVE_RESULT = "govhub.content-packages.native-result.v1"
PREVIEW_SCHEMA = "govhub.content-packages.preview.v1"
TYPES = {
    "PACKAGE_EXPORT": "export",
    "PACKAGE_PREVIEW": "preview",
    "PACKAGE_IMPORT": "import",
    "PACKAGE_STATUS": "status",
}
READ_TYPES = frozenset(TYPES) - {"PACKAGE_IMPORT"}
SHA256 = re.compile(r"^[0-9a-f]{64}$")
UUID = re.compile(r"^[0-9a-fA-F]{8}(?:-[0-9a-fA-F]{4}){3}-[0-9a-fA-F]{12}$")
ENTITY_TYPE = re.compile(r"^[a-z][a-z0-9_]*$")


def selection(value):
    """One native archive contains one explicit root and its dependency graph."""
    if not isinstance(value, list) or len(value) != 1 or not isinstance(value[0], dict):
        raise ValueError("Select one original Drupal entity type and UUID; the native exporter includes its whole dependency graph.")
    item = value[0]
    entity_type, uuid = item.get("entity_type"), item.get("uuid")
    if not isinstance(entity_type, str) or not ENTITY_TYPE.fullmatch(entity_type):
        raise ValueError("Use the original Drupal entity type machine name.")
    if not isinstance(uuid, str) or not UUID.fullmatch(uuid):
        raise ValueError("Use the original complete Drupal entity UUID.")
    return [{"entity_type": entity_type, "uuid": uuid.lower()}]


def options(value):
    value = deepcopy(value or {})
    if not isinstance(value, dict):
        raise ValueError("Supply the native package options as a JSON object.")
    unknown = set(value) - {"package_type", "max_depth", "unpublished"}
    if unknown:
        raise ValueError("Unknown native package options: " + ", ".join(sorted(unknown)))
    package_type = value.get("package_type", "content_entity")
    if not isinstance(package_type, str) or not ENTITY_TYPE.fullmatch(package_type):
        raise ValueError("Select the installed native package type machine name.")
    depth = value.get("max_depth", 20)
    if isinstance(depth, bool) or not isinstance(depth, int) or depth < 0:
        raise ValueError("The native graph depth must be a nonnegative integer.")
    unpublished = value.get("unpublished", True)
    if not isinstance(unpublished, bool):
        raise ValueError("unpublished must be a boolean.")
    return {"package_type": package_type, "max_depth": depth, "unpublished": unpublished}


def original_result(value, operation_id, action):
    if not isinstance(value, dict) or value.get("schema") != NATIVE_RESULT:
        raise ValueError("The native bridge must return its complete content-package result.")
    if value.get("operation_id") != operation_id or value.get("action") != action:
        raise ValueError("The native result belongs to a different original operation.")
    return value


def preview(value, archive_sha256):
    if not isinstance(value, dict) or value.get("schema") != PREVIEW_SCHEMA:
        raise ValueError("Select the complete native content-package preview.")
    if value.get("archive_sha256") != archive_sha256:
        raise ValueError("The native preview belongs to different archive bytes.")
    for field in ("target_sha256", "before_sha256"):
        if not isinstance(value.get(field), str) or not SHA256.fullmatch(value[field]):
            raise ValueError("The native preview must retain its exact " + field + ".")
    if not isinstance(value.get("packages"), list) or not isinstance(value.get("assets"), list):
        raise ValueError("The native preview must retain every selected package and asset.")
    if not isinstance(value.get("issues"), list):
        raise ValueError("The native preview must retain its original module validation outcome.")
    return value

"""Content Packages on GovHub's existing native command and operation journal."""
from __future__ import annotations

import hashlib
import json
import os
from pathlib import Path

import native_adapter as base
from content_consolidation.drupal.adapter import _verified, _write_once
from govhub import packed
from .model import NATIVE_REQUEST, NATIVE_RESULT, TYPES, original_result


def _collect(session):
    """Retain complete source/result files through the existing GovHub store."""
    known = {item["path"] for item in session.artifacts}
    for path in sorted(session.out.rglob("*")):
        if not path.is_file() or path.is_symlink() or str(path) in known:
            continue
        if ".writing" in path.name or ".govhub-writing" in path.name or path.name == "native-state.json":
            continue
        if path.name.startswith("event-") and path.suffix == ".json":
            continue
        if "relocated-originals" in path.parts:
            role = "original_relocation_record"
        elif path.name.endswith(".command.json"):
            role = "native_command"
        elif path.suffix in {".stdout", ".stderr"}:
            role = "native_command_output"
        elif path.name.endswith(".result.json"):
            role = "package_result"
        elif path.name == "package-graph.zip":
            role = "package_archive"
        elif path.parent.name == "assets":
            role = "package_asset"
        elif path.name.endswith(".module-source.json"):
            role = "package_module_source"
        else:
            role = "package_native_artifact"
        session.add(path, role)
        known.add(str(path))


def _state(session, operation, source_paths):
    path = session.out / "native-state.json"
    saved = source_paths.get("checkpoint") or operation.get("resume_checkpoint") or {}
    saved = saved.get("resume_checkpoint", saved.get("state", saved))
    state = session.read_private_json(path) if path.is_file() else session.resolve_private(saved)
    if state and state.get("intent_sha256") != operation["package_intent_sha256"]:
        raise ValueError("The native journal belongs to a different original content operation.")
    session.state = dict(state or {
        "intent_sha256": operation["package_intent_sha256"],
        "operation_id": operation["id"],
        "phase": "prepared", "attempt": 0, "mutation_started": False,
        "output_dir": str(session.out),
    })
    session.save_state()


def _sources(operation, source_paths):
    files = {}
    for item in source_paths.get("package_files", []):
        role = item.get("role")
        if role not in {"archive", "reviewed_preview"} or role in files:
            raise ValueError("Each original content archive and reviewed preview has one retained binding.")
        path = _verified(item)
        files[role] = {**item, "path": str(path), "bytes": path.stat().st_size}
    request = operation["package_request"]
    if "archive_sha256" in request:
        archive = files.get("archive")
        if not archive or archive["sha256"] != request["archive_sha256"] or archive["bytes"] != request["archive_bytes"]:
            raise ValueError("This operation requires the exact original archive edition.")
    if operation["type"] == "PACKAGE_IMPORT":
        reviewed = files.get("reviewed_preview")
        if not reviewed or reviewed["sha256"] != request["preview_sha256"]:
            raise ValueError("This import requires the exact original reviewed preview bytes.")
    return files


def _settle_original(session):
    """An admitted original child must be complete or positively reaped."""
    label = session.state.get("current_label")
    if not label:
        return None
    record_path = session.out / (label + ".command.json")
    if not record_path.is_file():
        # current_label is saved before Session prepares the command. A pending
        # mutation without that record remains an unknown dispatched operation.
        if session.state.get("pending_command") == label:
            raise base.NativeWaiting("Restore the original dispatched command record before resuming this import.")
        return None
    record = session.read_private_json(record_path)
    if record.get("phase") == "not_started":
        return record
    if record.get("phase") == "complete" or (
        record.get("phase") == "interrupted" and record.get("owned_process_reaped") is True
    ):
        for role in ("stdout", "stderr"):
            if record.get(role):
                _verified(record[role])
        session.state.update(pending_command=None, phase="native_reconciled")
        session.save_state()
        return record
    raise base.NativeWaiting("The original content command is still running or lacks its own completed/reaped process record.")


def _saved_result(session, operation, record):
    ref = session.state.get("result_ref")
    selected = ref.get("path") if ref else session.state.get("current_result_path")
    if not selected:
        return None
    path = Path(session.private_path(selected))
    if path.parent != session.out or not path.name.endswith(".result.json"):
        raise ValueError("The saved native result must remain in its original private operation.")
    if not path.is_file():
        return None
    if record is not None and record.get("phase") == "not_started":
        raise ValueError("An unstarted native command cannot supply a completed result.")
    if ref:
        raw = _verified(ref).read_bytes()
    else:
        if not record:
            raise base.NativeWaiting("Recover the original command completion before adopting its retained content result.")
        raw = path.read_bytes()
    value = original_result(json.loads(raw), operation["id"], TYPES[operation["type"]])
    if value.get("intent_sha256") != operation["package_intent_sha256"]:
        raise ValueError("The retained result belongs to another original content request.")
    if value.get("status") == "complete":
        descriptor = base._file(path, "package_result")
        session.state.update(result_ref=descriptor, phase="native_complete")
        session.save_state()
        return value
    return None



def _guarded_prefix(session, attempt):
    """Use the PHP executable/entrypoint observed from this original Drush."""
    probe = "echo json_encode(['php_binary'=>PHP_BINARY,'script'=>realpath($_SERVER['SCRIPT_FILENAME']),'original_auto_prepend_file'=>ini_get('auto_prepend_file'),'posix'=>function_exists('posix_kill')],JSON_THROW_ON_ERROR);"
    record = session.command(f"package-php-runtime-{attempt:04d}",
                             base._prefix(session.p) + ["php:eval", probe])
    runtime = json.loads(_verified(record["stdout"]).read_bytes())
    binary, script = Path(runtime["php_binary"]), Path(runtime["script"])
    if not binary.is_absolute() or not binary.is_file() or not os.access(binary, os.X_OK):
        raise ValueError("The original Drush did not return its usable native PHP executable.")
    if not script.is_absolute() or not script.is_file() or runtime.get("posix") is not True:
        raise ValueError("The selected native Drush must retain its PHP entrypoint and existing POSIX extension.")
    guard_path = session.out / f"package-guard-{attempt:04d}.php"
    guard_source = Path(__file__).resolve().parent / "native" / "shutdown.php"
    _write_once(guard_path, guard_source.read_bytes())
    _write_once(Path(str(guard_path) + ".runtime.json"), runtime)
    prefix = base._prefix(session.p)
    original_options = prefix[2:] if session.p.get("php_path") else prefix[1:]
    # Keep the selected PHP launcher: extracted runtimes may establish their
    # library and ini paths in that original wrapper before executing PHP_BINARY.
    launcher = prefix[0] if session.p.get("php_path") else str(binary)
    return [launcher, "-d", "auto_prepend_file=" + str(guard_path), str(script), *original_options]


def _attempt(session, operation, intent_ref, files, reconciled):
    attempt = int(session.state.get("attempt", 0)) + 1
    label = f"package-native-{attempt:04d}"
    request_path = session.out / (label + ".request.json")
    result_path = session.out / (label + ".result.json")
    script = Path(__file__).resolve().parent / "native" / "run.php"
    script_copy = session.out / f"package-run-{attempt:04d}.php"
    # Each actual attempt retains the exact operated bridge. A corrected
    # installed bridge can continue the same business operation after its
    # original child is complete/reaped; old source and commands remain intact.
    _write_once(script_copy, script.read_bytes())
    script_ref = base._file(script_copy, "package_bridge_source")
    payload = {
        "schema": NATIVE_REQUEST,
        "operation_id": operation["id"], "action": TYPES[operation["type"]],
        "intent": intent_ref, "intent_sha256": operation["package_intent_sha256"],
        "parameters": operation["package_request"], "files": files,
        "output_dir": str(session.out), "result_path": str(result_path),
        "archive_destination": str(session.out / "package-graph.zip"),
        "provider_environment_id": operation["provider_environment_id"],
        "profile_revision": operation["profile"]["revision"],
        "resume_reconciled": bool(reconciled),
        "lock_seconds": int(session.p["timeout_seconds"]) + 60,
    }
    request_ref = _write_once(request_path, payload)
    session.state.update(attempt=attempt, current_label=label, current_request=request_ref,
                         current_result_path=str(result_path), script_ref=script_ref,
                         phase="native_prepared")
    session.save_state()
    prefix = _guarded_prefix(session, attempt) if operation["type"] == "PACKAGE_IMPORT" else base._prefix(session.p)
    argv = prefix + [
        "php:script", script_copy.stem, "--script-path=" + str(session.out), "--", str(request_path)
    ]
    session.command(label, argv, mutating=operation["type"] == "PACKAGE_IMPORT")
    ref = base._file(result_path, "package_result")
    result = original_result(json.loads(_verified(ref).read_bytes()), operation["id"], TYPES[operation["type"]])
    if result.get("intent_sha256") != operation["package_intent_sha256"]:
        raise ValueError("The original native result differs from its retained operation intent.")
    session.state.update(result_ref=ref, phase="native_complete", pending_command=None)
    session.save_state()
    return result


def execute(operation, config, source_paths, checkpoint=None, cancelled=None):
    profile = base._profile(config)
    if profile["source_kind"] != "drush":
        raise ValueError("Select the existing equipped Drupal / Drush profile for this content operation.")
    session = base.Session(profile, source_paths["output_dir"], checkpoint, cancelled,
                           source_paths.get("workspace_relocations"))
    source_paths = session.resolve_private(source_paths)
    observations = {}
    try:
        if operation.get("type") not in TYPES or operation["provider_environment_id"] != profile["environment_id"]:
            raise ValueError("The original operation must select this exact configured Drupal environment.")
        if source_paths.get("package_request") != operation["package_request"]:
            raise ValueError("The original queued package parameters changed.")
        intent = operation["package_intent"]
        intent_bytes = packed(intent).encode()
        if hashlib.sha256(intent_bytes).hexdigest() != operation["package_intent_sha256"]:
            raise ValueError("The original queued content intent changed.")
        files = _sources(operation, source_paths)
        intent_ref = _write_once(session.out / "package-intent.json", intent_bytes)
        _state(session, operation, source_paths)
        record = _settle_original(session)
        result = _saved_result(session, operation, record)
        if result is None:
            native_status, commands, native_fingerprint = base._drush_info(session, fresh=True)
            if "php:script" not in commands:
                raise ValueError("The installed original Drush must expose php:script.")
            session.state["native_preflight"] = {
                "native_status": native_status, "target_fingerprint": native_fingerprint,
                "observed_at": base._now(),
            }
            session.save_state()
            result = _attempt(session, operation, intent_ref, files, record is not None)
        observations = {
            "package_result": result, "result_file": session.state.get("result_ref"),
            "native_action": operation["native_action"],
            "provider_context": base._context(profile),
            "native_preflight": session.state.get("native_preflight", {}),
            "intent_file": intent_ref,
        }
        if result.get("archive"):
            archive = session.out / "package-graph.zip"
            actual = base._file(archive, "package_archive")
            if actual["sha256"] != result["archive"]["sha256"] or actual["size"] != result["archive"]["bytes"]:
                raise ValueError("The retained native graph archive differs from its completed export.")
        final_path = session.out / f"package-observations-{int(session.state['attempt']):04d}.json"
        _write_once(final_path, observations)
        success = result.get("status") == "complete"
        session.state.update(phase="completed" if success else "native_failed",
                             observations_ref=base._file(final_path, "package_observations"))
        session.save_state()
        _collect(session)
        return session.result("COMPLETE" if success else "FAILED", observations,
                              None if success else result.get("error", {}).get("message", "The native content operation failed."))
    except base.NativeCancelled as exc:
        _collect(session)
        return session.result("WAITING_NATIVE" if session.state.get("mutation_started") else "CANCELLED", observations, str(exc))
    except base.NativeWaiting as exc:
        _collect(session)
        return session.result("WAITING_NATIVE", observations, str(exc))
    except Exception as exc:
        _collect(session)
        status = "WAITING_NATIVE" if session.state.get("phase") == "native_interrupted" else "FAILED"
        return session.result(status, observations, str(exc))

#!/usr/bin/env python3
"""Operate one original GovHub commissioning Content Packages workshare through GovHub."""
from __future__ import annotations
import argparse
from contextlib import contextmanager
from datetime import datetime, timezone
import fcntl
import hashlib
import json
import os
from pathlib import Path
import sys
import time
import tempfile

OP = "GOVHUB-CONTENT-PACKAGES-COMMISSIONING-V1"
ROOT_UUID = "5cac3f15-ec81-4f2e-8e87-691645eb6850"
FINAL = {"COMPLETE", "FAILED", "WAITING_NATIVE", "PAUSED", "CANCELLED"}

def canonical(value):
    return json.dumps(value, sort_keys=True, separators=(",", ":"), ensure_ascii=False, allow_nan=False)

def sha(raw):
    return hashlib.sha256(raw).hexdigest()

def now():
    return datetime.now(timezone.utc).isoformat().replace("+00:00", "Z")

def read(path):
    return json.loads(Path(path).read_bytes())

def publish(path, raw, *, replace):
    """Publish complete bytes and remove only the temporary file created here."""
    descriptor, name = tempfile.mkstemp(prefix="." + path.name + ".writing-", dir=path.parent)
    temporary = Path(name)
    try:
        with os.fdopen(descriptor, "wb") as stream:
            stream.write(raw)
            stream.flush()
            os.fsync(stream.fileno())
        if replace:
            os.replace(temporary, path)
        else:
            os.link(temporary, path)
    finally:
        temporary.unlink(missing_ok=True)

def immutable(path, value):
    path = Path(path)
    raw = value if isinstance(value, bytes) else (canonical(value) + "\n").encode()
    path.parent.mkdir(mode=0o700, parents=True, exist_ok=True)
    if path.exists():
        if path.is_symlink() or path.read_bytes() != raw:
            raise ValueError("Different original data occupies " + str(path))
        return
    publish(path, raw, replace=False)

def current(path, value):
    path = Path(path)
    publish(path, (canonical(value) + "\n").encode(), replace=True)

@contextmanager
def controller(root):
    root.mkdir(mode=0o700, parents=True, exist_ok=True)
    descriptor = os.open(root / "controller.lock", os.O_RDWR | os.O_CREAT | os.O_NOFOLLOW, 0o600)
    try:
        fcntl.flock(descriptor, fcntl.LOCK_EX | fcntl.LOCK_NB)
        yield
    finally:
        os.close(descriptor)

class Operator:
    def __init__(self, args, workspace, actor):
        self.args, self.workspace, self.actor = args, workspace, actor
        self.root = args.out
        self.requests = self.root / "requests"
        self.requests.mkdir(mode=0o700, exist_ok=True)

    def progress(self, stage, **values):
        value = {"operation": OP, "stage": stage, "at": now(), **values}
        current(self.root / "operator-progress.json", value)
        print(json.dumps(value), flush=True)

    def call(self, label, action, payload):
        """Resume the original accepted application request without rebuilding it."""
        request = {"action": action, "payload": {"request_key": OP + "/" + label, **payload}}
        intent_path = self.requests / (label + ".request.json")
        result_path = self.requests / (label + ".result.json")
        if intent_path.exists():
            original = read(intent_path)
            if original["action"] != action:
                raise ValueError("The original action changed: " + label)
            request = original
        else:
            immutable(intent_path, request)
        if result_path.exists():
            return read(result_path)
        result = self.workspace.dispatch(request["action"], request["payload"], self.actor)
        immutable(result_path, result)
        return result

    def get(self, operation_id):
        return self.workspace.dispatch("packages.operations.get", {"operation_id": operation_id}, self.actor)["operation"]

    def wait(self, operation_id, accepted=("COMPLETE",)):
        deadline = time.monotonic() + self.args.timeout
        while time.monotonic() < deadline:
            value = self.get(operation_id)
            if value["state"] in FINAL:
                if value["state"] not in accepted:
                    current(self.root / "original-operation-followup.json", value)
                    raise ValueError("Original operation " + operation_id + " requires its retained continuation: " + value["state"] + " " + str(value.get("error")))
                return value
            time.sleep(.25)
        current(self.root / "original-operation-followup.json", self.get(operation_id))
        raise TimeoutError("The same native operation is still queued or running: " + operation_id)

    def native(self, value):
        return (value.get("native_result") or {}).get("observations", {}).get("package_result", {})

    def queue(self, label, action, payload, accepted=("COMPLETE",)):
        created = self.call(label, action, payload)
        self.progress(label, operation_id=created["operation"]["id"])
        return self.wait(created["operation"]["id"], accepted)

    def seed(self, role, edition, profile, site_uuid):
        import native_adapter as native
        directory = self.root / "native-source" / (role + "-" + edition)
        directory.mkdir(mode=0o700, parents=True, exist_ok=True)
        source = Path(__file__).with_name("seed-native.php")
        raw = source.read_bytes()
        script = directory / ("seed-" + sha(raw)[:16] + ".php")
        immutable(script, raw)
        request = {"schema": "govhub.commissioning.native-case.v1", "operation": OP,
                   "role": role, "edition": edition, "site_uuid": site_uuid}
        input_path = directory / "source-input.json"
        immutable(input_path, request)
        session = native.Session(native._profile(profile), directory)
        state_path = directory / "native-state.json"
        if state_path.is_file():
            session.state = session.read_private_json(state_path)
        for record in directory.glob("seed-*.command.json"):
            prior = read(record)
            if prior.get("phase") not in {"complete", "not_started"} and not (
                    prior.get("phase") == "interrupted" and prior.get("owned_process_reaped") is True):
                raise ValueError("Reconcile this original owned source command before continuing: " + str(record))
        record = session.command("seed-" + sha(raw)[:16],
            native._prefix(session.p) + ["php:script", script.stem, "--script-path=" + str(directory),
                                       "--", str(input_path)], mutating=True)
        result = json.loads(Path(record["stdout"]["path"]).read_bytes())
        if result.get("site_uuid") != site_uuid or result.get("role") != role or result.get("edition") != edition:
            raise ValueError("The original native source result belongs to another site or edition.")
        immutable(directory / "source-result.json", result)
        self.progress("original-source-" + role + "-" + edition,
                      site_uuid=site_uuid, root_uuid=result["root"]["uuid"])
        return result

    def environment(self, role, profile):
        identity = "govhub_commissioning-" + role + "-20261012"
        with self.workspace.connect(snapshot=True) as db:
            exists = db.execute("SELECT 1 FROM entities WHERE kind='environments' AND id=?", (identity,)).fetchone()
        if exists:
            row = self.workspace.record("environments", identity)
            if row["data"]["provider_resource_id"] != profile["environment_id"]:
                raise ValueError("The existing source environment has another native identity.")
        else:
            row = self.workspace.save("environments", identity, {
                "data": {"name": "GovHub commissioning " + role, "provider": "Drupal native",
                         "purpose": "Rehearsal", "provider_resource_id": profile["environment_id"],
                         "canonical_url": profile["uri"], "owner": "GovHub commissioning receiving engineer",
                         "authorization_reference": OP,
                         "notes": "Independently owned native receiving site; original Drupal and Content Packages interfaces."},
                "note": "Original source-backed GovHub commissioning receiving environment."}, self.actor)
        label = "configure-" + role
        result_path = self.requests / (label + ".result.json")
        intent_path = self.requests / (label + ".request.json")
        if result_path.exists():
            configured = read(result_path)
        else:
            # This maintained action uses a revision guard, not request-key replay.
            # Read its committed profile before repeating an interrupted reply.
            with self.workspace.connect(snapshot=True) as db:
                stored = db.execute("SELECT revision,data FROM govhub_config WHERE environment_id=?", (identity,)).fetchone()
                current_environment = self.workspace._record_db(db, "environments", identity)
            existing = json.loads(stored["data"]) if stored else None
            if intent_path.exists() and existing is not None and all(existing.get(key) == value for key, value in profile.items()):
                configured = {"environment": current_environment,
                              "profile": {"revision": stored["revision"], "config": existing}}
                immutable(result_path, configured)
            else:
                configured = self.call(label, "operations.configure",
                    {"environment_id": identity, "expected_revision": row["revision"], "config": profile})
        actual = configured["profile"]["config"]
        if any(actual.get(key) != value for key, value in profile.items()):
            raise ValueError("The original configured environment differs.")
        with self.workspace.connect(snapshot=True) as db:
            selected = db.execute("SELECT data FROM govhub_config WHERE environment_id=?", (identity,)).fetchone()
            latest_environment = self.workspace._record_db(db, "environments", identity)
        latest_profile = json.loads(selected["data"]) if selected else None
        if latest_profile is None or any(latest_profile.get(key) != value for key, value in profile.items()):
            raise ValueError("The selected original site profile changed; reconcile that same environment.")
        if latest_environment["data"]["provider_resource_id"] != profile["environment_id"]:
            raise ValueError("The original environment now names another native site.")
        return latest_environment

    def retain_source(self, label, filename, raw):
        """Use original source intake and reconcile any already committed file."""
        if not isinstance(raw, bytes):
            raw = (canonical(raw) + "\n").encode()
        digest = sha(raw)
        name = label + "-" + digest[:16] + "-" + filename
        original = self.args.source_root / name
        immutable(original, raw)
        source_label = OP + "/" + label + "/" + digest
        with self.workspace.connect(snapshot=True) as db:
            rows = db.execute("SELECT * FROM files WHERE sha256=? AND bytes=? AND filename=? AND source_label=? AND author=? ORDER BY created_at,id",
                (digest, len(raw), name, source_label, self.actor["name"])).fetchall()
        if rows:
            result = dict(rows[0])
            self.workspace._verify_file(result)
        else:
            result = self.workspace.dispatch("sources.retain", {"path": name,
                "category": "Evidence", "source_label": source_label}, self.actor)
        immutable(self.requests / ("source-" + label + "-" + digest + ".json"), result)
        return result

    def retain_operating_source(self, handoff):
        directory = Path(__file__).resolve().parent
        result = {"native_sites": self.retain_source("native-sites", "profiles.json", handoff)}
        for name in ("operate-native.py", "seed-native.php", "govhub_receiving_boundary.module",
                     "govhub_receiving_boundary.info.yml", "OPERATE.md"):
            result[name] = self.retain_source("operating-source", name, (directory / name).read_bytes())
        for source in sorted((self.root / "native-source").glob("*/source-result.json")):
            role = source.parent.name
            result[role] = self.retain_source(role, "source-result.json", source.read_bytes())
        return result

    def native_phase(self, handoff):
        source, destination = handoff["source"], handoff["destination"]
        if source["site_uuid"] == destination["site_uuid"]:
            raise ValueError("Choose the independently owned source and destination sites.")
        source_profile, destination_profile = source["profile"], destination["profile"]
        for profile in (source_profile, destination_profile):
            if profile.get("source_kind") != "drush":
                raise ValueError("Use the actual installed Drupal/Drush site profiles.")
        self.seed("destination", "initial", destination_profile, destination["site_uuid"])
        seeded = self.seed("source", "initial", source_profile, source["site_uuid"])
        operating_source = self.retain_operating_source(handoff)
        source_environment = self.environment("source", source_profile)
        destination_environment = self.environment("destination", destination_profile)
        family = self.call("family", "packages.families.save", {
            "label": "GovHub commissioning community-service content receiving",
            "owner": "GovHub commissioning receiving engineer",
            "environment_id": destination_environment["id"],
            "source_environment_id": source_environment["id"],
            "comparison_id": "govhub_commissioning-content-migration-workshare-20261012",
            "plan_ids": handoff.get("plan_ids", []),
            "notes": "Original Drupal graph: bilingual root, linked guidance, taxonomy and attachment. The first archive is returned, corrected at its original source, compared and reviewed for native receiving.",
            "recovery_instruction": "Read or resume the original import operation. The source-inclusive handover and private workspace backup retain every edition, decision, native command and source file; any whole-site restoration uses the selected original site backup."})["family"]
        family_id = family["id"]
        actual_family = self.workspace.dispatch("packages.families.get", {"family_id": family_id}, self.actor)["family"]
        for key in ("environment_id", "source_environment_id", "comparison_id", "plan_ids"):
            if actual_family[key] != family[key]:
                raise ValueError("The original content workshare changed its " + key + "; reconcile that same family.")
        self.workspace.start_worker()
        try:
            first_export = self.queue("export-original", "packages.exports.create", {
                "family_id": family_id, "roots": [seeded["root"]],
                "options": {"package_type": "content_entity", "max_depth": 20, "unpublished": True},
                "reason": "Retain the complete original source graph for editorial review."})
            first_edition = self.call("edition-original", "packages.editions.create", {
                "family_id": family_id, "export_operation_id": first_export["id"],
                "label": "Original source schedule", "notes": "Original native export before the receiving-hours correction."})["edition"]
            first_preview = self.queue("preview-original", "packages.previews.create", {
                "family_id": family_id, "edition_id": first_edition["id"],
                "reason": "Review this original archive on its selected destination."})
            first_view = self.workspace.dispatch("packages.previews.get", {"preview_operation_id": first_preview["id"]}, self.actor)
            returned = self.call("return-original", "packages.reviews.save", {
                "preview_operation_id": first_preview["id"], "preview_sha256": first_view["preview_file"]["sha256"],
                "expected_review_id": "", "decision": "RETURN",
                "reason": "Correct the draft receiving hours in both languages and the attachment, and include the accessible-appointment guidance."})["review"]
            corrected_source = self.seed("source", "corrected", source_profile, source["site_uuid"])
            operating_source["source-corrected"] = self.retain_source("source-corrected", "source-result.json", corrected_source)
            second_export = self.queue("export-corrected", "packages.exports.create", {
                "family_id": family_id, "roots": [seeded["root"]],
                "options": {"package_type": "content_entity", "max_depth": 20, "unpublished": True},
                "reason": "Retain the corrected original Drupal graph as a new edition."})
            second_edition = self.call("edition-corrected", "packages.editions.create", {
                "family_id": family_id, "export_operation_id": second_export["id"],
                "previous_edition_id": first_edition["id"], "label": "Reviewed receiving hours and access guidance",
                "notes": "Corrected at the original source; includes both languages and complete native attachment bytes."})["edition"]
            second_preview = self.queue("preview-corrected", "packages.previews.create", {
                "family_id": family_id, "edition_id": second_edition["id"],
                "reason": "Review the corrected graph against the same original destination."})
            second_view = self.workspace.dispatch("packages.previews.get", {"preview_operation_id": second_preview["id"]}, self.actor)
            comparison = self.call("compare-original-corrected", "packages.comparisons.create", {
                "baseline_preview_operation_id": first_preview["id"],
                "candidate_preview_operation_id": second_preview["id"]})["comparison"]
            if second_view["preview"]["issues"]:
                raise ValueError("The actual corrected native preview has issues: " + canonical(second_view["preview"]["issues"]))
            if not comparison["counts"]["CHANGED"] or not comparison["counts"]["ADDED"]:
                raise ValueError("The retained native comparison did not contain the original corrected and added source content.")
            approved = self.call("approve-corrected", "packages.reviews.save", {
                "preview_operation_id": second_preview["id"], "preview_sha256": second_view["preview_file"]["sha256"],
                "expected_review_id": "", "comparison_id": comparison["id"], "decision": "APPROVE",
                "reason": "Reviewed the complete corrected source, both languages, linked guidance, native attachment changes and destination-owned publication."})["review"]
            boundary = self.root / "original-native-boundary.json"
            immutable(boundary, {"operation": OP, "site_uuid": destination["site_uuid"], "root_uuid": ROOT_UUID})
            original_env = os.environ.get("GOVHUB_RECEIVING_BOUNDARY")
            os.environ["GOVHUB_RECEIVING_BOUNDARY"] = str(boundary)
            try:
                created = self.call("import-reviewed", "packages.imports.create", {
                    "family_id": family_id, "edition_id": second_edition["id"], "review_id": approved["id"],
                    "reason": "Apply this exact reviewed native edition, retaining the original import identity through its controlled shutdown and recovery."})
                imported = self.wait(created["operation"]["id"], tuple(FINAL))
                interrupt_record = self.root / "native-shutdown-observed.json"
                if not interrupt_record.exists():
                    consumed = Path(str(boundary) + ".consumed")
                    if imported["state"] == "COMPLETE" or not consumed.is_file():
                        raise ValueError("The original native boundary module did not reach the selected first import shutdown.")
                    native_status = self.queue("read-uncommitted-original", "packages.receiving.create", {
                        "family_id": family_id, "import_operation_id": imported["id"],
                        "reason": "Read the original import receipt after its actual pre-commit shutdown."})
                    if self.native(native_status).get("receiving", {}).get("status") != "NO_COMMITTED_IMPORT_RECEIPT":
                        raise ValueError("The interrupted native import unexpectedly retained a committed receipt.")
                    after_rollback = self.queue("preview-after-original-shutdown", "packages.previews.create", {
                        "family_id": family_id, "edition_id": second_edition["id"],
                        "reason": "Read the original destination after the actual import rollback."})
                    observed = self.native(after_rollback)["preview"]
                    expected = second_view["preview"]
                    if observed["before_sha256"] != expected["before_sha256"] or observed["target_sha256"] != expected["target_sha256"]:
                        raise ValueError("The actual native shutdown did not preserve the reviewed original destination.")
                    immutable(interrupt_record, {"import_operation_id": imported["id"],
                        "native": imported, "boundary": read(consumed),
                        "receipt_read": native_status, "rollback_preview": after_rollback,
                        "same_original_destination": True})
                if imported["state"] != "COMPLETE":
                    resumed = self.call("resume-original-import", "operations.resume", {
                        "operation_id": imported["id"], "expected_revision": imported["revision"],
                        "reason": "Continue the same original import after its positively completed native shutdown and verified rollback."})
                    imported = self.wait(resumed["operation"]["id"])
            finally:
                if original_env is None:os.environ.pop("GOVHUB_RECEIVING_BOUNDARY", None)
                else:os.environ["GOVHUB_RECEIVING_BOUNDARY"] = original_env
            native = self.native(imported)
            if native.get("receiving", {}).get("status") != "MATCHES_SAVED_IMPORT":
                raise ValueError("The original applied native receipt and current content differ.")
            after = native["receipt"]["after"]
            root_after = after["node:" + ROOT_UUID]
            translations = root_after["translations"]
            if translations["en"]["published"] is not True or translations["es"]["published"] is not False:
                raise ValueError("The original destination-owned English publication or newly received Spanish draft differs.")
            publication = {language: {"published": value["published"],
                                      "moderation_state": value["moderation_state"]}
                           for language, value in translations.items()}
            for name in ("guide", "accessibility", "topic"):
                kind = "taxonomy_term" if name == "topic" else "node"
                if not after[kind + ":" + corrected_source["identities"][name]]["exists"]:
                    raise ValueError("The native imported graph omits its original " + name + " identity.")
            document = root_after["linked_assets"]["file:" + corrected_source["identities"]["document"]]
            if (document["bytes"], document["sha256"]) != (corrected_source["asset"]["bytes"], corrected_source["asset"]["sha256"]):
                raise ValueError("The received attachment differs from the corrected original source bytes.")
            replay_request = read(self.requests / "import-reviewed.request.json")
            replay = self.workspace.dispatch(replay_request["action"], replay_request["payload"], self.actor)
            if replay["operation"]["id"] != imported["id"]:
                raise ValueError("The same application request created another native import.")
            received = self.queue("read-applied-original", "packages.receiving.create", {
                "family_id": family_id, "import_operation_id": imported["id"],
                "reason": "Read the completed original import through the receiving operator."})
            if self.native(received).get("receiving", {}).get("status") != "MATCHES_SAVED_IMPORT":
                raise ValueError("The receiving read did not recover the original matching import.")
            outcome = {"schema": "govhub.commissioning.native-operation.v1", "operation": OP,
                "completed_at": now(), "family_id": family_id,
                "original_export_id": first_export["id"], "original_edition_id": first_edition["id"],
                "returned_review_id": returned["id"], "corrected_export_id": second_export["id"],
                "corrected_edition_id": second_edition["id"], "comparison_id": comparison["id"],
                "comparison_counts": comparison["counts"], "review_id": approved["id"],
                "import_operation_id": imported["id"], "native_receiving_operation_id": received["id"],
                "import_state": native["import_state"], "receipt": native["receipt"],
                "destination_publication": publication,
                "receiving": self.native(received)["receiving"],
                "repeated_request_operation_id": replay["operation"]["id"],
                "native_shutdown": read(self.root / "native-shutdown-observed.json"),
                "source_seed": seeded, "corrected_source_seed": corrected_source,
                "operating_source": operating_source}
            outcome["shutdown_source"] = self.retain_source("native-shutdown", "native-shutdown-observed.json",
                (self.root / "native-shutdown-observed.json").read_bytes())
            immutable(self.root / "operator-native-result.json", outcome)
            self.progress("NATIVE_CONTENT_RECEIVED", family_id=family_id,
                          import_operation_id=imported["id"], comparison_counts=comparison["counts"])
            return outcome
        finally:
            self.workspace.stop_worker()
            if self.workspace._worker and self.workspace._worker.is_alive():
                self.workspace._worker.join(timeout=10)
            if self.workspace._worker and self.workspace._worker.is_alive():
                raise RuntimeError("The original native worker still owns its command; retain this controller for reconciliation.")

def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--application-root", type=Path, required=True)
    parser.add_argument("--profiles", type=Path, required=True)
    parser.add_argument("--workspace", type=Path, required=True)
    parser.add_argument("--source-root", type=Path, required=True)
    parser.add_argument("--out", type=Path, required=True)
    parser.add_argument("--username", default="govhub_commissioning-engineer")
    parser.add_argument("--password-env", default="GOVHUB_PASSWORD")
    parser.add_argument("--phase", choices=("native", "receive"), required=True)
    parser.add_argument("--application-zip", type=Path)
    parser.add_argument("--application-sha256")
    parser.add_argument("--module-archive", type=Path)
    parser.add_argument("--timeout", type=int, default=900)
    args = parser.parse_args()
    os.umask(0o077)
    for path in (args.application_root, args.profiles, args.workspace, args.source_root, args.out):
        if not path.is_absolute() or path.is_symlink():
            raise ValueError("Use the original absolute source, profile and operation paths.")
    args.source_root.mkdir(mode=0o700, parents=True, exist_ok=True)
    sys.path.insert(0, str(args.application_root / "workspace"))
    from govhub import open_workspace
    handoff = read(args.profiles)
    if handoff.get("schema") != "govhub.commissioning.native-sites.v1" or handoff.get("operation") != OP:
        raise ValueError("Use the original selected GovHub commissioning native sites.")
    secret = os.environ.get(args.password_env)
    if not secret or len(secret) < 12:
        raise ValueError("The existing original engineer password environment is required.")
    with controller(args.out):
        immutable(args.out / "native-sites.json", handoff)
        scope = {"operation": OP, "workspace": str(args.workspace),
                 "source_root": str(args.source_root), "username": args.username, "mode": "PILOT"}
        initialization_path = args.out / "workspace-initialization.json"
        if initialization_path.exists():
            initialization = read(initialization_path)
            if any(initialization.get(key) != value for key, value in scope.items()):
                raise ValueError("The original private workspace initialization belongs to another case.")
        else:
            initialization = {**scope, "new_workspace": not (args.workspace / "assessment.sqlite3").exists()}
            immutable(initialization_path, initialization)
        missing_storage = any(not (args.workspace / name).exists()
                              for name in ("assessment.sqlite3", "sources", "reconciliation.key"))
        create = bool(initialization["new_workspace"] and missing_storage)
        workspace = open_workspace(args.workspace, args.source_root, create=create,
                                   name="GovHub commissioning Content Packages receiving", mode="PILOT")
        if not workspace.user(args.username):
            with workspace.connect(snapshot=True) as db:
                accounts = db.execute("SELECT COUNT(*) FROM users").fetchone()[0]
            if not initialization["new_workspace"] or accounts:
                raise ValueError("Use the existing original workspace administrator.")
            workspace.add_user(args.username, secret, "admin")
        actor = workspace.authenticate(args.username, secret)
        if not actor:
            raise ValueError("The retained original engineer account was not recognized.")
        operation = Operator(args, workspace, actor)
        try:
            if args.phase == "native":
                final = args.out / "operator-native-result.json"
                if final.exists():
                    outcome = read(final)
                    original = operation.get(outcome["import_operation_id"])
                    if original["state"] != "COMPLETE":
                        raise ValueError("The saved original import requires its existing continuation.")
                    print(json.dumps({"phase": "REOPENED_ORIGINAL_NATIVE_OPERATION", "result": outcome}), flush=True)
                else:
                    with workspace.service_lease():
                        outcome = operation.native_phase(handoff)
                    print(json.dumps({"phase": "ORIGINAL_NATIVE_OPERATION_COMPLETE", "result": outcome}), flush=True)
            else:
                if not args.application_zip or not args.application_sha256 or not args.module_archive:
                    raise ValueError("Complete receiving requires the original application ZIP, its SHA and upstream module archive.")
                outcome = read(args.out / "operator-native-result.json")
                from content_packages.receiving import receive
                receiving = argparse.Namespace(
                    workspace=args.workspace, source_root=args.source_root,
                    assessment_core=args.application_root / "workspace/vendor/assessment-core",
                    username=args.username, password_env=args.password_env, password_stdin=False,
                    operation_key="govhub_commissioning-original-customer-20261012",
                    family_id=[outcome["family_id"]], import_operation_id=[outcome["import_operation_id"]],
                    application_zip=str(args.application_zip), application_sha256=args.application_sha256,
                    module_archive=str(args.module_archive), destination=str(args.out / "customer-receiving"),
                    name="GovHub commissioning Content Packages complete engineer handover", timeout=args.timeout)
                delivered = receive(receiving)
                repeated = receive(receiving)
                if canonical(delivered) != canonical(repeated):
                    raise ValueError("The repeated original receiving operation changed its completed result.")
                immutable(args.out / "operator-customer-result.json", delivered)
                operation.progress("COMPLETE_CUSTOMER_RECEIVING_REOPENED",
                                   family_id=outcome["family_id"], delivery=delivered["delivery"])
                print(json.dumps({"phase": "ORIGINAL_CUSTOMER_RECEIVING_COMPLETE", "result": delivered}), flush=True)
        finally:
            workspace.stop_worker()
    return 0

if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except Exception as error:
        print(json.dumps({"operation": OP, "error": str(error), "type": type(error).__name__}), file=sys.stderr, flush=True)
        raise SystemExit(2)

"""Content Packages in the original GovHub store, worker and delivery flow."""
from copy import deepcopy
import json

from govhub import GovHubError, digest, ident, json_bytes, now, packed, text
from .model import TYPES, READ_TYPES, NATIVE_RESULT, options, preview, selection
from .delivery import PackageDeliveryMixin


class NativeFacade:
    def __init__(self, original):
        self.original = original

    def __getattr__(self, name):
        return getattr(self.original, name)

    def execute(self, operation, config, source_paths, checkpoint=None, cancelled=None):
        if operation.get("type") in TYPES:
            from .native import execute
            return execute(operation, config, source_paths, checkpoint=checkpoint, cancelled=cancelled)
        return self.original.execute(operation, config, source_paths, checkpoint=checkpoint, cancelled=cancelled)


class PackagesMixin(PackageDeliveryMixin):
    def _native(self):
        return NativeFacade(super()._native())

    def _package_family(self, db, family_id):
        family = self._get(db, "package_family", family_id)
        versions = self._objects(db, "package_family_version", family_id)
        return dict(family, **versions[-1]["data"], revision=versions[-1]["id"]) if versions else dict(family, revision=family["id"])

    def _packages_summary(self, db):
        result = []
        for original in self._objects(db, "package_family"):
            family = self._package_family(db, original["id"])
            editions = self._objects(db, "package_edition", family["id"])
            reviews = self._objects(db, "package_review", family["id"])
            result.append(dict(family, edition_count=len(editions), latest_edition_id=editions[-1]["id"] if editions else "", latest_review=reviews[-1] if reviews else None))
        return {"families": result, "observed_at": now()}

    def _package_target(self, db, environment_id):
        environment = self._record_db(db, "environments", environment_id)
        profile = self._config(db, environment["id"])
        if environment["archived"] or environment["data"]["provider_resource_id"] != profile["config"]["environment_id"] or environment["data"]["native_profile"] != profile["revision"]:
            raise GovHubError("PACKAGE_TARGET_CHANGED", "Reopen the selected environment and its current native profile.", 409)
        if profile["config"].get("source_kind") != "drush":
            raise GovHubError("PACKAGE_NATIVE_PROFILE", "Select the original Drupal / Drush profile for this site's content operation.")
        return environment, profile

    def _packages_family_save(self, payload, actor):
        with self.connect(write=True) as db:
            key, fingerprint, prior = self._request(db, payload, actor)
            if prior:
                return prior
            environment, profile = self._package_target(db, payload.get("environment_id"))
            source_id = text(payload.get("source_environment_id", ""), 240)
            if source_id:
                self._package_target(db, source_id)
            plan_ids = payload.get("plan_ids", [])
            if not isinstance(plan_ids, list) or any(not isinstance(p, str) for p in plan_ids) or len(set(plan_ids)) != len(plan_ids):
                raise GovHubError("PACKAGE_COHORT", "Select each original cutover or recovery plan once.")
            for plan_id in plan_ids:
                self._plan(db, plan_id)
            data = {
                "label": text(payload.get("label", ""), 500, True),
                "owner": text(payload.get("owner", actor["name"]), 500, True),
                "notes": text(payload.get("notes", ""), 32000),
                "environment_id": environment["id"],
                "source_environment_id": source_id,
                "comparison_id": text(payload.get("comparison_id", ""), 240),
                "plan_ids": plan_ids,
                "recovery_instruction": text(payload.get("recovery_instruction", ""), 32000),
                "profile_revision": profile["revision"],
            }
            if payload.get("family_id"):
                family = self._package_family(db, payload["family_id"])
                if payload.get("expected_revision") != family["revision"]:
                    raise GovHubError("PACKAGE_FAMILY_REVISION", "The content workshare changed. Reopen its current version before saving.", 409)
                version = self._object(db, "package_family_version", {"family_id": family["id"], "previous_revision": family["revision"], "data": data}, parent=family["id"], actor=actor["name"])
                family = dict(family, **data, revision=version["id"])
            else:
                original = self._object(db, "package_family", data, actor=actor["name"])
                family = dict(original, revision=original["id"])
            result = {"family": family}
            self._remember(db, key, fingerprint, result, actor)
            self._changed(db, actor, "Content package workshare saved", "package_family", family["id"])
            return result

    def _package_artifact(self, db, operation, role, sha256=None):
        candidates = [item for item in operation.get("retained_artifacts", []) if item.get("role") == role and (sha256 is None or item["file"]["sha256"] == sha256)]
        if not candidates:
            raise GovHubError("PACKAGE_NATIVE_OUTPUT", "The original native operation has not retained " + role + ".", 409)
        item = candidates[-1]["file"]
        actual = self._file_row(db, item["id"])
        if actual["sha256"] != item["sha256"] or actual["bytes"] != item["bytes"]:
            raise GovHubError("PACKAGE_NATIVE_OUTPUT_CHANGED", "The retained native output identity changed.", 409)
        return actual, self._verify_file(actual)

    def _package_result(self, db, operation):
        observed = (operation.get("native_result") or {}).get("observations", {})
        ref = observed.get("result_file") or {}
        file, path = self._package_artifact(db, operation, "package_result", ref.get("sha256"))
        native = json_bytes(path.read_bytes())
        if native.get("schema") != NATIVE_RESULT or native.get("operation_id") != operation["id"] or native.get("action") != TYPES.get(operation["type"]):
            raise GovHubError("PACKAGE_NATIVE_RESULT", "The retained bridge output belongs to another original operation.", 409)
        if observed.get("package_result") != native:
            raise GovHubError("PACKAGE_NATIVE_RESULT_CHANGED", "The observed native result differs from its original saved bytes.", 409)
        return file, native

    def _packages_edition_create(self, payload, actor):
        with self.connect(write=True) as db:
            key, fingerprint, prior = self._request(db, payload, actor)
            if prior:
                return prior
            family = self._package_family(db, payload.get("family_id"))
            export_id = text(payload.get("export_operation_id", ""), 240)
            if export_id:
                operation = self._operation(db, export_id)
                if operation.get("package_family_id") != family["id"] or operation["type"] != "PACKAGE_EXPORT" or operation["state"] != "COMPLETE":
                    raise GovHubError("PACKAGE_EXPORT_STATE", "Choose this workshare's completed original graph export.", 409)
                _, native = self._package_result(db, operation)
                archive = native.get("archive", {})
                file, _ = self._package_artifact(db, operation, "package_archive", archive.get("sha256"))
                if payload.get("file_id") and payload["file_id"] != file["id"]:
                    raise GovHubError("PACKAGE_ARCHIVE_IDENTITY", "The selected file differs from the original graph export.", 409)
                provenance = {"export_operation_id": operation["id"], "source_target": native.get("target"), "roots": native.get("roots", [])}
            else:
                file = self._file_row(db, payload.get("file_id"))
                self._verify_file(file)
                provenance = {"source_reference": text(payload.get("source_reference", ""), 16000)}
            versions = self._objects(db, "package_edition", family["id"])
            previous_id = text(payload.get("previous_edition_id", ""), 240)
            if previous_id:
                previous = self._get(db, "package_edition", previous_id)
                if previous["family_id"] != family["id"]:
                    raise GovHubError("PACKAGE_EDITION_FAMILY", "Choose the preceding archive from this workshare.")
            elif versions:
                previous_id = versions[-1]["id"]
            edition = self._object(db, "package_edition", {
                "family_id": family["id"], "family_revision": family["revision"],
                "label": text(payload.get("label", file["filename"]), 500, True),
                "file_id": file["id"], "archive_sha256": file["sha256"], "archive_bytes": file["bytes"],
                "filename": file["filename"], "previous_edition_id": previous_id,
                "notes": text(payload.get("notes", ""), 32000), "provenance": provenance,
            }, parent=family["id"], actor=actor["name"])
            result = {"edition": edition}
            self._remember(db, key, fingerprint, result, actor)
            self._changed(db, actor, "Original content archive edition retained", "package_edition", edition["id"], {"archive_sha256": file["sha256"]})
            return result

    def _package_preview_record(self, db, operation_id):
        operation = self._operation(db, operation_id)
        if operation["type"] != "PACKAGE_PREVIEW" or operation["state"] != "COMPLETE":
            raise GovHubError("PACKAGE_PREVIEW_STATE", "Select a completed original native archive preview.", 409)
        file, native = self._package_result(db, operation)
        value = preview(native.get("preview"), operation["package_request"]["archive_sha256"])
        return operation, file, value

    def _packages_comparison_create(self, payload, actor):
        with self.connect(write=True) as db:
            key, fingerprint, prior = self._request(db, payload, actor)
            if prior:
                return prior
            baseline, baseline_file, before = self._package_preview_record(db, payload.get("baseline_preview_operation_id"))
            candidate, candidate_file, after = self._package_preview_record(db, payload.get("candidate_preview_operation_id"))
            if baseline["package_family_id"] != candidate["package_family_id"]:
                raise GovHubError("PACKAGE_COMPARISON_SCOPE", "Select two archive previews from the same content workshare.")
            if baseline["package_edition_id"] == candidate["package_edition_id"]:
                raise GovHubError("PACKAGE_COMPARISON_EDITION", "Choose the original and corrected archive editions.")
            def changes(previous, current, identity, source):
                old = {row[identity]: row for row in previous}
                new = {row[identity]: row for row in current}
                if len(old) != len(previous) or len(new) != len(current):
                    raise GovHubError("PACKAGE_COMPARISON_IDENTITY", "The original native preview contains a repeated source identity.", 409)
                output = []
                for item_id in sorted(set(old) | set(new)):
                    a, b = old.get(item_id), new.get(item_id)
                    state = "ADDED" if a is None else "EXCLUDED" if b is None else "UNCHANGED" if source(a) == source(b) else "CHANGED"
                    output.append({"identity": item_id, "change": state, "baseline": a, "candidate": b})
                return output
            packages = changes(before["packages"], after["packages"], "key",
                               lambda row: packed({"source": row["source"]["sha256"],
                                   "entity_type": row["entity_type"], "bundle": row["bundle"],
                                   "references": row.get("references", []), "assets": row.get("assets", [])}))
            assets = changes(before["assets"], after["assets"], "path",
                             lambda row: (row["sha256"], row["bytes"]))
            comparison = self._object(db, "package_comparison", {
                "schema": "govhub.content-packages.comparison.v1",
                "family_id": candidate["package_family_id"],
                "baseline_edition_id": baseline["package_edition_id"],
                "candidate_edition_id": candidate["package_edition_id"],
                "baseline_preview_operation_id": baseline["id"],
                "candidate_preview_operation_id": candidate["id"],
                "baseline_preview_file_id": baseline_file["id"],
                "candidate_preview_file_id": candidate_file["id"],
                "baseline_preview_sha256": baseline_file["sha256"],
                "candidate_preview_sha256": candidate_file["sha256"],
                "baseline_target_sha256": before["target_sha256"],
                "candidate_target_sha256": after["target_sha256"],
                "packages": packages, "assets": assets,
                "counts": {kind: sum(row["change"] == kind for row in packages)
                           for kind in ("ADDED", "CHANGED", "UNCHANGED", "EXCLUDED")},
                "exclusion_behavior": "Excluded packages remain on the destination; native archive import does not delete them.",
            }, parent=candidate["package_family_id"], actor=actor["name"])
            result = {"comparison": comparison}
            self._remember(db, key, fingerprint, result, actor)
            self._changed(db, actor, "Original and corrected content archives compared", "package_comparison", comparison["id"])
            return result

    def _packages_review_save(self, payload, actor):
        self._authorize(actor, "reviewer")
        if payload.get("decision") not in {"APPROVE", "RETURN"}:
            raise GovHubError("PACKAGE_REVIEW", "Approve this exact native preview or return it for correction.")
        with self.connect(write=True) as db:
            key, fingerprint, prior = self._request(db, payload, actor)
            if prior:
                return prior
            operation = self._operation(db, payload.get("preview_operation_id"))
            if operation["type"] != "PACKAGE_PREVIEW" or operation["state"] != "COMPLETE":
                raise GovHubError("PACKAGE_PREVIEW_STATE", "Open the completed native archive preview.", 409)
            family = self._package_family(db, operation["package_family_id"])
            edition = self._get(db, "package_edition", operation["package_edition_id"])
            result_file, result = self._package_result(db, operation)
            if result_file["sha256"] != payload.get("preview_sha256"):
                raise GovHubError("PACKAGE_REVIEW_PREVIEW", "Save the review against the exact displayed native result bytes.", 409)
            native_preview = preview(result.get("preview"), edition["archive_sha256"])
            if operation["package_family_revision"] != family["revision"]:
                raise GovHubError("PACKAGE_REVIEW_SCOPE", "The workshare changed after this preview. Prepare the current target and scope.", 409)
            if payload["decision"] == "APPROVE" and native_preview["issues"]:
                raise GovHubError("PACKAGE_PREVIEW_ISSUES", "Resolve the native archive or destination issues before applying this edition.", fields={"preview": str(len(native_preview["issues"])) + " original module issues."})
            reviews = [r for r in self._objects(db, "package_review", family["id"]) if r["preview_operation_id"] == operation["id"]]
            latest_id = reviews[-1]["id"] if reviews else ""
            if payload.get("expected_review_id", "") != latest_id:
                raise GovHubError("PACKAGE_REVIEW_REVISION", "A newer review decision exists for this preview. Reopen it before saving.", 409)
            comparison_id = text(payload.get("comparison_id", ""), 240)
            if comparison_id:
                comparison = self._get(db, "package_comparison", comparison_id)
                if comparison["candidate_preview_operation_id"] != operation["id"] or comparison["candidate_preview_sha256"] != result_file["sha256"]:
                    raise GovHubError("PACKAGE_REVIEW_COMPARISON", "Select the source comparison for this exact candidate preview.", 409)
            decision = self._object(db, "package_review", {
                "family_id": family["id"], "family_revision": family["revision"],
                "edition_id": edition["id"], "archive_sha256": edition["archive_sha256"],
                "preview_operation_id": operation["id"], "preview_file_id": result_file["id"],
                "preview_sha256": result_file["sha256"], "profile_revision": operation["profile"]["revision"],
                "target_sha256": native_preview["target_sha256"], "before_sha256": native_preview["before_sha256"],
                "decision": payload["decision"], "reason": text(payload.get("reason", ""), 32000, True),
                "previous_review_id": latest_id, "comparison_id": comparison_id,
            }, parent=family["id"], actor=actor["name"])
            response = {"review": decision}
            self._remember(db, key, fingerprint, response, actor)
            self._changed(db, actor, "Exact native content-package review saved", "package_review", decision["id"], {"decision": decision["decision"]})
            return response

    def _packages_queue(self, type_, payload, actor):
        with self.connect(write=True) as db:
            key, fingerprint, prior = self._request(db, payload, actor)
            if prior:
                return prior
            family = self._package_family(db, payload.get("family_id"))
            source_operation = None
            if type_ == "PACKAGE_STATUS":
                source_operation = self._operation(db, payload.get("import_operation_id"))
                if source_operation.get("package_family_id") != family["id"] or source_operation["type"] != "PACKAGE_IMPORT":
                    raise GovHubError("PACKAGE_RECEIVING_SOURCE", "Choose this workshare's original import operation.")
                environment, profile = deepcopy(source_operation["environment"]), deepcopy(source_operation["profile"])
            else:
                target_id = (family["source_environment_id"] or family["environment_id"]) if type_ == "PACKAGE_EXPORT" else family["environment_id"]
                environment, profile = self._package_target(db, target_id)
            edition, review, preview_operation = None, None, None
            if type_ in {"PACKAGE_PREVIEW", "PACKAGE_IMPORT"}:
                edition = self._get(db, "package_edition", payload.get("edition_id"))
                if edition["family_id"] != family["id"]:
                    raise GovHubError("PACKAGE_EDITION_FAMILY", "Select an archive from this content workshare.")
                file = self._file_row(db, edition["file_id"])
                if file["sha256"] != edition["archive_sha256"] or file["bytes"] != edition["archive_bytes"]:
                    raise GovHubError("PACKAGE_ARCHIVE_CHANGED", "The original retained archive changed.", 409)
                self._verify_file(file)
            if type_ == "PACKAGE_IMPORT":
                review = self._get(db, "package_review", payload.get("review_id"))
                if review["family_id"] != family["id"] or review["edition_id"] != edition["id"] or review["decision"] != "APPROVE":
                    raise GovHubError("PACKAGE_IMPORT_REVIEW", "Select the saved approval for this exact archive and target.")
                reviews = [r for r in self._objects(db, "package_review", family["id"]) if r["preview_operation_id"] == review["preview_operation_id"]]
                if reviews[-1]["id"] != review["id"] or review["family_revision"] != family["revision"] or review["profile_revision"] != profile["revision"]:
                    raise GovHubError("PACKAGE_IMPORT_REVISION", "The scope, target or review changed. Preview and review that current edition.", 409)
                preview_operation = self._operation(db, review["preview_operation_id"])
                result_file, result = self._package_result(db, preview_operation)
                if result_file["sha256"] != review["preview_sha256"]:
                    raise GovHubError("PACKAGE_IMPORT_PREVIEW", "The original reviewed preview bytes changed.", 409)
                preview(result.get("preview"), edition["archive_sha256"])
            parameters = {"action": TYPES[type_], "environment_id": profile["config"]["environment_id"]}
            if type_ == "PACKAGE_EXPORT":
                try:
                    parameters.update(roots=selection(payload.get("roots")), options=options(payload.get("options")))
                except ValueError as exc:
                    raise GovHubError("PACKAGE_GRAPH_SELECTION", str(exc)) from exc
            if edition:
                parameters.update(archive_sha256=edition["archive_sha256"], archive_bytes=edition["archive_bytes"], edition_id=edition["id"])
            if review:
                parameters.update(review_id=review["id"], preview_sha256=review["preview_sha256"], target_sha256=review["target_sha256"], before_sha256=review["before_sha256"])
            if source_operation:
                parameters.update(import_operation_id=source_operation["id"], import_intent_sha256=source_operation["package_intent_sha256"])
                for name in ("archive_sha256", "archive_bytes", "edition_id", "target_sha256", "before_sha256"):
                    if name in source_operation["package_request"]:
                        parameters[name] = source_operation["package_request"][name]
                edition = self._get(db, "package_edition", parameters["edition_id"])
            timestamp, operation_id = now(), ident("operation-")
            business_intent = {"operation_id": operation_id, "family_id": family["id"], "family_revision": family["revision"], "parameters": parameters, "provider_environment_id": profile["config"]["environment_id"]}
            value = {
                "id": operation_id, "type": type_, "native_action": "drupal-package-" + TYPES[type_],
                "state": "QUEUED", "plan_id": "", "plan_revision": family["revision"], "plan": None,
                "audit_id": None, "review_id": review["id"] if review else None,
                "environment_id": environment["id"], "environment": environment, "profile": profile,
                "provider_environment_id": profile["config"]["environment_id"],
                "source_snapshot_id": "", "source_snapshot": None, "source_snapshot_sha256": "",
                "authorization_reference": environment["data"].get("authorization_reference", ""),
                "agency_ids": [family["comparison_id"]] if family["comparison_id"] else [],
                "package_family_id": family["id"], "package_family_revision": family["revision"],
                "package_edition_id": edition["id"] if edition else "",
                "package_review_id": review["id"] if review else "",
                "package_preview_operation_id": preview_operation["id"] if preview_operation else "",
                "package_request": parameters, "package_intent_sha256": digest(packed(business_intent)),
                "package_intent": business_intent,
                "package_reason": text(payload.get("reason", ""), 32000, True),
                "created_at": timestamp, "updated_at": timestamp, "author": actor["name"],
                "progress": {"completed": 0, "total": 1, "stage": "QUEUED", "detail": "Queued for the selected native Content Packages module"},
                "error": None, "cancel_requested": False, "native_attempted": False,
                "checkpoint": None, "resume_checkpoint": None, "native_capture_file_id": None,
                "native_result": None, "result_snapshot_id": None, "actual_started_at": None,
                "actual_finished_at": None,
            }
            operation = self._write_operation(db, value, actor, "Original native content-package action queued", {"action": TYPES[type_], "archive_sha256": parameters.get("archive_sha256")})
            response = {"operation": operation}
            self._remember(db, key, fingerprint, response, actor)
        self._worker_wake.set()
        return response

    def _operation_sources(self, value, output_dir):
        if value.get("type") not in TYPES:
            return super()._operation_sources(value, output_dir)
        files = []
        with self.connect(snapshot=True) as db:
            checkpoint = value.get("resume_checkpoint") or value.get("checkpoint") or {}
            checkpoint = checkpoint.get("resume_checkpoint", checkpoint.get("state", checkpoint))
            if value["type"] == "PACKAGE_IMPORT" and not value.get("native_attempted") and not checkpoint.get("mutation_started"):
                family = self._package_family(db, value["package_family_id"])
                reviews = [r for r in self._objects(db, "package_review", family["id"]) if r["preview_operation_id"] == value["package_preview_operation_id"]]
                if family["revision"] != value["package_family_revision"] or not reviews or reviews[-1]["id"] != value["package_review_id"] or reviews[-1]["decision"] != "APPROVE":
                    raise GovHubError("PACKAGE_QUEUED_REVIEW_CHANGED", "The queued archive's scope or review changed before native import. Reopen its current decision.", 409)
                _, profile = self._package_target(db, family["environment_id"])
                if profile["revision"] != value["profile"]["revision"]:
                    raise GovHubError("PACKAGE_QUEUED_TARGET_CHANGED", "The native target changed before this queued import started.", 409)
            if value.get("package_edition_id"):
                edition = self._get(db, "package_edition", value["package_edition_id"])
                file = self._file_row(db, edition["file_id"])
                if file["sha256"] != value["package_request"]["archive_sha256"] or file["bytes"] != value["package_request"]["archive_bytes"]:
                    raise GovHubError("PACKAGE_ORIGINAL_ARCHIVE", "The queued content archive differs from its original source edition.", 409)
                files.append({"role": "archive", "file_id": file["id"], "path": str(self._verify_file(file)), "sha256": file["sha256"], "bytes": file["bytes"]})
            if value.get("package_review_id"):
                review = self._get(db, "package_review", value["package_review_id"])
                file = self._file_row(db, review["preview_file_id"])
                if file["sha256"] != review["preview_sha256"]:
                    raise GovHubError("PACKAGE_ORIGINAL_REVIEW", "The queued native preview differs from its reviewed source.", 409)
                files.append({"role": "reviewed_preview", "file_id": file["id"], "path": str(self._verify_file(file)), "sha256": file["sha256"], "bytes": file["bytes"]})
        return {"package_request": deepcopy(value["package_request"]), "package_intent": deepcopy(value["package_intent"]),
                "package_files": files, "output_dir": str(output_dir),
                "checkpoint": value.get("resume_checkpoint") or value.get("checkpoint"),
                "workspace_relocations": self._workspace_relocations(),
                "snapshot_id": "", "snapshot_sha256": "", "rows": [], "bindings": []}

    def _content_native_completion(self, current, native_result):
        super()._content_native_completion(current, native_result)
        if current.get("type") in TYPES and native_result.get("status") == "COMPLETE":
            current["state"] = "COMPLETE"
            current["progress"] = {"completed": 1, "total": 1, "stage": "COMPLETE", "detail": "Original native content-package result and receiving artifacts retained"}

    def _operation_summary(self, value):
        result = super()._operation_summary(value)
        return dict(result, **{name: value[name] for name in ("package_family_id", "package_edition_id", "package_review_id") if name in value})

    def _packages_dispatch(self, action, payload, actor):
        handlers = {
            "families.save": self._packages_family_save,
            "editions.create": self._packages_edition_create,
            "reviews.save": self._packages_review_save,
            "comparisons.create": self._packages_comparison_create,
            "exports.create": lambda p, a: self._packages_queue("PACKAGE_EXPORT", p, a),
            "previews.create": lambda p, a: self._packages_queue("PACKAGE_PREVIEW", p, a),
            "imports.create": lambda p, a: self._packages_queue("PACKAGE_IMPORT", p, a),
            "receiving.create": lambda p, a: self._packages_queue("PACKAGE_STATUS", p, a),
            "handovers.create": self._exports_create,
        }
        if action in handlers:
            return handlers[action](payload, actor)
        with self.connect(snapshot=True) as db:
            if action == "families.list":
                return self._packages_summary(db)
            if action == "families.get":
                family = self._package_family(db, payload.get("family_id"))
                operations = [json.loads(row[0]) for row in db.execute("SELECT data FROM govhub_operations ORDER BY rowid")]
                return {"family": family, "editions": self._objects(db, "package_edition", family["id"]), "reviews": self._objects(db, "package_review", family["id"]), "comparisons": self._objects(db, "package_comparison", family["id"]), "operations": [self._operation_summary(o) for o in operations if o.get("package_family_id") == family["id"]]}
            if action == "comparisons.get":
                return {"comparison": self._get(db, "package_comparison", payload.get("comparison_id"))}
            if action == "editions.get":
                edition = self._get(db, "package_edition", payload.get("edition_id"))
                file = self._file_row(db, edition["file_id"])
                self._verify_file(file)
                return {"edition": edition, "file": file}
            if action == "previews.get":
                operation = self._operation(db, payload.get("preview_operation_id"))
                if operation["type"] != "PACKAGE_PREVIEW":
                    raise GovHubError("PACKAGE_PREVIEW", "Choose the original native preview operation.")
                file, result = self._package_result(db, operation)
                value = deepcopy(result.get("preview"))
                assets = {item["file"]["sha256"]: item["file"] for item in operation.get("retained_artifacts", []) if item.get("role") == "package_asset"}
                for asset in (value or {}).get("assets", []):
                    if asset["sha256"] in assets:
                        asset["file"] = self._file_row(db, assets[asset["sha256"]]["id"])
                return {"operation": self._operation_summary(operation), "preview_file": file, "preview": value, "native": result}
            if action == "operations.get":
                operation = self._operation(db, payload.get("operation_id"))
                if operation["type"] not in TYPES:
                    raise GovHubError("PACKAGE_OPERATION", "Choose a native content-package operation.")
                return {"operation": operation, "events": self._objects(db, "operation_event", operation["id"]), "files": self._output_list(db, "operation", operation["id"])}
        raise GovHubError("PACKAGE_ACTION", "This content-package action does not exist.", 404)

