}
function Artifact([string]$Path,[string]$Role='') {
    $file=Get-Item -LiteralPath $Path
    $base=[IO.Path]::GetFullPath($script:Work).TrimEnd('\')+'\'
    Require ($file.FullName.StartsWith($base,[StringComparison]::OrdinalIgnoreCase)) 'Keep native artifacts under the original operation directory.'
    return @{path=$file.FullName.Substring($base.Length).Replace('\','/');bytes=$file.Length;sha256=Hash-File $file.FullName;role=$Role}
}
function Offline-Bytes {
    $prior=Get-Field $script:Journal 'availability'
    Require ($null -ne $prior) 'Capture the original maintenance state before applying it.'
    if($prior.original_offline){
        Require ([IO.File]::Exists($prior.original_file) -and (Hash-File $prior.original_file) -eq $prior.original_sha256) 'The original maintenance page is not intact in its private retained location.'
        return ,[IO.File]::ReadAllBytes($prior.original_file)
    }
    $marker='<!doctype html><title>Scheduled maintenance</title><h1>Scheduled maintenance</h1><p>The service is being updated.</p><!-- DNN operation '+$script:Request.operation_id+' -->'
    return ,[Text.Encoding]::UTF8.GetBytes($marker)
}
function Set-Offline {
    $file=Join-Path $script:SiteRoot 'app_offline.htm'
    $prior=Get-Field $script:Journal 'availability'
    if($null -eq $prior){
        $prior=@{original_offline=[IO.File]::Exists($file);original_pool_state=$script:Iis.pool_state;pool_stopped=$false;marked_at=[DateTime]::UtcNow.ToString('o')}
        if($prior.original_offline){
            $prior.original_file=Join-Path $script:Work 'original-app-offline.htm'
            $bytes=[IO.File]::ReadAllBytes($file);Atomic-Bytes $prior.original_file $bytes -Exclusive
            $prior.original_sha256=Hash-Bytes $bytes;$prior.original_sddl=(Get-Acl -LiteralPath $file).Sddl
        }
        $script:Journal.availability=$prior;Save-Journal
    }
    $bytes=Offline-Bytes;$sha=Hash-Bytes $bytes
    if([IO.File]::Exists($file)){Require ((Hash-File $file) -eq $sha) 'Another operator changed the maintenance page; preserve that actual state.'}
    else{Atomic-Bytes $file $bytes -Exclusive}
    $prior.marker_sha256=$sha;Save-Journal
    if(@($script:Iis.pool_applications).Count -eq 1 -and $prior.original_pool_state -eq 'Started'){
        $manager=[Microsoft.Web.Administration.ServerManager]::new()
        try{$pool=$manager.ApplicationPools[$script:PoolName];if($pool.State.ToString() -eq 'Started'){$null=$pool.Stop()};$prior.pool_stopped=$true;Save-Journal}finally{$manager.Dispose()}
    }
    return $prior
}
function Restore-Availability {
    $prior=Get-Field $script:Journal 'availability'
    if($null -eq $prior){return}
    $file=Join-Path $script:SiteRoot 'app_offline.htm'
    if($prior.original_offline){
        $bytes=Offline-Bytes
        if([IO.File]::Exists($file)){Require ((Hash-File $file) -eq $prior.marker_sha256) 'Another operator changed app_offline.htm; retain that maintenance page for review.'}
        Atomic-Bytes $file $bytes
        if(Get-Field $prior 'original_sddl'){
            $acl=Get-Acl -LiteralPath $file;$acl.SetSecurityDescriptorSddlForm($prior.original_sddl);Set-Acl -LiteralPath $file -AclObject $acl
        }
    }elseif([IO.File]::Exists($file)){
        Require ((Hash-File $file) -eq $prior.marker_sha256) 'Another operator changed app_offline.htm; retain the actual maintenance state for review.'
        [IO.File]::Delete($file)
    }
    if($prior.pool_stopped -and $prior.original_pool_state -eq 'Started'){
        $manager=[Microsoft.Web.Administration.ServerManager]::new()
        try{$pool=$manager.ApplicationPools[$script:PoolName];if($pool.State.ToString() -eq 'Stopped'){$null=$pool.Start()}}finally{$manager.Dispose()}
    }
    $prior.restored_at=[DateTime]::UtcNow.ToString('o');Save-Journal
}
function New-PairedBackup {
    # Later release phases own the current maintenance state. Reopening their original
    # backup must never bring a partially prepared application online or replace DNN's
    # native upgrade marker before the recorded installer phase can reconcile it.
    $releaseContinued=($script:Request.action -eq 'upgrade' -and @($script:Journal.steps.Keys|Where-Object {$_ -match '^(platform|extension)-[0-9]{2}-'}).Count -gt 0)
    if($releaseContinued){
        foreach($key in @('backup-offline','backup-sql','backup-files')){
            $retained=Get-Field $script:Journal.steps $key
            Require ($null -ne $retained -and $retained.state -eq 'complete') 'The continued release must retain its completed original paired backup.'
        }
    }
    $folder=Join-Path $script:Work 'backup';[IO.Directory]::CreateDirectory($folder)|Out-Null
    $pair=$script:Request.operation_id
    $initial=$script:Journal.steps['initial-inventory'].value
    Require ($null -ne $initial.platform -and $null -ne $initial.target) 'The paired generation needs its original pre-mutation native inventory.'

    $serverDirectory=Get-Field $script:Connection 'sql_backup_directory' ''
    $readerDirectory=Get-Field $script:Connection 'sql_backup_read_directory' $serverDirectory
    Require (-not [string]::IsNullOrWhiteSpace($serverDirectory)) 'Set the approved SQL Server backup path and its readable operator-host counterpart.'
    Require ($script:Native.inventory.sql.engine_edition -notin @(5,8)) 'This native SQL backup route requires SQL Server BACKUP/RESTORE support; select the approved provider backup adapter for this database service.'
    $nativeName='dnn-'+$pair+'.bak';$serverFile=Join-Path $serverDirectory $nativeName;$readerFile=Join-Path $readerDirectory $nativeName
    $state=Invoke-Step 'backup-offline' 'write' {Set-Offline} {param($prior) Set-Offline}
    $database=Invoke-Step 'backup-sql' 'write' {
        Require (-not [IO.File]::Exists($readerFile)) 'The selected new SQL backup path already exists.'
        $compression=if(Get-Field $script:Connection 'sql_compression' $false){', COMPRESSION'}else{''}
        Sql ('BACKUP DATABASE '+(Quote-SqlName $script:Database)+' TO DISK='+(Quote-SqlText $serverFile)+' WITH COPY_ONLY, CHECKSUM'+$compression+';') -NonQuery
        $verify=Sql-VerifyBackup $serverFile
        Require ([IO.File]::Exists($readerFile)) 'SQL backup completed but the configured operator read path does not resolve its output.'
        $dest=Join-Path $folder 'database.bak';[IO.File]::Copy($readerFile,$dest,$false)
        @{file=Artifact $dest 'database';verify=$verify;header=(Sql ('RESTORE HEADERONLY FROM DISK='+(Quote-SqlText $serverFile)) -Master);files=(Sql ('RESTORE FILELISTONLY FROM DISK='+(Quote-SqlText $serverFile)) -Master)}
    } {
        param($prior)
        Require ([IO.File]::Exists($readerFile)) 'The original SQL backup has no returned file; inspect its original server request.'
        $running=Sql "SELECT session_id FROM sys.dm_exec_requests WHERE command LIKE 'BACKUP%' AND database_id=DB_ID()"
        if($running.Count -gt 0){Uncertain 'The original native SQL backup is still executing.'}
        $verify=Sql-VerifyBackup $serverFile
        $dest=Join-Path $folder 'database.bak'
        if([IO.File]::Exists($dest)){Require ((Hash-File $dest) -eq (Hash-File $readerFile)) 'The retained backup copy differs from the original SQL output.'}else{[IO.File]::Copy($readerFile,$dest,$false)}
        @{file=Artifact $dest 'database';verify=$verify;header=(Sql ('RESTORE HEADERONLY FROM DISK='+(Quote-SqlText $serverFile)) -Master);files=(Sql ('RESTORE FILELISTONLY FROM DISK='+(Quote-SqlText $serverFile)) -Master)}
    }
    $files=Invoke-Step 'backup-files' 'write' {
        $manifest=@{schema='commons.dnn-files-generation/v1';pair_id=$pair;site_id=$script:Request.target.site_id;source_target=$initial.target;database=$initial.sql;database_version=$initial.platform.database_version;created_at=[DateTime]::UtcNow.ToString('o');root_sddl=(Get-Acl -LiteralPath $script:SiteRoot).Sddl;files=@();directories=@()}
        $zip=Join-Path $folder 'files.zip';$pending=$zip+'.pending'
        Require (-not [IO.File]::Exists($zip) -and -not [IO.File]::Exists($pending)) 'The original file-backup step has retained output; reopen that step.'
        $archive=[IO.Compression.ZipFile]::Open($pending,[IO.Compression.ZipArchiveMode]::Create)
        try{
            foreach($item in Get-ChildItem -LiteralPath $script:SiteRoot -Recurse -Force){
                Assert-NoReparse $item.FullName
                $relative=$item.FullName.Substring($script:SiteRoot.Length+1).Replace('\','/')
                if($relative -eq 'app_offline.htm' -and -not $script:Journal.availability.original_offline){continue}
                if($item.PSIsContainer){$manifest.directories+=@{path=$relative;sddl=(Get-Acl -LiteralPath $item.FullName).Sddl};continue}
                $before=@{bytes=$item.Length;mtime=$item.LastWriteTimeUtc.ToString('o');sha256=Hash-File $item.FullName}
                $entry=$archive.CreateEntry($relative,[IO.Compression.CompressionLevel]::Fastest)
                $input=[IO.File]::OpenRead($item.FullName);$out=$entry.Open()
                try{$input.CopyTo($out)}finally{$input.Dispose();$out.Dispose()}
                $after=Get-Item -LiteralPath $item.FullName
                Require ($after.Length -eq $before.bytes -and (Hash-File $item.FullName) -eq $before.sha256) 'A website file changed while its paired generation was captured.'
                $manifest.files+=@{path=$relative;bytes=$before.bytes;sha256=$before.sha256;last_write_utc=$before.mtime;sddl=(Get-Acl -LiteralPath $item.FullName).Sddl}
            }
        }finally{$archive.Dispose()}
        $manifestPath=Join-Path $folder 'manifest.json';Atomic-Json $manifestPath $manifest -Exclusive
        [IO.File]::Move($pending,$zip)
        @{files=Artifact $zip 'website-files';manifest=Artifact $manifestPath 'file-manifest'}
    } {
        param($prior)
        $zip=Join-Path $folder 'files.zip';$manifestPath=Join-Path $folder 'manifest.json'
        if(-not [IO.File]::Exists($manifestPath)){Uncertain 'The original file backup has no complete manifest; retain its same-operation generation for recovery.'}
        $pending=$zip+'.pending'
        if(-not [IO.File]::Exists($zip) -and [IO.File]::Exists($pending)){
            # The original ZIP can finish before its final rename; validate that exact generation first.
            Assert-FilesZip $pending (Read-Json $manifestPath)
            [IO.File]::Move($pending,$zip)
        }
        if(-not [IO.File]::Exists($zip)){Uncertain 'The original file backup did not publish its complete generation; preserve its output and use the recorded recovery path.'}
        Assert-FilesZip $zip (Read-Json $manifestPath)
        @{files=Artifact $zip 'website-files';manifest=Artifact $manifestPath 'file-manifest'}
    }
    $pairResult=@{pair_id=$pair;files=$files.files;database=$database.file;manifest=$files.manifest;verifyonly_complete=$true;database_version=$initial.platform.database_version;created_at=$script:Journal.steps['backup-offline'].started_at;sql_header=$database.header;sql_files=$database.files}
    $script:Native.backup=$pairResult;Save-Native
    if(-not $releaseContinued){Restore-Availability}
    return $pairResult
}
function Assert-FilesZip([string]$Zip,$Manifest) {
    Zip-Index $Zip
    $expected=@{};foreach($file in $Manifest.files){Require (-not $expected.ContainsKey($file.path.ToLowerInvariant())) 'Duplicate original file manifest path.';$expected[$file.path.ToLowerInvariant()]=$file}
    $archive=[IO.Compression.ZipFile]::OpenRead($Zip);$found=@{}
    try{
        foreach($entry in $archive.Entries){
            if($entry.FullName.EndsWith('/')){continue}
            $key=$entry.FullName.ToLowerInvariant();Require ($expected.ContainsKey($key)) 'Backup ZIP contains an unmanifested file.'
            $algorithm=[Security.Cryptography.SHA256]::Create();$stream=$entry.Open()
            try{$sha=[BitConverter]::ToString($algorithm.ComputeHash($stream)).Replace('-','').ToLowerInvariant()}finally{$stream.Dispose();$algorithm.Dispose()}
            Require ($entry.Length -eq $expected[$key].bytes -and $sha -eq $expected[$key].sha256) 'Backup member differs from its original paired manifest.'
            $found[$key]=$true
        }
    }finally{$archive.Dispose()}
    Require ($found.Count -eq $expected.Count) 'Backup ZIP omits original website files.'
}
function Save-Native {Atomic-Json (Join-Path $script:Work 'native.json') $script:Native}

function Assert-StagingBindings($BackupManifest) {
    if(-not (Get-Field $script:Request.backup 'staging_copy' $false)){return}
    Require ($script:Request.target.environment -eq 'staging') 'Cross-installation restore requires the selected isolated staging target.'
    Require ($script:Request.target.site_id -ne $BackupManifest.site_id) 'The source and staging receiving site are the same.'
    $sourceTarget=$BackupManifest.source_target
    Require ($script:Native.inventory.target.root_identity -ne $sourceTarget.root_identity) 'The staging receiver resolves to the original production website root.'
    Require (($script:Native.inventory.sql.database -ine $BackupManifest.database.database) -or ($script:Native.inventory.sql.server -ine $BackupManifest.database.server)) 'The staging receiver resolves to the original production database.'
    $bindings=Get-Field $script:Request.backup 'staging_bindings'
    Require ($null -ne $bindings -and @($bindings.portal_aliases).Count -gt 0) 'Supply the reviewed mapping from each original PortalAliasID to its isolated staging alias.'
    Require (-not [string]::IsNullOrWhiteSpace((Get-Field $bindings 'data_handling_note' ''))) 'Record the approved staging-data handling method.'
    foreach($row in $bindings.portal_aliases){
        Require ([int]$row.portal_alias_id -ge 0 -and $row.alias -match '^[A-Za-z0-9.-]+(?::[0-9]+)?(?:/[A-Za-z0-9_./-]*)?$') 'Each staging alias needs an actual original PortalAliasID and a host/path without a scheme or credentials.'
    }
    $targetConfig=[xml][IO.File]::ReadAllText($script:BindingConfigPath)
    Require ($null -ne $targetConfig.configuration.connectionStrings -and $null -eq $targetConfig.configuration.connectionStrings.EncryptedData) 'Use the approved readable staging connection section for this paired restore; retain its external credential custody.'
    Require (-not $targetConfig.configuration.connectionStrings.configSource) 'Resolve the staging connection configSource into the approved receiver before this restore.'
}
function Assert-RestoredGeneration([string]$Root,$Manifest,[switch]$Maintenance,[switch]$StagingConfig) {
    Require ([IO.Directory]::Exists($Root)) 'The original restored tree is absent.'
    Assert-NoReparse $Root
    foreach($entry in $Manifest.files){
        if($Maintenance -and $entry.path -ieq 'app_offline.htm'){continue}
        if($StagingConfig -and $entry.path -ieq 'web.config'){continue}
        $file=Under $Root $entry.path
        Require ([IO.File]::Exists($file)) 'The original restored generation is incomplete.'
        Assert-NoReparse $file
        Require ((Get-Item -LiteralPath $file).Length -eq $entry.bytes -and (Hash-File $file) -eq $entry.sha256) 'A restored website member differs from its original generation.'
    }
    if($Maintenance){
        $file=Join-Path $Root 'app_offline.htm'
        Require ([IO.File]::Exists($file) -and (Hash-File $file) -eq (Hash-Bytes (Offline-Bytes))) 'The original restore tree is not protected by its retained receiving maintenance state.'
    }
}
function Stage-RestoreMaintenance([string]$Root,$Manifest) {
    # The completed extract step proves the original full generation before its one deliberate override.
    Require ($script:Journal.steps['restore-extract'].state -eq 'complete') 'Verify the original generation before placing its receiving maintenance state.'
    foreach($entry in $Manifest.files){
        if($entry.path -ieq 'app_offline.htm'){continue}
        $file=Under $Root $entry.path
        Require ([IO.File]::Exists($file) -and (Hash-File $file) -eq $entry.sha256) 'The original received generation changed before its directory transition.'
    }
    $file=Join-Path $Root 'app_offline.htm';$bytes=Offline-Bytes;$desired=Hash-Bytes $bytes
    $sourceMarker=@($Manifest.files|Where-Object {$_.path -ieq 'app_offline.htm'})
    if([IO.File]::Exists($file)){
        $actual=Hash-File $file
        Require ($actual -eq $desired -or ($sourceMarker.Count -eq 1 -and $actual -eq $sourceMarker[0].sha256)) 'The incoming maintenance page is neither its source generation nor this original receiving state.'
    }else{Require ($sourceMarker.Count -eq 0) 'The source generation lost its original maintenance page before receiving.'}
    Atomic-Bytes $file $bytes
    $script:Journal.restore_maintenance=@{receiving_sha256=$desired;receiving_original_offline=$script:Journal.availability.original_offline;source_file=if($sourceMarker.Count){$sourceMarker[0]}else{$null};staged_before_swap=$true}
    Save-Journal
    Assert-RestoredGeneration $Root $Manifest -Maintenance
}
function Apply-RestorePermissions($Manifest) {
    $rootAcl=Get-Acl -LiteralPath $script:SiteRoot;$rootAcl.SetSecurityDescriptorSddlForm($Manifest.root_sddl);Set-Acl -LiteralPath $script:SiteRoot -AclObject $rootAcl
    foreach($entry in @($Manifest.directories)+@($Manifest.files)){
        $file=Under $script:SiteRoot $entry.path
        if(-not (Test-Path -LiteralPath $file)){[IO.Directory]::CreateDirectory($file)|Out-Null}
        $acl=Get-Acl -LiteralPath $file;$acl.SetSecurityDescriptorSddlForm($entry.sddl);Set-Acl -LiteralPath $file -AclObject $acl
        if([IO.File]::Exists($file) -and (Get-Field $entry 'last_write_utc')){[IO.File]::SetLastWriteTimeUtc($file,[DateTime]::Parse($entry.last_write_utc).ToUniversalTime())}
    }
    return @{completed=$true}
}
function Restore-PairedBackup {
    $input=Join-Path $script:InputRoot 'backup'
    $manifestPath=Join-Path $input 'manifest.json';$filesZip=Join-Path $input 'files.zip';$databaseFile=Join-Path $input 'database.bak'
    foreach($pair in @(@('manifest',$manifestPath),@('files',$filesZip),@('database',$databaseFile))){
        $expected=$script:Request.backup[$pair[0]]
        Require ((Hash-File $pair[1]) -eq $expected.sha256 -and (Get-Item -LiteralPath $pair[1]).Length -eq $expected.bytes) 'The selected paired restore input changed.'
    }
    $manifest=Read-Json $manifestPath
    Require ($manifest.pair_id -eq $script:Request.backup.pair_id) 'The website files belong to another backup generation.'
    Assert-FilesZip $filesZip $manifest
    Assert-StagingBindings $manifest
    $restoreFolder=Join-Path $script:Work 'restore';[IO.Directory]::CreateDirectory($restoreFolder)|Out-Null
    $received=$script:SiteRoot+'.restore-'+$script:Request.operation_id
    $savedConfig=Join-Path $script:Work 'receiving-target-web.config.private'
    Require ([IO.File]::Exists($savedConfig) -and (Hash-File $savedConfig) -eq $script:Journal.restore_target_config.sha256) 'The original private receiving configuration is not intact.'
    $sourceOwner=[string]$manifest.database.database_owner;$sourceQualifier=[string]$manifest.database.object_qualifier
    Require ($sourceOwner -match '^[A-Za-z_][A-Za-z0-9_]*$' -and $sourceQualifier -match '^[A-Za-z0-9_]*$') 'The exact backup database needs its original supported owner and object qualifier.'
    $generation=@{pair_id=$manifest.pair_id;manifest_sha256=Hash-File $manifestPath;files_sha256=Hash-File $filesZip;received_path=$received;database_owner=$sourceOwner;object_qualifier=$sourceQualifier;receiving_config_sha256=$script:Journal.restore_target_config.sha256}
    if($script:Journal.ContainsKey('restore_generation')){
        foreach($key in $generation.Keys){Require ($generation[$key] -ceq $script:Journal.restore_generation[$key]) 'The original restore generation or receiving binding changed.'}
    }else{$script:Journal.restore_generation=$generation;Save-Journal}
    $databaseFiles=Sql 'SELECT name,physical_name,type_desc FROM sys.database_files ORDER BY file_id'
    $fileMap=@{}
    foreach($row in $databaseFiles){$fileMap[$row.name]=[string]$row.physical_name}
    $configured=Get-Field $script:Connection 'restore_files' @()
    foreach($row in $configured){
        Require (-not [string]::IsNullOrWhiteSpace($row.logical_name) -and [IO.Path]::IsPathRooted($row.physical_path)) 'Every configured SQL restore file requires its actual absolute destination.'
        $fileMap[$row.logical_name]=$row.physical_path
    }
    $serverDir=Get-Field $script:Connection 'sql_restore_directory' (Get-Field $script:Connection 'sql_backup_directory' '')
    $readDir=Get-Field $script:Connection 'sql_restore_read_directory' (Get-Field $script:Connection 'sql_backup_read_directory' $serverDir)
    Require (-not [string]::IsNullOrWhiteSpace($serverDir)) 'Select the existing SQL restore-readable directory.'
    $name='restore-dnn-'+$script:Request.operation_id+'.bak';$serverFile=Join-Path $serverDir $name;$readFile=Join-Path $readDir $name
    if([IO.File]::Exists($readFile)){Require ((Hash-File $readFile) -eq (Hash-File $databaseFile)) 'The original receiving backup path contains another generation.'}
    else{[IO.File]::Copy($databaseFile,$readFile,$false)}
    $null=Sql-VerifyBackup $serverFile
    $nativeFiles=Sql ('RESTORE FILELISTONLY FROM DISK='+(Quote-SqlText $serverFile)) -Master
    $moves=@()
    foreach($file in $nativeFiles){
        Require ($fileMap.ContainsKey($file.LogicalName)) ('Provide the receiving SQL file destination for '+$file.LogicalName+'.')
        $moves+=('MOVE '+(Quote-SqlText $file.LogicalName)+' TO '+(Quote-SqlText $fileMap[$file.LogicalName]))
    }
    $null=Invoke-Step 'restore-extract' 'read' {
        Extract-Verified $filesZip $received $manifest
        Assert-RestoredGeneration $received $manifest
        @{path=$received;pair_id=$manifest.pair_id}
    }
    $null=Invoke-Step 'restore-offline' 'write' {Set-Offline} {param($prior) Set-Offline}
    # Preserve the failed tree beside the selected root. Never overlay a backup over failed files.
    $failed=$script:SiteRoot+'.before-'+$script:Request.operation_id
    $null=Invoke-Step 'restore-files' 'write' {
        Require (-not [IO.Directory]::Exists($failed)) 'The retained failed site tree already exists; reopen this original restore.'
        Stage-RestoreMaintenance $received $manifest
        [IO.Directory]::Move($script:SiteRoot,$failed)
        [IO.Directory]::Move($received,$script:SiteRoot)
        Assert-RestoredGeneration $script:SiteRoot $manifest -Maintenance
        @{failed_tree=$failed;pair_id=$manifest.pair_id;maintenance_staged_before_swap=$true}
    } {
        param($prior)
        if(-not [IO.Directory]::Exists($failed) -and [IO.Directory]::Exists($script:SiteRoot) -and [IO.Directory]::Exists($received)){
            Stage-RestoreMaintenance $received $manifest
            [IO.Directory]::Move($script:SiteRoot,$failed)
        }
        if([IO.Directory]::Exists($failed) -and -not [IO.Directory]::Exists($script:SiteRoot) -and [IO.Directory]::Exists($received)){
            Assert-RestoredGeneration $received $manifest -Maintenance
            [IO.Directory]::Move($received,$script:SiteRoot)
        }
        if(-not [IO.Directory]::Exists($failed) -or -not [IO.Directory]::Exists($script:SiteRoot) -or [IO.Directory]::Exists($received)){return $null}
        Assert-RestoredGeneration $script:SiteRoot $manifest -Maintenance
        @{failed_tree=$failed;pair_id=$manifest.pair_id;maintenance_staged_before_swap=$true}
    }
    $null=Set-Offline
    $null=Invoke-Step 'restore-permissions' 'write' {
        Apply-RestorePermissions $manifest
    } {
        param($prior)
        Assert-RestoredGeneration $script:SiteRoot $manifest -Maintenance
        # Reapply only the exact original generation's ACL values; no second file/SQL restore.
        Apply-RestorePermissions $manifest
    }
    $sqlRestore=Invoke-Step 'restore-sql' 'write' {
        Sql ('ALTER DATABASE '+(Quote-SqlName $script:Database)+' SET SINGLE_USER WITH ROLLBACK IMMEDIATE;') -NonQuery -Master
        try{
            Sql ('RESTORE DATABASE '+(Quote-SqlName $script:Database)+' FROM DISK='+(Quote-SqlText $serverFile)+' WITH REPLACE, RECOVERY, CHECKSUM, '+($moves -join ', ')+';') -NonQuery -Master
        }finally{Sql ('ALTER DATABASE '+(Quote-SqlName $script:Database)+' SET MULTI_USER;') -NonQuery -Master}
        @{completed=$true;at=[DateTime]::UtcNow.ToString('o');pair_id=$manifest.pair_id}
    } {
        param($prior)
        $running=Sql ("SELECT session_id FROM sys.dm_exec_requests WHERE command LIKE 'RESTORE%' AND database_id=DB_ID("+(Quote-SqlText $script:Database)+")") -Master
        if($running.Count -gt 0){Uncertain 'The original SQL restore is still executing.'}
        # A matching recent native restorehistory backup UUID identifies this restore, not just its resulting version.
        $history=Sql ("SELECT TOP(1) rh.restore_date,bs.backup_set_uuid FROM msdb.dbo.restorehistory rh JOIN msdb.dbo.backupset bs ON bs.backup_set_id=rh.backup_set_id WHERE rh.destination_database_name="+(Quote-SqlText $script:Database)+" ORDER BY rh.restore_history_id DESC") -Master
        $header=Sql ('RESTORE HEADERONLY FROM DISK='+(Quote-SqlText $serverFile)) -Master
        if($history.Count -eq 0 -or $header.Count -ne 1){return $null}
        if([guid]$history[0].backup_set_uuid -ne [guid]$header[0].BackupSetGUID -or [DateTime]$history[0].restore_date -lt ([DateTime]$prior.started_at).ToLocalTime().AddSeconds(-2)){return $null}
        Sql ('ALTER DATABASE '+(Quote-SqlName $script:Database)+' SET MULTI_USER;') -NonQuery -Master
        @{completed=$true;recovered_from='msdb.restorehistory';pair_id=$manifest.pair_id;backup_set_uuid=$history[0].backup_set_uuid}
    }
    # SQL target remains the original receiving server/database. Its restored DNN table prefix comes from the selected source generation.
    $script:DatabaseOwner=$sourceOwner;$script:ObjectQualifier=$sourceQualifier
    $stagingApplied=$false
    if(Get-Field $script:Request.backup 'staging_copy' $false){
        $stagingApplied=Invoke-Step 'restore-staging-bindings' 'write' {
            $config=[xml][IO.File]::ReadAllText((Join-Path $script:SiteRoot 'web.config'))
            $target=[xml][IO.File]::ReadAllText($savedConfig)
            $replacement=$config.ImportNode($target.configuration.connectionStrings,$true)
            $null=$config.configuration.ReplaceChild($replacement,$config.configuration.connectionStrings)
            $targetMachine=$target.SelectSingleNode('/configuration/system.web/machineKey')
            if($null -ne $targetMachine){
                $old=$config.SelectSingleNode('/configuration/system.web/machineKey')
                $new=$config.ImportNode($targetMachine,$true)
                if($old){$null=$old.ParentNode.ReplaceChild($new,$old)}else{$null=$config.SelectSingleNode('/configuration/system.web').AppendChild($new)}
            }
            $oldLegacy=$config.SelectSingleNode('/configuration/appSettings/add[@key="SiteSqlServer"]')
            $newLegacy=$target.SelectSingleNode('/configuration/appSettings/add[@key="SiteSqlServer"]')
            if($oldLegacy -and $newLegacy){$oldLegacy.SetAttribute('value',$newLegacy.GetAttribute('value'))}
            $temporary=Join-Path $script:Work 'staging-web.config.private'
            $config.Save($temporary);Atomic-Bytes (Join-Path $script:SiteRoot 'web.config') ([IO.File]::ReadAllBytes($temporary))
            $aliases=Read-DnnTable 'PortalAlias' @('PortalAliasID','PortalID','HTTPAlias')
            $map=@{};foreach($entry in $script:Request.backup.staging_bindings.portal_aliases){Require (-not $map.ContainsKey([int]$entry.portal_alias_id)) 'A staged alias is mapped twice.';$map[[int]$entry.portal_alias_id]=$entry.alias}
            Require ($map.Count -eq $aliases.Count) 'Map every original portal alias before opening the staged copy.'
            $table=(Quote-SqlName $script:DatabaseOwner)+'.'+(Quote-SqlName ($script:ObjectQualifier+'PortalAlias'))
            $query='BEGIN TRANSACTION;'
            foreach($row in $aliases){
                Require ($map.ContainsKey([int]$row.PortalAliasID)) 'A source portal alias has no reviewed staging mapping.'
                Require ($map[[int]$row.PortalAliasID] -ine $row.HTTPAlias) 'A staging alias still selects the original source host.'
                $query+='UPDATE '+$table+' SET HTTPAlias='+(Quote-SqlText $map[[int]$row.PortalAliasID])+' WHERE PortalAliasID='+([int]$row.PortalAliasID)+';'
            }
            $query+='COMMIT;';Sql $query -NonQuery
            @{completed=$true;config_sha256=Hash-File (Join-Path $script:SiteRoot 'web.config');portal_aliases=(Read-DnnTable 'PortalAlias' @('PortalAliasID','PortalID','HTTPAlias'));data_handling_note=$script:Request.backup.staging_bindings.data_handling_note}
        } {
            param($prior)
            $saved=Join-Path $script:Work 'staging-web.config.private'
            if(-not [IO.File]::Exists($saved) -or (Hash-File $saved) -ne (Hash-File (Join-Path $script:SiteRoot 'web.config'))){return $null}
            $actual=Read-DnnTable 'PortalAlias' @('PortalAliasID','HTTPAlias')
            foreach($entry in $script:Request.backup.staging_bindings.portal_aliases){
                $row=@($actual|Where-Object {[int]$_.PortalAliasID -eq [int]$entry.portal_alias_id})
                if($row.Count -ne 1 -or $row[0].HTTPAlias -cne $entry.alias){return $null}
            }
            @{completed=$true;config_sha256=Hash-File $saved;portal_aliases=$actual;data_handling_note=$script:Request.backup.staging_bindings.data_handling_note}
        }
    }
    Assert-RestoredGeneration $script:SiteRoot $manifest -Maintenance -StagingConfig:([bool]$stagingApplied)
    $script:Native.restore=@{pair_id=$manifest.pair_id;files_verified=$true;database_restored=$sqlRestore.completed;staging_bindings_applied=[bool]$stagingApplied;bindings=$stagingApplied;failed_tree_retained=$true;source_site_id=$manifest.site_id;availability_override=$script:Journal.restore_maintenance;database_binding=@{database_owner=$sourceOwner;object_qualifier=$sourceQualifier;receiving_database=$script:Database};finished_at=[DateTime]::UtcNow.ToString('o')}
    Save-Native
    Restore-Availability
    return $script:Native.restore
}
function New-HttpClient {
    $handler=[Net.Http.HttpClientHandler]::new()
    $handler.AllowAutoRedirect=$false
    $client=[Net.Http.HttpClient]::new($handler)
    $client.Timeout=[TimeSpan]::FromSeconds([int](Get-Field $script:Connection 'http_timeout_seconds' 180))
    return $client
}
function Dnn-Http([string]$Method,[string]$Relative,$Body=$null,[switch]$HostHeaders,[Net.Http.HttpContent]$Content=$null) {
    $base=[Uri]($script:Request.target.url.TrimEnd('/')+'/')
    Require ($Relative.StartsWith('/') -and -not $Relative.StartsWith('//') -and $Relative -notmatch '[\x00-\x1f\\]') 'Use a site-relative native route.'
    # An installation below a virtual application keeps that application path.
    $uri=[Uri]($script:Request.target.url.TrimEnd('/')+$Relative)
    Require ($uri.Scheme -eq $base.Scheme -and $uri.Host -eq $base.Host -and $uri.Port -eq $base.Port) 'The native request leaves the approved site origin.'
    $client=New-HttpClient
    $request=[Net.Http.HttpRequestMessage]::new([Net.Http.HttpMethod]::new($Method),$uri)
    try{
        if($HostHeaders){
            $reference=Get-Field $script:Connection 'host_headers_env' ''
            $value=if($reference){[Environment]::GetEnvironmentVariable($reference)}else{''}
            if(-not $value){Need-Input 'Supply the existing authorized DNN Host session headers through the private environment reference.'}
            $headers=Convert-Map ($value|ConvertFrom-Json)
            foreach($key in $headers.Keys){
                Require ($key -notmatch '^(?i:Host|Content-Length|Content-Type|Connection|Transfer-Encoding)$') 'The Host session reference includes a transport header that this client owns.'
                $null=$request.Headers.TryAddWithoutValidation($key,[string]$headers[$key])
            }
        }
        if($null -ne $Content){$request.Content=$Content}
        elseif($null -ne $Body){$request.Content=[Net.Http.StringContent]::new(($Body|ConvertTo-Json -Depth 100 -Compress),[Text.Encoding]::UTF8,'application/json')}
        $response=$client.SendAsync($request).GetAwaiter().GetResult()
        try{
            $text=$response.Content.ReadAsStringAsync().GetAwaiter().GetResult()
            Require ($text.Length -le 16777216) 'The native HTTP response exceeds the receiver limit.'
            $json=$null
            if($text){try{$json=Convert-Map ($text|ConvertFrom-Json)}catch{}}
            return @{status=[int]$response.StatusCode;body=$text;json=$json;location=[string]$response.Headers.Location;content_type=[string]$response.Content.Headers.ContentType;observed_at=[DateTime]::UtcNow.ToString('o')}
        }finally{$response.Dispose()}
    }finally{$request.Dispose();$client.Dispose()}
}
function Host-Json([string]$Method,[string]$Route,$Body=$null) {
    $response=Dnn-Http $Method $Route $Body -HostHeaders
    if($response.status -in @(401,403,302)){Need-Input ('The original DNN Host session needs its normal login/permission renewal for '+$Route+'.')}
    Require ($response.status -ge 200 -and $response.status -lt 300) ('The native DNN endpoint returned HTTP '+$response.status+' for '+$Route+'.')
    return $response
}
function Http-Checks {
    $checks=Get-Field $script:Request 'checks' (Get-Field (Get-Field $script:Request 'release') 'checks' @())
    $answer=@()
    foreach($check in $checks){
        $response=Dnn-Http 'GET' $check.path
        $passed=$response.status -eq [int]$check.status
        if($check.contains){$passed=$passed -and $response.body.Contains($check.contains)}
        $answer+=@{label=$check.label;path=$check.path;expected_status=[int]$check.status;observed_status=$response.status;contains_requested=[bool]$check.contains;passed=$passed;response_sha256=Hash-Bytes ([Text.Encoding]::UTF8.GetBytes($response.body));observed_at=$response.observed_at}
    }
    $script:Native.checks=$answer;Save-Native
    Require (@($answer|Where-Object {-not $_.passed}).Count -eq 0) 'An actual requested service check failed; inspect the retained result.'
    return ,$answer
}

# Native DNN platform and extension routes. Source contracts are pinned in PRIMARY_SOURCES.json.
function Platform-Package($Step) {
    $matches=@($script:Request.packages|Where-Object {
        $_.package.kind -eq 'platform' -and (Version3 $_.package.version) -eq (Version3 $Step.to) -and $_.package.package_type -eq $Step.package_type
    })
    Require ($matches.Count -eq 1) 'The exact version hop does not select one approved native package.'
    return $matches[0]
}
function Verify-Package($Package) {
    $path=Under (Join-Path $script:InputRoot 'packages') $Package.name
    Require ([IO.File]::Exists($path) -and (Get-Item -LiteralPath $path).Length -eq $Package.bytes -and (Hash-File $path) -eq $Package.sha256) 'An approved package changed before native use.'
    Zip-Index $path
    if($Package.package.kind -eq 'platform'){
        $archive=[IO.Compression.ZipFile]::OpenRead($path)
        $temporary=Join-Path $script:Work ('assembly-version-'+$Package.sha256+'.private')
        try{
            $entry=@($archive.Entries|Where-Object {$_.FullName -ieq 'bin/DotNetNuke.dll'})
            Require ($entry.Count -eq 1) 'The selected platform package has no unique original platform assembly.'
            if([IO.File]::Exists($temporary)){[IO.File]::Delete($temporary)}
            $source=$entry[0].Open();$output=[IO.File]::Open($temporary,[IO.FileMode]::CreateNew)
            try{$source.CopyTo($output);$output.Flush($true)}finally{$source.Dispose();$output.Dispose()}
            $actual=Dnn-FileVersion $temporary
            Require ((Version3 $actual.ToString()) -eq (Version3 $Package.package.version)) 'The actual DNN platform file version differs from the reviewed package filename.'
        }finally{$archive.Dispose();if([IO.File]::Exists($temporary)){[IO.File]::Delete($temporary)}}
    }
    return $path
}
function Expected-PlatformFiles($Package) {
    $path=Verify-Package $Package
    $archive=[IO.Compression.ZipFile]::OpenRead($path);$answer=@()
    try{
        # Match the selected original LocalUpgradeService: custom settings replace defaults.
        $excluded=@('App_Data/Database.mdf','Config/DotNetNuke.config','Install/InstallWizard','favicon.ico','robots.txt','web.config')
        $upgrade=@($archive.Entries|Where-Object {$_.FullName -ieq 'App_Data/Upgrade/upgrade.json'})
        if($upgrade.Count -gt 0){
            Require ($upgrade.Count -eq 1) 'The selected package has ambiguous native upgrade settings.'
            $reader=[IO.StreamReader]::new($upgrade[0].Open())
            try{$rules=Convert-Map ($reader.ReadToEnd()|ConvertFrom-Json)}finally{$reader.Dispose()}
            $excluded=@(Get-Field $rules 'upgradeExclude' @())
        }
        foreach($entry in $archive.Entries){
            if($entry.FullName.EndsWith('/')){continue}
            $isAssembly=$entry.FullName -match '(?i)^bin/[^/]+\.dll$'
            $skip=$false
            if(-not $isAssembly){
                foreach($filter in $excluded){
                    if($entry.FullName.StartsWith([string]$filter,[StringComparison]::OrdinalIgnoreCase)){$skip=$true;break}
                }
            }
            if($skip){continue}
            $stream=$entry.Open();$algorithm=[Security.Cryptography.SHA256]::Create()
            try{$sha=[BitConverter]::ToString($algorithm.ComputeHash($stream)).Replace('-','').ToLowerInvariant()}finally{$stream.Dispose();$algorithm.Dispose()}
            $answer+=@{path=$entry.FullName;bytes=$entry.Length;sha256=$sha}
        }
    }finally{$archive.Dispose()}
    return ,$answer
}
function Assert-PreparedPlatform($Package) {
    foreach($file in Expected-PlatformFiles $Package){
        $target=Under $script:SiteRoot $file.path
        # DNN's installer can remove its Upgrade package/manifest after preparation. The compiled platform,
        # installer source, and all other intended files must match before an uncertain preparation is adopted.
        if($file.path -like 'App_Data/Upgrade/*'){continue}
        if(-not [IO.File]::Exists($target) -or (Get-Item -LiteralPath $target).Length -ne $file.bytes -or (Hash-File $target) -ne $file.sha256){return $false}
    }
    return $true
}
function Copy-LegacyPlatform($Step,$Package,[string]$StepId) {
    $null=Verify-Package $Package
    $expected=Expected-PlatformFiles $Package
    $null=Set-Offline
    $path=Verify-Package $Package
    $archive=[IO.Compression.ZipFile]::OpenRead($path)
    try{
        foreach($file in $expected){
            $target=Under $script:SiteRoot $file.path
            [IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($target))|Out-Null
            if([IO.File]::Exists($target) -and (Hash-File $target) -eq $file.sha256){continue}
            $entry=$archive.GetEntry($file.path)
            $temporary=$target+'.dnn-'+$script:Request.operation_id+'.pending'
            # The same original operation may recover its own partial copy, never another operator's file.
            if([IO.File]::Exists($temporary)){[IO.File]::Delete($temporary)}
            $input=$entry.Open();$output=[IO.FileStream]::new($temporary,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::None)
            try{$input.CopyTo($output);$output.Flush($true)}finally{$input.Dispose();$output.Dispose()}
            Require ((Hash-File $temporary) -eq $file.sha256) 'The exact package member changed during file preparation.'
            if([IO.File]::Exists($target)){[IO.File]::Replace($temporary,$target,$null)}else{[IO.File]::Move($temporary,$target)}
        }
    }finally{$archive.Dispose()}
    Require (Assert-PreparedPlatform $Package) 'The original Upgrade package has not completed its native file preparation.'
    Restore-Availability
    return @{route='pre-10.2';from=$Step.from;to=$Step.to;package_sha256=$Package.sha256;files_prepared=$true}
}
function Upload-ModernPlatform($Step,$Package,[string]$StepId) {
    $path=Verify-Package $Package
    $destination=Join-Path (Join-Path $script:SiteRoot 'App_Data\Upgrade') $Package.name
    if([IO.File]::Exists($destination)){
        Require ((Hash-File $destination) -eq $Package.sha256) 'The existing DNN upgrade slot contains a different package.'
        return @{package_name=$Package.name;sha256=$Package.sha256;transport='existing-native-slot'}
    }
    if((Version3 $Step.from) -eq [version]'10.2.3'){
        [IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($destination))|Out-Null
        $pending=$destination+'.'+$script:Request.operation_id+'.resources'
        if([IO.File]::Exists($pending)){Require ((Hash-File $pending) -eq $Package.sha256) 'The original 10.2.3 package staging has different bytes.'}
        else{[IO.File]::Copy($path,$pending,$false)}
        [IO.File]::Move($pending,$destination)
        return @{package_name=$Package.name;sha256=$Package.sha256;transport='documented-10.2.3-App_Data-Upgrade'}
    }
    $settings=Host-Json 'GET' '/API/PersonaBar/Upgrades/GetSettings'
    if(-not (Get-Field $settings.json 'AllowDnnUpgradeUpload' $false)){
        Need-Input 'The existing DNN Host setting AllowDnnUpgradeUpload is disabled. Enable its ordinary approved upload route before resuming this original upload.'
    }
    $fileId='dnn-'+$script:Request.operation_id+'-'+$Step.to.Replace('.','-')
    $upload=Get-Field $script:Journal.uploads $StepId
    if($null -ne $upload){
        Require ($upload.file_id -ceq $fileId -and $upload.package_sha256 -ceq $Package.sha256 -and [long]$upload.total -eq [long]$Package.bytes) 'The original native upload slot selects another package.'
    }else{
        # The deterministic original slot exists in our journal BEFORE its first network write.
        $script:Journal.uploads[$StepId]=@{file_id=$fileId;position=0L;total=$Package.bytes;package_sha256=$Package.sha256;package_name=$Package.name}
        Save-Journal
    }
    $input=[IO.File]::OpenRead($path)
    try{
        # Native Upload uses OpenOrCreate and an explicit byte offset; replay only this original slot.
        $buffer=[byte[]]::new(4*1024*1024);$position=0L
        while(($count=$input.Read($buffer,0,$buffer.Length)) -gt 0){
            $chunk=[byte[]]::new($count);[Array]::Copy($buffer,$chunk,$count)
            $form=[Net.Http.MultipartFormDataContent]::new()
            $form.Add([Net.Http.ByteArrayContent]::new($chunk),'chunk','chunk.bin')
            $form.Add([Net.Http.StringContent]::new([string]$position),'start')
            $form.Add([Net.Http.StringContent]::new([string]$Package.bytes),'totalSize')
            $form.Add([Net.Http.StringContent]::new($fileId),'fileId')
            $response=Dnn-Http 'POST' '/API/PersonaBar/Upgrades/Upload' -HostHeaders -Content $form
            if($response.status -in @(401,403,302)){Need-Input 'Renew the original normal Host session before continuing the same package upload.'}
            Require ($response.status -eq 200) ('Native DNN upload returned HTTP '+$response.status+'.')
            $position+=$count
            $script:Journal.uploads[$StepId].position=$position
            Save-Journal
        }
    }finally{$input.Dispose()}
    $response=Host-Json 'POST' '/API/PersonaBar/Upgrades/UploadComplete' @{fileId=$fileId;fileName=$Package.name}
    Require ([IO.File]::Exists($destination) -and (Hash-File $destination) -eq $Package.sha256) 'DNN did not retain the complete selected Install package.'
    return @{package_name=$Package.name;sha256=$Package.sha256;transport='native-Host-upload';native_status=$response.status}
}
function Prepare-ModernPlatform($Step,$Package,[string]$StepId) {
    $nativeStep=Get-Field $script:Journal.steps ($StepId+'-native-files')
    if($null -ne $nativeStep -and $nativeStep.state -in @('started','uncertain','complete')){
        # StartUpgrade deletes its selected ZIP. Recover this dispatched step before upload/list access.
        return Invoke-Step ($StepId+'-native-files') 'write' {Uncertain 'The retained file dispatch must use its original recovery path.'} {
            param($prior)
            if(Assert-PreparedPlatform $Package){
                Restore-NativePreparationAvailability $StepId
                return @{route='post-10.2';from=$Step.from;to=$Step.to;package_sha256=$Package.sha256;files_prepared=$true;recovered_from='complete-installed-package'}
            }
            return $null
        }
    }
    $null=Invoke-Step ($StepId+'-upload') 'write' {Upload-ModernPlatform $Step $Package $StepId} {
        param($prior)
        $destination=Join-Path (Join-Path $script:SiteRoot 'App_Data\Upgrade') $Package.name
        if([IO.File]::Exists($destination) -and (Hash-File $destination) -eq $Package.sha256){return @{package_name=$Package.name;sha256=$Package.sha256;transport='original-upload-recovered'}}
        # A multipart write uses an explicit original file ID and offsets. Continue only that same upload.
        $upload=Get-Field $script:Journal.uploads $StepId
        if($null -ne $upload -and $upload.package_sha256 -eq $Package.sha256){return Upload-ModernPlatform $Step $Package $StepId}
        return $null
    }
    $list=Host-Json 'GET' '/API/PersonaBar/Upgrades/List'
    $packageStem=[IO.Path]::GetFileNameWithoutExtension($Package.name)
    $selected=@($list.json|Where-Object {$_.PackageName -ieq $packageStem})
    Require ($selected.Count -eq 1 -and $selected[0].IsValid -and $selected[0].CanInstall) 'DNN rejected the exact Install package or its installed-version compatibility.'
    Require ((Version3 ([string]$selected[0].Version)) -eq (Version3 $Package.package.version)) 'The native package stem resolves a different selected DNN version.'
    $nativePackageName=[string]$selected[0].PackageName
    $validationPath=Join-Path $script:Work ($StepId+'-native-package-validation.json')
    if(-not [IO.File]::Exists($validationPath)){Atomic-Json $validationPath @{package_name=$Package.name;package_sha256=$Package.sha256;native_package_name=$nativePackageName;native=$selected[0];observed_at=$list.observed_at} -Exclusive}
    Capture-NativePreparationAvailability $StepId
    return Invoke-Step ($StepId+'-native-files') 'write' {
        $response=Host-Json 'POST' '/API/PersonaBar/Upgrades/StartUpgrade' @{packageName=$nativePackageName}
        Require ($response.status -eq 204) 'The native DNN file preparation returned an unexpected completion status.'
        Require (Assert-PreparedPlatform $Package) 'DNN file preparation has not reached the exact approved package.'
        Restore-NativePreparationAvailability $StepId
        @{route='post-10.2';from=$Step.from;to=$Step.to;package_sha256=$Package.sha256;files_prepared=$true;native_status=$response.status}
    } {
        param($prior)
        if(Assert-PreparedPlatform $Package){Restore-NativePreparationAvailability $StepId;return @{route='post-10.2';from=$Step.from;to=$Step.to;package_sha256=$Package.sha256;files_prepared=$true;recovered_from='complete-installed-package'}}
        return $null
    }
}
function Capture-NativePreparationAvailability([string]$StepId) {
    $key=$StepId+'-native-availability'
    if($script:Journal.ContainsKey($key)){return}
    $file=Join-Path $script:SiteRoot 'App_Offline.htm'
    Require (-not [IO.File]::Exists($file)) 'Open the reviewed native Host upgrade with the site available; retain any existing app_offline.htm through the maintenance owner.'
    $templates=@()
    foreach($relative in @('Portals/_default/AppOffline/App_Offline.htm.resources','Resources/AppOffline/App_Offline.htm.resources')){
        $path=Under $script:SiteRoot $relative
        if([IO.File]::Exists($path)){$templates+=@{path=$relative;sha256=Hash-File $path}}
    }
    $script:Journal[$key]=@{original_offline=$false;templates=$templates;observed_at=[DateTime]::UtcNow.ToString('o')}
    Save-Journal
}
function Restore-NativePreparationAvailability([string]$StepId) {
    $prior=Get-Field $script:Journal ($StepId+'-native-availability')
    $file=Join-Path $script:SiteRoot 'App_Offline.htm'
    if(-not [IO.File]::Exists($file)){return}
    Require ($null -ne $prior -and -not $prior.original_offline) 'Preserve the original maintenance file until its native preparation state is reconciled.'
    $hash=Hash-File $file
    Require (@($prior.templates|Where-Object {$_.sha256 -eq $hash}).Count -gt 0) 'A different app_offline.htm is present; retain its owning maintenance operation.'
    $retained=Join-Path $script:Work ($StepId+'-native-offline-template.htm')
    if(-not [IO.File]::Exists($retained)){Atomic-Bytes $retained ([IO.File]::ReadAllBytes($file)) -Exclusive}
    [IO.File]::Delete($file)
    $prior.recovered_online_at=[DateTime]::UtcNow.ToString('o');$prior.recovered_template_sha256=$hash;Save-Journal
}
function Wizard-Account {
    $userRef=Get-Field $script:Connection 'host_username_env' ''
    $passwordRef=Get-Field $script:Connection 'host_password_env' ''
    $username=if($userRef){[Environment]::GetEnvironmentVariable($userRef)}else{''}
    $password=if($passwordRef){[Environment]::GetEnvironmentVariable($passwordRef)}else{''}
    if(-not $username -or -not $password){Need-Input 'Supply the authorized SuperUser through the two private environment references used by the original DNN upgrade wizard.'}
    return @{username=$username;password=$password;acceptTerms='Y'}
}
function Wizard-Call([string]$Method,$Body) {
    $response=Dnn-Http 'POST' ('/Install/UpgradeWizard.aspx/'+$Method) $Body
    Require ($response.status -eq 200 -and $null -ne $response.json) ('The original DNN UpgradeWizard '+$Method+' returned HTTP '+$response.status+'.')
    return Get-Field $response.json 'd' $response.json
}
function Wizard-Input {
    $page=Dnn-Http 'GET' '/Install/UpgradeWizard.aspx'
    Require ($page.status -eq 200) 'Open the original UpgradeWizard in its actual available application before native authentication.'
    $account=Wizard-Account
    $validation=Wizard-Call 'ValidateInput' @{accountInfo=$account}
    if(-not (Get-Field $validation 'Item1' $false)){Need-Input 'DNN did not authenticate the selected SuperUser for this original upgrade.'}
    $view=Wizard-Call 'GetSecurityTab' @{accountInfo=$account}
    $state=Get-Field $view 'Item3'
    Require ((Get-Field $view 'Item1' $false) -and $null -ne $state) 'The original DNN upgrade security step did not return its native decision.'
    if(-not (Get-Field $state 'CanProceed' $false)){Need-Input 'DNN requires its compatibility/security work before starting this upgrade. Open the original UpgradeWizard security step.'}
    $html=[string](Get-Field $state 'View' '')
    # Consume only the actual server-generated hidden anti-forgery value; do not persist it in any artifact.
    $token=[regex]::Match($html,'(?is)<input\b[^>]*(?:id|name)=["'']telerikAntiForgeryToken["''][^>]*value=["'']([^"'']*)["'']')
    if(-not $token.Success){$token=[regex]::Match($html,'(?is)<input\b[^>]*value=["'']([^"'']*)["''][^>]*(?:id|name)=["'']telerikAntiForgeryToken["'']')}
    if($token.Success){$account['telerikAntiForgeryToken']=[Net.WebUtility]::HtmlDecode($token.Groups[1].Value)}
    $key='telerikUninstallOption'
    if($token.Success){
        $choices=@()
        foreach($match in [regex]::Matches($html,'(?is)<input\b[^>]*>')){
            $tag=$match.Value
            if($tag -notmatch '(?i)(?:id|name)=["'']telerikUninstallOption["'']'){continue}
            $value=[regex]::Match($tag,'(?i)value=["'']([^"'']*)["'']')
            if(-not $value.Success){continue}
            $choices+=@{value=[Net.WebUtility]::HtmlDecode($value.Groups[1].Value);selected=($tag -match '(?i)\bchecked\b|\btype=["'']hidden["'']');disabled=($tag -match '(?i)\bdisabled\b')}
        }
        $selected=@($choices|Where-Object {$_.selected})
        $decision=Get-Field $script:Request.release 'telerik_decision' 'native_required'
        if($decision -eq 'remove'){
            Require (@($choices|Where-Object {$_.value -eq 'Y' -and -not $_.disabled}).Count -gt 0) 'The native Telerik security view does not offer the reviewed removal; resolve its actual dependent-extension finding.'
            $account[$key]='Y'
        }else{
            Require ($selected.Count -eq 1 -and $selected[0].value -in @('Y','N')) 'Select the actual Telerik decision in the original native security view before dispatch.'
            $account[$key]=$selected[0].value
        }
    }
    return $account
}
function Upgrade-LogMarker {
    $path=Join-Path $script:SiteRoot 'Install\upgradestat.log.resources.txt'
    if(-not [IO.File]::Exists($path)){return @{exists=$false;bytes=0;sha256=$null}}
    return @{exists=$true;bytes=(Get-Item -LiteralPath $path).Length;sha256=Hash-File $path}
}
function Read-UpgradeOutcome($Marker,[string]$Target,[string]$StepId) {
    $path=Join-Path $script:SiteRoot 'Install\upgradestat.log.resources.txt'
    if(-not [IO.File]::Exists($path)){return $null}
    $bytes=[IO.File]::ReadAllBytes($path);$currentHash=Hash-Bytes $bytes
    if($Marker.exists -and $currentHash -eq $Marker.sha256){return $null}
    $offset=[long](Get-Field $Marker 'bytes' 0)
    if($bytes.LongLength -lt $offset){Uncertain 'The original installer status log was replaced or truncated; retain this dispatch and reconcile its original native output.'}
    if($Marker.exists -and $offset -gt 0){
        $prefix=[byte[]]::new([int]$offset)
        [Array]::Copy($bytes,0,$prefix,0,[int]$offset)
        Require ((Hash-Bytes $prefix) -eq $Marker.sha256) 'The prior installer log prefix changed; an earlier completion cannot identify this run.'
    }
    if($bytes.LongLength -eq $offset){return $null}
    $content=[Text.Encoding]::UTF8.GetString($bytes,[int]$offset,$bytes.Length-[int]$offset)
    $rows=@()
    foreach($line in ($content -split '\r?\n')){
        if(-not $line.Trim()){continue}
        try{$value=Convert-Map ($line|ConvertFrom-Json);if($value -is [Collections.IDictionary]){$rows+=,$value}}catch{}
    }
    if($rows.Count -eq 0){return $null}
    $final=$rows[-1]
    if([int](Get-Field $final 'progress' 0) -lt 100){return $null}
    $a=[string](Get-Field $final 'check0' '');$b=[string](Get-Field $final 'check1' '')
    if($a -match '(?i)error|fail' -or $b -match '(?i)error|fail'){
        $failed=Join-Path $script:Work ($StepId+'-failed-upgrade-status-'+$currentHash.Substring(0,12)+'.log')
        if(-not [IO.File]::Exists($failed)){Atomic-Bytes $failed $bytes -Exclusive}
        throw 'The original DNN installer completed with errors; its complete native log is retained for paired recovery.'
    }
    if($a -notmatch '(?i)done|complete' -or $b -notmatch '(?i)done|complete'){return $null}
    $inventory=Native-Inventory
    if((Version3 $inventory.platform.database_version) -ne (Version3 $Target) -or (Version3 $inventory.platform.assembly_version) -ne (Version3 $Target)){return $null}
    $retained=Join-Path $script:Work ($StepId+'-original-upgrade-status.log')
    if(-not [IO.File]::Exists($retained)){Atomic-Bytes $retained $bytes -Exclusive}
    $script:Native.inventory=$inventory;Save-Native
    return @{completed=$true;target_version=$Target;native_status=$final;status_log=Artifact $retained 'native-installer-log';appended_after_bytes=$offset;original_prefix_sha256=$Marker.sha256;database_version=$inventory.platform.database_version;assembly_version=$inventory.platform.assembly_version}
}
function Finish-NativeUpgrade($Step,[string]$StepId) {
    $markerKey=$StepId+'-wizard-marker'
    if(-not $script:Journal.ContainsKey($markerKey)){
        $script:Journal[$markerKey]=Upgrade-LogMarker;Save-Journal
    }
    $marker=$script:Journal[$markerKey]
    $completed=Invoke-Step ($StepId+'-native-database') 'write' {
        $account=Wizard-Input
        # Authentication and the server-generated security decision are resolved before the one native RunUpgrade POST.
        $script:Journal[$StepId+'-wizard-dispatch']=@{at=[DateTime]::UtcNow.ToString('o');target_version=$Step.to;marker=$marker}
        Save-Journal
        try{$null=Wizard-Call 'RunUpgrade' @{accountInfo=$account}}
        catch{$script:Journal[$StepId+'-wizard-transport']=@{state='response-unavailable';at=[DateTime]::UtcNow.ToString('o')};Save-Journal}
        $deadline=[DateTime]::UtcNow.AddSeconds([int](Get-Field $script:Connection 'installer_wait_seconds' 600))
        do{
            $result=Read-UpgradeOutcome $marker $Step.to $StepId
            if($null -ne $result){return $result}
            Start-Sleep -Seconds 2
        }while([DateTime]::UtcNow -lt $deadline)
        Uncertain 'The original upgrade is still running or its native completion is unresolved. Resume this same request to read its status; do not start another upgrade.'
    } {
        param($prior)
        # A pre-dispatch validation failure can be resumed through the same original authentication step.
        if(-not $script:Journal.ContainsKey($StepId+'-wizard-dispatch')){
            $account=Wizard-Input
            $script:Journal[$StepId+'-wizard-dispatch']=@{at=[DateTime]::UtcNow.ToString('o');target_version=$Step.to;marker=$marker}
            Save-Journal
            try{$null=Wizard-Call 'RunUpgrade' @{accountInfo=$account}}catch{}
        }
        return Read-UpgradeOutcome $marker $Step.to $StepId
    }
    # The normal completion link deletes installer/status files. Keep the original completed log first.
    $null=Invoke-Step ($StepId+'-wizard-finish') 'write' {
        $record=Get-Field $script:Journal.steps ($StepId+'-native-database')
        Require ($null -ne $record -and $record.state -eq 'complete' -and $record.value.completed) 'Retain the actual database completion before final installer cleanup.'
        $log=Under $script:Work $record.value.status_log.path
        Require ([IO.File]::Exists($log) -and (Hash-File $log) -eq $record.value.status_log.sha256) 'The original completed installer log must survive the normal finish action.'
        $response=Dnn-Http 'GET' '/Install/UpgradeWizard.aspx?complete'
        Require ($response.status -in @(200,301,302,303,307,308,404)) 'The native finish link returned an unexpected response.'
        @{finished=$true;status=$response.status;completion_log_sha256=$record.value.status_log.sha256}
    } {
        param($prior)
        $wizard=Join-Path $script:SiteRoot 'Install\UpgradeWizard.aspx'
        $current=Native-Inventory
        if(-not [IO.File]::Exists($wizard) -and (Version3 $current.platform.database_version) -eq (Version3 $Step.to)){
            return @{finished=$true;recovered_from='original-installer-removal'}
        }
        return $null
    }
    return $completed
}
function Extension-Version([string]$Value) {
    $parts=$Value.Split('.')
    Require ($parts.Count -ge 3 -and $parts.Count -le 4 -and @($parts|Where-Object {$_ -notmatch '^\d+$'}).Count -eq 0) 'Use the actual complete numeric extension version.'
    if($parts.Count -eq 3){$parts+=,'0'}
    return [version]::new([int]$parts[0],[int]$parts[1],[int]$parts[2],[int]$parts[3])
}
function Install-Extension($Package,[string]$StepId) {
    $path=Verify-Package $Package
    $manifest=$Package.package.manifests
    $null=Invoke-Step ($StepId+'-parse') 'read' {
        $form=[Net.Http.MultipartFormDataContent]::new()
        $stream=[IO.File]::OpenRead($path);$content=[Net.Http.StreamContent]::new($stream)
        $form.Add($content,'POSTFILE',$Package.name)
        $response=Dnn-Http 'POST' '/API/PersonaBar/Extensions/ParsePackage' -HostHeaders -Content $form
        Require ($response.status -eq 200 -and (Get-Field $response.json 'Success' $false)) 'DNN did not accept the original extension package for installation.'
        $retained=Join-Path $script:Work ($StepId+'-native-extension-parse.json')
        Atomic-Json $retained @{package_sha256=$Package.sha256;native=$response.json;observed_at=$response.observed_at} -Exclusive
        @{completed=$true;native_result=Artifact $retained 'native-extension-validation'}
    }
    return Invoke-Step ($StepId+'-install') 'write' {
        $form=[Net.Http.MultipartFormDataContent]::new()
        $stream=[IO.File]::OpenRead($path);$content=[Net.Http.StreamContent]::new($stream)
        $form.Add($content,'POSTFILE',$Package.name)
        $response=Dnn-Http 'POST' '/API/PersonaBar/Extensions/InstallPackage' -HostHeaders -Content $form
        $retained=Join-Path $script:Work ($StepId+'-native-extension-install.json')
        Atomic-Json $retained @{package_sha256=$Package.sha256;status=$response.status;native=$response.json;observed_at=$response.observed_at} -Exclusive
        Require ($response.status -eq 200 -and (Get-Field $response.json 'Success' $false)) 'The original native extension installer returned a failure.'
        $inventory=Native-Inventory
        foreach($item in $manifest){
            $actual=@($inventory.packages|Where-Object {$_.name -ieq $item.name})
            Require ($actual.Count -eq 1 -and (Extension-Version $actual[0].version) -eq (Extension-Version $item.version)) 'The installed extension version does not match the selected package.'
        }
        $script:Native.inventory=$inventory;Save-Native
        @{completed=$true;package_sha256=$Package.sha256;native_result=Artifact $retained 'native-extension-installation'}
    } {
        param($prior)
        $retained=Join-Path $script:Work ($StepId+'-native-extension-install.json')
        if(-not [IO.File]::Exists($retained)){return $null}
        $response=Read-Json $retained
        if($response.package_sha256 -ne $Package.sha256 -or $response.status -ne 200 -or -not $response.native.Success){return $null}
        $inventory=Native-Inventory
        foreach($item in $manifest){$actual=@($inventory.packages|Where-Object {$_.name -ieq $item.name});if($actual.Count -ne 1 -or (Extension-Version $actual[0].version) -ne (Extension-Version $item.version)){return $null}}
        $script:Native.inventory=$inventory;Save-Native
        @{completed=$true;package_sha256=$Package.sha256;native_result=Artifact $retained 'native-extension-installation';recovered_from='original-native-result-and-installed-version'}
    }
}
function Run-Upgrade {
    Require ($null -ne $script:Request.release -and $null -ne $script:Request.review) 'The native release needs its retained exact review.'
    foreach($package in $script:Request.packages){$null=Verify-Package $package}
    $null=New-PairedBackup
    $steps=@($script:Request.release.steps)
    $index=0
    foreach($step in $steps){
        $index++;$id='platform-'+$index.ToString('D2')+'-'+$step.to.Replace('.','-')
        $package=Platform-Package $step
        $preparedKey=$id+'-prepared'
        $prepared=Get-Field $script:Journal.steps $preparedKey
        if($null -eq $prepared -or $prepared.state -ne 'complete'){
            $current=Native-Inventory
            $nativeFiles=Get-Field $script:Journal.steps ($id+'-native-files')
            if($null -eq $nativeFiles -or $nativeFiles.state -notin @('started','uncertain','complete')){
                Require ((Version3 $current.platform.database_version) -eq (Version3 $step.from)) 'This hop no longer begins at its reviewed installed DNN version.'
            }
            if((Version3 $step.from) -lt [version]'10.2.0'){
                $null=Invoke-Step $preparedKey 'write' {Copy-LegacyPlatform $step $package $id} {
                    param($prior)
                    $current=Native-Inventory
                    if((Version3 $current.platform.database_version) -ne (Version3 $step.from)){return $null}
                    return Copy-LegacyPlatform $step $package $id
                }
            }else{
                $value=Prepare-ModernPlatform $step $package $id
                $script:Journal.steps[$preparedKey]=@{state='complete';kind='write';started_at=$script:Journal.steps[$id+'-native-files'].started_at;finished_at=[DateTime]::UtcNow.ToString('o');value=$value};Save-Journal
            }
        }
        $null=Finish-NativeUpgrade $step $id
    }
    $index=0
    foreach($package in $script:Request.packages|Where-Object {$_.package.kind -eq 'extension'}){
        $index++;$null=Install-Extension $package ('extension-'+$index.ToString('D2'))
    }
    $script:Native.inventory=Native-Inventory
    Require ((Version3 $script:Native.inventory.platform.database_version) -eq (Version3 $script:Request.release.target_version)) 'The native database has not reached the selected maintenance target.'
    Require ((Version3 $script:Native.inventory.platform.assembly_version) -eq (Version3 $script:Request.release.target_version)) 'The native platform files have not reached the selected maintenance target.'
    $script:Native.upgrade_completed=$true;Save-Native
    $null=Http-Checks
    return @{completed=$true;platform_hops=$steps.Count;finished_at=[DateTime]::UtcNow.ToString('o')}
}

[CmdletBinding()]
param(
    [Parameter(Mandatory=$true)][string]$RequestDirectory,
    [Parameter(Mandatory=$true)][string]$ConnectionPath,
    [string]$OutputDirectory,
    [switch]$Resume
)
Set-StrictMode -Version Latest
$ErrorActionPreference='Stop'
. (Join-Path $PSScriptRoot 'native-host.ps1')
. (Join-Path $PSScriptRoot 'native-upgrade.ps1')
$script:InputRoot=[IO.Path]::GetFullPath($RequestDirectory)
$script:Connection=Read-Json ([IO.Path]::GetFullPath($ConnectionPath))
Require ($script:Connection.schema -eq 'commons.dnn-connection/v1') 'Use this receiver version of the private connection file.'
$requestPath=Join-Path $script:InputRoot 'request.json'
$raw=[IO.File]::ReadAllBytes($requestPath)
$script:Request=Read-Json $requestPath
$script:RequestHash=Hash-Bytes $raw
$expected=[IO.File]::ReadAllText((Join-Path $script:InputRoot 'request.sha256')).Trim()
Require ($script:RequestHash -eq $expected) 'The native request differs from its original approved bytes.'
Require ($script:Request.schema -eq 'commons.dnn-native/v1') 'Use the matching DNN request schema.'
$operation=[guid]::Empty
Require ([guid]::TryParse($script:Request.operation_id,[ref]$operation)) 'The native request has no original operation UUID.'
Require ([IO.Path]::IsPathRooted([string]$script:Connection.state_directory)) 'Set an absolute private state directory outside the website.'
$stateRoot=[IO.Path]::GetFullPath([string]$script:Connection.state_directory)
Require ([IO.Path]::IsPathRooted($stateRoot)) 'Set an absolute private state directory outside the website.'
[IO.Directory]::CreateDirectory($stateRoot)|Out-Null
$script:Work=Join-Path $stateRoot $operation.ToString()
[IO.Directory]::CreateDirectory($script:Work)|Out-Null
Assert-NoReparse $stateRoot
Assert-NoReparse $script:Work
if(-not $OutputDirectory){$OutputDirectory=$script:Work}
$OutputDirectory=[IO.Path]::GetFullPath($OutputDirectory)
[IO.Directory]::CreateDirectory($OutputDirectory)|Out-Null
$script:OperationLease=$null
try{$script:OperationLease=[IO.FileStream]::new((Join-Path $script:Work 'operation.lock'),[IO.FileMode]::OpenOrCreate,[IO.FileAccess]::ReadWrite,[IO.FileShare]::None)}
catch{throw 'The original operation is already executing; read its existing journal and return locator.'}
$journalPath=Join-Path $script:Work 'journal.json'
$priorExists=[IO.File]::Exists($journalPath)
if($priorExists){
    $script:Journal=Read-Json $journalPath
    Require ($script:Journal.operation_id -eq $script:Request.operation_id -and $script:Journal.request_sha256 -eq $script:RequestHash) 'The original native operation directory belongs to another request.'
    Require ($Resume -or $script:Journal.state -eq 'complete') 'Use -Resume to continue this original operation and read its retained outcomes.'
}else{
    $script:Journal=@{schema='commons.dnn-native-journal/v1';operation_id=$script:Request.operation_id;request_sha256=$script:RequestHash;state='prepared';created_at=[DateTime]::UtcNow.ToString('o');steps=@{};uploads=@{};source=@{}}
    foreach($file in @('native.ps1','native-host.ps1','native-upgrade.ps1')){
        $script:Journal.source[$file]=Hash-File (Join-Path $PSScriptRoot $file)
    }
    Atomic-Bytes (Join-Path $script:Work 'request.json') $raw -Exclusive
    Save-Journal
}
$nativePath=Join-Path $script:Work 'native.json'
$script:Native=if([IO.File]::Exists($nativePath)){Read-Json $nativePath}else{@{}}
$started=$script:Journal.created_at
$script:Lease=$null
$status='failed';$message=''
function Native-ErrorText($ErrorRecord) {
    $text=[string]$ErrorRecord.Exception.Message
    foreach($key in @('sql_connection_string_env','host_username_env','host_password_env','host_headers_env')){
        $reference=Get-Field $script:Connection $key ''
        if($reference){$secret=[Environment]::GetEnvironmentVariable($reference);if($secret){$text=$text.Replace($secret,'[private reference]')}}
    }
    if((Get-Variable -Name SqlConnection -Scope Script -ErrorAction SilentlyContinue) -and $script:SqlConnection){$text=$text.Replace($script:SqlConnection,'[private SQL reference]')}
    return $text
}
function Publish-Return([string]$State,[string]$Message) {
    Save-Native
    $artifacts=@()
    # Private connection/configuration binding files never enter the return package.
    foreach($file in Get-ChildItem -LiteralPath $script:Work -File -Recurse){
        $relative=$file.FullName.Substring($script:Work.Length+1).Replace('\','/')
        if($relative -match '(^|/)(?:result[^/]*\.json|(?:DNN_)?return[^/]*\.zip|.*\.lock|.*\.private|.*\.pending(?:-.*)?|original-app-offline\.htm)$'){continue}
        if($relative.StartsWith('restore/received-tree/')){continue}
        if($relative -eq 'connection.json'){continue}
        $artifacts+=Artifact $file.FullName
    }
    $result=@{schema='commons.dnn-native/v1';operation_id=$script:Request.operation_id;request_sha256=$script:RequestHash;status=$State;started_at=$started;finished_at=[DateTime]::UtcNow.ToString('o');message=$Message;native=$script:Native;artifacts=$artifacts}
    $resultBytes=Json-Bytes $result
    $generation=Hash-Bytes $resultBytes
    $resultPath=Join-Path $script:Work ('result-'+$generation+'.json')
    Atomic-Bytes $resultPath $resultBytes -Exclusive
    $name='DNN_Return_'+$operation.ToString()+'_'+$generation.Substring(0,12)+'.zip'
    $zipPath=Join-Path $OutputDirectory $name
    if(-not [IO.File]::Exists($zipPath)){
        $temporary=$zipPath+'.pending-'+[guid]::NewGuid().ToString('N')
        $archive=$null
        try{
            $archive=[IO.Compression.ZipFile]::Open($temporary,[IO.Compression.ZipArchiveMode]::Create)
            $entry=$archive.CreateEntry('result.json',[IO.Compression.CompressionLevel]::Optimal)
            $out=$entry.Open();try{$out.Write($resultBytes,0,$resultBytes.Length)}finally{$out.Dispose()}
            foreach($artifact in $artifacts){
                $file=Under $script:Work $artifact.path
                Require ((Get-Item -LiteralPath $file).Length -eq $artifact.bytes -and (Hash-File $file) -eq $artifact.sha256) 'A retained native artifact changed before publication.'
                $entry=$archive.CreateEntry($artifact.path,[IO.Compression.CompressionLevel]::Fastest)
                $input=[IO.File]::OpenRead($file);$out=$entry.Open()
                try{$input.CopyTo($out)}finally{$input.Dispose();$out.Dispose()}
            }
            $archive.Dispose();$archive=$null
            [IO.File]::Move($temporary,$zipPath)
        }finally{if($null -ne $archive){$archive.Dispose()};if([IO.File]::Exists($temporary)){[IO.File]::Delete($temporary)}}
    }
    $summary=@{schema='commons.dnn-native-return/v1';operation_id=$script:Request.operation_id;request_sha256=$script:RequestHash;state=$State;path=$zipPath;bytes=(Get-Item -LiteralPath $zipPath).Length;sha256=Hash-File $zipPath;message=$Message}
    Atomic-Json (Join-Path $script:Work 'return-locator.json') $summary
    return $summary
}
try{
    # The original request gets a process lease before mutable journal/native records are reused.
    foreach($file in $script:Journal.source.Keys){
        Require ((Hash-File (Join-Path $PSScriptRoot $file)) -eq $script:Journal.source[$file]) 'Resume with the same original native receiver source. Receive the prior result before preparing a revised operation.'
    }
    Bind-Host
    $targetLock=Hash-Bytes ([Text.Encoding]::UTF8.GetBytes($script:SiteRoot.ToLowerInvariant()))
    $script:Lease=[IO.FileStream]::new((Join-Path $stateRoot ('site-'+$targetLock+'.lock')),[IO.FileMode]::OpenOrCreate,[IO.FileAccess]::ReadWrite,[IO.FileShare]::None)
    if($script:Journal.state -eq 'complete'){
        $savedLocator=Join-Path $script:Work 'return-locator.json'
        $locator=if([IO.File]::Exists($savedLocator)){Read-Json $savedLocator}else{$null}
        if($null -eq $locator -or $locator.state -ne 'complete'){
            $locator=Publish-Return 'complete' 'The original completed native action was recovered before its return publication.'
        }
        Require ([IO.File]::Exists($locator.path) -and (Hash-File $locator.path) -eq $locator.sha256) 'Reopen the original completed return archive from its retained location.'
        $locator|ConvertTo-Json -Depth 20 -Compress
        if($null -ne $script:Lease){$script:Lease.Dispose()}
        $script:OperationLease.Dispose()
        exit 0
    }
    if(-not $script:Journal.steps.ContainsKey('initial-inventory')){
        $inventory=Native-Inventory
        Assert-Baseline $inventory
        $script:Native.inventory=$inventory
        $script:Journal.steps['initial-inventory']=@{state='complete';kind='read';started_at=[DateTime]::UtcNow.ToString('o');value=@{platform=$inventory.platform;target=$inventory.target;sql=$inventory.sql}}
        Save-Journal;Save-Native
    }elseif(-not $script:Native.ContainsKey('inventory')){
        $script:Native.inventory=Native-Inventory;Save-Native
    }
    $script:Journal.state='running';Save-Journal
    switch($script:Request.action){
        'inventory' {$script:Native.inventory=Native-Inventory;Save-Native}
        'backup' {$null=New-PairedBackup;$script:Native.inventory=Native-Inventory;Save-Native}
        'upgrade' {$null=Run-Upgrade}
        'restore' {$null=Restore-PairedBackup;$script:Native.inventory=Native-Inventory;Save-Native;$null=Http-Checks}
        'verify' {$script:Native.inventory=Native-Inventory;Save-Native;$null=Http-Checks}
        default {throw 'The original request selects an unknown native operation.'}
    }
    $status='complete';$message='The original native action and its requested checks completed.'
    $script:Journal.state='complete';Save-Journal
}catch{
    $message=Native-ErrorText $_
    $uncertain=@($script:Journal.steps.Values|Where-Object {$_.kind -eq 'write' -and $_.state -in @('started','uncertain')})
    $status=if($message.StartsWith('DNN_INPUT:')){'waiting'}elseif($uncertain.Count -gt 0 -or $message.StartsWith('DNN_UNCERTAIN:')){'uncertain'}else{'failed'}
    $script:Journal.state=$status
    if($null -ne $script:OperationLease){Save-Journal}
    # Keep the selected site in its actual maintenance state after an uncertain mutation.
}
try{
    $summary=Publish-Return $status $message
    $summary|ConvertTo-Json -Depth 20 -Compress
}finally{
    if($null -ne $script:Lease){$script:Lease.Dispose()}
    if($null -ne $script:OperationLease){$script:OperationLease.Dispose()}
}
if($status -eq 'complete'){exit 0}else{exit 2}

"""DNN staff operations in the original authenticated, versioned source store."""
from __future__ import annotations
