        return ("<!doctype html><html lang=en><meta charset=utf-8><meta name=viewport content='width=device-width,initial-scale=1'><title>" + e(capture["name"]) + "</title><style>body{font:15px/1.5 system-ui,sans-serif;color:#171717;background:white;max-width:1200px;margin:36px auto;padding:0 20px}h1,h2,h3{line-height:1.2}h2{border-top:2px solid #333;padding-top:20px;margin-top:36px}table{border-collapse:collapse;width:100%;table-layout:fixed;margin:16px 0}th,td{border:1px solid #bbb;padding:9px;text-align:left;vertical-align:top;overflow-wrap:anywhere}th{background:#ededed}dt{font-weight:650}dd{margin:0 0 8px}.hash{font:12px/1.5 ui-monospace,monospace}@media print{body{font-size:10pt;margin:0}tr{break-inside:avoid}}</style><main>" + "".join(blocks) + "</main></html>").encode("utf-8")

    def _write_export_payload(self, directory, capture):
        from govhub import APPROVAL_FIELDS, MANIFEST_FIELDS, csv_bytes, digest, packed
        files = {}
        def write(name, content):
            path = directory / name
            with path.open("wb") as output:
                output.write(content)
                output.flush()
                os.fsync(output.fileno())
            os.chmod(path, 0o600)
            files[name] = path
        write("handover.json", (packed(capture) + "\n").encode("utf-8"))
        write("handover.html", self._handover_html(capture))
        write("record-history.ndjson", ("".join(packed(row) + "\n" for row in capture["record_history"])).encode("utf-8"))
        write("operations.json", (packed(capture["operations"]) + "\n").encode("utf-8"))
        if "visitor" in capture:
            from visitor_journeys.delivery import write_payload
            write_payload(write, capture)
        for kind, records in capture["records"].items():
            fields = ["id", "revision", "archived", "author", "updated_at"] + [field["name"] for field in self._schema.SCHEMAS[kind]["fields"]]
            rows = []
            for item in records:
                row = {key: item[key] for key in ("id", "revision", "archived", "author", "updated_at")}
                row.update({key: packed(value) if isinstance(value, (dict, list)) else value for key, value in item["data"].items()})
                rows.append(row)
            write(kind + ".csv", csv_bytes(rows, fields))
        snapshots = {item["id"]: item for item in capture["snapshots"]}
        for item in capture["plans"]:
            plan = item["plan"]
            cohort = set(plan["agency_ids"])
            prefix = plan["id"] + "-"
            write(prefix + "baseline.csv", csv_bytes([row for row in snapshots[plan["baseline_id"]]["rows"] if row["agency_id"] in cohort], MANIFEST_FIELDS))
            write(prefix + "candidate.csv", csv_bytes([row for row in snapshots[plan["candidate_id"]]["rows"] if row["agency_id"] in cohort], MANIFEST_FIELDS))
            write(prefix + "approvals.csv", csv_bytes(item["applicable_approvals"], APPROVAL_FIELDS))
            if plan["latest_audit_id"]:
                audit = next(value for value in item["audits"] if value["id"] == plan["latest_audit_id"])
                write(prefix + "audit.json", (packed(audit["report"]) + "\n").encode("utf-8"))
                rendered = self.auditor.render_html(audit["report"])
                write(prefix + "audit.html", rendered.encode("utf-8") if isinstance(rendered, str) else rendered)
        self._content_export_files(capture, write)
        source_manifest, source_paths, by_hash = [], {}, {}
        for item in capture["sources"]:
            path = self._verify_file(item)
            archive_name = by_hash.setdefault(item["sha256"], "sources/" + item["sha256"][:20] + "-" + item["filename"])
            source_manifest.append(dict(item, archive_path=archive_name if capture["include_sources"] else None))
            if capture["include_sources"]:
                source_paths[archive_name] = path
        write("source-manifest.json", (packed({"include_sources": capture["include_sources"], "sources": source_manifest}) + "\n").encode("utf-8"))
        entries = [{"name": name, "sha256": digest(path.read_bytes()), "size": path.stat().st_size} for name, path in sorted(files.items())]
        write("manifest.json", (packed({"format": "govhub-handover-files/1", "files": entries, "original_sources": source_manifest}) + "\n").encode("utf-8"))
        archive = directory / "handover.zip"
        with zipfile.ZipFile(archive, "w", compression=zipfile.ZIP_DEFLATED, compresslevel=5, allowZip64=True) as output:
            for name, path in sorted(files.items()):
                output.write(path, name)
            for name, path in sorted(source_paths.items()):
                compression = zipfile.ZIP_STORED if Path(name).suffix.lower() in {".gz", ".zip", ".xz", ".bz2", ".jpg", ".png", ".pdf"} else zipfile.ZIP_DEFLATED
                output.write(path, name, compress_type=compression)
        with archive.open("rb") as output:
            os.fsync(output.fileno())
        os.chmod(archive, 0o600)
        files["handover.zip"] = archive
        return files

    def _exports_create(self, payload, actor):
        from govhub import GovHubError, digest, ident, now, packed
        with self._export_lease():
            with self.connect(write=True) as db:
                key, fingerprint, prior = self._request(db, payload, actor)
                if prior:
                    return prior
                intents = self._objects(db, "export_intent", key)
                if intents:
                    intent = intents[0]
                    if intent["request_fingerprint"] != fingerprint:
                        raise GovHubError("RETRY_CHANGED", "This handover identity belongs to different input.", 409)
                else:
                    capture = self._handover_capture(db, payload, actor)
                    intent = self._object(db, "export_intent", {"export_id": ident("export-"), "request_fingerprint": fingerprint, "capture": capture}, parent=key, actor=actor["name"])
            capture = intent["capture"]
            export_id = intent["export_id"]
            root = self.root / "govhub-export-builds"
            root.mkdir(mode=0o700, exist_ok=True)
            if root.is_symlink():
                raise GovHubError("EXPORT_DIRECTORY", "The handover build directory must remain private and local.", 409)
            directory = root / export_id
            directory.mkdir(mode=0o700, exist_ok=True)
            if directory.is_symlink():
                raise GovHubError("EXPORT_DIRECTORY", "The selected handover build directory changed.", 409)
            paths = self._write_export_payload(directory, capture)
            with self.connect(write=True) as db:
                key, fingerprint, prior = self._request(db, payload, actor)
                if prior:
                    return prior
                # A previous interrupted final transaction may have left only
                # unreferenced immutable blobs; the same captured intent is reused.
                files = [self._register_generated(db, path, name, actor, export_id) for name, path in sorted(paths.items())]
                value = {"id": export_id, "name": capture["name"], "created_at": capture["observed_at"], "author": capture["author"], "plan_ids": capture["plan_ids"], "content_family_ids": capture.get("content_family_ids", []), "package_family_ids": capture.get("package_family_ids", []), "visitor_edition_ids": capture.get("visitor_edition_ids", []), "pots_project_ids": capture.get("pots_project_ids", []), "playbook_version_ids": capture.get("playbook_version_ids", []), "files": files, "snapshot_sha256": digest(packed(capture)), "intent_id": intent["id"], "include_sources": capture["include_sources"]}
                result = {"export": self._object(db, "export", value, actor=actor["name"])}
                self._remember(db, key, fingerprint, result, actor)
                self._changed(db, actor, "Complete immutable cohort handover created", "export", export_id, {"plan_ids": capture["plan_ids"], "files": len(files)})
            try:
                directory.rmdir()
            except OSError:
                pass
            return result

    def _exports_get(self, payload):
        with self.connect(snapshot=True) as db:
            value = self._get(db, "export", payload.get("export_id"))
            return {"export": value}

    @staticmethod
    def _compare_objects(before, after, key="id"):
        a, b = {item[key]: item for item in before}, {item[key]: item for item in after}
        changed = []
        for identity in sorted(set(a) & set(b)):
            if a[identity] != b[identity]:
                fields = [{"field": name, "before": a[identity].get(name), "after": b[identity].get(name)} for name in sorted(set(a[identity]) | set(b[identity])) if a[identity].get(name) != b[identity].get(name)]
                changed.append({"id": identity, "fields": fields})
        return {"added": [b[key] for key in sorted(set(b) - set(a))], "removed": [a[key] for key in sorted(set(a) - set(b))], "changed": changed, "unchanged": sorted(key for key in set(a) & set(b) if a[key] == b[key])}

    def _exports_compare(self, payload):
        with self.connect(snapshot=True) as db:
            before = self._get(db, "export", payload.get("before_id"))
            after = self._get(db, "export", payload.get("after_id"))
            a = self._get(db, "export_intent", before["intent_id"])["capture"]
            b = self._get(db, "export_intent", after["intent_id"])["capture"]
            records = {kind: self._compare_objects(a["records"][kind], b["records"][kind]) for kind in a["records"]}
            result = {"before": {key: before[key] for key in ("id", "name", "created_at", "sha256")}, "after": {key: after[key] for key in ("id", "name", "created_at", "sha256")}, "plans": self._compare_objects([item["plan"] for item in a["plans"]], [item["plan"] for item in b["plans"]]), "operations": self._compare_objects([item["operation"] for item in a["operations"]], [item["operation"] for item in b["operations"]]), "records": records, "scope_changed": a["settings"] != b["settings"], "before_source_hashes": sorted({item["sha256"] for item in a["sources"]}), "after_source_hashes": sorted({item["sha256"] for item in b["sources"]})}
            if a.get("visitor") or b.get("visitor"):
                result["visitor"] = {name: self._compare_objects(
                    a.get("visitor", {}).get(name, []), b.get("visitor", {}).get(name, []))
                    for name in ("editions", "reviews", "finding_history")}
            return result

    def backup(self, output):
        """Copy one coherent database, immutable sources and original native journal."""
        from govhub import GovHubError
        with self._native_storage_lease(exclusive=True) as available:
            if not available:
                raise GovHubError("BACKUP_NATIVE_ACTIVE", "A native operation is still writing its journal. Let that operation finish, or pause it and wait for its retained terminal result, then create this private backup.", 409)
            # An orphaned RUNNING record may still own a native child even after
            # its Python process disappeared. Reconcile it through the existing
            # worker before declaring a consistent private backup.
            with self.connect() as db:
                if db.execute("SELECT 1 FROM govhub_operations WHERE state='RUNNING' LIMIT 1").fetchone():
                    raise GovHubError("BACKUP_NATIVE_ACTIVE", "An original native operation is still marked running. Reopen its worker and reconcile the retained operation before backing up its command journal.", 409)
            return self._backup_locked(output)

    def _backup_locked(self, output):
        from govhub import GovHubError, now, packed
        target = Path(output)
        if not target.is_absolute() or target.exists():
            raise GovHubError("BACKUP_DIRECTORY", "Choose a new absolute backup directory.")
        target = target.parent.resolve() / target.name
        if target.is_relative_to(self.root):
            raise GovHubError("BACKUP_DIRECTORY", "Choose a backup destination outside the live workspace.")
        target.mkdir(mode=0o700, parents=True)
        marker = target / "BACKUP_INCOMPLETE"
        self._durable_file(marker, b"Backup in progress.")
        self._sync_dir(target)
        def copy_file(source, destination, expected=None):
            destination.parent.mkdir(mode=0o700, parents=True, exist_ok=True)
            descriptor = os.open(source, os.O_RDONLY | os.O_NOFOLLOW)
            before = os.fstat(descriptor)
            if not stat.S_ISREG(before.st_mode):
                os.close(descriptor)
                raise GovHubError("BACKUP_SOURCE", "The private backup contains a nonregular source; its incomplete marker is retained.", 503)
            h, size = hashlib.sha256(), 0
            with os.fdopen(descriptor, "rb") as original:
                output_descriptor = os.open(destination, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
                with os.fdopen(output_descriptor, "wb") as copy:
                    for chunk in iter(lambda: original.read(1024 * 1024), b""):
                        h.update(chunk)
                        size += len(chunk)
                        copy.write(chunk)
                    copy.flush()
                    os.fsync(copy.fileno())
                after = os.fstat(original.fileno())
            if any(getattr(before, key) != getattr(after, key) for key in ("st_size", "st_mtime_ns", "st_ino", "st_dev")) or size != before.st_size:
                raise GovHubError("BACKUP_SOURCE", "A private source changed during its copy; the backup remains incomplete.", 503)
            value = {"path": destination.relative_to(target).as_posix(), "sha256": h.hexdigest(), "size": size}
            if expected and (size != expected["bytes"] or value["sha256"] != expected["sha256"]):
                raise GovHubError("BACKUP_SOURCE", "A retained source is inconsistent; the backup remains incomplete.", 503)
            return value
        with self.connect(write=True) as db:
            out = sqlite3.connect(target / "assessment.sqlite3")
            reader = sqlite3.connect(self.db)
            try:
                reader.backup(out)
            finally:
                reader.close()
                out.close()
            sources = [dict(row) for row in db.execute("SELECT DISTINCT sha256,bytes FROM files")]
            metadata = {"format": "systems-review-private-backup/v1", "created_at": now(), "workspace": self.meta(db)["workspace"]}
        (target / "sources").mkdir(mode=0o700)
        for row in sources:
            source = self.blobs / row["sha256"]
            if source.is_symlink() or not source.is_file():
                raise GovHubError("BACKUP_SOURCE", "A retained source is unavailable; the backup remains incomplete.", 503)
            copy_file(source, target / "sources" / row["sha256"], row)
        native_files = []
        native_root = self.root / "native-operations"
        if native_root.exists() or native_root.is_symlink():
            if native_root.is_symlink() or not native_root.is_dir():
                raise GovHubError("BACKUP_NATIVE_SOURCE", "The original native journal must be a private regular directory.", 503)
            for directory, dirs, files in os.walk(native_root, followlinks=False):
                folder = Path(directory)
                if any((folder / name).is_symlink() for name in dirs):
                    raise GovHubError("BACKUP_NATIVE_SOURCE", "The native journal contains a directory link; the backup remains incomplete.", 503)
                destination = target / folder.relative_to(self.root)
                destination.mkdir(mode=0o700, parents=True, exist_ok=True)
                for name in sorted(files):
                    native_files.append(copy_file(folder / name, destination / name))
            for directory, _, _ in os.walk(target / "native-operations", topdown=False):
                self._sync_dir(Path(directory))
        roots = {str(self.root), *(item["from"] for item in self._workspace_relocations())}
        metadata["native_storage"] = {"format": "govhub-native-storage/1", "original_roots": sorted(roots), "files": sorted(native_files, key=lambda value: value["path"])}
        self._durable_file(target / "reconciliation.key", self.key.read_bytes())
        os.chmod(target / "assessment.sqlite3", 0o600)
        with (target / "assessment.sqlite3").open("rb") as file:
            os.fsync(file.fileno())
        self._durable_file(target / "backup.json", packed(metadata).encode("utf-8"))
        self._sync_dir(target / "sources")
        self._sync_dir(target)
        marker.unlink()
        self._sync_dir(target)
        self._sync_dir(target.parent)
        return {"directory": str(target), **{key: value for key, value in metadata.items() if key != "native_storage"}, "native_files": len(native_files), "native_bytes": sum(value["size"] for value in native_files)}

"""Durable original-provider operations composed with GovHubWorkspace."""
from contextlib import contextmanager
from datetime import datetime, timedelta, timezone
from pathlib import Path
import fcntl
import importlib
import json
import os
import tempfile
import threading


class OperationsMixin:
    @contextmanager
    def _native_storage_lease(self, exclusive=False):
        """Keep a native command and its journal in the same backup generation."""
        descriptor = os.open(self.root / "native-snapshot.lock", os.O_CREAT | os.O_RDWR | os.O_NOFOLLOW, 0o600)
        held = False
        try:
            try:
                fcntl.flock(descriptor, (fcntl.LOCK_EX if exclusive else fcntl.LOCK_SH) | fcntl.LOCK_NB)
                held = True
            except BlockingIOError:
                pass
            yield held
        finally:
            if held:
                fcntl.flock(descriptor, fcntl.LOCK_UN)
            os.close(descriptor)

    def _workspace_relocations(self):
        """Resolve old private paths at use time; immutable journals stay original."""
        from govhub import GovHubError
        metadata = self.root / "backup.json"
        if not metadata.exists():
            return []
        if metadata.is_symlink() or not metadata.is_file():
            raise GovHubError("BACKUP_METADATA", "The retained backup metadata must be an original regular file.", 409)
        try:
            native = json.loads(metadata.read_bytes()).get("native_storage", {})
            roots = native.get("original_roots", [])
            if not isinstance(roots, list) or any(not isinstance(root, str) or not Path(root).is_absolute() or ".." in Path(root).parts for root in roots):
                raise ValueError("Invalid original workspace roots")
        except (ValueError, TypeError, AttributeError) as exc:
            raise GovHubError("BACKUP_METADATA", "The retained native backup relocation metadata is invalid.", 409) from exc
        return [{"from": root.rstrip("/"), "to": str(self.root)} for root in roots if root.rstrip("/") != str(self.root)]

    def _native(self):
        try:
            return importlib.import_module("native_adapter")
        except ImportError as exc:
            from govhub import GovHubError
            raise GovHubError("NATIVE_ADAPTER", "Install the original native_adapter.py with this workspace.", 503) from exc

    def _config(self, db, environment_id):
        from govhub import GovHubError
        row = db.execute("SELECT revision,data FROM govhub_config WHERE environment_id=?", (environment_id,)).fetchone()
        if not row:
            raise GovHubError("NATIVE_PROFILE", "Configure the actual operating environment's native profile first.")
        return {"revision": row[0], "config": json.loads(row[1])}

    def _operations_configure(self, payload, actor):
        from govhub import GovHubError, digest, packed, text
        self._authorize(actor, "admin")
        config = payload.get("config")
        providers = self._native().configuration_schema()["providers"]
        if not isinstance(config, dict) or config.get("source_kind") not in {item["value"] for item in providers}:
            raise GovHubError("NATIVE_CONFIG", "Choose a documented native provider profile.")
        definition = next(item for item in self._native().configuration_schema()["providers"] if item["value"] == config["source_kind"])
        fields = {item["name"]: item for item in definition["fields"]}
        allowed = {"source_kind", "api_base", "target_fingerprint", *fields}
        if set(config) - allowed:
            raise GovHubError("NATIVE_CONFIG", "The native profile contains unsupported fields: " + ", ".join(sorted(set(config) - allowed)))
        config = dict(config)
        for key, value in list(config.items()):
            field = fields.get(key, {})
            if field.get("type") == "boolean":
                if not isinstance(value, bool):
                    raise GovHubError("NATIVE_BOOLEAN", "Use a boolean value for " + field.get("label", key) + ".")
            elif field.get("type") == "integer":
                if value in (None, "") and not field.get("required"):
                    config.pop(key)
                    continue
                if isinstance(value, bool) or not isinstance(value, int) or value < field.get("minimum", 1) or value > field.get("maximum", 2**53 - 1):
                    raise GovHubError("NATIVE_INTEGER", "Use a whole value within the configured range for " + field.get("label", key) + ".")
            else:
                config[key] = text(value, field.get("max_length", 4000), key == "source_kind" or field.get("required", False))
        for key, field in fields.items():
            if field.get("required") and not config.get(key):
                raise GovHubError("NATIVE_REQUIRED", "Supply the native " + field.get("label", key) + ".", fields={key: "Required native profile field."})
        if config.get("access_token_env"):
            import re
            if not re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", config["access_token_env"]):
                raise GovHubError("TOKEN_REFERENCE", "Supply only the name of the existing token environment variable.")
        if config.get("api_base") and config["api_base"].rstrip("/") != "https://cloud.acquia.com/api":
            raise GovHubError("API_ORIGIN", "Use Acquia's documented native API origin.")
        with self.connect(write=True) as db:
            target = self._record_db(db, "environments", payload.get("environment_id"))
            self._expected(target, payload)
            if target["archived"]:
                raise GovHubError("TARGET_ARCHIVED", "Choose an active operating environment.")
            if not target["data"]["provider_resource_id"] or target["data"]["provider_resource_id"] != config["environment_id"]:
                raise GovHubError("TARGET_IDENTITY", "The profile's native environment ID must match the retained target environment record exactly.", 409)
            revision = digest(packed(config))
            previous = db.execute("SELECT revision FROM govhub_config WHERE environment_id=?", (target["id"],)).fetchone()
            if not previous or previous[0] != revision:
                self._object(db, "native_profile", {"environment_id": target["id"], "environment_revision": target["revision"], "config": config, "config_sha256": revision}, parent=target["id"], actor=actor["name"])
                db.execute("INSERT INTO govhub_config VALUES(?,?,?) ON CONFLICT(environment_id) DO UPDATE SET revision=excluded.revision,data=excluded.data", (target["id"], revision, packed(config)))
                data = dict(target["data"], native_profile=revision)
                self._write(db, "environments", target["id"], data, actor, target["revision"], "Native profile configured for the exact target")
                self._changed(db, actor, "Native environment profile configured", "environments", target["id"], {"config_sha256": revision})
            return {"environment": self._record_db(db, "environments", target["id"]), "profile": {"revision": revision, "config": config}}

    def _operations_capabilities(self, payload):
        native = self._native()
        if not payload.get("environment_id"):
            return {"configuration_schema": native.configuration_schema(), "configured": False}
        with self.connect() as db:
            environment = self._record_db(db, "environments", payload["environment_id"])
            configured = db.execute("SELECT 1 FROM govhub_config WHERE environment_id=?", (environment["id"],)).fetchone()
            if not configured:
                return {"environment": environment, "current_config": {}, "configuration_schema": native.configuration_schema(), "configured": False}
            profile = self._config(db, environment["id"])
        result = native.discover_capabilities(profile["config"], runtime_bindings=payload.get("runtime_bindings")) if "runtime_bindings" in payload else native.discover_capabilities(profile["config"])
        result["operation_actions"] = {kind: native.operation_actions(profile["config"], kind)
                                       for kind in ("CAPTURE", "PREVIEW", "BACKUP_CREATE", "BACKUP_DOWNLOAD", "REHEARSAL", "CUTOVER", "ROLLBACK")}
        return {"environment": environment, "profile": profile, "current_config": profile["config"], "configured": True, "capabilities": result, "configuration_schema": native.configuration_schema()}

    def _operation(self, db, operation_id):
        from govhub import GovHubError
        row = db.execute("SELECT data FROM govhub_operations WHERE id=?", (operation_id,)).fetchone()
        if not row:
            raise GovHubError("OPERATION_NOT_FOUND", "The selected native operation does not exist.", 404)
        return json.loads(row[0])

    def _write_operation(self, db, operation, actor, event, details=None):
        from govhub import ident, now, packed
        value = dict(operation, revision=ident("operation-version-"), updated_at=now())
        db.execute("INSERT INTO govhub_operations VALUES(?,?,?,?) ON CONFLICT(id) DO UPDATE SET revision=excluded.revision,state=excluded.state,data=excluded.data", (value["id"], value["revision"], value["state"], packed(value)))
        self._object(db, "operation_event", {"operation_id": value["id"], "operation_revision": value["revision"], "event": event, "state": value["state"], "details": details or {}}, parent=value["id"], actor=actor["name"] if isinstance(actor, dict) else actor)
        self._changed(db, actor, event, "operation", value["id"], details)
        return value

    @staticmethod
    def _operation_summary(value):
        keys = ("id", "revision", "plan_id", "plan_revision", "content_family_id", "content_plan_id", "type", "native_action", "state", "environment_id", "source_snapshot_id", "agency_ids", "created_at", "updated_at", "author", "progress", "error")
        return {key: value.get(key) for key in keys}

    def _operations_create(self, payload, actor, capture=False):
        from govhub import GovHubError, ident, now, text
        with self.connect(write=True) as db:
            key, fingerprint, prior = self._request(db, payload, actor)
            if prior:
                return prior
            target = self._record_db(db, "environments", payload.get("environment_id"))
            if target["archived"]:
                raise GovHubError("TARGET_ARCHIVED", "Choose an active native operating environment.")
            profile = self._config(db, target["id"])
            if payload.get("environment_revision") and payload["environment_revision"] != target["revision"]:
                raise GovHubError("TARGET_CHANGED", "The operating environment changed. Reopen its current native configuration before queuing this action.", 409)
            if payload.get("config_sha256") and payload["config_sha256"] != profile["revision"]:
                raise GovHubError("PROFILE_CHANGED", "The native profile changed. Reopen its current selections before queuing this action.", 409)
            if target["data"]["provider_resource_id"] != profile["config"]["environment_id"] or target["data"]["native_profile"] != profile["revision"]:
                raise GovHubError("TARGET_CHANGED", "The actual environment or native profile changed. Reconfigure the exact target before execution.", 409)
            if not target["data"]["authorization_reference"]:
                raise GovHubError("TARGET_AUTHORITY", "Retain the target operating authorization.")
            plan = source = review = audit = None
            operation_type = "CAPTURE" if capture else payload.get("type")
            available = self._native().operation_actions(profile["config"], operation_type)
            if not available:
                raise GovHubError("OPERATION_TYPE", "Choose an operation purpose supported by this native provider.")
            native_action = payload.get("native_action") or available[0]["value"]
            if native_action not in {item["value"] for item in available}:
                raise GovHubError("NATIVE_ACTION", "Choose the documented action for this provider and operation purpose.")
            if operation_type not in {"CAPTURE", "PREVIEW", "BACKUP_CREATE", "BACKUP_DOWNLOAD"}:
                plan = self._plan(db, payload.get("plan_id"))
                self._expected(plan, payload)
                if operation_type == "REHEARSAL" and target["data"]["purpose"] != "Rehearsal":
                    raise GovHubError("REHEARSAL_TARGET", "Choose the explicitly designated rehearsal environment for rehearsal work.")
                audit = self._current_audit(db, plan)
                review = self._current_review(db, plan, audit)
                if operation_type == "CUTOVER" and (not audit or audit["status"] != "PASS" or not review or review["decision"] != "APPROVE"):
                    raise GovHubError("CURRENT_REVIEW", "Complete the original comparison and reviewer approval for this exact cutover revision.", 409)
                source = self._get(db, "snapshot", plan["candidate_id"] if operation_type == "CUTOVER" else plan["baseline_id"])
                self._verify_snapshot(db, source)
            timestamp = now()
            value = {"id": ident("operation-"), "type": operation_type, "state": "QUEUED", "plan_id": plan["id"] if plan else "", "plan_revision": plan["revision"] if plan else "", "plan": plan, "audit_id": audit["id"] if audit else None, "review_id": review["id"] if review else None, "environment_id": target["id"], "environment": target, "profile": profile, "source_snapshot_id": source["id"] if source else "", "source_snapshot": source, "source_snapshot_sha256": source["sha256"] if source else "", "authorization_reference": text(payload.get("authorization_reference", target["data"]["authorization_reference"]), 8000, True), "created_at": timestamp, "updated_at": timestamp, "author": actor["name"], "progress": {"completed": 0, "total": 1, "stage": "QUEUED", "detail": "Queued for the selected native environment"}, "error": None, "cancel_requested": False, "native_attempted": False, "checkpoint": None, "resume_checkpoint": None, "native_capture_file_id": None, "native_result": None, "result_snapshot_id": None, "actual_started_at": None, "actual_finished_at": None}
            value["native_action"] = native_action
            value["provider_environment_id"] = profile["config"]["environment_id"]
            selected = payload.get("agency_ids", plan["agency_ids"] if plan else [])
            if not isinstance(selected, list) or (plan and not selected) or any(not isinstance(item, str) for item in selected) or len(set(selected)) != len(selected) or (plan and not set(selected) <= set(plan["agency_ids"])):
                raise GovHubError("OPERATION_COHORT", "Choose a unique, nonempty subset of this plan's original comparison IDs for the exact native environment.")
            value["agency_ids"] = sorted(selected)
            value["target_fingerprint"] = text(payload.get("target_fingerprint", profile["config"].get("target_fingerprint", "")), 4000)
            if payload.get("backup_sha256"):
                import re
                if not isinstance(payload["backup_sha256"], str) or not re.fullmatch(r"[0-9a-f]{64}", payload["backup_sha256"]):
                    raise GovHubError("BACKUP_IDENTITY", "Choose an exact retained SHA-256 backup identity.")
                value["backup_sha256"] = payload["backup_sha256"]
            operation = self._write_operation(db, value, actor, "Native source capture queued" if capture else "Native cohort operation queued", {"source_snapshot_id": value["source_snapshot_id"], "environment_revision": target["revision"], "config_sha256": profile["revision"]})
            result = {"operation": operation}
            self._remember(db, key, fingerprint, result, actor)
        self._worker_wake.set()
        return result

    def _operations_get(self, payload):
        with self.connect(snapshot=True) as db:
            value = self._operation(db, payload.get("operation_id"))
            return {"operation": value, "events": self._objects(db, "operation_event", value["id"]), "observations": self._objects(db, "operation_observation", value["id"]), "files": self._output_list(db, "operation", value["id"])}

    def _operations_cancel(self, payload, actor):
        from govhub import GovHubError, text
        reason = text(payload.get("reason", ""), 8000, True)
        with self.connect(write=True) as db:
            bound = dict(payload, operation_action="operations.cancel")
            key, fingerprint, prior = self._request(db, bound, actor, required=False)
            if prior is not None:
                return prior
            value = self._operation(db, payload.get("operation_id"))
            self._expected(value, payload)
            if value["state"] in {"COMPLETE", "CANCELLED"}:
                result = {"operation": value}
                self._remember(db, key, fingerprint, result, actor)
                return result
            value["cancel_requested"] = True
            if value["state"] == "RUNNING":
                value["progress"] = dict(value["progress"], detail="Cancellation requested; preserving the current native command or provider result")
            elif value["type"] in {"STATIC_PUBLISH", "STATIC_ROLLBACK"} and self._static_unresolved(value):
                value["state"] = "QUEUED"
                value["progress"] = dict(value["progress"], stage="RECONCILE_NATIVE", detail="Cancellation retained; inspect the original selection before resolving its outcome")
            elif value.get("native_attempted") and not value.get("native_result"):
                value["state"] = "WAITING_NATIVE"
                value["progress"] = dict(value["progress"], stage="RECONCILE_NATIVE", detail="Cancellation retained; reconcile the already attempted native action")
            else:
                value["state"] = "CANCELLED"
            value = self._write_operation(db, value, actor, "Operation cancellation requested", {"reason": reason})
            result = {"operation": value}
            self._remember(db, key, fingerprint, result, actor)
        self._worker_wake.set()
        return result

    def _operations_resume(self, payload, actor):
        from govhub import GovHubError, text
        reason = text(payload.get("reason", ""), 8000, True)
        with self.connect(write=True) as db:
            key, fingerprint, prior = self._request(db, payload, actor)
            if prior:
                return prior
            value = self._operation(db, payload.get("operation_id"))
            self._expected(value, payload)
            if value["state"] in {"QUEUED", "RUNNING", "COMPLETE"}:
                raise GovHubError("OPERATION_STATE", "This operation is already active or complete.", 409)
            if (value.get("native_result") or {}).get("status") == "COMPLETE":
                raise GovHubError("OBSERVATION_REQUIRED", "The native action completed. Attach its actual observed result inventory to complete reconciliation.", 409)
            if value["type"] != "CAPTURE" and value.get("native_attempted") and not value.get("resume_checkpoint") and not (value.get("checkpoint") or {}).get("safe_to_retry"):
                raise GovHubError("NATIVE_RECONCILIATION", "Reconcile the original native action with its retained execution capture before starting another restore.", 409)
            if payload.get("native_task_id") is not None:
                native_task_id = payload["native_task_id"]
                if (value.get("native_action") != "lagoon-switch-active-standby"
                        or isinstance(native_task_id, bool) or not isinstance(native_task_id, int)
                        or native_task_id < 1):
                    raise GovHubError("NATIVE_TASK", "Supply the actual positive Lagoon task ID for this original switch.")
                existing = self._native().lagoon_task_id(value.get("resume_checkpoint") or value.get("checkpoint"))
                if existing and existing != native_task_id:
                    raise GovHubError("NATIVE_TASK_CHANGED", "A different task cannot replace the retained original task.", 409)
                value["native_task_id"] = native_task_id
            if (payload.get("native_workflow_id") or payload.get("native_backup_files")
                    or "runtime_bindings" in payload or payload.get("skpr_native_request_id")
                    or "skpr_snapshot_choices" in payload or payload.get("tugboat_job_id")
                    or payload.get("upsun_activity_id") or payload.get("upsun_activity_ids_json")
                    or payload.get("castor_command_receipt")):
                try:
                    value.update(self._native().native_resume_fields(value, payload, reason))
                except ValueError as exc:
                    code = "CASTOR_CONTINUATION" if str(value.get("native_action", "")).startswith("castor-") else "UPSUN_CONTINUATION" if str(value.get("native_action", "")).startswith("upsun-") else "TUGBOAT_CONTINUATION" if str(value.get("native_action", "")).startswith("tugboat-") else "SKPR_CONTINUATION" if str(value.get("native_action", "")).startswith("skpr-") else "PANTHEON_CONTINUATION"
                    raise GovHubError(code, str(exc), 409) from exc
            value.update(state="QUEUED", cancel_requested=False, error=None)
            value["progress"] = dict(value["progress"], stage="QUEUED", detail="Continuing the retained native checkpoint")
            value = self._write_operation(db, value, actor, "Retained native operation resumed", {"reason": reason, "resume_checkpoint": value.get("resume_checkpoint"), "native_task_id": value.get("native_task_id"), "native_workflow_id": value.get("native_workflow_id"), "native_workflow_step": value.get("native_workflow_step"), "native_backup_selections": value.get("native_backup_selections"), "runtime_bindings": value.get("runtime_bindings"), "skpr_native_associations": value.get("skpr_native_associations"), "skpr_snapshot_selections": value.get("skpr_snapshot_selections"), "tugboat_job_association": value.get("tugboat_job_association"), "upsun_activity_association": value.get("upsun_activity_association"), "castor_command_receipt": value.get("castor_command_receipt")})
            result = {"operation": value}
            self._remember(db, key, fingerprint, result, actor)
        self._worker_wake.set()
        return result

    def _operation_sources(self, value, output_dir):
        from govhub import GovHubError
        snapshot = value.get("source_snapshot")
        result = {"snapshot_id": value["source_snapshot_id"], "snapshot_sha256": value["source_snapshot_sha256"], "rows": [], "bindings": [], "output_dir": str(output_dir), "checkpoint": value.get("resume_checkpoint") or value.get("checkpoint"), "workspace_relocations": self._workspace_relocations()}
        if not snapshot:
            return result
        cohort = set(value.get("agency_ids", value["plan"]["agency_ids"]))
        with self.connect(snapshot=True) as db:
            current = self._get(db, "snapshot", snapshot["id"])
            if current["sha256"] != snapshot["sha256"]:
                raise GovHubError("OPERATION_SOURCE", "The selected source snapshot identity changed.", 409)
            paths = self._verify_snapshot(db, current, deep=True, cohort=cohort)
        result["rows"] = [row for row in snapshot["rows"] if row["agency_id"] in cohort]
        for binding in snapshot["bindings"]:
            if binding["agency_id"] not in cohort:
                continue
            supplied = {"agency_id": binding["agency_id"], "files": []}
            for role in ("export", "backup"):
                if binding.get(role):
                    item = binding[role]
                    supplied[role] = {**item.get("native", {}), "path": str(paths[item["sha256"]]), "sha256": item["sha256"], "size": item["bytes"], "file_id": item["id"], "filename": item["filename"]}
            for extra in binding.get("files", []):
                item = extra["file"]
                supplied["files"].append({**extra.get("native", {}), "role": extra["role"], "path": str(paths[item["sha256"]]), "sha256": item["sha256"], "size": item["bytes"], "file_id": item["id"], "filename": item["filename"]})
            result["bindings"].append(supplied)
        return result

    def _cancelled(self, operation_id):
        if self._worker_stop.is_set():
            return True
        with self.connect() as db:
            value = self._operation(db, operation_id)
            return value.get("cancel_requested", False) or value.get("worker_owner") != self._worker_owner

    def _native_checkpoint(self, operation_id, data):
        from govhub import GovHubError, packed
        if not isinstance(data, dict) or len(packed(data).encode("utf-8")) > 1024 * 1024:
            raise GovHubError("NATIVE_CHECKPOINT", "The native adapter returned an invalid checkpoint.", 503)
        with self.connect(write=True) as db:
            value = self._operation(db, operation_id)
            if value.get("worker_owner") != self._worker_owner:
                raise GovHubError("WORKER_OWNERSHIP", "The operation's native worker ownership changed.", 409)
            value["checkpoint"] = data
            if data.get("resume_checkpoint"):
                value["resume_checkpoint"] = data["resume_checkpoint"]
            if data.get("mutation_started"):
                value["native_attempted"] = True
            if data.get("safe_to_retry"):
                value["native_attempted"] = False
            value["progress"] = dict(value["progress"], stage=str(data.get("stage", "NATIVE")), detail=str(data.get("detail", data.get("message", "Native checkpoint retained")))[:8000])
            self._write_operation(db, value, value["author"], "Native checkpoint retained", data)

    @staticmethod
    def _static_unresolved(value):
        if value.get("type") not in {"STATIC_PUBLISH", "STATIC_ROLLBACK"}:
            return False
        from static_releases.native import is_unresolved_selection
        return is_unresolved_selection(value)

    def _claim_next(self):
        from govhub import now
        with self.connect(write=True) as db:
            rows = db.execute("SELECT data FROM govhub_operations WHERE state IN ('QUEUED','WAITING_NATIVE') ORDER BY rowid").fetchall()
            for row in rows:
                value = json.loads(row[0])
                if value["state"] == "WAITING_NATIVE":
                    resume = value.get("resume_checkpoint") or {}
                    if value.get("cancel_requested") or not self._native().can_poll(resume) or (value.get("next_poll_at") and value["next_poll_at"] > now()):
                        continue
                if value.get("cancel_requested") and not self._static_unresolved(value):
                    value["state"] = "CANCELLED"
                    self._write_operation(db, value, value["author"], "Queued operation cancelled")
                    continue
                value.update(state="RUNNING", worker_owner=self._worker_owner)
                value["progress"] = dict(value["progress"], stage="VERIFY_SOURCE", detail="Rehashing the exact retained native inputs")
                return self._write_operation(db, value, value["author"], "Native worker acquired operation")
        return None

    def _capture_result_files(self, db, value, native_result, output_dir):
        from govhub import GovHubError, packed
        artifacts = native_result.get("artifacts", [])
        if not isinstance(artifacts, list):
            raise GovHubError("NATIVE_ARTIFACTS", "The native result did not supply its artifact array.", 503)
        retained = []
        previous_outputs = self._output_list(db, "operation", value["id"])
        used = {item["name"] for item in previous_outputs}
        originals = {(item["name"], item["sha256"]): item for item in previous_outputs}
        for previous_artifact in value.get("retained_artifacts", []):
            original_name = previous_artifact.get("native", {}).get("original_filename")
            if original_name:
                file = previous_artifact["file"]
                originals[(original_name, file["sha256"])] = {
                    "file_id": file["id"], "sha256": file["sha256"], "size": file["bytes"]}
        for index, artifact in enumerate(artifacts, 1):
            if not isinstance(artifact, dict) or not artifact.get("path"):
                raise GovHubError("NATIVE_ARTIFACTS", "Each native artifact must identify its actual regular output file.", 503)
            raw = Path(artifact["path"])
            if not raw.is_absolute():
                raw = output_dir / raw
            if raw.is_symlink() or not raw.is_file() or not raw.resolve().is_relative_to(output_dir.resolve()):
                raise GovHubError("NATIVE_ARTIFACT_PATH", "A native output must remain inside this operation's private output directory.", 409)
            name = raw.name
            original = originals.get((name, artifact.get("sha256")))
            if original:
                from govhub import file_digest
                actual_sha, actual_size = file_digest(raw)
                if (actual_sha, actual_size) != (original["sha256"], original["size"]):
                    raise GovHubError("NATIVE_ARTIFACT_CHANGED", "The replayed original artifact no longer matches its retained source.", 409)
                item = self._file_row(db, original["file_id"])
                self._verify_file(item)
            else:
                if name in used:
                    name = f"{len(used) + 1:04d}-" + name
                used.add(name)
                item = self._register(db, raw, name, value["author"], "Extract", "Native " + str(artifact.get("role", "artifact")) + " from " + value["id"], owner_kind="operation", owner_id=value["id"], expected_sha=artifact.get("sha256"))
                originals[(raw.name, item["sha256"])] = {"file_id": item["id"], "sha256": item["sha256"], "size": item["bytes"]}
            retained.append({"role": artifact.get("role", "artifact"), "file": item,
                             "native": {**{key: val for key, val in artifact.items() if key != "path"},
                                        "original_filename": raw.name}})
        envelope = {"format": "govhub-native-operation/1", "operation_id": value["id"], "plan_revision": value["plan_revision"], "source_snapshot_id": value["source_snapshot_id"], "source_snapshot_sha256": value["source_snapshot_sha256"], "environment_id": value["environment_id"], "provider_environment_id": value["profile"]["config"]["environment_id"], "config_sha256": value["profile"]["revision"], "actual_started_at": value["actual_started_at"], "actual_finished_at": value["actual_finished_at"], "result": native_result, "retained_artifacts": retained}
        name = "native-result.json" if "native-result.json" not in used else f"native-result-{len(used) + 1:04d}.json"
        path = output_dir / name
        path.write_text(packed(envelope) + "\n", encoding="utf-8")
        os.chmod(path, 0o600)
        capture = self._register(db, path, name, value["author"], "Evidence", "Original native operation result", owner_kind="operation", owner_id=value["id"])
        return capture, retained

    def _run_operation(self, value):
        from govhub import GovHubError, now
        output_dir = self.root / "native-operations" / value["id"]
        output_dir.mkdir(parents=True, mode=0o700, exist_ok=True)
        if output_dir.is_symlink() or not output_dir.resolve().is_relative_to(self.root):
            raise GovHubError("NATIVE_DIRECTORY", "The operation directory must remain inside its private workspace.", 409)
        native_result = None
        try:
            if value["type"] in {"STATIC_STAGE", "STATIC_PUBLISH", "STATIC_ROLLBACK"}:
                from static_releases.native import run_operation
                return run_operation(self, value)
            if value["type"] == "VISITOR_CAPTURE":
                from visitor_journeys.workspace import run_operation
                return run_operation(self, value)
            source_paths = self._operation_sources(value, output_dir)
            if self._cancelled(value["id"]):
                native_result = {"status": "CANCELLED", "artifacts": [], "safe_to_retry": True, "observations": {"stage": "before_native"}}
            else:
                native = self._native()
                with self.connect(write=True) as db:
                    current = self._operation(db, value["id"])
                    current["actual_started_at"] = current.get("actual_started_at") or now()
                    current["native_attempted"] = current["type"] not in {"CAPTURE", "CONTENT_STATUS", "CONTENT_RECEIVE", "PACKAGE_EXPORT", "PACKAGE_PREVIEW", "PACKAGE_STATUS"}
                    current["progress"] = dict(current["progress"], stage="NATIVE", detail="Executing the exact configured native action")
                    value = self._write_operation(db, current, current["author"], "Native action started", {"source_kind": current["profile"]["config"]["source_kind"], "config_sha256": current["profile"]["revision"]})
                checkpoint = lambda data: self._native_checkpoint(value["id"], data)
                cancelled = lambda: self._cancelled(value["id"])
                if value["type"] == "CAPTURE":
                    native_result = native.capture(value["profile"]["config"], {"operation_id": value["id"], "environment_id": value["environment_id"], "output_dir": str(output_dir), "checkpoint": source_paths["checkpoint"], "target_fingerprint": value["target_fingerprint"], "workspace_relocations": source_paths["workspace_relocations"], "runtime_bindings": value.get("runtime_bindings"), "castor_command_receipt": value.get("castor_command_receipt")}, checkpoint=checkpoint, cancelled=cancelled)
                else:
                    operation = dict(value, resume_checkpoint=source_paths["checkpoint"])
                    native_result = native.execute(operation, value["profile"]["config"], source_paths, checkpoint=checkpoint, cancelled=cancelled)
            if not isinstance(native_result, dict) or native_result.get("status") not in {"COMPLETE", "FAILED", "WAITING_NATIVE", "CANCELLED"}:
                raise GovHubError("NATIVE_RESULT", "The native adapter did not return a recognized durable result.", 503)
            with self.connect(write=True) as db:
                current = self._operation(db, value["id"])
                current["actual_finished_at"] = now()
                current["native_result"] = native_result
                capture, artifacts = self._capture_result_files(db, current, native_result, output_dir)
                current["native_capture_file_id"] = capture["id"]
                retained = {(item["file"]["id"], item["role"]): item
                            for item in current.get("retained_artifacts", [])}
                retained.update({(item["file"]["id"], item["role"]): item for item in artifacts})
                current["retained_artifacts"] = list(retained.values())
                if native_result.get("checkpoint"):
                    current["checkpoint"] = native_result["checkpoint"]
                if native_result.get("resume_checkpoint"):
                    current["resume_checkpoint"] = native_result["resume_checkpoint"]
                if native_result.get("safe_to_retry"):
                    current["native_attempted"] = False
                status = native_result["status"]
                needs_observation = current["type"] not in {"CAPTURE", "PREVIEW", "BACKUP_CREATE", "BACKUP_DOWNLOAD"}
                current["state"] = "WAITING_NATIVE" if status == "COMPLETE" and needs_observation else status
                resume = current.get("resume_checkpoint") or {}
                if status == "WAITING_NATIVE" and self._native().can_poll(resume) and not current.get("cancel_requested"):
                    delay = native_result.get("poll_after_seconds", 5)
                    delay = max(5, min(delay, 3600)) if type(delay) is int else 5
                    current["next_poll_at"] = (datetime.now(timezone.utc) + timedelta(seconds=delay)).isoformat(timespec="microseconds").replace("+00:00", "Z")
                else:
                    current["next_poll_at"] = None
                current["progress"] = {"completed": 1 if status == "COMPLETE" else 0, "total": 1,
                    "stage": "OBSERVE_RESULT" if status == "COMPLETE" and needs_observation else status,
                    "detail": "Native action complete; attach its actual observed result inventory" if status == "COMPLETE" and needs_observation else "Native source artifacts retained" if status == "COMPLETE" else str(native_result.get("message") or native_result.get("error") or "Native operation state retained")[:8000]}
                self._content_native_completion(current, native_result)
                current["error"] = native_result.get("error") or (native_result.get("message") if status in {"FAILED", "WAITING_NATIVE"} else None)
                self._write_operation(db, current, current["author"], "Native action result retained", {"native_status": status, "capture_file_id": capture["id"], "artifacts": len(artifacts)})
        except Exception as exc:
            with self.connect(write=True) as db:
                current = self._operation(db, value["id"])
                current["state"] = ("WAITING_NATIVE" if current.get("native_attempted") and not (current.get("checkpoint") or {}).get("safe_to_retry")
                    else "CANCELLED" if getattr(exc, "code", None) == "STATIC_CANCELLED"
                    else "PAUSED" if self._worker_stop.is_set() else "FAILED")
                current["error"] = {"code": getattr(exc, "code", type(exc).__name__), "message": str(exc)[:8000]}
                current["progress"] = dict(current["progress"], stage="RECONCILE_NATIVE" if current["state"] == "WAITING_NATIVE" else current["state"], detail=str(exc)[:8000])
                self._write_operation(db, current, current["author"], "Native operation stopped with retained checkpoint", current["error"])

    def _worker_loop(self):
        try:
            while not self._worker_stop.is_set():
                self._worker_wake.clear()
                value = None
                with self._native_storage_lease() as available:
                    if available:
                        value = self._claim_next()
                        if value:
                            self._run_operation(value)
                if value is None:
                    self._worker_wake.wait(1.0)
        finally:
            if self._worker_lock is not None:
                fcntl.flock(self._worker_lock, fcntl.LOCK_UN)
                os.close(self._worker_lock)
                self._worker_lock = None

    def start_worker(self):
        from govhub import GovHubError
        with self._worker_mutex:
            if self._worker and self._worker.is_alive():
                return self._worker
            path = self.root / "native-worker.lock"
            descriptor = os.open(path, os.O_CREAT | os.O_RDWR | os.O_NOFOLLOW, 0o600)
            try:
                fcntl.flock(descriptor, fcntl.LOCK_EX | fcntl.LOCK_NB)
            except BlockingIOError as exc:
                os.close(descriptor)
                raise GovHubError("WORKER_OWNED", "Another process owns this workspace's native worker.", 409) from exc
            self._worker_lock = descriptor
            self._worker_stop.clear()
            with self.connect(write=True) as db:
                for row in db.execute("SELECT data FROM govhub_operations WHERE state='RUNNING'").fetchall():
                    value = json.loads(row[0])
                    value["state"] = "QUEUED" if value["type"] == "CAPTURE" or value.get("resume_checkpoint") else "WAITING_NATIVE" if value.get("native_attempted") else "PAUSED"
                    value["progress"] = dict(value["progress"], stage="RESTART_RECOVERY", detail="Prior native checkpoint recovered after process restart")
                    self._write_operation(db, value, value["author"], "Native operation recovered after restart")
            self._worker = threading.Thread(target=self._worker_loop, name="govhub-native-worker", daemon=True)
            self._worker.start()
            return self._worker

    def stop_worker(self):
        self._worker_stop.set()
        self._worker_wake.set()
        if self._worker and self._worker is not threading.current_thread():
            self._worker.join(timeout=10)

    def _operations_observe(self, payload, actor):
        from govhub import GovHubError, digest, instant, json_bytes, packed, text
        with self.connect(write=True) as db:
            value = self._operation(db, payload.get("operation_id"))
            self._expected(value, payload)
            if value["state"] in {"QUEUED", "RUNNING"} or value["type"] in {"CAPTURE", "PREVIEW", "BACKUP_CREATE", "BACKUP_DOWNLOAD"}:
                raise GovHubError("OPERATION_STATE", "Attach an observed result after the selected restore operation's native action has completed.", 409)
            file_id = payload.get("capture_file_id") or value.get("native_capture_file_id")
            item = self._file_row(db, file_id)
            if item["bytes"] > 32 * 1024 * 1024:
                raise GovHubError("CAPTURE_SIZE", "The native result envelope may be at most 32 MiB.", 413)
            capture = json_bytes(self._verify_file(item).read_bytes())
            if not isinstance(capture, dict) or capture.get("format") != "govhub-native-operation/1":
                raise GovHubError("NATIVE_CAPTURE", "Select the retained govhub-native-operation/1 execution capture.")
            expected = {"operation_id": value["id"], "plan_revision": value["plan_revision"], "source_snapshot_id": value["source_snapshot_id"], "source_snapshot_sha256": value["source_snapshot_sha256"], "environment_id": value["environment_id"], "provider_environment_id": value["profile"]["config"]["environment_id"], "config_sha256": value["profile"]["revision"]}
            if any(capture.get(key) != item for key, item in expected.items()):
                raise GovHubError("NATIVE_CAPTURE_IDENTITY", "The execution capture belongs to a different operation, source revision, or native target.", 409)
            if not isinstance(capture.get("result"), dict) or capture["result"].get("status") != "COMPLETE":
                raise GovHubError("NATIVE_CAPTURE_STATUS", "The selected original execution capture does not record a completed native action.", 409)
            start = instant(payload.get("actual_started_at") or capture.get("actual_started_at", ""), True)
            end = instant(payload.get("actual_finished_at") or capture.get("actual_finished_at", ""), True)
            if end < start:
                raise GovHubError("EXECUTION_TIME", "The actual completion must follow the native action's start.")
            for key, expected_time in (("actual_started_at", start), ("actual_finished_at", end)):
                if capture.get(key) and instant(capture[key], True) != expected_time:
                    raise GovHubError("EXECUTION_TIME_SOURCE", "The entered actual time differs from the retained execution capture.", 409)
            restored = self._get(db, "snapshot", payload.get("restored_snapshot_id"))
            if restored["kind"] != "RESTORED":
                raise GovHubError("RESTORED_SOURCE", "Choose the actual RESTORED result inventory.")
            self._verify_snapshot(db, restored)
            source = self._get(db, "snapshot", value["source_snapshot_id"])
            self._verify_snapshot(db, source)
            cohort = set(value.get("agency_ids", value["plan"]["agency_ids"]))
            before = {row["agency_id"]: row for row in source["rows"] if row["agency_id"] in cohort}
            after = {row["agency_id"]: row for row in restored["rows"] if row["agency_id"] in cohort}
            summary = self.auditor.audit(before, after, {}, len(cohort))
            missing = sorted(cohort - set(before) - set(after))
            status = "PASS" if summary["status"] == "PASS" and not missing else "FAIL"
            observation = self._object(db, "operation_observation", {"operation_id": value["id"], "capture_file_id": item["id"], "capture_sha256": item["sha256"], "restored_snapshot_id": restored["id"], "restored_snapshot_sha256": restored["sha256"], "actual_started_at": start, "actual_finished_at": end, "duration_seconds": (datetime.fromisoformat(end.replace("Z", "+00:00")) - datetime.fromisoformat(start.replace("Z", "+00:00"))).total_seconds(), "status": status, "summary": summary, "missing_declared_ids": missing, "notes": text(payload.get("notes", ""), 16000)}, parent=value["id"], actor=actor["name"])
            value.update(state="COMPLETE" if status == "PASS" else "FAILED", result_snapshot_id=restored["id"], observation_id=observation["id"], native_capture_file_id=item["id"], actual_started_at=start, actual_finished_at=end, error=None if status == "PASS" else {"code": "RESTORED_DIFFERENCES", "message": "The actual observed result differs from the selected original source; inspect the per-site findings."})
            value["progress"] = {"completed": len(cohort) if status == "PASS" else len(set(before) & set(after)), "total": len(cohort), "stage": "COMPLETE" if status == "PASS" else "RECONCILE_RESULT", "detail": "Original native result inventory reconciled" if status == "PASS" else "Correct the actual result differences and retain a new observed inventory"}
            value = self._write_operation(db, value, actor, "Actual native result inventory reconciled", {"status": status, "observation_id": observation["id"]})
            return {"operation": value, "observation": observation}

    def _operations_compare(self, payload):
        with self.connect(snapshot=True) as db:
            before = self._operation(db, payload.get("before_id"))
            after = self._operation(db, payload.get("after_id"))
            a = self._get(db, "snapshot", before["result_snapshot_id"]) if before.get("result_snapshot_id") else before.get("source_snapshot")
            b = self._get(db, "snapshot", after["result_snapshot_id"]) if after.get("result_snapshot_id") else after.get("source_snapshot")
            return {"before": self._operation_summary(before), "after": self._operation_summary(after), "before_basis": "result" if before.get("result_snapshot_id") else "source", "after_basis": "result" if after.get("result_snapshot_id") else "source", "comparison": self._compare_rows(a["rows"] if a else [], b["rows"] if b else [])}

"""Lagoon native project, backup and active/standby operations for GovHub.

The selected original Lagoon CLI owns authentication and provider execution.
CLI raw output is decoded GraphQL data, not an HTTP response envelope.
Provider contract: uselagoon/lagoon 7ffbadcf159988952a9c7dddde3329935bd279ec.
CLI contract: uselagoon/lagoon-cli 38a7b36e6b1f13cabcc01a5009ddd01f51f2ca29.
"""
from __future__ import annotations

import hashlib
import json
import os
from pathlib import Path
import re
import tempfile
from urllib.parse import urlsplit, urlunsplit

VERSION = "govhub-lagoon/v1"
ROUTE_FIELDS = "id domain service source type primary environment { id name }"
PROJECT_FIELDS = ("id name gitUrl productionEnvironment standbyProductionEnvironment productionRoutes standbyRoutes "
                  "apiRoutes { " + ROUTE_FIELDS + " }")
TASK_FIELDS = "id name taskName status created started completed service remoteId environment { id name }"
BACKUP_FIELDS = "id backupId source created deleted"
ENVIRONMENT_FIELDS = """id name environmentType deployType deployBaseRef deployHeadRef
route routes created updated deleted
services { id name type replicas abandoned }
volumes { id name storageType type kibRequested kibUsed created updated abandoned }"""
SUCCEEDED = {"COMPLETE", "SUCCEEDED", "SUCCESSFUL"}
FAILED = {"FAILED", "ERROR", "CANCELLED"}
SCOPE = {
    "project": "one explicitly selected native project",
    "environments": "all authorized current environments; includeDeleted:false",
    "backups": "all authorized backups returned by the native resolver; no limit; original deleted values retained",
    "backup_filter": "includeDeleted:false is sent, but this pinned native resolver does not apply that argument",
    "tasks": "all tasks visible to the selected native account; no limit",
    "pagination": "native arrays have no cursor; omitted limits retain the full permitted arrays",
    "transport": "original Lagoon CLI decoded GraphQL data plus exact command/stdout/stderr/exit",
}


def provider_schema():
    def f(name, label, required=False, **extra):
        return {"name": name, "label": label, "type": "text", "required": required, **extra}
    return {"value": "lagoon", "label": "Lagoon native CLI", "fields": [
        f("environment_id", "Exact Lagoon environment ID", True,
          help="The native integer ID, retained as text in the operating environment record."),
        f("project_name", "Exact Lagoon project name", True),
        f("lagoon_path", "Existing Lagoon executable", True,
          placeholder="/usr/local/bin/lagoon"),
        f("lagoon_instance", "Existing configured Lagoon instance", True,
          help="The explicit native --lagoon selection; authentication stays on its host."),
        f("lagoon_config_file", "Existing native configuration file",
          help="Optional absolute YAML path. The operator uses it without reading its credential values."),
        f("site_root", "Native CLI working directory", True,
          help="An existing absolute directory on the configured native host."),
        f("expected_production_routes", "Reviewed production route URLs", type="textarea", max_length=64000,
          help="Complete comma- or newline-separated HTTP(S) route URLs for an active/standby switch."),
        f("expected_standby_routes", "Reviewed standby route URLs", type="textarea", max_length=64000,
          help="Complete comma- or newline-separated standby route URLs, retained separately from their native order."),
        f("lagoon_backup_id", "Selected original backupId",
          help="The opaque backupId from the native inventory, distinct from its integer row ID."),
        {"name": "timeout_seconds", "label": "Native command timeout (seconds)",
         "type": "integer", "default": 120, "minimum": 10, "maximum": 7200},
        {"name": "max_artifact_bytes", "label": "Maximum individual artifact bytes",
         "type": "integer", "default": 1073741824, "minimum": 1048576},
    ]}


def profile(config):
    allowed = {"source_kind", "target_fingerprint", *(f["name"] for f in provider_schema()["fields"])}
    unknown = set(config) - allowed
    if unknown:
        raise ValueError("Unsupported Lagoon profile fields: " + ", ".join(sorted(unknown)))
    p = dict(config)
    if p.get("source_kind") != "lagoon":
        raise ValueError("Select the Lagoon native profile.")
    if not isinstance(p.get("environment_id"), str) or not re.fullmatch(r"[1-9][0-9]*", p["environment_id"]):
        raise ValueError("Retain the exact positive Lagoon environment ID as text.")
    for key in ("project_name", "lagoon_instance"):
        if not isinstance(p.get(key), str) or not p[key].strip() or "\x00" in p[key]:
            raise ValueError("Set the exact native " + key + ".")
    for key, directory in (("lagoon_path", False), ("site_root", True)):
        path = Path(str(p.get(key, ""))).expanduser()
        if not path.is_absolute() or not (path.is_dir() if directory else path.is_file()):
            raise ValueError("Select the existing absolute native " + key + ".")
        if not directory and not os.access(path, os.X_OK):
            raise ValueError("The configured Lagoon executable is not executable.")
        p[key] = str(path.resolve())
    if p.get("lagoon_config_file"):
        path = Path(p["lagoon_config_file"]).expanduser()
        if not path.is_absolute() or not path.is_file():
            raise ValueError("Select the existing absolute native YAML configuration path.")
        p["lagoon_config_file"] = str(path.resolve())
    p["timeout_seconds"] = int(p.get("timeout_seconds") or 120)
    p["max_artifact_bytes"] = int(p.get("max_artifact_bytes") or 1073741824)
    if not 10 <= p["timeout_seconds"] <= 7200 or p["max_artifact_bytes"] < 1048576:
        raise ValueError("Native timeout or artifact limit is out of range.")
    backup = p.get("lagoon_backup_id")
    if backup is not None and (not isinstance(backup, str) or "\x00" in backup):
        raise ValueError("The native backupId must retain its original string value.")
    for name in ("expected_production_routes", "expected_standby_routes"):
        if p.get(name):
            _route_members(p[name])
    return p


def provider_context(p):
    return {"source_kind": "lagoon", "lagoon_instance": p["lagoon_instance"],
            "project_name": p["project_name"], "environment_id": p["environment_id"],
            **({"project_id": p["native_project_id"]} if p.get("native_project_id") else {}),
            **({"environment_name": p["native_environment_name"]} if p.get("native_environment_name") else {})}


def actions_for(operation_type):
    if operation_type == "CAPTURE":
        return [{"value": "lagoon-capture", "label": "Capture complete native project and environment inventory"}]
    if operation_type == "BACKUP_DOWNLOAD":
        return [{"value": "lagoon-backup-download", "label": "Prepare and download the selected native backup"}]
    if operation_type in {"REHEARSAL", "CUTOVER", "ROLLBACK"}:
        return [{"value": "lagoon-switch-active-standby",
                 "label": "Switch the reviewed project to the selected standby environment",
                 "required_profile_fields": ["expected_production_routes", "expected_standby_routes"]}]
    return []


def pollable(resume):
    value = resume.get("native_poll") or {}
    return (resume.get("phase") == "accepted" and value.get("provider") == "lagoon"
            and value.get("kind") in {"task", "backup"} and bool(value.get("id")))


def _api():
    import native_adapter
    return native_adapter


def _q(value):
    return json.dumps(value, ensure_ascii=True, separators=(",", ":"), allow_nan=False)


def _make_safe(value):
    """The native makeSafe helper operates on lowercased JavaScript UTF-16 units."""
    if not isinstance(value, str):
        raise ValueError("The native environment must retain its original name.")
    encoded = value.lower().encode("utf-16-le", errors="surrogatepass")
    units = [int.from_bytes(encoded[i:i + 2], "little") for i in range(0, len(encoded), 2)]
    return "".join(chr(unit) if 48 <= unit <= 57 or 97 <= unit <= 122 or unit == 45 else "-" for unit in units)


def _environment_for(project, selector):
    matches = [environment for environment in project["environments"]
               if selector in {environment.get("name"), _make_safe(environment.get("name"))}]
    if len(matches) != 1:
        raise ValueError("The native active/standby selector does not identify one unique current environment.")
    return matches[0]


def _route_members(value):
    if not isinstance(value, str):
        raise ValueError("Retain the reviewed route URLs as text.")
    if value.strip() == "[]":
        return []
    result = []
    for entry in re.split(r"[\r\n,]+", value):
        entry = entry.strip()
        if not entry:
            continue
        parsed = urlsplit(entry)
        if (parsed.scheme not in {"http", "https"} or not parsed.hostname
                or parsed.username or parsed.password or parsed.query or parsed.fragment
                or parsed.path not in {"", "/"}):
            raise ValueError("Each reviewed native route must be an HTTP(S) origin without credentials, query or fragment.")
        result.append(urlunsplit((parsed.scheme, parsed.netloc.lower(), "", "", "")))
    if len(result) != len(set(result)):
        raise ValueError("The reviewed route population repeats an origin.")
    return sorted(result)


def _api_route_bindings(project):
    result = {}
    for route in project["apiRoutes"]:
        native_id = route.get("id")
        if not isinstance(native_id, int) or isinstance(native_id, bool) or native_id in result:
            raise ValueError("The complete native API route population requires unique original integer IDs.")
        result[native_id] = {"id": native_id, "domain": route.get("domain"), "service": route.get("service"),
            "source": route.get("source"), "type": route.get("type"),
            "environment_id": (route.get("environment") or {}).get("id")}
    return result


def _prefix(p):
    result = [p["lagoon_path"], "--skip-update-check", "--lagoon", p["lagoon_instance"]]
    if p.get("lagoon_config_file"):
        result += ["--config-file", p["lagoon_config_file"]]
    return result


def _add_once(s, path, role, **extra):
    path = Path(s.private_path(str(path)))
    actual = _api()._file(path, role)
    for retained in s.artifacts:
        if retained["path"] == actual["path"] and retained["role"] == role:
            if (retained["sha256"], retained["size"]) != (actual["sha256"], actual["size"]):
                raise ValueError("An original native artifact changed during this operation.")
            return retained
    return s.add(path, role, **extra)


def _retain_command(s, label, record=None):
    path = s.out / (label + ".command.json")
    if path.is_file():
        record = s.read_private_json(path)
        _add_once(s, path, "native_command", format="lagoon-cli")
    if not record:
        return
    phase = record.get("phase")
    settled = phase in {"complete", "not_started"} or (
        phase == "interrupted" and record.get("owned_process_reaped") is True)
    if not settled:
        return
    for key in ("stdout", "stderr"):
        saved = record.get(key)
        if not saved:
            continue
        actual = _api()._file(s.private_path(saved["path"]), key)
        if (actual["sha256"], actual["size"]) != (saved["sha256"], saved["size"]):
            raise ValueError("The retained original native command output changed.")
        role = ("provider_cli_data" if phase == "complete" and record.get("returncode") == 0
                else "provider_cli_output") if key == "stdout" else "native_stderr"
        _add_once(s, actual["path"], role, format="lagoon-cli",
                  provider_context=provider_context(s.p), native_phase=phase,
                  native_returncode=record.get("returncode"))


def _raw(s, label, document, mutating=False):
    try:
        record = s.command(label, _prefix(s.p) + ["raw", "--raw", document], mutating=mutating)
    except BaseException as error:
        try:
            _retain_command(s, label)
        except Exception as retention_error:
            s.event({"kind": "native_artifact_retention_error", "label": label,
                     "message": str(retention_error)})
            if hasattr(error, "add_note"):
                error.add_note("Original artifact registration: " + str(retention_error))
        raise
    _retain_command(s, label, record)
    path = Path(record["stdout"]["path"])
    if path.stat().st_size > min(s.p["max_artifact_bytes"], 32 * 1024 * 1024):
        raise ValueError("The native GraphQL data exceeds the metadata intake size.")
    data = json.loads(path.read_bytes())
    if not isinstance(data, dict):
        raise ValueError("The original Lagoon CLI must return a decoded GraphQL data object.")
    return data, record


def _fresh(s, purpose, document):
    index = int(s.state.get("observation_index", 0)) + 1
    s.state["observation_index"] = index
    s.save_state()
    return _raw(s, purpose + "-" + str(index).zfill(6), document)


def inventory_query(p):
    return ("query { lagoonVersion projectByName(name:" + _q(p["project_name"]) + ") { "
            + PROJECT_FIELDS + " environments(includeDeleted:false) { "
            + ENVIRONMENT_FIELDS + " backups(includeDeleted:false) { " + BACKUP_FIELDS
            + " } tasks { " + TASK_FIELDS + " } } } }")


def _inventory(s, label, fresh=False):
    data, record = (_fresh(s, label, inventory_query(s.p)) if fresh
                    else _raw(s, label, inventory_query(s.p)))
    project = data.get("projectByName")
    if not isinstance(project, dict) or project.get("name") != s.p["project_name"]:
        raise ValueError("The native project differs from the selected original project.")
    if not isinstance(project.get("id"), int) or isinstance(project["id"], bool):
        raise ValueError("The native project did not return its integer identity.")
    if not isinstance(project.get("apiRoutes"), list):
        raise ValueError("The native project did not return its complete permitted API route array.")
    environments = project.get("environments")
    if not isinstance(environments, list):
        raise ValueError("The native project did not return its complete permitted environment array.")
    ids = []
    for environment in environments:
        if not isinstance(environment, dict) or not isinstance(environment.get("id"), int):
            raise ValueError("A native environment is missing its original identity.")
        ids.append(environment["id"])
        for key in ("services", "volumes", "backups", "tasks"):
            if not isinstance(environment.get(key), list):
                raise ValueError("The original permitted " + key + " array is unavailable.")
    if len(ids) != len(set(ids)):
        raise ValueError("The native project repeats an environment identity.")
    matches = [e for e in environments if str(e["id"]) == s.p["environment_id"]]
    if len(matches) != 1:
        raise ValueError("The selected environment is not in this project's current permitted set.")
    selected = matches[0]
    s.p.update(native_project_id=project["id"], native_environment_name=selected.get("name"))
    return {"project": project, "selected_environment": selected,
            "lagoon_version": data.get("lagoonVersion"), "record": record}


def _state(s, supplied):
    path = s.out / "native-state.json"
    value = s.read_private_json(path) if path.exists() else (supplied or {})
    value = value.get("resume_checkpoint", value.get("state", value))
    s.state = dict(s.resolve_private(value))


def _intent(s, value):
    fingerprint = _api()._digest(value)
    if s.state.get("intent_sha256") and s.state["intent_sha256"] != fingerprint:
        raise ValueError("This continuation belongs to a different native target, source or operation.")
    if not s.state.get("intent_sha256"):
        s.state.update(intent_sha256=fingerprint, intent=value, phase="prepared",
                       mutation_started=False, output_dir=str(s.out))
        s.save_state()


def _summary(inventory):
    environments = inventory["project"]["environments"]
    return {"project_id": inventory["project"]["id"],
            "selected_environment_id": inventory["selected_environment"]["id"],
            "environments": len(environments),
            "services": sum(len(e["services"]) for e in environments),
            "volumes": sum(len(e["volumes"]) for e in environments),
            "backups": sum(len(e["backups"]) for e in environments),
            "api_routes": len(inventory["project"]["apiRoutes"]),
            "tasks": sum(len(e["tasks"]) for e in environments)}


def discover_capabilities(config):
    result = {"ready": False, "configuration": {}, "current_config": {}, "actions": []}
    try:
        p = profile(config)
        result.update(configuration=p, current_config=p)
        with tempfile.TemporaryDirectory(prefix="govhub-lagoon-capabilities-") as folder:
            s = _api().Session(p, folder)
            inventory = _inventory(s, "capability-inventory")
            target = provider_context(p)
            result.update(ready=True, native_status={**_summary(inventory),
                "lagoon_version": inventory["lagoon_version"],
                "production_environment": inventory["project"].get("productionEnvironment"),
                "standby_environment": inventory["project"].get("standbyProductionEnvironment"),
                "source_scope": SCOPE}, provider_context=target,
                target_fingerprint=_api()._digest(target),
                actions=actions_for("CAPTURE") + actions_for("BACKUP_DOWNLOAD") + actions_for("CUTOVER"),
                observed_at=_api()._now())
    except Exception as exc:
        result["message"] = str(exc)
    return result


def capture(config, context, checkpoint=None, cancelled=None):
    p = profile(config)
    s = _api().Session(p, context["output_dir"], checkpoint, cancelled, context.get("workspace_relocations"))
    try:
        _state(s, context.get("checkpoint"))
        inventory = _inventory(s, "project-inventory")
        expected = context.get("target_fingerprint") or config.get("target_fingerprint")
        if expected and expected != _api()._digest(provider_context(p)):
            raise ValueError("The captured native target differs from its reviewed fingerprint.")
        _intent(s, {"action": "lagoon-capture", "target": provider_context(p),
                    "operation_id": context.get("operation_id")})
        manifest = {"schema": "lagoon-source-inventory/v1", "captured_at": _api()._now(),
                    "provider_context": provider_context(p), "scope": SCOPE,
                    "lagoon_version": inventory["lagoon_version"],
                    "project": inventory["project"], "selected_environment_id": int(p["environment_id"]),
                    "original_cli_stdout": inventory["record"]["stdout"]}
        path = s.out / "lagoon-source-inventory.json"
        if path.exists():
            prior = s.read_private_json(path)
            if prior.get("original_cli_stdout", {}).get("sha256") != inventory["record"]["stdout"]["sha256"]:
                raise ValueError("The original native inventory changed.")
        else:
            _api()._atomic(path, manifest)
        s.add(path, "configuration_export", format="lagoon-source-inventory",
              provider_context=provider_context(p))
        observations = {"native_action": "lagoon-capture", **_summary(inventory), "scope": SCOPE}
        s.state.update(phase="completed", observations=observations)
        s.save_state()
        return s.result("COMPLETE", observations)
    except _api().NativeCancelled as exc:
        return s.result("CANCELLED", message=str(exc))
    except _api().NativeWaiting as exc:
        return s.result("WAITING_NATIVE", message=str(exc))
    except Exception as exc:
        return s.result("FAILED", message=str(exc))


def _backup_status(s, backup_id):
    query = ("query { environmentById(id:" + str(int(s.p["environment_id"])) + ") { id project { id } "
             "backups(includeDeleted:false) { " + BACKUP_FIELDS
             + " restore { id backupId status created restoreSize } } } }")
    data, _ = _fresh(s, "backup-status", query)
    environment = data.get("environmentById") or {}
    if environment.get("id") != int(s.p["environment_id"]) or (environment.get("project") or {}).get("id") != s.p["native_project_id"]:
        raise ValueError("Backup observation returned a different project or environment.")
    backups = environment.get("backups")
    if not isinstance(backups, list):
        raise ValueError("The native backup observation is incomplete.")
    matches = [b for b in backups if b.get("backupId") == backup_id]
    if len(matches) != 1:
        raise _api().NativeWaiting("The original selected backup is absent from the current native observation.")
    restore = matches[0].get("restore")
    if restore is not None and (not isinstance(restore, dict) or restore.get("backupId") != backup_id):
        raise ValueError("The native restore record belongs to a different original backup.")
    return matches[0], restore


def _completed_download(s):
    """Recover retained bytes before consulting a locator that may have expired."""
    retained = s.state.get("download")
    request_identity = s.state.get("download_request")
    if not retained and request_identity:
        record_path = s.out / (request_identity["label"] + ".request.json")
        if record_path.is_file():
            result = s.read_private_json(record_path)
            if result.get("method") != "GET" or result.get("requested_url_sha256") != request_identity["url_sha256"]:
                raise ValueError("The original download record belongs to a different native request.")
            if result.get("status") == 200:
                retained = result["response"]
    if not retained:
        return None
    if not request_identity or request_identity.get("backup_id") != s.p.get("lagoon_backup_id"):
        raise ValueError("The retained backup has no matching original download intent.")
    if request_identity.get("restore_id") != s.state.get("restore_id"):
        raise ValueError("The retained backup belongs to a different native restore row.")
    actual = _api()._file(s.private_path(retained["path"]), "backup")
    if (actual["sha256"], actual["size"]) != (retained["sha256"], retained["size"]) or not actual["size"]:
        raise ValueError("The completed original backup bytes changed or are empty.")
    declared = request_identity["restore"].get("restoreSize")
    if isinstance(declared, (int, float)) and not isinstance(declared, bool) and declared > 0 and actual["size"] != declared:
        raise ValueError("The downloaded native backup size differs from the provider's byte count.")
    s.state["download"] = actual
    return actual


def _finish_download(s, downloaded):
    request_identity = s.state["download_request"]
    backup_id = request_identity["backup_id"]
    request_path = s.out / (request_identity["label"] + ".request.json")
    request_record = s.read_private_json(request_path)
    if (request_record.get("method") != "GET" or request_record.get("status") != 200
            or request_record.get("requested_url_sha256") != request_identity["url_sha256"]
            or ((request_record.get("response") or {}).get("sha256"),
                (request_record.get("response") or {}).get("size")) != (downloaded["sha256"], downloaded["size"])):
        raise ValueError("The completed backup has no matching original download request record.")
    _add_once(s, request_path, "native_download_request", format="lagoon-backup-download")
    locator = request_identity["locator_cli_stdout"]
    locator_path = Path(s.private_path(locator["path"]))
    actual_locator = _api()._file(locator_path, "provider_cli_data")
    if (actual_locator["sha256"], actual_locator["size"]) != (locator["sha256"], locator["size"]):
        raise ValueError("The original backup locator command output changed.")
    if locator_path.parent != s.out or locator_path.suffix != ".stdout":
        raise ValueError("The retained locator must belong to this original native operation.")
    _retain_command(s, locator_path.name[:-len(".stdout")])
    _add_once(s, locator_path, "provider_cli_data", format="lagoon-cli",
              provider_context=provider_context(s.p))
    _add_once(s, downloaded["path"], "backup", format="lagoon-backup-download",
          backup_id=backup_id, restore_id=s.state["restore_id"], provider_context=provider_context(s.p))
    manifest = {"schema": "lagoon-backup-download/v1", "provider_context": provider_context(s.p),
                "backup": s.state["backup_identity"], "restore": request_identity["restore"],
                "download": downloaded, "locator_cli_stdout": request_identity["locator_cli_stdout"],
                "meaning": "Original backup downloaded for receiving; application restoration is a separate native operation."}
    path = s.out / "lagoon-backup-download.json"
    if path.exists():
        previous = s.read_private_json(path)
        if previous.get("download", {}).get("sha256") != downloaded["sha256"]:
            raise ValueError("The original backup manifest names different retained bytes.")
    else:
        _api()._atomic(path, manifest)
    _add_once(s, path, "backup_manifest", format="lagoon-backup-download", provider_context=provider_context(s.p))
    observations = {"native_action": "lagoon-backup-download", "backup_id": backup_id,
                    "restore_id": s.state["restore_id"], "downloaded_sha256": downloaded["sha256"],
                    "downloaded_bytes": downloaded["size"], "application_restore_performed": False}
    s.state.update(phase="completed", native_poll=None, observations=observations)
    s.save_state()
    return s.result("COMPLETE", observations)


def _download_backup(s, inventory):
    backup_id = s.p.get("lagoon_backup_id")
    if not backup_id:
        raise ValueError("Select the original opaque backupId in this native profile.")
    original = [b for b in inventory["selected_environment"]["backups"] if b.get("backupId") == backup_id]
    if len(original) != 1:
        raise ValueError("The selected backupId is not in the original environment inventory.")
    s.state.setdefault("backup_identity", {**original[0], "environment_id": s.p["environment_id"]})
    downloaded = _completed_download(s)
    if downloaded:
        return _finish_download(s, downloaded)
    backup, restore = _backup_status(s, backup_id)
    known = s.state.get("restore_id")
    if known and (not restore or restore.get("id") != known):
        s.state.update(phase="reconcile_required", native_poll=None)
        s.save_state()
        raise _api().NativeWaiting("The original restore record is absent or changed. Reconcile that native record; the retained addRestore is not repeated.")
    if not known and restore:
        if not isinstance(restore.get("id"), int) or isinstance(restore["id"], bool):
            raise ValueError("The existing native restore has no valid integer ID.")
        s.state.update(restore_id=restore["id"], restore_origin="existing_native_record")
        known = restore["id"]
        s.save_state()
    if not known:
        mutation = "mutation { addRestore(input:{backupId:" + _q(backup_id) + "}) { id backupId status created } }"
        try:
            data, _ = _raw(s, "prepare-selected-backup", mutation, mutating=True)
            restore = data.get("addRestore")
            if (not isinstance(restore, dict) or not isinstance(restore.get("id"), int)
                    or isinstance(restore["id"], bool) or restore["id"] < 1 or restore.get("backupId") != backup_id):
                raise _api().NativeWaiting("The original backup preparation returned no usable restore identity.")
            s.state.update(restore_id=restore["id"], restore_origin="original_addRestore")
        except (_api().NativeWaiting, ValueError):
            # The provider may have inserted its row before a queue or response error.
            s.state.update(phase="reconcile_required", native_poll=None)
            s.save_state()
            raise _api().NativeWaiting("Reconcile the retained original backup preparation and its native restore row before continuing.")
    s.state["last_restore"] = restore
    status = str((restore or {}).get("status") or "")
    s.state.update(phase="accepted", native_poll={"provider": "lagoon", "kind": "backup", "id": s.state["restore_id"]})
    s.save_state()
    if status.upper() in FAILED:
        s.state.update(phase="failed", native_poll=None)
        s.save_state()
        return s.result("FAILED", {"native_action": "lagoon-backup-download", "restore": restore},
                        "The original native backup preparation returned " + status + ".")
    if status.upper() not in SUCCEEDED:
        return s.result("WAITING_NATIVE", {"native_action": "lagoon-backup-download", "restore": restore},
                        "The original backup preparation remains " + (status or "unreported") + ".")
    query = "query { getBackupDownloadLinkByBackupId(backupId:" + _q(backup_id) + ") }"
    data, locator = _fresh(s, "backup-download-location", query)
    location = data.get("getBackupDownloadLinkByBackupId")
    if not isinstance(location, str) or not location:
        raise _api().NativeWaiting("The original restore has no currently available native download location.")
    attempt = int(s.state.get("download_attempt", 0)) + 1
    label = "selected-backup" if attempt == 1 else "selected-backup-" + str(attempt).zfill(6)
    s.state.update(download_attempt=attempt, download_request={
        "label": label, "url_sha256": hashlib.sha256(location.encode()).hexdigest(),
        "backup_id": backup_id, "restore_id": s.state["restore_id"], "restore": restore,
        "locator_cli_stdout": locator["stdout"]})
    s.save_state()
    result = _api()._http(s, label, location, accept="application/octet-stream", acquia_auth=False)
    if result["status"] != 200:
        _add_once(s, s.out / (label + ".request.json"), "native_download_request", format="lagoon-backup-download")
        _add_once(s, result["response"]["path"], "provider_download_response")
        raise _api().NativeWaiting("The original backup download returned HTTP " + str(result["status"]) + ".")
    downloaded = _completed_download(s)
    if not downloaded:
        raise ValueError("The native download has no complete original response record.")
    return _finish_download(s, downloaded)


def _switch_source(project, selected, p):
    active = _environment_for(project, project.get("productionEnvironment"))
    standby = _environment_for(project, project.get("standbyProductionEnvironment"))
    if active["id"] == standby["id"] or selected["id"] != standby["id"]:
        raise ValueError("The selected target must be this project's distinct current standby environment.")
    services = lambda environment: sorted(item["name"] for item in environment["services"] if not item.get("abandoned"))
    if services(active) != services(standby):
        raise ValueError("The active and standby environments must have the same actual service names.")
    expected = {}
    for role in ("production", "standby"):
        value = p.get("expected_" + role + "_routes")
        if not isinstance(value, str) or not value.strip():
            raise ValueError("Retain the complete reviewed " + role + " route URLs in the profile; use [] for an intentionally empty set.")
        expected[role] = _route_members(value)
    return {"project_id": project["id"],
            "active_selector": project.get("productionEnvironment"), "standby_selector": project.get("standbyProductionEnvironment"),
            "active_environment_id": active["id"], "standby_environment_id": standby["id"],
            "active_name": active["name"], "standby_name": standby["name"],
            "production_routes": project.get("productionRoutes"), "standby_routes": project.get("standbyRoutes"),
            "expected_routes": expected, "services": services(active),
            "api_routes": list(_api_route_bindings(project).values()),
            "task_ids": [task["id"] for task in standby["tasks"] if isinstance(task.get("id"), int)]}


def _route_readback(project, before):
    production = _route_members(project.get("productionRoutes") or "")
    standby = _route_members(project.get("standbyRoutes") or "")
    routes = _api_route_bindings(project)
    expected = {}
    for original in before["api_routes"]:
        route = dict(original)
        if route["environment_id"] is not None and route["type"] in {"ACTIVE", "STANDBY"}:
            route["environment_id"] = before["standby_environment_id"] if route["type"] == "ACTIVE" else before["active_environment_id"]
        expected[route["id"]] = route
    findings = []
    for native_id in sorted(set(routes) | set(expected)):
        if routes.get(native_id) != expected.get(native_id):
            findings.append({"route_id": native_id, "expected": expected.get(native_id), "observed": routes.get(native_id)})
    return {"production_urls": production, "standby_urls": standby,
            "production_matches": production == before["expected_routes"]["production"],
            "standby_matches": standby == before["expected_routes"]["standby"],
            "api_route_count": len(routes), "api_route_findings": findings}


def _selectors_match(project, active_id, standby_id):
    return (_environment_for(project, project.get("productionEnvironment"))["id"] == active_id
            and _environment_for(project, project.get("standbyProductionEnvironment"))["id"] == standby_id)


def _normalize_selectors(s, project, active_id, standby_id, label, task_id=None):
    """Keep equivalent selectors usable by the native next-switch resolver.

    The native completion handler can write original names containing slashes;
    the next native switch resolves selectors using makeSafe(name).
    """
    active = next(environment for environment in project["environments"] if environment["id"] == active_id)
    standby = next(environment for environment in project["environments"] if environment["id"] == standby_id)
    desired = {"productionEnvironment": _make_safe(active["name"]),
               "standbyProductionEnvironment": _make_safe(standby["name"])}
    if not _selectors_match(project, active_id, standby_id):
        raise _api().NativeWaiting("Reconcile this original project's actual active/standby identities before selector continuation.")
    key = label + "_intent"
    intent = s.state.get(key)
    if all(project.get(name) == value for name, value in desired.items()):
        return project, {"required": bool(intent), "native_values_match": True,
                         "patch": desired, "original_task_id": task_id,
                         "reconciled_from_native_readback": bool(intent)}
    if not intent:
        intent = {"project_id": project["id"], "original_task_id": task_id,
                  "active_environment_id": active_id, "standby_environment_id": standby_id,
                  "preimage": {name: project.get(name) for name in desired}, "patch": desired}
        s.state[key] = intent
        s.save_state()
    if intent["patch"] != desired or intent["project_id"] != project["id"] or intent.get("original_task_id") != task_id:
        raise ValueError("The original equivalent-selector correction belongs to a different native switch.")
    document = ("mutation { updateProject(input:{id:" + str(project["id"]) + ",patch:{productionEnvironment:"
                + _q(desired["productionEnvironment"]) + ",standbyProductionEnvironment:"
                + _q(desired["standbyProductionEnvironment"]) + "}}) { id name productionEnvironment standbyProductionEnvironment } }")
    cli_error = None
    try:
        data, _ = _raw(s, label, document, mutating=True)
        result = data.get("updateProject")
        if not isinstance(result, dict) or result.get("id") != project["id"]:
            cli_error = "The original correction response did not contain its expected project identity."
    except (_api().NativeWaiting, ValueError) as exc:
        # The provider can apply the SQL patch before its audit/readback fails.
        cli_error = str(exc)
    observed = _inventory(s, label + "-readback", fresh=True)["project"]
    matched = (observed["id"] == project["id"]
               and all(observed.get(name) == value for name, value in desired.items())
               and _selectors_match(observed, active_id, standby_id))
    result = {"required": True, "native_values_match": matched, "patch": desired,
              "original_task_id": task_id, "cli_error": cli_error,
              "reconciled_from_native_readback": bool(cli_error)}
    s.state[label + "_result"] = result
    s.save_state()
    if not matched:
        s.state.update(phase="reconcile_required", native_poll=None)
        s.save_state()
        raise _api().NativeWaiting("The retained original selector correction has not reached its exact native readback; continue that correction without another switch.")
    return observed, result


def authoritative_task_id(state):
    task_id = state.get("task_id")
    if not task_id:
        return None
    if state.get("task_reference_origin") != "operator_reconciled_original_task":
        return task_id
    task = state.get("last_task") or {}
    before = state.get("switch_before") or {}
    matches = (task.get("id") == task_id and task.get("name") == "Active/Standby Switch"
               and (task.get("environment") or {}).get("id") == before.get("standby_environment_id")
               and task_id not in before.get("task_ids", []))
    return task_id if matches else None


def _switch(s, operation, inventory):
    project = inventory["project"]
    before = s.state.get("switch_before")
    if not before:
        before = _switch_source(project, inventory["selected_environment"], s.p)
        s.state["switch_before"] = before
        s.save_state()
    supplied = operation.get("native_task_id")
    task_id = authoritative_task_id(s.state)
    if s.state.get("task_id") and not task_id:
        # Older source editions persisted an operator candidate before its native readback.
        legacy_id = s.state.pop("task_id")
        s.state.setdefault("task_reference_attempts", []).append({
            "task_id": legacy_id, "status": "unverified_legacy_candidate",
            "observed_at": _api()._now()})
        s.state.update(pending_task_id=legacy_id, native_poll=None)
        s.save_state()
    manual_candidate = False
    if supplied is not None:
        if not isinstance(supplied, int) or isinstance(supplied, bool) or supplied < 1:
            raise ValueError("Supply the actual original native task ID as a positive integer.")
        if task_id and supplied != task_id:
            raise ValueError("A different task cannot replace the original retained task.")
        manual_candidate = not task_id
        task_id = supplied
    if not task_id and s.state.get("pending_task_id"):
        raise _api().NativeWaiting("Correct or continue the retained unverified task candidate; this original switch is not repeated.")
    if not task_id:
        command = s.out / "switch-active-standby.command.json"
        previous = s.read_private_json(command) if command.exists() else None
        not_started = previous is None and s.state.get("pending_command") != "switch-active-standby" or previous is not None and previous.get("phase") == "not_started"
        if not_started:
            fresh = _inventory(s, "switch-dispatch-preflight", fresh=True)
            current = _switch_source(fresh["project"], fresh["selected_environment"], s.p)
            immutable = ("project_id", "active_environment_id", "standby_environment_id", "active_name",
                         "standby_name", "expected_routes", "services", "api_routes")
            if any(current[key] != before[key] for key in immutable):
                raise ValueError("The reviewed native switch target, services or route assignments changed before dispatch.")
            if any(task_id not in before["task_ids"] for task_id in current["task_ids"]):
                before["task_ids"] = sorted(set(before["task_ids"]) | set(current["task_ids"]))
                s.save_state()
            normalized, correction = _normalize_selectors(s, fresh["project"],
                before["active_environment_id"], before["standby_environment_id"], "normalize-before-switch")
            confirmed = _switch_source(normalized, next(environment for environment in normalized["environments"]
                if environment["id"] == before["standby_environment_id"]), s.p)
            if any(confirmed[key] != before[key] for key in immutable):
                raise ValueError("The native target or route assignments changed during selector normalization.")
            s.state["pre_switch_selector_result"] = correction
            s.save_state()
        # The exact mutation label is reused after every transport/worker interruption.
        document = "mutation { switchActiveStandby(input:{project:{name:" + _q(s.p["project_name"]) + "}}) { id remoteId } }"
        data, _ = _raw(s, "switch-active-standby", document, mutating=True)
        value = data.get("switchActiveStandby")
        if not isinstance(value, dict) or not isinstance(value.get("id"), int) or isinstance(value["id"], bool) or value["id"] < 1:
            s.state.update(phase="reconcile_required", native_poll=None)
            s.save_state()
            raise _api().NativeWaiting("The original switch response has no usable task ID. Supply its actual original task ID in operating continuation; do not submit another switch.")
        task_id = value["id"]
        s.state.update(task_id=task_id, task_reference_origin="original_switch_response",
                       phase="accepted", native_poll={"provider": "lagoon", "kind": "task", "id": task_id})
        s.save_state()
    attempt = None
    if manual_candidate:
        attempt = {"task_id": task_id, "status": "awaiting_native_identity",
                   "observed_at": _api()._now()}
        s.state.setdefault("task_reference_attempts", []).append(attempt)
        s.state.update(pending_task_id=task_id, native_poll=None, phase="reconcile_required")
        s.save_state()
    try:
        if task_id in before["task_ids"]:
            raise ValueError("The selected task predates this original switch operation.")
        data, _ = _fresh(s, "switch-task", "query { taskById(id:" + str(task_id) + ") { " + TASK_FIELDS + " } }")
        task = data.get("taskById")
        if not isinstance(task, dict) or task.get("id") != task_id:
            raise _api().NativeWaiting("The original native task is absent from the current provider observation.")
        if task.get("name") != "Active/Standby Switch" or (task.get("environment") or {}).get("id") != before["standby_environment_id"]:
            raise ValueError("The supplied task is not the original active/standby task on the reviewed standby environment.")
    except Exception as exc:
        if attempt is not None:
            attempt.update(status="not_verified", message=str(exc), completed_at=_api()._now())
            s.save_state()
        raise
    if attempt is not None:
        attempt.update(status="verified_original_task", completed_at=_api()._now())
        s.state["task_reference_origin"] = "operator_verified_original_task"
    s.state.update(task_id=task_id, task_identity_verified=True, pending_task_id=None,
                   last_task=task, phase="accepted",
                   native_poll={"provider": "lagoon", "kind": "task", "id": task_id})
    s.save_state()
    status = str(task.get("status") or "")
    if status.upper() in FAILED:
        s.state.update(phase="failed", native_poll=None)
        s.save_state()
        return s.result("FAILED", {"native_action": "lagoon-switch-active-standby", "task": task},
                        "The original native switch returned " + status + ".")
    if status.upper() not in SUCCEEDED:
        s.save_state()
        return s.result("WAITING_NATIVE", {"native_action": "lagoon-switch-active-standby", "task": task},
                        "The original native switch remains " + (status or "unreported") + ".")
    after = _inventory(s, "switch-readback", fresh=True)["project"]
    if after["id"] != before["project_id"]:
        raise ValueError("The native project identity changed after the original task.")
    role_matches = _selectors_match(after, before["standby_environment_id"], before["active_environment_id"])
    routes = _route_readback(after, before)
    exact = role_matches and routes["production_matches"] and routes["standby_matches"] and not routes["api_route_findings"]
    observations = {"native_action": "lagoon-switch-active-standby", "task": task, "before": before,
                    "after": {key: after.get(key) for key in ("id", "productionEnvironment", "standbyProductionEnvironment", "productionRoutes", "standbyRoutes", "apiRoutes")},
                    "project_readback_matches": exact, "route_readback": routes,
                    "deployment_tasks_executed": False, "environment_variables_rewritten": False}
    if not exact:
        s.state["observations"] = observations
        s.save_state()
        return s.result("WAITING_NATIVE", observations,
                        "The original task completed; reconcile the observed environment roles, reviewed URL membership and native API route assignments.")
    normalized, correction = _normalize_selectors(s, after, before["standby_environment_id"],
        before["active_environment_id"], "normalize-after-switch", task_id)
    routes = _route_readback(normalized, before)
    if not routes["production_matches"] or not routes["standby_matches"] or routes["api_route_findings"]:
        raise _api().NativeWaiting("The native routes changed during selector reconciliation; retain and reconcile this same completed switch.")
    observations["selector_correction"] = correction
    observations["final_project_selectors"] = {key: normalized.get(key) for key in ("productionEnvironment", "standbyProductionEnvironment")}
    s.state.update(phase="completed", native_poll=None, observations=observations)
    s.save_state()
    return s.result("COMPLETE", observations)


def execute(operation, config, source_paths, checkpoint=None, cancelled=None):
    p = profile(config)
    s = _api().Session(p, source_paths["output_dir"], checkpoint, cancelled, source_paths.get("workspace_relocations"))
    action = operation.get("native_action")
    try:
        _state(s, source_paths.get("checkpoint") or operation.get("resume_checkpoint"))
        if operation.get("provider_environment_id") != p["environment_id"]:
            raise ValueError("The operation names a different native environment.")
        allowed = {item["value"] for item in actions_for(operation.get("type"))}
        if action not in allowed:
            raise ValueError("Select the documented Lagoon action for this operation purpose.")
        inventory = _inventory(s, "original-operation-inventory")
        target = provider_context(p)
        expected = operation.get("target_fingerprint") or config.get("target_fingerprint")
        if expected and expected != _api()._digest(target):
            raise ValueError("The observed Lagoon target differs from its reviewed fingerprint.")
        _intent(s, {"action": action, "target": target, "operation_id": operation.get("id"),
                    "snapshot_id": source_paths.get("snapshot_id"),
                    "snapshot_sha256": source_paths.get("snapshot_sha256"),
                    "backup_id": p.get("lagoon_backup_id"),
                    "expected_routes": {role: p.get("expected_" + role + "_routes") for role in ("production", "standby")},
                    "original_inventory_sha256": inventory["record"]["stdout"]["sha256"]})
        if s.state.get("phase") == "completed":
            return s.result("COMPLETE", s.state.get("observations"))
        if action == "lagoon-backup-download":
            return _download_backup(s, inventory)
        return _switch(s, operation, inventory)
    except _api().NativeCancelled as exc:
        return s.result("WAITING_NATIVE" if s.state.get("mutation_started") else "CANCELLED", message=str(exc))
    except _api().NativeWaiting as exc:
        return s.result("WAITING_NATIVE", message=str(exc))
    except Exception as exc:
        if s.state.get("mutation_started"):
            s.state.update(phase="reconcile_required", native_poll=None)
            s.save_state()
            return s.result("WAITING_NATIVE", message=str(exc))
        return s.result("FAILED", message=str(exc))

