                        "config_sha256": current["profile"]["revision"],
                        "target_fingerprint": current["capabilities"]["target_fingerprint"]}
                capture = journey.call("capture-" + label.lower(), "sources.capture", capture_body)
                complete = journey.operation("capture-" + label.lower(), capture)
                edition = journey.call("edition-" + label.lower(), "static.editions.receive", {
                    "operation_id": complete["operation"]["id"],
                    "expected_revision": complete["operation"]["revision"],
                    "label": "Complete native editorial edition " + label})["edition"]
                editions.append(edition["id"])
                target = journey.call("target", "static.targets.save", {
                    "environment_id": ENVIRONMENT, "release_root": str(release_root),
                    "current_name": "current", "label": "Original local static release"})["target"]
                target_id = target["target_id"]
                def target_body():
                    actual = ws.dispatch("static.targets.get", {"target_id": target_id}, actor)
                    return {"target_id": target_id, "expected_revision": actual["target"]["revision"],
                        "expected_current_release_id": (actual.get("current_release") or {}).get("id")}
                plan = journey.call("comparison-" + label.lower(), "static.plans.create",
                    lambda: {**target_body(), "candidate_id": edition["id"],
                             "label": "Review complete native edition " + label})["plan"]
                comparison_path = root / "results" / ("comparison-" + label.lower() + "-full.json")
                if comparison_path.exists():
                    comparison = read(comparison_path)
                    if comparison["plan"]["id"] != plan["id"] or comparison["plan"]["comparison_sha256"] != plan["comparison_sha256"]:
                        raise RuntimeError("Reopen the original complete comparison.")
                else:
                    pages, rows, offset = [], [], 0
                    while True:
                        page = ws.dispatch("static.plans.get", {"plan_id": plan["id"], "offset": offset, "limit": 1000, "status": "all"}, actor)
                        if page["plan"]["comparison_sha256"] != plan["comparison_sha256"] or page["comparison"]["offset"] != offset:
                            raise RuntimeError("The native comparison page changed identity.")
                        pages.append(page)
                        rows.extend(page["comparison"]["rows"])
                        next_offset = page["comparison"]["next_offset"]
                        if next_offset is None:
                            break
                        if next_offset <= offset:
                            raise RuntimeError("The original comparison cursor did not advance.")
                        offset = next_offset
                    if len(rows) != pages[-1]["comparison"]["total"]:
                        raise RuntimeError("Receive every original comparison row.")
                    comparison = {"schema": "tjl.govhub-complete-native-comparison.v1",
                        "plan": plan, "native_pages": pages, "rows": rows,
                        "counts": pages[-1]["comparison"]["counts"]}
                    retain(comparison_path, comparison)
                journey.call("review-" + label.lower(), "static.reviews.save", {
                    "plan_id": plan["id"], "comparison_sha256": plan["comparison_sha256"],
                    "decision": "APPROVE", "reason": "Reviewed the complete generated native edition, including all changed and removed paths, for this dedicated original local target."})
                for purpose in ["STATIC_STAGE", "STATIC_PUBLISH"]:
                    task = label.lower() + "-" + purpose.lower()
                    queued = journey.call(task, "static.operations.create",
                        lambda purpose=purpose: {**target_body(), "type": purpose,
                           "plan_id": plan["id"], "reason": "Operate the exact reviewed full native edition " + label})
                    operation = journey.operation(task, queued)
                    observed_path = root / "results" / (task + "-target.json")
                    if observed_path.exists():
                        observed = read(observed_path)
                    else:
                        observed = ws.dispatch("static.targets.inspect", {"target_id": target_id}, actor)
                        retain(observed_path, observed)
                    if purpose == "STATIC_PUBLISH":
                        selected = observed.get("current_release")
                        if not selected or selected["edition_id"] != edition["id"]:
                            raise RuntimeError("The actual native current selection differs from its completed publication.")
                        publications.append(selected["id"])
            rollback = journey.call("rollback", "static.operations.create",
                lambda: {**target_body(), "type": "STATIC_ROLLBACK",
                         "reason": "Select the retained predecessor of the completed second native edition."})
            journey.operation("rollback", rollback)
            selected = ws.dispatch("static.targets.inspect", {"target_id": target_id}, actor)
            if selected["current_release"]["edition_id"] != editions[0]:
                raise RuntimeError("The native rollback did not select the retained first edition.")
            retain(root / "results" / "rollback-target.json", selected)
            exported = journey.call("handover", "static.exports.create",
                lambda: {**target_body(), "name": "GovHub / Tome complete native operating handover"})["export"]
        finally:
            ws.stop_worker()
    output = root / "delivery"
    output.mkdir(mode=0o700, exist_ok=True)
    handover = output / "Static_Release_Handover.zip"
    if not handover.exists():
        downloaded = download(ws, exported["file"]["id"], handover)
        retain(output / "handover-download.json", downloaded)
    received = inspect_archive(handover, editions)
    retain(output / "handover-inspection.json", received)
    backup_path = root / "receiving-workspace"
    if not backup_path.exists():
        backup = ws.dispatch("workspace.backup", {"destination": str(backup_path)}, actor)
        retain(output / "workspace-backup.json", backup)
    if (backup_path / "BACKUP_INCOMPLETE").exists():
        raise RuntimeError("Continue the original complete workspace backup.")
    cold = govhub.open_workspace(backup_path, inputs, code / "vendor" / "assessment-core", create=False)
    cold_actor = cold.authenticate(account["username"], account["password"])
    if not cold_actor:
        raise RuntimeError("The original receiving account did not reopen.")
    reopened = cold.dispatch("static.targets.get", {"target_id": target_id}, cold_actor)
    if reopened["current_release"]["id"] != selected["current_release"]["id"]:
        raise RuntimeError("The receiving workspace reopened a different native current release.")
    reopened_editions = [cold.dispatch("static.editions.get", {"edition_id": item}, cold_actor)["edition"] for item in editions]
    reopened_export = cold.dispatch("static.exports.get", {"export_id": exported["id"]}, cold_actor)["export"]
    cold_download = output / "Static_Release_Independent_Receiving.zip"
    if not cold_download.exists():
        download(cold, reopened_export["file"]["id"], cold_download)
    if sha(cold_download) != sha(handover):
        raise RuntimeError("The independent original receiving download differs.")
    result = {"schema": "tjl.govhub-tome-native-journey.v1", "status": "COMPLETE",
        "application_source_commit": source_commit,
        "application_source_sha256": source_binding["source_manifest_sha256"], "workspace": str(workspace_path),
        "receiving_workspace": str(backup_path), "environment_id": ENVIRONMENT,
        "site_uuid": ready["site_uuid"], "target_id": target_id, "edition_ids": editions,
        "published_release_ids": publications, "selected_release": selected["current_release"],
        "reopened_editions": reopened_editions, "export": exported,
        "handover": {k: received[k] for k in ["path", "bytes", "sha256", "members"]},
        "independent_download": {"path": str(cold_download), "bytes": cold_download.stat().st_size, "sha256": sha(cold_download)}}
    retain(output / "GovHub-Tome-Native-Result.json", result)
    progress(root, "complete", target_id=target_id, edition_ids=editions,
             handover_sha256=received["sha256"])
    return result

def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--application", type=Path, required=True)
    parser.add_argument("--directory", type=Path, required=True)
    parser.add_argument("--runtime-manifest", type=Path, required=True)
    parser.add_argument("--site-root", type=Path, required=True)
    parser.add_argument("--tome-archive", type=Path, required=True)
    parser.add_argument("--site-mail", required=True, help="Actual selected site administrator email.")
    parser.add_argument("--application-source-commit", required=True,
                        help="Full source commit from the selected complete APPLICATION_SOURCE.json.")
    args = parser.parse_args()
    for value in [args.application, args.directory, args.runtime_manifest, args.site_root, args.tome_archive]:
        if not value.is_absolute():
            raise SystemExit("Choose actual absolute retained source and private native operation paths.")
    os.umask(0o077)
    sys.path.insert(0, str(args.application / "workspace"))
    from content_consolidation.examples.native_site import NativeDrupalSite
    with NativeDrupalSite(runtime_manifest=args.runtime_manifest,
            directory=args.directory / "native-site", site_root=args.site_root,
            environment_id=ENVIRONMENT, site_name="Tome operating workshare",
            site_mail=args.site_mail) as site:
        run_tome_journey(site=site, application_directory=args.application,
                         directory=args.directory, tome_archive=args.tome_archive,
                         expected_source_commit=args.application_source_commit)
    return 0

if __name__ == "__main__":
    raise SystemExit(main())

"""Complete native static-output manifest and comparison contracts."""
from pathlib import PurePosixPath
from urllib.parse import urlsplit
import hashlib
import json
import re

BUILD_SCHEMA = "govhub.tome-static-build.v1"
EDITION_SCHEMA = "govhub.static-edition.v1"
MAX_FILES = 250000
MAX_MANIFEST_BYTES = 64 * 1024 * 1024
SHA = re.compile(r"^[0-9a-f]{64}$")
MAX_EXACT_INTEGER = 2**53 - 1


def error(code, message, status=422):
    from govhub import GovHubError
    raise GovHubError(code, message, status)


def canonical(value):
    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"), allow_nan=False).encode("utf-8")


def sha(raw):
    return hashlib.sha256(raw).hexdigest()


def relative(value):
    if not isinstance(value, str) or not value or len(value.encode("utf-8")) > 4096:
        error("STATIC_PATH", "Use a complete ordinary relative output path within 4,096 UTF-8 bytes.")
    if "\\" in value or any(ord(c) < 32 or ord(c) == 127 for c in value):
        error("STATIC_PATH", "Output paths cannot contain backslashes or control characters.")
    parts = value.split("/")
    if any(part in ("", ".", "..") for part in parts) or str(PurePosixPath(value)) != value or value.startswith("/"):
        error("STATIC_PATH", "Keep each original file path relative to its complete output root.")
    return value


def file_rows(rows):
    if not isinstance(rows, list) or not rows or len(rows) > MAX_FILES:
        error("STATIC_FILES", "A complete edition contains 1–250,000 original output files.")
    result, seen, total = [], set(), 0
    for row in rows:
        if not isinstance(row, dict):
            error("STATIC_FILE", "Each output row must name its original path, bytes, and SHA-256.")
        path = relative(row.get("path"))
        count, digest = row.get("bytes"), row.get("sha256")
        if isinstance(count, bool) or not isinstance(count, int) or not 0 <= count <= MAX_EXACT_INTEGER:
            error("STATIC_FILE_BYTES", "Keep the exact nonnegative original byte count.")
        if not isinstance(digest, str) or not SHA.fullmatch(digest):
            error("STATIC_FILE_HASH", "Keep the complete lowercase SHA-256 for every output file.")
        if path in seen:
            error("STATIC_FILE_DUPLICATE", "The complete edition repeats output path " + path + ".")
        seen.add(path)
        total += count
        result.append({"path": path, "bytes": count, "sha256": digest})
    if total > MAX_EXACT_INTEGER:
        error("STATIC_TOTAL_BYTES", "The total output size exceeds the supported exact byte count.")
    for path in seen:
        parts = path.split("/")
        if any("/".join(parts[:index]) in seen for index in range(1, len(parts))):
            error("STATIC_PATH_COLLISION", "One output file is also used as another file's directory.")
    return sorted(result, key=lambda row: row["path"])


def validate_report(report):
    if not isinstance(report, dict) or report.get("schema") != BUILD_SCHEMA:
        error("STATIC_BUILD_SCHEMA", "Select the original govhub.tome-static-build.v1 native report.")
    if report.get("complete") is not True or not isinstance(report.get("errors"), list) or report["errors"]:
        error("STATIC_BUILD_INCOMPLETE", "The original build must declare its complete output and an empty collected error list.", 409)
    uri = report.get("production_uri")
    if not isinstance(uri, str):
        error("STATIC_PRODUCTION_URI", "Retain the native build's actual production URI.")
    parsed = urlsplit(uri)
    if parsed.scheme not in ("https", "http") or not parsed.hostname or parsed.username or parsed.password or parsed.fragment:
        error("STATIC_PRODUCTION_URI", "Retain the actual HTTP(S) production URI without credentials or a fragment.")
    generator = report.get("generator")
    if not isinstance(generator, dict) or generator.get("package") != "drupal/tome":
        error("STATIC_GENERATOR", "The completed native build must identify its original drupal/tome generator.")
    if not isinstance(generator.get("version"), str) or not generator["version"].strip() or not SHA.fullmatch(str(generator.get("source_sha256", ""))):
        error("STATIC_GENERATOR_IDENTITY", "Retain the exact installed Tome version and generator source SHA-256.")
    inputs = report.get("inputs")
    if not isinstance(inputs, list):
        error("STATIC_BUILD_INPUTS", "Retain the native report's original input descriptors.")
    files = file_rows(report.get("files"))
    return {"production_uri": uri, "generator": generator, "inputs": inputs,
            "files": files, "file_count": len(files), "total_bytes": sum(r["bytes"] for r in files),
            "files_sha256": sha(canonical(files))}


def compare_rows(before, after):
    left, right = {r["path"]: r for r in before}, {r["path"]: r for r in after}
    rows, counts = [], {key: 0 for key in ("added", "removed", "changed", "unchanged")}
    for path in sorted(left.keys() | right.keys()):
        a, b = left.get(path), right.get(path)
        status = "added" if a is None else "removed" if b is None else "unchanged" if (a["sha256"], a["bytes"]) == (b["sha256"], b["bytes"]) else "changed"
        counts[status] += 1
        identity = {"path": path, "status": status, "before": a, "after": b}
        rows.append(dict(identity, change_id=sha(canonical(identity))))
    return {"schema": "govhub.static-comparison.v1", "counts": counts, "rows": rows,
            "sha256": sha(canonical(rows))}


def page(rows, payload):
    def integer(value, default, maximum):
        if value is None:
            return default
        if isinstance(value, str) and value.isdigit():
            value = int(value)
        if isinstance(value, bool) or not isinstance(value, int) or not 0 <= value <= maximum:
            error("STATIC_PAGE", "Use an ordinary nonnegative page offset and a page size through 1,000.")
        return value
    offset = integer(payload.get("offset"), 0, MAX_EXACT_INTEGER)
    limit = integer(payload.get("limit"), 100, 1000)
    if not limit:
        error("STATIC_PAGE", "Choose at least one row per page.")
    query = payload.get("query", "")
    status = payload.get("status", "all")
    if not isinstance(query, str) or len(query.encode("utf-8")) > 2000:
        error("STATIC_QUERY", "Use a path search within 2,000 UTF-8 bytes.")
    if status not in ("all", "added", "removed", "changed", "unchanged"):
        error("STATIC_FILTER", "Choose an original change category.")
    needle = query.casefold()
    selected = [r for r in rows if needle in r["path"].casefold() and (status == "all" or r.get("status") == status)]
    end = min(offset + limit, len(selected))
    return {"rows": selected[offset:end], "total": len(selected), "offset": offset, "limit": limit,
            "next_offset": end if end < len(selected) else None}

"""Native local-directory stage and atomic pointer operations.

Executed only by GovHub's existing worker under its original storage lease.
The target lock protects one configured filesystem pointer across workspaces.
"""
from __future__ import annotations
from contextlib import contextmanager
from pathlib import Path
import fcntl
import hashlib
import json
import os
import stat
import tempfile
import uuid

from .model import canonical, sha, relative
from .service import problem, edition, manifest, target, current_release, _environment, _latest_review


def sync_dir(path):
    fd = os.open(path, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW)
    try:
        os.fsync(fd)
    finally:
        os.close(fd)


def _root(value):
    path = Path(value["release_root"])
    try:
        info = path.lstat()
        valid = stat.S_ISDIR(info.st_mode) and path.resolve(strict=True) == path
    except OSError:
        valid = False
        info = None
    if not valid or (info.st_dev, info.st_ino) != (value["root_device"], value["root_inode"]):
        problem("STATIC_ROOT_CHANGED", "The explicitly configured release directory moved or changed.", 409)
    return path


@contextmanager
def target_lock(value):
    root = _root(value)
    fd = os.open(root / ".govhub-static.lock", os.O_RDWR | os.O_CREAT | os.O_NOFOLLOW, 0o600)
    try:
        if not stat.S_ISREG(os.fstat(fd).st_mode):
            problem("STATIC_LOCK_TYPE", "The existing target lock is not an ordinary file.", 409)
        try:
            fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
        except BlockingIOError:
            problem("STATIC_TARGET_BUSY", "The original target is in use by another release operation.", 409)
        _root(value)
        yield root
    finally:
        os.close(fd)


def inspect_target(value):
    root = _root(value)
    current = root / value["current_name"]
    try:
        info = current.lstat()
    except FileNotFoundError:
        return {"pointer": None, "resolved_path": None}
    if not stat.S_ISLNK(info.st_mode):
        problem("STATIC_POINTER_TYPE", "The selected current entry must be an actual release symlink, or absent for the first edition.", 409)
    literal = os.readlink(current)
    path = current.resolve(strict=True)
    if not path.is_relative_to(root) or path == root or path.is_symlink() or not path.is_dir():
        problem("STATIC_POINTER_SCOPE", "The current release must resolve to an ordinary output directory inside its configured root.", 409)
    return {"pointer": literal, "resolved_path": str(path)}


def _file_digest(path):
    fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW)
    try:
        before = os.fstat(fd)
        if not stat.S_ISREG(before.st_mode):
            problem("STATIC_FILE_TYPE", "Static output must contain ordinary files.", 409)
        h = hashlib.sha256()
        length = 0
        with os.fdopen(os.dup(fd), "rb") as handle:
            for block in iter(lambda: handle.read(1024 * 1024), b""):
                h.update(block)
                length += len(block)
        after = os.fstat(fd)
        if (before.st_dev, before.st_ino, before.st_size, before.st_mtime_ns, before.st_ctime_ns) != (after.st_dev, after.st_ino, after.st_size, after.st_mtime_ns, after.st_ctime_ns):
            problem("STATIC_FILE_CHANGED", "A static output file changed during verification.", 409)
        return h.hexdigest(), length
    finally:
        os.close(fd)


def verify_tree(path, rows):
    if path.is_symlink() or not path.is_dir():
        problem("STATIC_OUTPUT_MISSING", "The complete selected output directory is unavailable.", 409)
    expected = {r["path"]: r for r in rows}
    actual = set()
    for directory, directories, files in os.walk(path, followlinks=False):
        directories.sort()
        files.sort()
        for name in directories:
            child = Path(directory) / name
            if child.is_symlink() or not child.is_dir():
                problem("STATIC_OUTPUT_LINK", "The complete static edition cannot include linked directories.", 409)
        for name in files:
            child = Path(directory) / name
            key = relative(child.relative_to(path).as_posix())
            if key not in expected or child.is_symlink():
                problem("STATIC_OUTPUT_SET", "The output has an unretained path: " + key, 409)
            row = expected[key]
            if _file_digest(child) != (row["sha256"], row["bytes"]):
                problem("STATIC_OUTPUT_BYTES", "The output differs from the retained edition: " + key, 409)
            actual.add(key)
    if actual != set(expected):
        problem("STATIC_OUTPUT_SET", "The output is missing paths from the complete edition.", 409)


def _directory(path, mode=0o755):
    try:
        path.mkdir(mode=mode)
        sync_dir(path.parent)
    except FileExistsError:
        pass
    if path.is_symlink() or not path.is_dir():
        problem("STATIC_DIRECTORY_TYPE", "A retained release path is not an ordinary directory.", 409)
    return path


def immutable_json(path, value):
    raw = canonical(value)
    if path.exists() or path.is_symlink():
        if path.is_symlink() or not path.is_file() or path.read_bytes() != raw:
            problem("STATIC_RETAINED_CHANGED", "The original retained release file differs: " + path.name, 409)
        return
    fd, name = tempfile.mkstemp(prefix=".write-", dir=path.parent)
    temporary = Path(name)
    try:
        with os.fdopen(fd, "wb") as handle:
            handle.write(raw)
            handle.flush()
            os.fsync(handle.fileno())
        try:
            os.link(temporary, path)
        except FileExistsError:
            if path.is_symlink() or path.read_bytes() != raw:
                problem("STATIC_RETAINED_CHANGED", "A different original release file already exists.", 409)
        sync_dir(path.parent)
    finally:
        temporary.unlink(missing_ok=True)


def _area(value):
    root = _root(value)
    base = _directory(_directory(root / ".govhub-static") / value["namespace"])
    immutable_json(base / "owner.json", {
        "schema": "govhub.static-target-directory.v1", "namespace": value["namespace"],
        "target_id": value["target_id"], "root_device": value["root_device"],
        "root_inode": value["root_inode"], "current_name": value["current_name"],
    })
    _directory(base / "editions")
    _directory(base / "releases")
    return base


def _cancel(ws, operation):
    from govhub import GovHubError
    with ws.connect() as db:
        current = ws._operation(db, operation["id"])
    if current.get("cancel_requested"):
        raise GovHubError("STATIC_CANCELLED", "The original static operation was cancelled; completed staged files remain retained.", 409)
    if ws._worker_stop.is_set():
        raise GovHubError("STATIC_PAUSED", "The original worker is closing; complete staged files and the original checkpoint remain retained.", 409)


def _checkpoint(ws, value, stage, detail, **extra):
    binding = {"schema": "govhub.static-resume.v1", "operation_id": value["id"],
               "target_id": value["static_target_id"], "target_sha256": value["static_target"]["sha256"],
               "edition_id": value["static_edition"]["id"], "edition_sha256": value["static_edition"]["sha256"]}
    binding.update(extra)
    unsafe = bool(value.get("native_attempted")) or stage == "PUBLISH_READY"
    ws._native_checkpoint(value["id"], {"stage": stage, "detail": detail,
        "safe_to_retry": not unsafe, "mutation_started": unsafe, "resume_checkpoint": binding})


def _stage(ws, operation, selected, rows, base):
    identifier = selected["id"]
    final = base / "editions" / identifier
    metadata = {"schema": "govhub.static-staged-edition.v1", "edition_id": identifier,
                "edition_sha256": selected["sha256"], "files_sha256": selected["files_sha256"],
                "file_count": selected["file_count"], "total_bytes": selected["total_bytes"],
                "files": [{k: row[k] for k in ("path", "bytes", "sha256")} for row in rows]}
    if final.exists() or final.is_symlink():
        if final.is_symlink() or not final.is_dir():
            problem("STATIC_STAGE_IDENTITY", "The retained edition path changed.", 409)
        immutable_json(final / "edition.json", metadata)
        verify_tree(final / "site", rows)
        return final
    stage = _directory(base / ("stage-" + operation["id"] + "-" + identifier))
    immutable_json(stage / "owner.json", {"operation_id": operation["id"], "edition_id": identifier,
                                        "edition_sha256": selected["sha256"]})
    site = _directory(stage / "site")
    temporary = _directory(stage / "transfer", 0o700)
    for index, row in enumerate(rows):
        _cancel(ws, operation)
        output = site
        parts = relative(row["path"]).split("/")
        for component in parts[:-1]:
            output = _directory(output / component)
        output /= parts[-1]
        if output.exists() or output.is_symlink():
            if output.is_symlink() or _file_digest(output) != (row["sha256"], row["bytes"]):
                problem("STATIC_STAGE_BYTES", "An already staged file differs from this original edition: " + row["path"], 409)
        else:
            with ws.connect() as db:
                item = ws._file_row(db, row["file_id"])
            if (item["sha256"], item["bytes"]) != (row["sha256"], row["bytes"]):
                problem("STATIC_SOURCE_BINDING", "A retained source row changed.", 409)
            source = ws._verify_file(item)
            scratch = temporary / (sha(row["path"].encode()) + ".partial")
            if scratch.is_symlink() or scratch.exists() and not scratch.is_file():
                problem("STATIC_PARTIAL_TYPE", "The retained partial transfer is not an ordinary file.", 409)
            scratch.unlink(missing_ok=True)
            fd = os.open(scratch, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, 0o600)
            try:
                h = hashlib.sha256()
                size = 0
                with os.fdopen(fd, "wb") as out, source.open("rb") as original:
                    for block in iter(lambda: original.read(1024 * 1024), b""):
                        _cancel(ws, operation)
                        out.write(block)
                        h.update(block)
                        size += len(block)
                    out.flush()
                    os.fsync(out.fileno())
                if (h.hexdigest(), size) != (row["sha256"], row["bytes"]):
                    problem("STATIC_TRANSFER_BYTES", "The source changed while staging: " + row["path"], 409)
                os.chmod(scratch, 0o444)
                os.link(scratch, output)
                sync_dir(output.parent)
            finally:
                scratch.unlink(missing_ok=True)
        if index == 0 or (index + 1) % 50 == 0 or index + 1 == len(rows):
            _checkpoint(ws, operation, "STAGING", "Retained " + str(index + 1) + " of " + str(len(rows)) + " complete output files",
                        staged_edition_id=identifier, completed=index + 1, total=len(rows))
    verify_tree(site, rows)
    immutable_json(stage / "edition.json", metadata)
    for directory, directories, files in os.walk(site, topdown=False):
        os.chmod(directory, 0o555)
        sync_dir(directory)
    sync_dir(stage)
    # There is one original worker and the target lock is held. A preexisting
    # complete directory is still treated as an immutable identity, never replaced.
    if final.exists():
        immutable_json(final / "edition.json", metadata)
        verify_tree(final / "site", rows)
    else:
        os.rename(stage, final)
        sync_dir(final.parent)
    return final


def _pins(ws, db, value, *, completing=False):
    current = ws._operation(db, value["id"])
    if current.get("worker_owner") != ws._worker_owner or current["state"] != "RUNNING":
        problem("STATIC_WORKER_CHANGED", "The original worker no longer owns this operation.", 409)
    if completing:
        # This is only permission to inspect/reconcile the retained action.
        # Current account/configuration/review checks still precede a new replace.
        return current
    old = current_release(ws, db, value["static_target_id"])
    if (old["id"] if old else None) != (value["static_previous"]["id"] if value["static_previous"] else None):
        problem("STATIC_RELEASE_CHANGED", "Another retained release became current. Preserve this original operation and compare the current target.", 409)
    ws._authorize(value["queued_actor"])
    selected = target(ws, db, value["static_target_id"])
    if selected["id"] != value["static_target"]["id"]:
        problem("STATIC_TARGET_CHANGED", "The configured target changed after this original operation was queued.", 409)
    environment = _environment(ws, db, selected)
    if environment["revision"] != value["environment"]["revision"]:
        problem("STATIC_ENVIRONMENT_CHANGED", "The native environment changed after this operation was queued.", 409)
    if value["type"] == "STATIC_PUBLISH":
        review = _latest_review(ws, db, value["static_plan"]["id"])
        if not review or review["id"] != value["static_review"]["id"] or review["decision"] != "APPROVE":
            problem("STATIC_REVIEW_CHANGED", "The current review changed after publication was queued.", 409)
    if current.get("cancel_requested"):
        problem("STATIC_CANCELLED", "The original static operation was cancelled.", 409)
    return current


def is_unresolved_selection(value):
    checkpoint = value.get("resume_checkpoint") or {}
    return (value.get("type") in {"STATIC_PUBLISH", "STATIC_ROLLBACK"}
            and value.get("native_attempted") is True
            and checkpoint.get("schema") == "govhub.static-resume.v1")


def _resume_binding(value):
    if not is_unresolved_selection(value):
        return False
    checkpoint = value["resume_checkpoint"]
    expected = {"operation_id": value["id"], "target_id": value["static_target_id"],
                "target_sha256": value["static_target"]["sha256"],
                "edition_id": value["static_edition"]["id"],
                "edition_sha256": value["static_edition"]["sha256"]}
    if any(checkpoint.get(key) != val for key, val in expected.items()):
        problem("STATIC_RESUME_CHANGED", "The unresolved selection checkpoint belongs to different original input.", 409)
    return True


def _cancel_before_selection(ws, value, out, observed):
    from govhub import now
    body = {"schema": "govhub.static-cancellation.v1", "operation_id": value["id"],
            "target_id": value["static_target_id"], "target_sha256": value["static_target"]["sha256"],
            "observed_pointer": observed["pointer"], "action": "No pointer replacement performed"}
    receipt = _receipt(out / "static-cancelled.json", body)
    digest, count = _file_digest(out / "static-cancelled.json")
    result = {"status": "CANCELLED", "safe_to_retry": True, "observations": receipt,
              "artifacts": [{"role": "static_cancellation_receipt", "path": str(out / "static-cancelled.json"),
                             "size": count, "sha256": digest}]}
    with ws.connect(write=True) as db:
        current = _pins(ws, db, value, completing=True)
        capture, artifacts = ws._capture_result_files(db, current, result, out)
        current.update(state="CANCELLED", native_attempted=False, native_result=result,
                       actual_finished_at=receipt["completed_at"], error=None,
                       native_capture_file_id=capture["id"], retained_artifacts=list({(r["file"]["id"], r["role"]): r for r in [*current.get("retained_artifacts", []), *artifacts]}.values()),
                       progress={"completed": 0, "total": value["static_edition"]["file_count"],
                                 "stage": "CANCELLED", "detail": "Original current pointer unchanged; cancellation reconciled"})
        ws._write_operation(db, current, current["author"], "Static cancellation reconciled before selection")


def _context_now(ws, db, value):
    account = db.execute("SELECT u.name,u.role,COALESCE(d.disabled,0) AS disabled FROM users u LEFT JOIN govhub_disabled_users d ON d.username=u.name WHERE u.name=?", (value["author"],)).fetchone()
    environment = db.execute("SELECT revision FROM entities WHERE kind='environments' AND id=?", (value["environment_id"],)).fetchone()
    selected = ws._setting(db, "static.target:" + value["static_target_id"])
    current = current_release(ws, db, value["static_target_id"])
    review = _latest_review(ws, db, value["static_plan"]["id"]) if value.get("static_plan") else None
    expected = {"target_revision": value["static_target"]["id"], "environment_revision": value["environment"]["revision"],
                "release_id": (value.get("static_previous") or {}).get("id"),
                "review_id": (value.get("static_review") or {}).get("id"),
                "account": {"name": value["queued_actor"]["name"], "role": value["queued_actor"]["role"], "disabled": 0}}
    observed = {"target_revision": selected, "environment_revision": environment["revision"] if environment else None,
                "release_id": current["id"] if current else None, "review_id": review["id"] if review else None,
                "account": dict(account) if account else None}
    return {"expected_before_action": expected, "observed_when_recording": observed,
            "changed_fields": [key for key in expected if expected[key] != observed[key]]}


def _receipt(path, body):
    from govhub import now
    if path.exists() or path.is_symlink():
        if path.is_symlink() or not path.is_file():
            problem("STATIC_RECEIPT_CHANGED", "The retained operation receipt changed.", 409)
        value = json.loads(path.read_bytes())
        if any(value.get(key) != val for key, val in body.items()) or set(value) != set(body) | {"completed_at"}:
            problem("STATIC_RECEIPT_CHANGED", "The retained operation receipt belongs to different input.", 409)
        return value
    value = dict(body, completed_at=now())
    immutable_json(path, value)
    return value


def _reconciled_stage(configured, selected, rows, operation_id, before, after, observed):
    root = _root(configured)
    base = root / ".govhub-static" / configured["namespace"]
    staged = base / "editions" / selected["id"]
    selection = base / "releases" / operation_id
    for path in (root / ".govhub-static", base, base / "editions", staged,
                 staged / "site", base / "releases", selection):
        if path.is_symlink() or not path.is_dir() or path.resolve(strict=True) != path:
            problem("STATIC_SELECTION_CHANGED", "The already selected original release directory changed.", 409)
    expected_files = {
        base / "owner.json": {
            "schema": "govhub.static-target-directory.v1", "namespace": configured["namespace"],
            "target_id": configured["target_id"], "root_device": configured["root_device"],
            "root_inode": configured["root_inode"], "current_name": configured["current_name"]},
        staged / "edition.json": {
            "schema": "govhub.static-staged-edition.v1", "edition_id": selected["id"],
            "edition_sha256": selected["sha256"], "files_sha256": selected["files_sha256"],
            "file_count": selected["file_count"], "total_bytes": selected["total_bytes"],
            "files": [{k: row[k] for k in ("path", "bytes", "sha256")} for row in rows]},
        selection / "selection.json": {
            "schema": "govhub.static-selection.v1", "operation_id": operation_id,
            "target_id": configured["target_id"], "target_sha256": configured["sha256"],
            "edition_id": selected["id"], "edition_sha256": selected["sha256"],
            "before_pointer": before, "after_pointer": after},
    }
    for path, expected in expected_files.items():
        if path.is_symlink() or not path.is_file() or path.read_bytes() != canonical(expected):
            problem("STATIC_SELECTION_CHANGED", "The already selected pointer lacks its exact original retained identity.", 409)
    link = selection / "site"
    if not link.is_symlink() or os.readlink(link) != "../../editions/" + selected["id"] + "/site":
        problem("STATIC_SELECTION_CHANGED", "The actual original release selection changed.", 409)
    if observed["resolved_path"] != str(staged / "site"):
        problem("STATIC_SELECTION_CHANGED", "The current pointer resolves outside its original staged edition.", 409)
    verify_tree(staged / "site", rows)
    return staged


def run_operation(ws, value):
    from govhub import now
    selected = value["static_edition"]
    configured = value["static_target"]
    out = ws.root / "native-operations" / value["id"]
    out.mkdir(parents=True, exist_ok=True, mode=0o700)
    if out.is_symlink() or not out.resolve().is_relative_to(ws.root):
        problem("STATIC_OPERATION_DIRECTORY", "The original operation directory changed.", 409)
    unresolved = _resume_binding(value)
    with ws.connect(write=True) as db:
        current = _pins(ws, db, value, completing=unresolved)
        current["actual_started_at"] = current.get("actual_started_at") or now()
        value = ws._write_operation(db, current, current["author"], "Static native operation started")
        if ws._get(db, "static_target", configured["id"]) != configured or edition(ws, db, selected["id"]) != selected:
            problem("STATIC_QUEUED_SOURCE", "The queued operation differs from its immutable original target or edition.", 409)
        rows = manifest(ws, db, selected)
        previous_edition = edition(ws, db, value["static_previous"]["edition_id"]) if value["static_previous"] else None
        previous_rows = manifest(ws, db, previous_edition) if previous_edition else []
    with target_lock(configured):
        already_selected = False
        if unresolved:
            before = value["static_previous"]["pointer"] if value["static_previous"] else None
            after = ".govhub-static/" + configured["namespace"] + "/releases/" + value["id"] + "/site"
            observed = inspect_target(configured)
            if observed["pointer"] not in (before, after):
                problem("STATIC_POINTER_CHANGED", "The unresolved original selection has a different actual pointer.", 409)
            if observed["pointer"] == after:
                staged = _reconciled_stage(configured, selected, rows, value["id"], before, after, observed)
                before_pointer, after_pointer = before, after
                already_selected = True
            else:
                with ws.connect() as db:
                    current = ws._operation(db, value["id"])
                if current.get("cancel_requested"):
                    return _cancel_before_selection(ws, value, out, observed)
                with ws.connect() as db:
                    _pins(ws, db, value)
                value["native_attempted"] = False
        if not already_selected:
            _checkpoint(ws, value, "VERIFY_STATIC_SOURCE", "Verifying the complete retained static edition")
            base = _area(configured)
            staged = _stage(ws, value, selected, rows, base)
            before_pointer = value["static_previous"]["pointer"] if value["static_previous"] else None
            after_pointer = None
            if value["type"] != "STATIC_STAGE":
                if previous_edition:
                    _stage(ws, value, previous_edition, previous_rows, base)
                selected_release = _directory(base / "releases" / value["id"])
                link = selected_release / "site"
                literal = "../../editions/" + selected["id"] + "/site"
                if link.exists() or link.is_symlink():
                    if not link.is_symlink() or os.readlink(link) != literal:
                        problem("STATIC_SELECTION_CHANGED", "The retained release selection differs from this original operation.", 409)
                else:
                    os.symlink(literal, link)
                    sync_dir(selected_release)
                after_pointer = str(link.relative_to(_root(configured)))
                intent = {"schema": "govhub.static-selection.v1", "operation_id": value["id"],
                          "target_id": configured["target_id"], "target_sha256": configured["sha256"],
                          "edition_id": selected["id"], "edition_sha256": selected["sha256"],
                          "before_pointer": before_pointer, "after_pointer": after_pointer}
                immutable_json(selected_release / "selection.json", intent)
                observed = inspect_target(configured)
                completed_pointer = observed["pointer"] == after_pointer
                if not completed_pointer:
                    if observed["pointer"] != before_pointer:
                        problem("STATIC_POINTER_CHANGED", "The actual current pointer changed outside this original operation.", 409)
                    if previous_rows:
                        verify_tree(Path(observed["resolved_path"]), previous_rows)
                    _cancel(ws, value)
                    _checkpoint(ws, value, "PUBLISH_READY", "Complete edition and predecessor retained; ready for atomic pointer change",
                                before_pointer=before_pointer, after_pointer=after_pointer)
                    with ws.connect(write=True) as db:
                        _pins(ws, db, value)
                        # Hold the original database transaction across the single
                        # pointer replacement. Recovery uses this exact on-disk intent.
                        root = _root(configured)
                        temporary = root / (".current-" + value["id"])
                        if temporary.exists() or temporary.is_symlink():
                            if not temporary.is_symlink() or os.readlink(temporary) != after_pointer:
                                problem("STATIC_POINTER_TEMP", "A different pending pointer already exists.", 409)
                        else:
                            os.symlink(after_pointer, temporary)
                        sync_dir(root)
                        if inspect_target(configured)["pointer"] != before_pointer:
                            problem("STATIC_POINTER_CHANGED", "The current pointer changed immediately before publication.", 409)
                        os.replace(temporary, root / configured["current_name"])
                        sync_dir(root)
                if inspect_target(configured)["pointer"] != after_pointer:
                    problem("STATIC_POINTER_CHANGED", "The actual selected pointer differs after the original publication.", 409)
                verify_tree(staged / "site", rows)
            else:
                observed = inspect_target(configured)
                if observed["pointer"] != before_pointer:
                    problem("STATIC_POINTER_CHANGED", "The target's current pointer changed while this edition was staging.", 409)
        body = {"schema": "govhub.static-operation-result.v1", "operation_id": value["id"],
                "type": value["type"], "target_id": configured["target_id"],
                "target_sha256": configured["sha256"], "edition_id": selected["id"],
                "edition_sha256": selected["sha256"], "files_sha256": selected["files_sha256"],
                "file_count": selected["file_count"], "total_bytes": selected["total_bytes"],
                "staged_directory": str(staged), "before_pointer": before_pointer,
                "after_pointer": after_pointer, "plan_id": (value.get("static_plan") or {}).get("id"),
                "review_id": (value.get("static_review") or {}).get("id")}
        receipt = _receipt(out / "static-result.json", body)
        digest, count = _file_digest(out / "static-result.json")
        result = {"status": "COMPLETE", "safe_to_retry": True, "observations": receipt,
                  "artifacts": [{"role": "static_release_receipt", "path": str(out / "static-result.json"),
                                 "size": count, "sha256": digest}],
                  "provider_context": {"source_kind": "local-static-release",
                    "target_id": configured["target_id"], "release_root": configured["release_root"]}}
        with ws.connect(write=True) as db:
            current = _pins(ws, db, value, completing=after_pointer is not None)
            if after_pointer is not None and inspect_target(configured)["pointer"] != after_pointer:
                problem("STATIC_POINTER_CHANGED", "The actual pointer changed before original outcome retention.", 409)
            reconciliation = _context_now(ws, db, value)
            if value["type"] == "STATIC_STAGE":
                record = ws._object(db, "static_stage", dict(receipt, target_revision=configured["id"]),
                                    parent=value["static_plan"]["id"], actor=current["author"],
                                    object_id="static-stage-" + value["id"])
            else:
                record = ws._object(db, "static_release", {
                    "kind": "ROLLBACK" if value["type"] == "STATIC_ROLLBACK" else "PUBLISH",
                    "target_id": configured["target_id"], "target_revision": configured["id"],
                    "target": configured, "edition_id": selected["id"], "edition_sha256": selected["sha256"],
                    "pointer": after_pointer, "previous_release_id": (value["static_previous"] or {}).get("id"),
                    "restored_release_id": (value.get("static_rollback_to") or {}).get("id"),
                    "operation_id": value["id"], "plan_id": body["plan_id"], "review_id": body["review_id"],
                    "reason": value["reason"], "receipt": receipt, "reconciliation_context": reconciliation,
                }, parent=configured["target_id"], actor=current["author"],
                   object_id="static-release-" + value["id"])
                ws._set(db, "static.current:" + configured["target_id"], record["id"])
            current["native_result"] = result
            capture, artifacts = ws._capture_result_files(db, current, result, out)
            current.update(state="COMPLETE", native_attempted=False, actual_finished_at=receipt["completed_at"],
                           native_capture_file_id=capture["id"], retained_artifacts=list({(r["file"]["id"], r["role"]): r for r in [*current.get("retained_artifacts", []), *artifacts]}.values()),
                           static_result_id=record["id"], reconciliation_context=reconciliation, error=None,
                           progress={"completed": selected["file_count"], "total": selected["file_count"],
                                     "stage": "COMPLETE", "detail": "Complete static edition staged" if value["type"] == "STATIC_STAGE" else "Original atomic release selection retained"})
            ws._write_operation(db, current, current["author"], "Static release native result retained",
                                {"record_id": record["id"], "capture_file_id": capture["id"]})

"""Static output editions and releases in the original GovHub journal.

The native Tome owner supplies the completed capture. This module retains and
compares that capture; only the original worker changes a configured release.
"""
from __future__ import annotations
from pathlib import Path
import hashlib
import json
import os
import tempfile

from .model import canonical, sha, file_rows, validate_report, compare_rows, page, MAX_MANIFEST_BYTES

MAX_STORED_MANIFEST = 128 * 1024 * 1024
MUTATIONS = {"editions.receive", "targets.save", "plans.create", "reviews.save",
             "operations.create", "exports.create"}
STATIC_TYPES = {"STATIC_STAGE", "STATIC_PUBLISH", "STATIC_ROLLBACK"}


def problem(code, message, status=422):
    from govhub import GovHubError
    raise GovHubError(code, message, status)


def clean(value, limit=16000, required=False):
    from govhub import text
    return text(value, limit, required)


def _store_json(ws, db, value, name, actor, *, kind, owner):
    raw = canonical(value)
    if len(raw) > MAX_STORED_MANIFEST:
        problem("STATIC_MANIFEST_SIZE", "The complete retained manifest exceeds 128 MiB.", 413)
    ws.blobs.mkdir(parents=True, exist_ok=True, mode=0o700)
    fd, filename = tempfile.mkstemp(prefix=".static-", dir=ws.blobs)
    try:
        with os.fdopen(fd, "wb") as out:
            out.write(raw)
            out.flush()
            os.fsync(out.fileno())
        return ws._register(db, filename, name, actor, category="Generated",
                            label="Static release " + kind, owner_kind=kind,
                            owner_id=owner, output_name=name, expected_sha=sha(raw))
    finally:
        Path(filename).unlink(missing_ok=True)


def _json_file(ws, db, file_id, limit=MAX_STORED_MANIFEST):
    from govhub import json_bytes
    item = ws._file_row(db, file_id)
    if item["bytes"] > limit:
        problem("STATIC_MANIFEST_SIZE", "The retained manifest exceeds its supported size.", 413)
    return json_bytes(ws._verify_file(item).read_bytes()), item


def edition(ws, db, edition_id):
    return ws._get(db, "static_edition", edition_id)


def manifest(ws, db, value):
    data, item = _json_file(ws, db, value["manifest_file_id"])
    if item["sha256"] != value["manifest_sha256"] or data.get("edition_id") != value["id"]:
        problem("STATIC_EDITION_IDENTITY", "The edition's complete manifest changed.", 409)
    rows = file_rows(data.get("files"))
    if sha(canonical(rows)) != value["files_sha256"]:
        problem("STATIC_EDITION_IDENTITY", "The edition's path and byte identities changed.", 409)
    by_path = {r["path"]: r for r in data["files"]}
    return [dict(row, file_id=by_path[row["path"]]["file_id"]) for row in rows]


def target(ws, db, target_id, revision=None):
    head = ws._setting(db, "static.target:" + clean(target_id, 240, True))
    if not head:
        problem("STATIC_TARGET_NOT_FOUND", "Choose an existing static release target.", 404)
    value = ws._get(db, "static_target", revision or head)
    if value["target_id"] != target_id:
        problem("STATIC_TARGET_IDENTITY", "This target revision belongs to a different target.", 409)
    return value


def current_release(ws, db, target_id):
    ref = ws._setting(db, "static.current:" + target_id)
    return ws._get(db, "static_release", ref) if ref else None


def _expected_target(value, payload):
    if payload.get("expected_revision") != value["revision"]:
        problem("STATIC_TARGET_CHANGED", "The target configuration changed. Reopen its current version.", 409)


def _namespace(ws, db):
    from govhub import ident
    value = ws._setting(db, "static.namespace")
    if not value:
        value = ident("workspace-")
        ws._set(db, "static.namespace", value)
    return value


def _environment(ws, db, value):
    environment = ws._record_db(db, "environments", value["environment_id"])
    if environment["archived"] or not environment["data"]["authorization_reference"]:
        problem("STATIC_TARGET_AUTHORITY", "Select an active environment with its original operating authorization.", 409)
    if environment["data"]["provider_resource_id"] != value["provider_resource_id"]:
        problem("STATIC_ENVIRONMENT_CHANGED", "The release target's native environment identity changed.", 409)
    return environment


def _receive(ws, db, payload, actor):
    from govhub import ident
    value = ws._operation(db, payload.get("operation_id"))
    ws._expected(value, payload)
    if value["state"] != "COMPLETE" or (value.get("native_result") or {}).get("status") != "COMPLETE":
        problem("STATIC_BUILD_INCOMPLETE", "Complete the original native build before retaining its output edition.", 409)
    if value.get("profile", {}).get("config", {}).get("source_kind") != "tome":
        problem("STATIC_BUILD_SOURCE", "Choose the original Tome native capture.", 409)
    native = value["native_result"].get("artifacts", [])
    if not isinstance(native, list):
        problem("STATIC_BUILD_ARTIFACTS", "The native result has no complete artifact inventory.", 409)
    reports = [r for r in native if r.get("role") == "static_build_report"]
    if len(reports) != 1:
        problem("STATIC_BUILD_REPORT", "The completed native result must identify exactly one build report.", 409)
    retained = value.get("retained_artifacts", [])

    def binding(item):
        matches = [r for r in retained if r.get("role") == item.get("role")
                   and r.get("file", {}).get("sha256") == item.get("sha256")
                   and r.get("file", {}).get("bytes") == item.get("size", item.get("bytes"))
                   and r.get("native", {}).get("relative_path") == item.get("relative_path")]
        if not matches:
            problem("STATIC_ARTIFACT_MISSING", "A completed native artifact is missing from the original retained capture.", 409)
        row = ws._file_row(db, matches[-1]["file"]["id"])
        ws._verify_file(row)
        return row

    report_file = binding(reports[0])
    report, _ = _json_file(ws, db, report_file["id"], MAX_MANIFEST_BYTES)
    normalized = validate_report(report)
    assets = [r for r in native if r.get("role") == "static_asset"]
    by_path = {}
    for item in assets:
        path = item.get("relative_path")
        if not isinstance(path, str) or path in by_path:
            problem("STATIC_ARTIFACT_SET", "The completed output has repeated or missing relative paths.", 409)
        by_path[path] = item
    if set(by_path) != {r["path"] for r in normalized["files"]}:
        problem("STATIC_ARTIFACT_SET", "The build report and retained output must contain the same complete path set.", 409)
    existing = [e for e in ws._objects(db, "static_edition", value["id"])
                if e["report_sha256"] == report_file["sha256"]]
    if existing:
        return {"edition": existing[0], "reused": True}
    rows = []
    for row in normalized["files"]:
        item = binding(by_path[row["path"]])
        if (item["sha256"], item["bytes"]) != (row["sha256"], row["bytes"]):
            problem("STATIC_ARTIFACT_IDENTITY", "A generated file differs from the complete build report: " + row["path"], 409)
        rows.append(dict(row, file_id=item["id"]))
    identifier = ident("static-edition-")
    stored = _store_json(ws, db, {"schema": "govhub.static-edition-files.v1", "edition_id": identifier,
                        "operation_id": value["id"], "operation_revision": value["revision"],
                        "report_file_id": report_file["id"], "files": rows},
                        "output-manifest.json", actor, kind="static_edition", owner=identifier)
    sources = []
    for item in native:
        if item.get("role") != "static_asset":
            kept = binding(item)
            sources.append({"role": item.get("role"), "file_id": kept["id"],
                            "filename": kept["filename"], "bytes": kept["bytes"], "sha256": kept["sha256"]})
    if value.get("native_capture_file_id"):
        kept = ws._file_row(db, value["native_capture_file_id"])
        ws._verify_file(kept)
        sources.append({"role": "native_capture", "file_id": kept["id"], "filename": kept["filename"],
                        "bytes": kept["bytes"], "sha256": kept["sha256"]})
    result = ws._object(db, "static_edition", {
        "id": identifier, "schema": "govhub.static-edition.v1",
        "label": clean(payload.get("label", "Tome output"), 500, True),
        "environment_id": value["environment_id"], "operation_id": value["id"],
        "operation_revision": value["revision"], "native_capture_file_id": value.get("native_capture_file_id"),
        "report_file_id": report_file["id"], "report_sha256": report_file["sha256"],
        "manifest_file_id": stored["id"], "manifest_sha256": stored["sha256"],
        "files_sha256": normalized["files_sha256"], "file_count": len(rows),
        "total_bytes": sum(r["bytes"] for r in rows), "production_uri": normalized["production_uri"],
        "generator": normalized["generator"], "inputs": normalized["inputs"],
        "sources": sources, "completed_at": value.get("actual_finished_at"),
        "profile_revision": value["profile"]["revision"],
    }, parent=value["id"], actor=actor["name"])
    return {"edition": result, "reused": False}


def _save_target(ws, db, payload, actor):
    from govhub import ident
    from .native import inspect_target, verify_tree, target_lock
    ws._authorize(actor, "admin")
    old = target(ws, db, payload["target_id"]) if payload.get("target_id") else None
    if old:
        _expected_target(old, payload)
        fixed = ("environment_id", "release_root", "current_name")
        if any(payload.get(k, old[k]) != old[k] for k in fixed):
            problem("STATIC_TARGET_BINDING", "The saved target keeps its original environment and filesystem path. Configure a separate target for a different location.", 409)
        environment = _environment(ws, db, old)
        identity = {k: old[k] for k in ("target_id", "environment_id", "provider_resource_id",
                    "release_root", "root_device", "root_inode", "current_name", "namespace")}
        observed = inspect_target(old)
    else:
        environment = ws._record_db(db, "environments", payload.get("environment_id"))
        if environment["archived"] or not environment["data"]["authorization_reference"] or not environment["data"]["provider_resource_id"]:
            problem("STATIC_TARGET_AUTHORITY", "Choose an active original environment with its native identity and operating authorization.")
        root = Path(clean(payload.get("release_root", ""), 4000, True))
        if not root.is_absolute() or root.is_symlink() or not root.is_dir():
            problem("STATIC_TARGET_DIRECTORY", "Select an existing absolute local release directory.")
        root = root.resolve(strict=True)
        if root == ws.root or root.is_relative_to(ws.root) or ws.root.is_relative_to(root):
            problem("STATIC_TARGET_DIRECTORY", "Keep the selected release directory outside the private workspace and its ancestors.")
        info = root.stat()
        name = clean(payload.get("current_name", "current"), 200, True)
        if Path(name).name != name or name in (".", "..", ".govhub-static", ".govhub-static.lock") or "\\" in name:
            problem("STATIC_CURRENT_NAME", "Use one ordinary filename for the current release symlink.")
        target_id = ident("static-target-")
        identity = {"target_id": target_id, "environment_id": environment["id"],
                    "provider_resource_id": environment["data"]["provider_resource_id"],
                    "release_root": str(root), "root_device": info.st_dev, "root_inode": info.st_ino,
                    "current_name": name, "namespace": _namespace(ws, db) + "-" + target_id}
        for entry in ws._objects(db, "static_target"):
            if (entry["root_device"], entry["root_inode"], entry["current_name"]) == (info.st_dev, info.st_ino, name):
                problem("STATIC_TARGET_EXISTS", "This current pointer already belongs to retained target " + entry["target_id"] + ".", 409)
        observed = inspect_target(identity)
    value = dict(identity, label=clean(payload.get("label", old["label"] if old else ""), 500, True),
                 notes=clean(payload.get("notes", old.get("notes", "") if old else ""), 16000),
                 revision=ident("target-revision-"), environment_revision=environment["revision"])
    saved = ws._object(db, "static_target", value, parent=identity["target_id"], actor=actor["name"])
    if not old and observed["pointer"] is not None:
        baseline = edition(ws, db, payload.get("baseline_edition_id"))
        if baseline["environment_id"] != environment["id"]:
            problem("STATIC_BASELINE_ENVIRONMENT", "The existing pointer baseline must come from this original build environment.", 409)
        with target_lock(saved):
            current = inspect_target(saved)
            if current != observed:
                problem("STATIC_POINTER_CHANGED", "The selected current pointer changed during configuration.", 409)
            verify_tree(Path(current["resolved_path"]), manifest(ws, db, baseline))
        adopted = ws._object(db, "static_release", {
            "target_id": saved["target_id"], "target_revision": saved["id"],
            "kind": "ADOPTED", "edition_id": baseline["id"], "edition_sha256": baseline["sha256"],
            "pointer": observed["pointer"], "previous_release_id": None, "operation_id": None,
            "reason": "Existing pointer matched the complete original retained build edition",
            "target": saved, "plan_id": None, "review_id": None,
        }, parent=saved["target_id"], actor=actor["name"])
        ws._set(db, "static.current:" + saved["target_id"], adopted["id"])
    elif not old and payload.get("baseline_edition_id"):
        problem("STATIC_BASELINE_POINTER", "An absent current pointer has no existing output to adopt.")
    ws._set(db, "static.target:" + saved["target_id"], saved["id"])
    return {"target": saved, "observed": observed, "current_release": current_release(ws, db, saved["target_id"])}


def _create_plan(ws, db, payload, actor):
    from govhub import ident
    value = target(ws, db, payload.get("target_id"))
    _expected_target(value, payload)
    _environment(ws, db, value)
    before = current_release(ws, db, value["target_id"])
    if payload.get("expected_current_release_id") != (before["id"] if before else None):
        problem("STATIC_RELEASE_CHANGED", "The current retained release changed. Reopen the target before comparing.", 409)
    candidate = edition(ws, db, payload.get("candidate_id"))
    if candidate["environment_id"] != value["environment_id"]:
        problem("STATIC_EDITION_ENVIRONMENT", "Choose a complete edition from this target's original build environment.")
    baseline = edition(ws, db, before["edition_id"]) if before else None
    comparison = compare_rows(manifest(ws, db, baseline) if baseline else [], manifest(ws, db, candidate))
    identifier = ident("static-plan-")
    source = _store_json(ws, db, comparison, "comparison.json", actor, kind="static_plan", owner=identifier)
    saved = ws._object(db, "static_plan", {
        "id": identifier, "label": clean(payload.get("label", ""), 500, True),
        "notes": clean(payload.get("notes", ""), 16000), "target_id": value["target_id"],
        "target_revision": value["id"], "target_sha256": value["sha256"],
        "candidate_id": candidate["id"], "candidate_sha256": candidate["sha256"],
        "baseline_id": baseline["id"] if baseline else None,
        "baseline_sha256": baseline["sha256"] if baseline else None,
        "previous_release_id": before["id"] if before else None,
        "previous_release_sha256": before["sha256"] if before else None,
        "comparison_file_id": source["id"], "comparison_sha256": source["sha256"],
        "counts": comparison["counts"],
    }, parent=value["target_id"], actor=actor["name"])
    return {"plan": saved}


def _latest_review(ws, db, plan_id):
    rows = ws._objects(db, "static_review", plan_id)
    return rows[-1] if rows else None


def _review(ws, db, payload, actor):
    ws._authorize(actor, "reviewer")
    plan = ws._get(db, "static_plan", payload.get("plan_id"))
    if payload.get("comparison_sha256") != plan["comparison_sha256"]:
        problem("STATIC_COMPARISON_CHANGED", "Review the exact retained comparison for this plan.", 409)
    decision = payload.get("decision")
    if decision not in ("APPROVE", "RETURN"):
        problem("STATIC_REVIEW_DECISION", "Choose Approve or Return.")
    saved = ws._object(db, "static_review", {
        "plan_id": plan["id"], "plan_sha256": plan["sha256"],
        "comparison_sha256": plan["comparison_sha256"], "decision": decision,
        "reason": clean(payload.get("reason", ""), 12000, True),
    }, parent=plan["id"], actor=actor["name"])
    return {"review": saved, "plan": plan}


def _queue(ws, db, payload, actor):
    from govhub import ident, now
    kind = payload.get("type")
    if kind not in STATIC_TYPES:
        problem("STATIC_OPERATION_TYPE", "Choose Stage, Publish, or Roll back the retained predecessor.")
    selected_target = target(ws, db, payload.get("target_id"))
    _expected_target(selected_target, payload)
    environment = _environment(ws, db, selected_target)
    previous = current_release(ws, db, selected_target["target_id"])
    if payload.get("expected_current_release_id") != (previous["id"] if previous else None):
        problem("STATIC_RELEASE_CHANGED", "The current release changed. Reopen the selected target.", 409)
    plan = review = baseline = None
    if kind == "STATIC_ROLLBACK":
        if not previous or not previous.get("previous_release_id"):
            problem("STATIC_PREDECESSOR", "The selected current release has no retained predecessor.", 409)
        baseline = ws._get(db, "static_release", previous["previous_release_id"])
        selected_edition = edition(ws, db, baseline["edition_id"])
    else:
        plan = ws._get(db, "static_plan", payload.get("plan_id"))
        if (plan["target_id"], plan["target_revision"], plan["previous_release_id"]) != (selected_target["target_id"], selected_target["id"], previous["id"] if previous else None):
            problem("STATIC_PLAN_CHANGED", "Create a comparison against the current target and release before staging or publishing.", 409)
        selected_edition = edition(ws, db, plan["candidate_id"])
        review = _latest_review(ws, db, plan["id"])
        if kind == "STATIC_PUBLISH":
            if not review or review["decision"] != "APPROVE":
                problem("STATIC_REVIEW_REQUIRED", "Review this complete path comparison before publication.", 409)
            stages = ws._objects(db, "static_stage", plan["id"])
            if not stages:
                problem("STATIC_STAGE_REQUIRED", "Stage this complete edition on the configured target first.", 409)
    for row in db.execute("SELECT data FROM govhub_operations WHERE state NOT IN ('COMPLETE','FAILED','CANCELLED')"):
        operation = json.loads(row[0])
        if operation.get("static_target_id") == selected_target["target_id"]:
            problem("STATIC_TARGET_BUSY", "Finish or cancel the original active static operation for this target.", 409)
    timestamp = now()
    operation = {
        "id": ident("operation-"), "type": kind, "state": "QUEUED",
        "plan_id": "", "plan_revision": "", "plan": None, "audit_id": None,
        "review_id": review["id"] if review else None,
        "environment_id": environment["id"], "environment": environment,
        "profile": {"revision": selected_target["revision"], "config": {
            "source_kind": "static-release", "environment_id": environment["data"]["provider_resource_id"]}},
        "source_snapshot_id": "", "source_snapshot": None, "source_snapshot_sha256": "",
        "authorization_reference": environment["data"]["authorization_reference"],
        "created_at": timestamp, "updated_at": timestamp, "author": actor["name"],
        "queued_actor": actor, "progress": {"completed": 0, "total": selected_edition["file_count"],
            "stage": "QUEUED", "detail": "Queued on the original GovHub release worker"},
        "error": None, "cancel_requested": False, "native_attempted": False,
        "checkpoint": None, "resume_checkpoint": None, "native_capture_file_id": None,
        "native_result": None, "result_snapshot_id": None, "actual_started_at": None,
        "actual_finished_at": None, "native_action": kind.lower().replace("_", "-"),
        "provider_environment_id": environment["data"]["provider_resource_id"], "agency_ids": [],
        "target_fingerprint": sha(canonical(selected_target)),
        "static_target_id": selected_target["target_id"], "static_target": selected_target,
        "static_plan": plan, "static_review": review, "static_edition": selected_edition,
        "static_previous": previous, "static_rollback_to": baseline,
        "reason": clean(payload.get("reason", ""), 12000, True),
    }
    saved = ws._write_operation(db, operation, actor, "Static release operation queued",
                                {"type": kind, "edition_id": selected_edition["id"], "target_id": selected_target["target_id"]})
    return {"operation": saved}


def _get_plan(ws, db, payload):
    plan = ws._get(db, "static_plan", payload.get("plan_id"))
    comparison, item = _json_file(ws, db, plan["comparison_file_id"])
    if item["sha256"] != plan["comparison_sha256"]:
        problem("STATIC_COMPARISON_IDENTITY", "The retained comparison source changed.", 409)
    values = page(comparison["rows"], payload)
    value = target(ws, db, plan["target_id"])
    current = current_release(ws, db, plan["target_id"])
    return {"plan": plan, "comparison": dict(values, counts=comparison["counts"]),
            "reviews": ws._objects(db, "static_review", plan["id"]),
            "stages": ws._objects(db, "static_stage", plan["id"]),
            "target": value, "current_release": current,
            "current": plan["target_revision"] == value["id"] and plan["previous_release_id"] == (current["id"] if current else None)}


def summaries(ws, db):
    targets = []
    for row in db.execute("SELECT value FROM govhub_settings WHERE key LIKE 'static.target:%' ORDER BY key"):
        value = ws._get(db, "static_target", json.loads(row[0]))
        targets.append(dict(value, current_release=current_release(ws, db, value["target_id"])))
    builds = []
    for row in db.execute("SELECT data FROM govhub_operations ORDER BY rowid DESC"):
        operation = json.loads(row[0])
        if operation.get("profile", {}).get("config", {}).get("source_kind") == "tome":
            builds.append(ws._operation_summary(operation))
    return {
        "targets": targets, "builds": builds,
        "editions": list(reversed(ws._objects(db, "static_edition"))),
        "plans": [dict(p, latest_review=_latest_review(ws, db, p["id"]))
                  for p in reversed(ws._objects(db, "static_plan"))],
        "releases": list(reversed(ws._objects(db, "static_release"))),
        "exports": list(reversed(ws._objects(db, "static_export"))),
    }


def dispatch(ws, action, payload, actor):
    from govhub import packed
    name = action.removeprefix("static.")
    if name == "targets.inspect":
        from .native import inspect_target
        with ws.connect(snapshot=True) as db:
            selected = target(ws, db, payload.get("target_id"))
            return {"target": selected, "current_release": current_release(ws, db, selected["target_id"]),
                    "observed": inspect_target(selected)}
    if name not in MUTATIONS:
        with ws.connect(snapshot=True) as db:
            if name == "list":
                return summaries(ws, db)
            if name == "editions.get":
                value = edition(ws, db, payload.get("edition_id"))
                return {"edition": value, "files": page(manifest(ws, db, value), payload)}
            if name == "plans.get":
                return _get_plan(ws, db, payload)
            if name == "targets.get":
                value = target(ws, db, payload.get("target_id"), payload.get("revision"))
                return {"target": value, "current_release": current_release(ws, db, value["target_id"]),
                        "history": ws._objects(db, "static_target", value["target_id"]),
                        "releases": ws._objects(db, "static_release", value["target_id"])}
            if name == "exports.get":
                return {"export": ws._get(db, "static_export", payload.get("export_id"))}
            if name == "requests.get":
                key = clean(payload.get("request_key", ""), 240, True)
                row = db.execute("SELECT result,author FROM govhub_requests WHERE request_key=?", (key,)).fetchone()
                if not row or row["author"] != actor["name"]:
                    problem("REQUEST_NOT_FOUND", "No completed original request exists for this account.", 404)
                return {"request_key": key, "result": json.loads(row["result"])}
            problem("STATIC_ACTION_NOT_FOUND", "This static release action does not exist.", 404)
    if name == "exports.create":
        from .exporting import create_export
        return create_export(ws, payload, actor)
    with ws.connect(write=True) as db:
        bound = dict(payload, static_action=name)
        key, fingerprint, prior = ws._request(db, bound, actor)
        if prior is not None:
            return dict(prior, replayed=True)
        handlers = {"editions.receive": _receive, "targets.save": _save_target,
                    "plans.create": _create_plan, "reviews.save": _review, "operations.create": _queue}
        result = handlers[name](ws, db, payload, actor)
        ws._remember(db, key, fingerprint, result, actor)
        ws._changed(db, actor, "Static release " + name, details={"request_key": key})
    if name == "operations.create":
        ws._worker_wake.set()
    return result

