    return [{"value": "upsun-" + action, "label": LABELS[action],
             "required_profile_fields": required.get(action, [])}
            for action in KINDS.get(kind, [])]


def pollable(resume):
    pending = resume.get("native_poll") or {}
    return resume.get("phase") == "accepted" and pending.get("provider") == "upsun" and bool(pending.get("ids"))


def resume_fields(operation, payload, reason):
    if not str(operation.get("native_action", "")).startswith("upsun-"):
        raise ValueError("These continuation fields belong to the original Upsun operation.")
    result = {}
    if "runtime_bindings" in payload:
        bindings = payload["runtime_bindings"]
        selected = profile(operation["profile"]["config"], bindings)
        result["runtime_bindings"] = {k: selected.get(k, "") for k in RUNTIME_FIELDS if k in bindings}
    if payload.get("upsun_activity_id") or payload.get("upsun_activity_ids_json"):
        selected = json.loads(payload["upsun_activity_ids_json"]) if payload.get("upsun_activity_ids_json") else [payload["upsun_activity_id"]]
        if not isinstance(selected, list) or not selected or len(selected) > 1000:
            raise ValueError("Select the actual complete original activity ID array.")
        ids = [_id(value, "activity ID") for value in selected]
        if len(ids) != len(set(ids)):
            raise ValueError("Select every original activity once.")
        if payload.get("upsun_activity_id") and payload["upsun_activity_id"] not in ids:
            raise ValueError("The primary activity must belong to the original selected set.")
        state = operation.get("resume_checkpoint") or {}
        if state.get("phase") not in {"dispatching", "native_interrupted", "accepted"}:
            raise ValueError("Join actual activities only to their original unfinished dispatch.")
        existing = state.get("native_poll", {}).get("ids", [])
        if existing and set(ids) != set(existing):
            raise ValueError("The original accepted activity set cannot be replaced.")
        staged = set(state.get("before_staged_activity_ids", []))
        for selected_id in ids:
            if selected_id in state.get("before_activity_ids", []) and not (
                    operation.get("native_action") == "upsun-deploy" and selected_id in staged):
                raise ValueError("The selected activity predates the original dispatch.")
        result["upsun_activity_association"] = {"id": ids[0], "ids": ids, "reason": str(reason),
                                               "request_sha256": state.get("request_sha256")}
    return result

def _read_json(path):
    return json.loads(Path(path).read_bytes())


def _state(s, supplied=None):
    path = s.out / "native-state.json"
    saved = s.read_private_json(path) if path.exists() else supplied or {}
    saved = saved.get("resume_checkpoint", saved.get("state", saved))
    s.state = dict(s.resolve_private(saved))
    if s.state.get("provider") not in (None, "upsun"):
        raise ValueError("This native output directory belongs to another provider.")
    s.state["provider"] = "upsun"


def _intent(s, value):
    digest = _api()._digest(value)
    if s.state.get("intent_sha256") not in (None, digest):
        raise ValueError("The saved Upsun operation belongs to another reviewed instruction.")
    s.state.update(intent=value, intent_sha256=digest)
    s.save_state()


def _retain(s, path, role, **extra):
    item = s.add(path, role, **extra)
    if not any(x["path"] == item["path"] for x in s.state.setdefault("retained_artifacts", [])):
        s.state["retained_artifacts"].append(item)
    return item


def _json_file(s, name, value, role):
    path = s.out / name
    if path.exists() and _read_json(path) != value:
        path = path.with_name(path.stem + "-" + _api()._digest(value) + path.suffix)
    _api()._atomic(path, value)
    return _retain(s, path, role)


def _delay(headers):
    value = headers.get("retry-after", "")
    try:
        return max(1, int(value))
    except (ValueError, TypeError):
        try:
            return max(1, int((parsedate_to_datetime(value) - datetime.now(timezone.utc)).total_seconds()))
        except (ValueError, TypeError):
            return 15



def _base(s):
    return "/projects/" + _segment(s.p["project_id"])


def _environment_path(s, environment_id=None):
    return _base(s) + "/environments/" + _segment(environment_id or s.p["native_environment_id"])


def _url(s, path):
    """Only the selected project on the current central API receives credentials."""
    value = parse.urlsplit(parse.urljoin(API_BASE + "/", path))
    hostname = value.hostname or ""
    provider_host = hostname == "api.upsun.com" or hostname.endswith(".platform.sh") or hostname.endswith(".upsun.com")
    native_path = value.path[4:] if value.path.startswith("/api/projects/") else value.path
    if (value.scheme != "https" or not provider_host or value.port not in (None, 443)
            or value.username or value.password or value.fragment
            or not (native_path == _base(s) or native_path.startswith(_base(s) + "/"))):
        raise ValueError("The request must remain on this exact current Upsun project.")
    # The official client likewise retains the configured API authority for HAL references.
    return parse.urlunsplit(("https", "api.upsun.com", native_path, value.query, ""))


def _credential(s):
    key = "access_token_env" if s.p.get("access_token_env") else "api_token_env"
    value = os.environ.get(s.p[key], "")
    if not value or any(c in value for c in ("\r", "\n", "\x00")):
        raise _api().NativeWaiting("The original credential variable is empty or invalid on this host.")
    return key, value


def _auth_body(response):
    expected = getattr(response, "length", None)
    if expected is None:
        expected = getattr(getattr(response, "fp", None), "length", None)
    declared = response.headers.get("Content-Length")
    if expected is None and declared is not None and "chunked" not in response.headers.get("Transfer-Encoding", "").lower():
        expected = int(declared)
    if expected is not None and (type(expected) is not int or expected < 0 or expected > 1048576):
        raise ValueError("The native token response has an invalid declared length.")
    data = response.read(1048577)
    if len(data) > 1048576 or (expected is not None and len(data) != expected):
        raise IOError("The native token response is incomplete or exceeds its bound.")
    return data


def _token(s):
    kind, value = _credential(s)
    if kind == "access_token_env":
        return value
    fingerprint = hashlib.sha256((AUTH_URL + "\x00" + value).encode()).hexdigest()
    cached = _TOKENS.get(fingerprint)
    if cached and cached["expires_at"] > time.time() + 30:
        return cached["token"]
    payload = parse.urlencode({"grant_type": "api_token", "api_token": value}).encode()
    headers = {"Authorization": "Basic " + base64.b64encode(b"platform-api-user:").decode(),
               "Content-Type": "application/x-www-form-urlencoded",
               "Accept": "application/json", "Accept-Encoding": "identity"}
    req = request.Request(AUTH_URL, data=payload, headers=headers, method="POST")
    try:
        with request.build_opener(_api().NoRedirect).open(req, timeout=s.p["timeout_seconds"]) as response:
            data = _auth_body(response)
            native = json.loads(data)
            if response.status != 200 or not isinstance(native, dict) or not native.get("access_token"):
                raise ValueError("The current Upsun account did not return an access token.")
            if not isinstance(native["access_token"], str) or any(c in native["access_token"] for c in ("\r", "\n", "\x00")):
                raise ValueError("The original access token has an invalid native representation.")
            if str(native.get("token_type", "bearer")).lower() != "bearer":
                raise ValueError("Unexpected native token type.")
            expiry = native.get("expires_in")
            if type(expiry) not in (int, float) or expiry <= 0:
                raise ValueError("The original token response has no valid expiry.")
            _TOKENS[fingerprint] = {"token": native["access_token"], "expires_at": time.time() + expiry}
            s.event({"kind": "upsun_auth", "url": AUTH_URL, "status": response.status,
                     "credential_reference": s.p[kind], "expires_in": expiry,
                     "response_bytes": len(data), "observed_at": _api()._now()})
            return native["access_token"]
    except error.HTTPError as exc:
        retained_headers = {k.lower(): v for k, v in exc.headers.items()
                            if k.lower() not in {"set-cookie", "authorization"}}
        if exc.code in {429, 503}:
            _provider_deadline(s, {"url": AUTH_URL, "status": exc.code,
                                  "response_headers": retained_headers})
        facts = {"kind": "upsun_auth", "url": AUTH_URL, "status": exc.code,
                 "credential_reference": s.p[kind], "response_headers": retained_headers,
                 "observed_at": _api()._now()}
        try:
            body = _auth_body(exc)
            facts.update(response_bytes=len(body), response_sha256=hashlib.sha256(body).hexdigest(),
                         body_complete=True)
        except Exception as body_error:
            facts.update(body_complete=False, body_error=type(body_error).__name__)
        finally:
            exc.close()
        s.event(facts)
        raise _api().NativeWaiting("The original Upsun token exchange returned HTTP " + str(exc.code) + ".") from None


def _provider_deadline(s, response=None, url=None):
    kind, value = _credential(s)
    identity = hashlib.sha256((API_BASE + "\x00" + value).encode()).hexdigest()
    root = Path(os.environ.get("XDG_STATE_HOME", str(Path.home() / ".local" / "state")))
    if not root.is_absolute():
        raise ValueError("The native provider state directory must be absolute.")
    root = root / "tjl-govhub" / "upsun"
    root.mkdir(mode=0o700, parents=True, exist_ok=True)
    if root.is_symlink():
        raise ValueError("Use an ordinary native provider state directory.")
    path, lock = root / (identity + ".json"), root / (identity + ".lock")
    with lock.open("a+b") as guard:
        os.chmod(lock, 0o600)
        fcntl.flock(guard.fileno(), fcntl.LOCK_EX)
        current = _read_json(path) if path.exists() else {}
        account = max(float(current.get("not_before", 0)), float(s.state.get("provider_not_before", 0)))
        resources = s.state.setdefault("provider_resource_deadlines", {})
        if response is not None:
            headers = response.get("response_headers", {})
            if response.get("status") in {429, 503} or "retry-after" in headers:
                observed = time.time() + _delay(headers)
                if response.get("status") in {429, 503}:
                    account = max(account, observed)
                    _api()._atomic(path, {"authority": API_BASE, "not_before": account,
                                         "observed_at": _api()._now(), "status": response.get("status"),
                                         "url": response.get("url"),
                                         "retry_after": headers.get("retry-after")})
                else:
                    resource = response["url"]
                    resources[resource] = max(float(resources.get(resource, 0)), observed)
        s.state["provider_not_before"] = account
        selected = url or (response or {}).get("url")
        deadline = max(account, float(resources.get(selected, 0)))
        s.state["provider_request_not_before"] = deadline
        s.state["provider_request_url"] = selected
        s.state["poll_after_seconds"] = max(1, int(deadline - time.time() + 1)) if deadline > time.time() else 0
        s.save_state()
    return deadline


def _http(s, label, path, method="GET", body=None, accept="application/json"):
    """One actual request; complete original body/headers or retained uncertainty."""
    s.check()
    url = _url(s, path)
    deadline = _provider_deadline(s, url=url)
    if time.time() < deadline:
        raise _api().NativeWaiting("Continue after the original Upsun Retry-After deadline: " +
                                   datetime.fromtimestamp(deadline, timezone.utc).isoformat())
    token = _token(s)  # Before the mutation admission record; never replay POST after a 401.
    payload = None if body is None else json.dumps(body, sort_keys=True, separators=(",", ":"), ensure_ascii=False).encode()
    stem = s.out / (label + "-" + str(time.time_ns()))
    body_path, record_path = Path(str(stem) + ".response"), Path(str(stem) + ".http.json")
    record = {"schema": VERSION, "method": method, "url": url, "started_at": _api()._now(),
              "complete": False, "status": None, "response_headers": {},
              "request_sha256": hashlib.sha256(payload or b"").hexdigest()}
    if payload is not None:
        original = Path(str(stem) + ".input.json")
        original.write_bytes(payload)
        os.chmod(original, 0o600)
        record["input"] = _retain(s, original, "native_request_body")
    _api()._atomic(record_path, record)
    if method != "GET":
        s.state.update(phase="dispatching", mutation_started=True,
                       dispatch_record=str(record_path), dispatch_path=str(body_path),
                       dispatched_at=record["started_at"])
        s.save_state()
    headers = {"Authorization": "Bearer " + token, "Accept": accept,
               "Accept-Encoding": "identity", "User-Agent": "TJL-GovHub-Upsun/1"}
    if payload is not None:
        headers["Content-Type"] = "application/json"
    req = request.Request(url, data=payload, headers=headers, method=method)
    try:
        try:
            response = request.build_opener(_api().NoRedirect).open(req, timeout=s.p["timeout_seconds"])
        except error.HTTPError as exc:
            response = exc
        record.update(status=response.code,
                      response_header_items=list(response.headers.items()),
                      response_headers={k.lower(): v for k, v in response.headers.items()})
        _provider_deadline(s, record)
        encoding = record["response_headers"].get("content-encoding", "identity").lower()
        if encoding not in {"", "identity"}:
            # Retain any encoded original body; JSON parsing then reports its actual encoding.
            record["content_encoding"] = encoding
        expected = getattr(response, "length", None)
        if expected is None:
            expected = getattr(getattr(response, "fp", None), "length", None)
        declared = record["response_headers"].get("content-length")
        if expected is None and declared is not None and "chunked" not in record["response_headers"].get("transfer-encoding", "").lower():
            expected = int(declared)
        if expected is not None and (type(expected) is not int or expected < 0):
            raise ValueError("The original HTTP response has an invalid length.")
        record["expected_body_bytes"] = expected
        count = 0
        with response, body_path.open("wb") as stream:
            os.chmod(body_path, 0o600)
            while True:
                s.check()
                chunk = response.read(1024 * 1024)
                if not chunk:
                    break
                count += len(chunk)
                if count > s.p["max_artifact_bytes"]:
                    raise ValueError("The native response exceeds the configured artifact bound.")
                stream.write(chunk)
                record["received_body_bytes"] = count
            stream.flush()
            os.fsync(stream.fileno())
        if expected is not None and count != expected:
            raise IOError("The native HTTP body ended before its declared length.")
        record.update(complete=True, completed_at=_api()._now(), received_body_bytes=count)
    except BaseException as exc:
        record.update(error={"type": type(exc).__name__, "message": str(exc)}, completed_at=_api()._now())
        if body_path.is_file():
            record["response"] = _api()._file(body_path, "provider_response_partial")
        _api()._atomic(record_path, record)
        _retain(s, record_path, "provider_http_record")
        if body_path.is_file():
            _retain(s, body_path, "provider_response_partial")
        if method != "GET":
            s.state["phase"] = "native_interrupted"
            s.save_state()
        raise
    record["response"] = _retain(s, body_path, "provider_response")
    _api()._atomic(record_path, record)
    _retain(s, record_path, "provider_http_record")
    s.event({"kind": "upsun_http", "method": method, "path": parse.urlsplit(url).path,
             "status": record["status"], "record": str(record_path), "complete": True})
    return record


def _value(result, expected=(200,)):
    if not result.get("complete"):
        raise _api().NativeWaiting("Continue the retained original incomplete response.")
    if result["status"] not in expected:
        if result["status"] in {401, 429, 503}:
            raise _api().NativeWaiting("Upsun returned HTTP " + str(result["status"]) +
                                       "; retain the same operation and its actual response.")
        raise ValueError("Upsun returned HTTP " + str(result["status"]) + "; inspect the original response.")
    if result.get("content_encoding"):
        raise ValueError("The original response used " + result["content_encoding"] +
                         "; its complete encoded bytes are retained.")
    value = _read_json(result["response"]["path"])
    if not isinstance(value, (dict, list)):
        raise ValueError("The native response is not a JSON object or collection.")
    return value


def _object(value, native_id, label):
    if not isinstance(value, dict) or value.get("id") != native_id:
        raise ValueError("The returned original " + label + " identity differs.")
    return value


def _next_link(s, response, value):
    candidates = []
    if isinstance(value, dict):
        link = value.get("_links", {}).get("next")
        if isinstance(link, dict) and link.get("href"):
            candidates.append(link["href"])
    for key, header in response.get("response_header_items", []):
        if key.lower() == "link":
            for part in re.split(r",(?=\s*<)", header):
                match = re.match(r'\s*<([^>]+)>\s*;(.*)', part)
                if match and re.search(r'\brel\s*=\s*["\']?next(?:["\';\s]|$)', match[2]):
                    candidates.append(match[1])
    if not candidates:
        return None
    urls = {_url(s, parse.urljoin(response["url"], item)) for item in candidates}
    if len(urls) != 1:
        raise ValueError("The native next-page links disagree.")
    return urls.pop()


def _collection(s, label, path, collection_name):
    items, pages, seen = [], [], set()
    current = _url(s, path)
    while current:
        s.check()
        if current in seen:
            raise ValueError("The native collection repeats an opaque page URL.")
        seen.add(current)
        response = _http(s, label + "-page-" + str(len(pages)), current)
        value = _value(response)
        if isinstance(value, list):
            rows = value
        elif isinstance(value, dict):
            rows = value.get("_embedded", {}).get(collection_name)
            if rows is None:
                rows = value.get("items")
        else:
            rows = None
        if not isinstance(rows, list) or any(not isinstance(row, dict) for row in rows):
            raise ValueError("The original " + collection_name + " response is not a native collection.")
        items.extend(rows)
        pages.append({"url": response["url"], "response": response["response"], "count": len(rows)})
        current = _next_link(s, response, value)
    ids = [row.get("id") for row in items]
    if any(not isinstance(native_id, str) or not native_id for native_id in ids) or len(ids) != len(set(ids)):
        raise ValueError("The complete native collection has missing or repeated identities.")
    _json_file(s, label + "-pages.json", {"pages": pages, "total": len(items)}, "native_collection_pages")
    return items


def _inventory(s, label):
    project = _object(_value(_http(s, label + "-project", _base(s))), s.p["project_id"], "project")
    environments = _collection(s, label + "-environments", _base(s) + "/environments", "environments")
    environment = _object(_value(_http(s, label + "-environment", _environment_path(s))),
                          s.p["native_environment_id"], "environment")
    if environment.get("project") not in (None, s.p["project_id"]):
        raise ValueError("The selected environment names another project.")
    if environment["id"] not in {row["id"] for row in environments}:
        raise ValueError("The selected environment is absent from this original project.")
    backups = _collection(s, label + "-backups", _environment_path(s) + "/backups", "backups")
    activities = _collection(s, label + "-activities", _base(s) + "/activities", "activities")
    staged_activities = _collection(s, label + "-staged-activities",
                                    _environment_path(s) + "/activities?state=staged", "activities")
    deployments = _collection(s, label + "-deployments", _environment_path(s) + "/deployments", "deployments")
    response = _http(s, label + "-current-deployment", _environment_path(s) + "/deployments/current")
    current = None if response.get("complete") and response.get("status") == 404 else _value(response)
    if current is not None and not isinstance(current, dict):
        raise ValueError("The native current deployment is not an object.")
    parent_environment, parent_deployment, parent_deployment_status = None, None, None
    if environment.get("parent"):
        parent_id = _id(environment["parent"], "parent environment")
        parent_environment = _object(_value(_http(s, label + "-parent",
                                                  _environment_path(s, parent_id))),
                                     parent_id, "parent environment")
        parent_response = _http(s, label + "-parent-deployment",
                                _environment_path(s, parent_id) + "/deployments/current")
        parent_deployment_status = parent_response["status"]
        parent_deployment = (None if parent_response.get("complete") and parent_deployment_status == 404
                             else _value(parent_response))
    inventory = {"project": project, "environment": environment, "environments": environments,
                 "backups": backups, "activities": activities, "staged_activities": staged_activities, "deployments": deployments,
                 "current_deployment": current, "current_deployment_status": response["status"],
                 "parent_environment": parent_environment, "parent_current_deployment": parent_deployment,
                 "parent_current_deployment_status": parent_deployment_status,
                 "observed_at": _api()._now()}
    _json_file(s, label + "-inventory.json", inventory, "provider_inventory")
    return inventory


def _action_link(resource, action, expected):
    relation = resource.get("_links", {}).get("#" + action)
    if not isinstance(relation, dict) or not isinstance(relation.get("href"), str):
        raise ValueError("The current native resource does not offer the selected " + action + " operation.")
    original = parse.urlsplit(relation["href"])
    if original.query or original.fragment:
        raise ValueError("The native action link has additional parameters requiring its original review.")
    path = original.path
    # Regional HAL references use /api/projects; dispatch remains on the official central origin.
    if path.startswith("/api/projects/"):
        path = path[4:]
    if path != expected:
        raise ValueError("The original native action link names a different resource.")
    meta = relation.get("meta")
    if isinstance(meta, dict) and meta.get("method") and str(meta["method"]).upper() != "POST":
        raise ValueError("The original native action uses a different HTTP method.")
    return relation


def _source(s, inventory):
    from upsun_source import capture_source
    selection = dict(s.p)
    if not selection.get("source_revision"):
        selection["source_revision"] = inventory["environment"].get("head_commit")
    value = capture_source(s, inventory, selection)
    if not isinstance(value, dict):
        raise ValueError("The complete native source receiver returned no source manifest.")
    for item in list(s.artifacts):
        if not any(x["path"] == item["path"] for x in s.state.setdefault("retained_artifacts", [])):
            s.state["retained_artifacts"].append(item)
    s.state["source"] = value
    s.save_state()
    return value


def _source_binding(inventory, action):
    result = {"environment_id": inventory["environment"]["id"],
              "head_commit": inventory["environment"].get("head_commit"),
              "deployment_id": (inventory.get("current_deployment") or {}).get("id")}
    if action in {"merge", "synchronize"}:
        parent = inventory.get("parent_environment") or {}
        result["parent"] = {"id": inventory["environment"].get("parent"),
                            "observed_id": parent.get("id"), "head_commit": parent.get("head_commit"),
                            "deployment_id": (inventory.get("parent_current_deployment") or {}).get("id")}
    if action == "deploy":
        result["staged_activities"] = sorted(row["id"] for row in inventory["staged_activities"]
            if row.get("state") == "staged" and inventory["environment"]["id"] in row.get("environments", []))
    return result


def _request_body(s, action, operation, inventory):
    p, environment = s.p, inventory["environment"]
    endpoint = "backup" if action == "backup-create" else "restore" if action == "restore-backup" else action
    expected_head = p.get("source_revision")
    if action != "backup-create" and not expected_head:
        raise ValueError("Select the reviewed original source commit before this lifecycle operation.")
    if expected_head and environment.get("head_commit") != expected_head:
        raise ValueError("The selected native environment no longer has the reviewed original commit.")
    purpose = operation["type"]
    if purpose == "PREVIEW" and action != "branch" and (
            environment.get("type") == "production" or environment.get("is_main")):
        raise ValueError("Preview activation and redeployment require an actual nonproduction environment.")
    path = _environment_path(s) + "/" + endpoint
    resource = environment
    body = None
    affected = [environment["id"]]
    if action == "branch":
        name = _id(p.get("branch_name"), "new child name")
        title = p.get("branch_title")
        if not isinstance(title, str) or not title.strip() or len(title) > 1024:
            raise ValueError("Supply the reviewed native child title.")
        if any(row.get("id") == name or row.get("name") == name for row in inventory["environments"]):
            raise ValueError("The selected child already exists. Continue its original operation or select it directly.")
        body = {"name": name, "title": title, "clone_parent": p["clone_parent"], "type": p["branch_type"]}
        affected.append(name)
    elif action in {"synchronize", "merge"}:
        parent = p.get("parent_environment_id")
        if not parent or environment.get("parent") != parent:
            raise ValueError("Select the exact current parent for this reviewed native operation.")
        original_parent = next((row for row in inventory["environments"] if row["id"] == parent), None)
        if original_parent is None:
            raise ValueError("The reviewed parent is missing from the actual project.")
        affected.append(parent)
        if action == "synchronize":
            if not any(p[k] for k in ("synchronize_code", "synchronize_data", "synchronize_resources")):
                raise ValueError("Choose the actual code, data or resource synchronization.")
            if p["rebase"] and not p["synchronize_code"]:
                raise ValueError("The rebase option requires code synchronization.")
            body = {k: p[k] for k in ("synchronize_code", "synchronize_data", "synchronize_resources", "rebase")}
        else:
            body = {}
    elif action == "backup-create":
        body = {"safe": p["safe_backup"]}
    elif action == "restore-backup":
        backup = next((row for row in inventory["backups"] if row["id"] == p.get("backup_id")), None)
        if backup is None or backup.get("environment") != environment["id"]:
            raise ValueError("Select the actual original snapshot belonging to this environment.")
        if backup.get("restorable") is not True or backup.get("status") != "CREATED":
            raise ValueError("The selected native snapshot is not currently restorable.")
        resource = _object(_value(_http(s, "selected-backup",
                            _environment_path(s) + "/backups/" + _segment(backup["id"]))),
                           backup["id"], "backup")
        path = _environment_path(s) + "/backups/" + _segment(backup["id"]) + "/restore"
        body = {"restore_code": p["restore_code"], "restore_resources": p["restore_resources"]}
        if resource.get("environment") != environment["id"] or resource.get("restorable") is not True or resource.get("status") != "CREATED":
            raise ValueError("The selected snapshot changed before the original restore request.")
        s.state["selected_backup"] = resource
    elif action == "deploy":
        if p["deployment_strategy"] == "rolling" and environment.get("can_rolling_deploy") is not True:
            raise ValueError("The original environment does not offer rolling deployment.")
        if not _source_binding(inventory, action)["staged_activities"]:
            raise ValueError("The selected environment has no original staged activities to deploy.")
        body = {"strategy": p["deployment_strategy"]}
    elif action == "activate":
        body = {}
    elif action != "redeploy":
        raise ValueError("Unknown original Upsun lifecycle action.")
    init = p.get("resources_init")
    if init:
        allowed = {"branch": {"default", "minimum", "parent"},
                   "activate": {"default", "minimum", "parent"},
                   "merge": {"child", "default", "manual", "minimum"},
                   "restore-backup": {"backup", "default", "minimum", "parent"}}
        if init not in allowed.get(action, set()):
            raise ValueError("This resource initialization is not declared for the selected native action.")
        body["resources"] = {"init": init}
    link = _action_link(resource, endpoint, path)
    s.state["affected_environment_ids"] = affected
    s.state["native_action_link"] = link
    return path, body


def _activity(s, row, action, *, association=False, primary=False):
    native_id = _id(row.get("id"), "activity") if isinstance(row, dict) else None
    if not native_id or row.get("project") != s.p["project_id"]:
        raise ValueError("The actual activity belongs to another project.")
    environments = row.get("environments")
    if not isinstance(environments, list) or not set(environments).intersection(s.state["affected_environment_ids"]):
        raise ValueError("The actual activity does not involve this original selected environment.")
    staged = action == "deploy" and native_id in s.state.get("before_staged_activity_ids", [])
    if association or primary:
        if not staged and row.get("type") not in ACTIVITY_TYPES[action]:
            raise ValueError("The selected activity has a different native lifecycle purpose.")
    if association:
        if native_id in s.state.get("before_activity_ids", []) and not staged:
            raise ValueError("The selected activity existed before this original operation.")
        parameters = row.get("parameters") or {}
        if not isinstance(parameters, dict):
            raise ValueError("The native activity parameters are not an object.")
        body = s.state["request"].get("body") or {}
        matched, omitted = [], []
        for key, expected in body.items():
            if key in parameters:
                if parameters[key] != expected:
                    raise ValueError("The native activity contradicts the reviewed parameter " + key + ".")
                matched.append(key)
            else:
                omitted.append(key)
        return {"id": native_id, "type": row.get("type"),
                "matched_parameter_names": matched, "parameters_not_exposed": omitted,
                "request_sha256": s.state["request_sha256"], "native_parameters": parameters,
                "selection": "explicit-original-operation-association"}
    return {"id": native_id, "type": row.get("type")}


def _accept(s, response, action):
    status = response.get("status")
    if not response.get("complete"):
        raise _api().NativeWaiting("Continue the same original dispatch after its interrupted response.")
    if status == 429:
        s.state.update(phase="rate_limited", mutation_started=False)
        s.save_state()
        raise _api().NativeWaiting("The native request was rate limited; its original deadline is retained.")
    if isinstance(status, int) and 400 <= status < 500:
        s.state.update(phase="failed", native_failure={"status": status, "response": response})
        s.save_state()
        raise ValueError("The original native mutation returned HTTP " + str(status) + ".")
    if not isinstance(status, int) or not 200 <= status < 300:
        s.state["phase"] = "native_interrupted"
        s.save_state()
        raise _api().NativeWaiting("The mutation response is uncertain; associate the actual original activity.")
    value = _value(response, tuple(range(200, 300)))
    embedded = value.get("_embedded", {}) if isinstance(value, dict) else {}
    activities = embedded.get("activities")
    if not isinstance(activities, list) or not activities:
        s.state.update(phase="native_interrupted", accepted_response=value)
        s.save_state()
        raise _api().NativeWaiting("The accepted response has no complete activity list; select its original native activity.")
    ids = []
    for row in activities:
        ids.append(_activity(s, row, action)["id"])
    if len(ids) != len(set(ids)):
        raise ValueError("The accepted native response repeats an activity identity.")
    # Auxiliary native activities stay in the complete set. The original returned response
    # is the direct request association, so do not assume every activity has the primary type.
    s.state.update(phase="accepted", accepted_response=value,
                   accepted_entity=embedded.get("entity"),
                   native_poll={"provider": "upsun", "ids": ids, "id": ids[0], "action": action},
                   native_resume={"provider": "upsun", "activity_ids": ids,
                                  "request_sha256": s.state["request_sha256"]})
    s.save_state()


def _associate(s, operation, action):
    selected = operation.get("upsun_activity_association") or {}
    if not selected:
        return False
    if not selected.get("reason") or selected.get("request_sha256") != s.state.get("request_sha256"):
        raise ValueError("The selected native activity belongs to another original request.")
    ids = selected.get("ids") or [selected.get("id")]
    ids = [_id(value, "activity") for value in ids]
    if len(ids) != len(set(ids)):
        raise ValueError("The selected original activity set repeats an ID.")
    if action == "deploy" and not set(s.state.get("before_staged_activity_ids", [])).issubset(ids):
        raise ValueError("Controlled deployment recovery must retain the complete original staged activity set.")
    matches = []
    for native_id in ids:
        row = _object(_value(_http(s, "associated-activity",
                                  _base(s) + "/activities/" + _segment(native_id))),
                      native_id, "activity")
        matches.append(_activity(s, row, action, association=True))
    s.state.update(phase="accepted", association=selected, associated_request=matches,
                   native_poll={"provider": "upsun", "ids": ids, "id": ids[0], "action": action},
                   native_resume={"provider": "upsun", "activity_ids": ids,
                                  "request_sha256": s.state["request_sha256"]})
    s.save_state()
    return True


def _poll(s, action):
    pending = s.state["native_poll"]
    current = []
    for native_id in pending["ids"]:
        row = _object(_value(_http(s, "activity-" + native_id,
                                  _base(s) + "/activities/" + _segment(native_id))),
                      native_id, "activity")
        _activity(s, row, action)
        current.append(row)
    s.state["last_activities"] = current
    s.state["poll_after_seconds"] = max(10, int(s.state.get("poll_after_seconds", 0)))
    s.save_state()
    if any(row.get("state") not in {"complete", "cancelled"} for row in current):
        raise _api().NativeWaiting("The original native activities are still pending; continue the same operation.")
    for row in current:
        native_id = row["id"]
        if native_id in s.state.setdefault("complete_activity_logs", {}):
            continue
        response = _http(s, "complete-activity-log-" + native_id,
                         _base(s) + "/activities/" + _segment(native_id) + "/log", accept="text/plain")
        if not response.get("complete") or response.get("status") != 200:
            raise _api().NativeWaiting("The native activity is terminal; retain its full original log before completing.")
        s.state["complete_activity_logs"][native_id] = response
        s.save_state()
    failures = [{"id": row["id"], "state": row.get("state"), "result": row.get("result"),
                 "failure_reason": row.get("failure_reason"),
                 "failed_commands": [command for command in row.get("commands", [])
                                     if command.get("exit_code") not in (None, 0)]}
                for row in current if row.get("state") != "complete" or row.get("result") != "success"
                or any(command.get("exit_code") not in (None, 0) for command in row.get("commands", []))]
    if failures:
        s.state.update(phase="failed", native_failure=failures)
        _json_file(s, "terminal-native-activities.json", {"activities": current, "failures": failures},
                   "native_activity_result")
        s.save_state()
        raise ValueError("The original native lifecycle finished with retained failures; inspect its activities and logs.")
    inventory = _inventory(s, "completed")
    selected = inventory["environment"]
    if action == "branch":
        entity = s.state.get("accepted_entity")
        candidates = [row for row in inventory["environments"] if
                      row.get("id") == s.p["branch_name"] or row.get("name") == s.p["branch_name"]]
        if isinstance(entity, dict) and entity.get("id"):
            candidates = [row for row in inventory["environments"] if row["id"] == entity["id"]]
        if len(candidates) != 1 or candidates[0].get("parent") != s.p["native_environment_id"]:
            raise ValueError("The completed branch cannot be bound to its original parent and name.")
        selected = candidates[0]
    elif action == "merge":
        selected = next((row for row in inventory["environments"]
                         if row["id"] == s.p["parent_environment_id"]), None)
        if selected is None:
            raise ValueError("The completed merge target is absent from its original project.")
    new_backups = [row for row in inventory["backups"] if row["id"] not in s.state.get("before_backup_ids", [])]
    if action == "backup-create" and not new_backups:
        raise _api().NativeWaiting("The original backup activity succeeded; its snapshot has not appeared in native inventory.")
    if action == "restore-backup" and s.p["restore_code"]:
        expected = s.state["selected_backup"].get("commit_id")
        if selected.get("head_commit") != expected:
            raise ValueError("The restored environment does not match its selected snapshot's original commit.")
    return _finish(s, {"native_action": "upsun-" + action, "activities": current,
                       "activity_ids": pending["ids"], "native_inventory": inventory,
                       "affected_environment": selected, "source": s.state.get("source"),
                       "selected_backup": s.state.get("selected_backup"),
                       "new_backups": new_backups, "native_result": "success",
                       "request_sha256": s.state["request_sha256"]})


def _finish(s, observations):
    value = {"schema": VERSION, "intent_sha256": s.state["intent_sha256"],
             "provider_context": provider_context(s.p), "observations": observations,
             "artifacts": list(s.state.get("retained_artifacts", []))}
    _json_file(s, "upsun-completed-operation.json", value, "restored_native_status")
    s.state.update(phase="completed", completion=str(s.out / "upsun-completed-operation.json"))
    s.save_state()
    return _completed(s, value)


def _completed(s, value):
    if value["intent_sha256"] != s.state["intent_sha256"]:
        raise ValueError("The completed native source belongs to another original instruction.")
    s.artifacts = []
    for item in value["artifacts"]:
        current = _api()._file(s.private_path(item["path"]), item["role"])
        if current["sha256"] != item["sha256"] or current["size"] != item["size"]:
            raise ValueError("A retained original Upsun artifact changed.")
        s.add(current["path"], item["role"])
    s.add(s.out / "upsun-completed-operation.json", "restored_native_status")
    result = s.result("COMPLETE", value["observations"])
    result["native_resume"] = s.state.get("native_resume", {})
    return result


def _failure(s, exc):
    if isinstance(exc, _api().NativeCancelled):
        status = "WAITING_NATIVE" if s.state.get("mutation_started") else "CANCELLED"
    elif isinstance(exc, _api().NativeWaiting) or s.state.get("phase") in {
            "dispatching", "native_interrupted", "accepted", "rate_limited"}:
        status = "WAITING_NATIVE"
    else:
        status = "FAILED"
    s.artifacts = list(s.state.get("retained_artifacts", []))
    result = s.result(status, message=str(exc))
    result["native_resume"] = s.state.get("native_resume", {})
    result["safe_to_retry"] = not s.state.get("mutation_started") or s.state.get("phase") in {
        "failed", "completed", "rate_limited"}
    if pollable(s.state):
        result["poll_after_seconds"] = max(10, min(int(s.state.get("poll_after_seconds", 15)), 3600))
    return result


def _identity_binding(s, operation_id, action, config):
    _intent(s, {"action": action, "operation_id": operation_id,
                "target": provider_context(s.p),
                "profile": {k: v for k, v in config.items() if k not in RUNTIME_FIELDS}})


def discover_capabilities(config, runtime_bindings=None):
    result = {"ready": False, "actions": [], "configuration": dict(config), "current_config": dict(config)}
    try:
        p = profile(config, runtime_bindings)
        with tempfile.TemporaryDirectory(prefix="govhub-upsun-capabilities-") as folder:
            s = _api().Session(p, folder)
            _state(s)
            inventory = _inventory(s, "capability")
            environment = inventory["environment"]
            result.update(ready=True, target_fingerprint=_api()._digest(provider_context(p)),
                          native_inventory=inventory,
                          native_status={"project_id": p["project_id"],
                              "environment_id": p["native_environment_id"],
                              "head_commit": environment.get("head_commit"),
                              "type": environment.get("type"), "status": environment.get("status"),
                              "parent": environment.get("parent"),
                              "current_deployment_id": (inventory["current_deployment"] or {}).get("id"),
                              "available_native_actions": [key[1:] for key in environment.get("_links", {})
                                                           if key.startswith("#")]},
                          actions=[item for kind in KINDS for item in actions_for(kind)])
    except Exception as exc:
        result["error"] = str(exc)
    return result


def capture(config, context, checkpoint=None, cancelled=None):
    p = profile(config, context.get("runtime_bindings"))
    s = _api().Session(p, context["output_dir"], checkpoint, cancelled, context.get("workspace_relocations"))
    try:
        _state(s, context.get("checkpoint"))
        expected = context.get("target_fingerprint") or config.get("target_fingerprint")
        if expected and expected != _api()._digest(provider_context(p)):
            raise ValueError("The original capture target fingerprint changed.")
        _identity_binding(s, context.get("operation_id"), "capture", config)
        completed = s.out / "upsun-completed-operation.json"
        if completed.exists():
            return _completed(s, s.read_private_json(completed))
        inventory = s.state.get("capture_inventory")
        if inventory is None:
            inventory = _inventory(s, "original")
            s.state["capture_inventory"] = inventory
            s.save_state()
        if p.get("source_revision") and inventory["environment"].get("head_commit") != p["source_revision"]:
            raise ValueError("The captured original head differs from the selected source commit.")
        source = _source(s, inventory)
        following = _inventory(s, "following-source")
        if (following["environment"].get("head_commit") != inventory["environment"].get("head_commit")
                or (following["current_deployment"] or {}).get("id") !=
                   (inventory["current_deployment"] or {}).get("id")):
            s.state["capture_changed"] = {"before": inventory, "after": following}
            s.save_state()
            raise ValueError("The native code or deployment changed during source receiving; every original capture remains retained.")
        return _finish(s, {"native_action": "upsun-capture", "native_inventory": inventory,
                          "following_inventory": following, "source": source,
                          "source_consistency": "same-head-and-deployment; independently observed database and mounts"})
    except Exception as exc:
        return _failure(s, exc)


def execute(operation, config, source_paths, checkpoint=None, cancelled=None):
    p = profile(config, operation.get("runtime_bindings"))
    s = _api().Session(p, source_paths["output_dir"], checkpoint, cancelled,
                       source_paths.get("workspace_relocations"))
    try:
        _state(s, source_paths.get("checkpoint") or operation.get("resume_checkpoint"))
        action = str(operation.get("native_action", "")).removeprefix("upsun-")
        if action == "capture" or action not in KINDS.get(operation.get("type"), []):
            raise ValueError("Select the native action belonging to this original reviewed purpose.")
        if operation.get("provider_environment_id") != p["environment_id"]:
            raise ValueError("The original operation names another provider environment.")
        expected = operation.get("target_fingerprint") or config.get("target_fingerprint")
        if expected and expected != _api()._digest(provider_context(p)):
            raise ValueError("The original native target fingerprint changed.")
        _identity_binding(s, operation["id"], action, config)
        completed = s.out / "upsun-completed-operation.json"
        if completed.exists():
            return _completed(s, s.read_private_json(completed))
        if s.state.get("phase") == "failed":
            raise ValueError("This original operation has a terminal native failure; inspect its retained response.")
        if s.state.get("phase") == "accepted":
            return _poll(s, action)
        if s.state.get("phase") in {"dispatching", "native_interrupted"}:
            saved = s.state.get("dispatch_record")
            if saved and Path(saved).is_file():
                response = s.read_private_json(saved)
                if response.get("complete"):
                    try:
                        _accept(s, response, action)
                    except _api().NativeWaiting:
                        if s.state.get("phase") == "rate_limited":
                            raise
                    except (ValueError, KeyError, TypeError) as exc:
                        if s.state.get("phase") == "failed":
                            raise
                        s.state["acceptance_read_error"] = str(exc)
                        s.save_state()
                    if s.state.get("phase") == "accepted":
                        return _poll(s, action)
            if _associate(s, operation, action):
                return _poll(s, action)
            candidates = _collection(s, "original-dispatch-candidates", _base(s) + "/activities", "activities")
            s.state["candidate_activities"] = [row for row in candidates
                                              if row["id"] not in s.state.get("before_activity_ids", [])]
            s.state["native_resume"] = {"provider": "upsun", "activity_ids": [],
                                      "request_sha256": s.state.get("request_sha256"),
                                      "candidate_activities": s.state["candidate_activities"]}
            s.save_state()
            raise _api().NativeWaiting("Select the actual original activity to recover this dispatch without repeating it.")
        if s.state.get("phase") == "rate_limited" and time.time() < s.state.get("provider_not_before", 0):
            raise _api().NativeWaiting("The original native Retry-After deadline has not elapsed.")
        inventory = _inventory(s, "before")
        # Native snapshots need only their own provider operation. Other content-changing
        # actions retain the full selected code/database/mount source before dispatch.
        if action in {"synchronize", "restore-backup", "merge", "deploy", "redeploy"}:
            if "source_inventory" not in s.state:
                s.state["source_inventory"] = inventory
                s.save_state()
            source = _source(s, s.state["source_inventory"])
            inventory = _inventory(s, "before-dispatch")
            if _source_binding(s.state["source_inventory"], action) != _source_binding(inventory, action):
                s.state["changed_source_binding"] = {
                    "before": _source_binding(s.state["source_inventory"], action),
                    "after": _source_binding(inventory, action)}
                s.save_state()
                raise ValueError("The original environment or reviewed parent head/deployment changed during source capture.")
        else:
            source = None
        path, body = _request_body(s, action, operation, inventory)
        instruction = {"method": "POST", "path": path, "body": body}
        request_sha = _api()._digest(instruction)
        if s.state.get("request_sha256") not in (None, request_sha):
            raise ValueError("The original prepared native request changed.")
        s.state.update(phase="prepared", request=instruction, request_sha256=request_sha,
                       before_activity_ids=[row["id"] for row in inventory["activities"]],
                       before_staged_activity_ids=[row["id"] for row in inventory["staged_activities"]
                           if row.get("state") == "staged" and p["native_environment_id"] in row.get("environments", [])],
                       before_backup_ids=[row["id"] for row in inventory["backups"]],
                       before_environment_ids=[row["id"] for row in inventory["environments"]],
                       before=inventory, source=source)
        s.save_state()
        response = _http(s, "dispatch", path, method="POST", body=body)
        _accept(s, response, action)
        return _poll(s, action)
    except Exception as exc:
        return _failure(s, exc)

#!/usr/bin/env python3
"""Receive a complete selected Upsun operating course in the existing GovHub project.

Copyright 2026 Token Junkie Labs contributors. Apache-2.0; see ../LICENSE.
Actual provider work, current plan review, native commands, files and private backup
remain with the original GovHub engines. This programme retains the whole course.
"""
from __future__ import annotations

import argparse
from datetime import datetime
import hashlib
import json
import os
from pathlib import Path
import re
import shutil
import sys
import time

from pantheon_receive import (Commands, add_workspace, atomic, directory, identity,
                              lease, opened, read_json, request_payload, utc)
from tugboat_receive import arguments, copy_intake, receive_application
import upsun_adapter

SCHEMA = "govhub-upsun-native-receiving/v1"
CONTINUATION = "govhub-upsun-native-continuation/v1"


def digest(value):
    return hashlib.sha256(json.dumps(value, sort_keys=True, separators=(",", ":"),
                                    ensure_ascii=False, allow_nan=False).encode()).hexdigest()


def save(path, value):
    atomic(path, value)
    return value


def native_checkpoint(operation):
    value = operation.get("resume_checkpoint") or operation.get("checkpoint") or {}
    return value.get("resume_checkpoint", value.get("state", value))


def source_pointer(value, pointer):
    if not isinstance(pointer, str) or not pointer.startswith("/"):
        raise ValueError("Select an explicit JSON pointer into the complete original operation.")
    for raw in pointer.split("/")[1:]:
        key = raw.replace("~1", "/").replace("~0", "~")
        if isinstance(value, list):
            if not re.fullmatch(r"0|[1-9][0-9]*", key):
                raise ValueError("A source pointer must select an actual original list item.")
            value = value[int(key)]
        elif isinstance(value, dict):
            value = value[key]
        else:
            raise ValueError("The selected source pointer does not name an original value.")
    if not isinstance(value, (str, int, bool)) or isinstance(value, float):
        raise ValueError("A profile source selection must resolve to its native scalar value.")
    return value


class Receiving:
    def __init__(self, request_path, continuation_path=None):
        self.request, self.original = request_payload(request_path)
        if self.request.get("schema") != SCHEMA:
            raise ValueError("Use the complete original Upsun receiving request.")
        if not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9_.:-]{2,159}", self.request.get("operation_id", "")):
            raise ValueError("Supply the original whole-course operation identifier.")
        self.root = directory(self.request["work_directory"], True)
        self.state_file = self.root / "receiving.json"
        self.state = read_json(self.state_file) if self.state_file.exists() else {
            "schema": SCHEMA, "operation_id": self.request["operation_id"],
            "request_sha256": self.original["sha256"], "phase": "prepared", "steps": {},
        }
        if self.state.get("request_sha256") != self.original["sha256"]:
            raise ValueError("This receiving directory belongs to another original request.")
        self.args = arguments(self.request["workspace"])
        self.workspace, self.actor = opened(self.args)
        self.steps = self.request.get("steps")
        if not isinstance(self.steps, list) or not 1 <= len(self.steps) <= 64:
            raise ValueError("Select between one and 64 complete native operating steps.")
        ids = []
        for step in self.steps:
            if not isinstance(step, dict) or not re.fullmatch(r"[a-z0-9][a-z0-9-]{0,79}", step.get("id", "")):
                raise ValueError("Each selected native step needs a unique plain identifier.")
            if step["id"] in ids:
                raise ValueError("Each native step identifier must be unique.")
            ids.append(step["id"])
            kind = step.get("type")
            actions = upsun_adapter.actions_for(kind)
            if step.get("native_action") not in {row["value"] for row in actions}:
                raise ValueError("Select an actual Upsun action for each existing operation purpose.")
            if not isinstance(step.get("profile"), dict) or step["profile"].get("source_kind") != "upsun":
                raise ValueError("Retain the selected complete Upsun profile for every step.")
            if not step.get("environment_id"):
                raise ValueError("Select the existing local environment record for every native step.")
            for source in step.get("profile_sources", []):
                if source.get("step") not in ids[:-1]:
                    raise ValueError("A profile source must select an earlier completed course step.")
        self.continuation = {}
        self.continuation_identity = None
        if continuation_path:
            value, original = request_payload(continuation_path)
            if value.get("schema") != CONTINUATION or value.get("request_sha256") != self.original["sha256"]:
                raise ValueError("Continuation must name this immutable original course request.")
            if not isinstance(value.get("operations", {}), dict):
                raise ValueError("Continuation operations must be keyed by their original operation IDs.")
            self.continuation = value
            self.continuation_identity = original

    def reload(self):
        if self.state_file.exists():
            current = read_json(self.state_file)
            if current.get("request_sha256") != self.original["sha256"]:
                raise ValueError("The saved receiving state belongs to another original request.")
            self.state = current

    def persist(self):
        save(self.state_file, self.state)

    def retained(self, label, value):
        path = self.root / (label + "-" + digest(value) + ".json")
        if not path.exists():
            save(path, value)
        elif read_json(path) != value:
            raise ValueError("A retained original receiving result changed.")
        return identity(path)

    def key(self, label):
        return self.request["operation_id"] + "/" + label

    def original_operation(self, step_id):
        step = self.state["steps"].get(step_id) or {}
        if step.get("phase") != "COMPLETE" or not step.get("operation_id"):
            raise ValueError("The selected earlier native source operation is not complete.")
        result = self.workspace.dispatch("operations.get", {"operation_id": step["operation_id"]}, self.actor)
        if result["operation"]["state"] != "COMPLETE":
            raise ValueError("The selected earlier original operation no longer has a complete outcome.")
        return result["operation"]

    def profile(self, step):
        selected = dict(step["profile"])
        schema = upsun_adapter.provider_schema()
        allowed = {field["name"] for field in schema["fields"]}
        host_fields = {field if isinstance(field, str) else field["name"]
                       for field in schema.get("runtime_fields", [])}
        bindings = []
        for source in step.get("profile_sources", []):
            name = source.get("field")
            if name not in allowed or name.endswith("_env") or name in host_fields:
                raise ValueError("Only native source selections may be received from a prior operation.")
            original = self.original_operation(source["step"])
            value = source_pointer(original, source.get("pointer"))
            selected[name] = value
            bindings.append({"field": name, "step": source["step"], "operation_id": original["id"],
                             "operation_revision": original["revision"], "pointer": source["pointer"],
                             "value": value, "original_sha256": digest(original)})
        upsun_adapter.profile(selected)
        return selected, bindings

    def configure(self, step, retained):
        if "profile" not in retained:
            selected, bindings = self.profile(step)
            retained.update(profile=selected, profile_sources=bindings)
            self.persist()
        selected = retained["profile"]
        before = self.workspace.dispatch("operations.capabilities",
                    {"environment_id": step["environment_id"]}, self.actor)
        environment = before["environment"]
        if environment["data"].get("provider_resource_id") != selected["environment_id"]:
            raise ValueError("The actual provider identity differs from the selected environment record.")
        if before.get("current_config") != selected:
            request = {"environment_id": environment["id"], "expected_revision": environment["revision"],
                       "config": selected}
            retained["configuration_request"] = self.retained(step["id"] + "-configuration-request", request)
            self.persist()
            result = self.workspace.dispatch("operations.configure", request, self.actor)
            retained["configuration_result"] = self.retained(step["id"] + "-configuration-result", result)
            self.persist()
            before = self.workspace.dispatch("operations.capabilities",
                      {"environment_id": environment["id"]}, self.actor)
        return before

    def queue(self, step, retained, capability):
        if "request" not in retained:
            request = {"request_key": self.key(step["id"]),
                "environment_id": step["environment_id"],
                "environment_revision": capability["environment"]["revision"],
                "config_sha256": capability["profile"]["revision"],
                "authorization_reference": step.get("authorization_reference") or self.request["authorization_reference"],
                "target_fingerprint": capability.get("capabilities", {}).get("target_fingerprint", ""),
                "native_action": step["native_action"]}
            if step["type"] != "CAPTURE":
                request["type"] = step["type"]
            if step["type"] not in {"CAPTURE", "PREVIEW", "BACKUP_CREATE", "BACKUP_DOWNLOAD"}:
                if not step.get("plan_id") or not step.get("expected_plan_revision"):
                    raise ValueError("Reviewed cohort operations require the selected original plan and revision.")
                request.update(plan_id=step["plan_id"], expected_revision=step["expected_plan_revision"])
                if "agency_ids" in step:
                    request["agency_ids"] = step["agency_ids"]
                if step.get("backup_sha256"):
                    request["backup_sha256"] = step["backup_sha256"]
            retained.update(method="sources.capture" if step["type"] == "CAPTURE" else "operations.create",
                            request=request, phase="PREPARED")
            self.persist()
        if not retained.get("operation_id"):
            result = self.workspace.dispatch(retained["method"], retained["request"], self.actor)
            retained.update(operation_id=result["operation"]["id"], phase=result["operation"]["state"],
                            queued=self.retained(step["id"] + "-queued", result))
            self.persist()

    def continue_operation(self, step, operation):
        selected = self.continuation.get("operations", {}).get(operation["id"], {})
        if selected and not isinstance(selected, dict):
            raise ValueError("A continuation must retain the selected original operation controls.")
        unknown = set(selected) - {"upsun_activity_id", "upsun_activity_ids_json", "runtime_bindings", "restored_snapshot_id",
                                  "reason", "resume_cancelled"}
        if unknown:
            raise ValueError("Unsupported original continuation fields: " + ", ".join(sorted(unknown)))
        if operation["state"] in {"COMPLETE", "QUEUED", "RUNNING"}:
            return
        if (operation.get("native_result") or {}).get("status") == "COMPLETE":
            snapshot_id = selected.get("restored_snapshot_id") or step.get("restored_snapshot_id")
            if snapshot_id:
                request = {"operation_id": operation["id"], "expected_revision": operation["revision"],
                    "capture_file_id": operation["native_capture_file_id"],
                    "restored_snapshot_id": snapshot_id,
                    "notes": selected.get("reason") or step.get("observation_notes") or
                             "Original selected restored inventory received through the complete native course"}
                result = self.workspace.dispatch("operations.observe", request, self.actor)
                self.retained(step["id"] + "-observed", {"request": request, "result": result})
            return
        native = native_checkpoint(operation)
        deadline = max(float(native.get("provider_not_before", 0)),
                       float(native.get("provider_request_not_before", 0)),
                       float(native.get("not_before", 0)))
        if operation.get("next_poll_at"):
            original_poll = datetime.fromisoformat(operation["next_poll_at"].replace("Z", "+00:00"))
            if original_poll.tzinfo is None:
                raise ValueError("The original operation poll deadline must include its timezone.")
            deadline = max(deadline, original_poll.timestamp())
        if time.time() < deadline:
            return
        cancelled = operation.get("cancel_requested") or operation["state"] == "CANCELLED"
        if cancelled and not selected.get("resume_cancelled"):
            return
        ambiguous = native.get("phase") in {"dispatching", "native_interrupted"}
        associated = bool(selected.get("upsun_activity_id") or selected.get("upsun_activity_ids_json"))
        explicit = bool(selected.get("runtime_bindings") or selected.get("resume_cancelled"))
        recoverable = operation["state"] in {"PAUSED", "WAITING_NATIVE"} and not ambiguous and not upsun_adapter.pollable(native)
        if not associated and not explicit and not recoverable:
            return
        request = {"request_key": self.key(step["id"] + "-resume-" + str(operation["revision"]) + "-" + digest(selected)),
            "operation_id": operation["id"], "expected_revision": operation["revision"],
            "reason": selected.get("reason") or "Continue the same original native course after its receiving condition"}
        for key in ("upsun_activity_id", "upsun_activity_ids_json", "runtime_bindings"):
            if key in selected:
                request[key] = selected[key]
        self.retained(step["id"] + "-resume-request", request)
        result = self.workspace.dispatch("operations.resume", request, self.actor)
        self.retained(step["id"] + "-resume-result", result)

    def run_step(self, step):
        retained = self.state["steps"].setdefault(step["id"], {"phase": "PREPARED"})
        if retained.get("phase") == "COMPLETE":
            self.original_operation(step["id"])
            return True
        if not retained.get("operation_id"):
            capability = self.configure(step, retained)
            self.queue(step, retained, capability)
        result = self.workspace.dispatch("operations.get", {"operation_id": retained["operation_id"]}, self.actor)
        self.continue_operation(step, result["operation"])
        from cli import run_worker
        run_worker(self.workspace, True)
        result = self.workspace.dispatch("operations.get", {"operation_id": retained["operation_id"]}, self.actor)
        # A newly completed provider mutation may now be joined to its actual
        # already-retained RESTORED inventory by the original comparison engine.
        if result["operation"]["state"] != "COMPLETE":
            self.continue_operation(step, result["operation"])
            result = self.workspace.dispatch("operations.get", {"operation_id": retained["operation_id"]}, self.actor)
        retained.update(phase=result["operation"]["state"], result=self.retained(step["id"] + "-result", result))
        self.persist()
        if retained["phase"] != "COMPLETE":
            self.state.update(phase="attention", current_step=step["id"])
            self.persist()
            return False
        return True

    def run(self):
        with lease(self.root, "receiving.lock"):
            self.reload()
            self.retained("original-request", self.request)
            if self.continuation_identity:
                self.retained("original-continuation", self.continuation)
            if self.state["phase"] == "complete":
                for step in self.steps:
                    self.original_operation(step["id"])
                return self.status()
            for step in self.steps:
                if not self.run_step(step):
                    return self.status()
            self.state.update(phase="complete", completed_at=utc())
            self.state.pop("current_step", None)
            self.persist()
            return self.status()

    def status(self):
        self.reload()
        return {"schema": SCHEMA, "state": self.state["phase"],
            "operation_id": self.state["operation_id"], "request_sha256": self.original["sha256"],
            "workspace": str(self.workspace.root), "current_step": self.state.get("current_step"),
            "steps": {key: {"state": row["phase"], "operation_id": row.get("operation_id")}
                      for key, row in self.state["steps"].items()},
            "result": identity(self.state_file) if self.state_file.exists() else None}

    def receive_sources(self, target, selected, handover, state_path):
        """Receive original complete packages and reopen their actual Git sources."""
        import upsun_source
        from native_adapter import Session
        exports = selected.get("source_exports")
        if not isinstance(exports, list) or not exports:
            raise ValueError("Select the actual complete source artifact from each source-capture step.")
        required = {step["id"] for step in self.steps if step["type"] == "CAPTURE"}
        if not required.issubset({row.get("step") for row in exports if isinstance(row, dict)}):
            raise ValueError("Include every completed source-capture step in independent native receiving.")
        seen = set()
        for index, selection in enumerate(exports):
            if not isinstance(selection, dict) or set(selection) - {"step", "file_name", "runtime_bindings"}:
                raise ValueError("Select the original step, complete file name and actual local runtime bindings.")
            key = (selection.get("step"), selection.get("file_name"))
            if key in seen:
                raise ValueError("Receive each original source artifact once in this handover.")
            seen.add(key)
            operation = self.original_operation(selection["step"])
            item = self.workspace.operation_file(operation["id"], selection["file_name"])
            slot = directory(target / ("native-source-" + str(index).zfill(2)), True)
            archive = slot / "original-source.zip"
            expected = {"bytes": item.get("size", item.get("bytes")), "sha256": item["sha256"]}
            if not archive.exists():
                partial = slot / "original-source.zip.receiving"
                if partial.is_symlink():
                    raise ValueError("The original source receiving path cannot be a link.")
                with Path(item["path"]).open("rb") as source, partial.open("wb") as output:
                    shutil.copyfileobj(source, output, 1024 * 1024)
                    output.flush()
                    os.fsync(output.fileno())
                actual = identity(partial)
                if any(actual[name] != expected[name] for name in expected):
                    raise ValueError("The complete retained source package changed while receiving.")
                os.replace(partial, archive)
            actual = identity(archive)
            if any(actual[name] != expected[name] for name in expected):
                raise ValueError("The original received source package changed.")
            original_config = operation["profile"]["config"]
            maximum = original_config.get("max_artifact_bytes", 1073741824)
            manifest = upsun_source.verify_source(archive, maximum)
            native_target = manifest.get("target") or {}
            if original_config["environment_id"] != str(native_target.get("project_id", "")) + "/" + str(native_target.get("environment_id", "")):
                raise ValueError("The complete source package belongs to another native project/environment.")
            expected_selection = {
                "application": original_config.get("source_app"),
                "database_relationship": original_config.get("source_database"),
                "database_schema": original_config.get("source_database_schema"),
                "mount_selection": [name.strip("/") for name in
                    json.loads(original_config.get("source_mounts_json") or "[]")],
            }
            if any(native_target.get(name) != value for name, value in expected_selection.items()):
                raise ValueError("The source artifact belongs to another original application/database/mount selection.")
            observed = (operation.get("native_result") or {}).get("observations") or {}
            actual_head = ((observed.get("native_inventory") or {}).get("environment") or {}).get("head_commit")
            expected_head = original_config.get("source_revision") or actual_head
            if not expected_head or manifest.get("source_revision") != expected_head or native_target.get("source_revision") != expected_head:
                raise ValueError("The source artifact differs from the original selected or actually observed source head.")
            received = upsun_source.receive_source(archive, slot / "members", maximum)
            host = directory(slot / "host", True)
            bindings = dict(selection.get("runtime_bindings") or {})
            if "site_root" in bindings and Path(bindings["site_root"]).resolve() != host:
                raise ValueError("The source reopening host directory is this original private handover slot.")
            bindings["site_root"] = str(host)
            profile = upsun_adapter.profile(original_config, bindings)
            session = Session(profile, slot / "native-reopen")
            saved = session.out / "native-state.json"
            if saved.exists():
                session.state = session.read_private_json(saved)
            reopened = upsun_source.reopen_source(session, slot / "members", slot / "checkout")
            receipt = {"step": selection["step"], "operation_id": operation["id"],
                       "file_name": selection["file_name"], "archive": actual,
                       "received": received, "reopened": reopened,
                       "native_output": str(session.out)}
            handover.setdefault("source_exports", {})[str(index)] = receipt
            save(state_path, handover)
        return handover["source_exports"]

    def handover(self, selected):
        with lease(self.root, "receiving.lock"):
            self.reload()
            if self.state["phase"] != "complete":
                raise ValueError("Complete the selected original native course before the full receiving handover.")
            target = Path(selected["destination"]).expanduser()
            if not target.is_absolute() or target.is_symlink():
                raise ValueError("Use the original absolute private receiving directory.")
            target = target.resolve(strict=False)
            for original in (self.root, self.workspace.root, Path(self.args.source_root)):
                original = original.resolve()
                if target == original or target.is_relative_to(original) or original.is_relative_to(target):
                    raise ValueError("Keep full receiving separate from the original input and project directories.")
            target.mkdir(mode=0o700, parents=True, exist_ok=True)
            path = self.root / "handover.json"
            handover = read_json(path) if path.exists() else {
                "schema": SCHEMA, "binding": digest(selected), "phase": "prepared", "destination": str(target)}
            if handover["binding"] != digest(selected):
                raise ValueError("Continue the same original whole handover selection.")
            save(path, handover)
            if handover.get("phase") == "complete":
                application = handover["application"]["archive"]
                if identity(application["path"])["sha256"] != application["sha256"]:
                    raise ValueError("The original received application archive changed.")
                if read_json(target / "original-course.json") != {"request": self.request, "receiving": self.state}:
                    raise ValueError("The completed original course changed after receiving.")
                return {"state": "RECEIVED", "workspace": handover["reopened"]["workspace"],
                        "operation_count": len(handover["reopened"]["operations"]),
                        "destination": str(target), "receiver": str(target / "application" /
                        "govhub-operations" / "workspace" / "upsun_receive.py"), "result": identity(path)}
            if not handover.get("intake_received"):
                handover["intake_received"] = copy_intake(Path(self.args.source_root), target / "original-inputs", handover, path)
                save(path, handover)
            if not handover.get("application"):
                handover["application"] = receive_application(Path(selected["application_zip"]),
                    selected["application_sha256"], target)
                save(path, handover)
            self.receive_sources(target, selected, handover, path)
            backup = target / "private-workspace"
            if not handover.get("backup"):
                if backup.exists():
                    if (backup / "BACKUP_INCOMPLETE").exists() or not (backup / "backup.json").is_file():
                        prior = target / ("incomplete-private-workspace-" + str(time.time_ns()))
                        os.rename(backup, prior)
                        handover.setdefault("retained_partial_backups", []).append(str(prior))
                        save(path, handover)
                    else:
                        metadata = read_json(backup / "backup.json")
                        if metadata["workspace"] != self.workspace.snapshot().get("workspace"):
                            raise ValueError("The retained backup belongs to another original workspace.")
                        handover["backup"] = {"directory": str(backup), **metadata}
                if not handover.get("backup"):
                    handover["backup"] = self.workspace.dispatch("workspace.backup",
                        {"destination": str(backup)}, self.actor)
                save(path, handover)
            receiver = target / "application" / "govhub-operations" / "workspace" / "upsun_receive.py"
            if not receiver.is_file():
                raise ValueError("The complete original application package is missing its Upsun receiver.")
            received_args = arguments({**self.request["workspace"], "workspace": str(backup),
                                       "source_root": str(target / "original-inputs")})
            received_workspace, _ = opened(received_args)
            original = received_workspace.snapshot()
            saved_operations = {row["id"]: row for row in original["govhub"]["operations"]}
            for step in self.steps:
                source_operation = self.original_operation(step["id"])
                if saved_operations.get(source_operation["id"]) != source_operation:
                    raise ValueError("The coherent private backup does not contain the completed original course.")
            selection_path = target / "original-course.json"
            if not selection_path.exists():
                save(selection_path, {"request": self.request, "receiving": self.state})
            elif read_json(selection_path) != {"request": self.request, "receiving": self.state}:
                raise ValueError("The received original course differs from its completed source.")
            commands = Commands(self.root / "cold-reopen", 600)
            receipt = commands.run("original-project-reopen", [
                sys.executable, str(receiver), "inspect", "--workspace", str(backup),
                "--source-root", str(target / "original-inputs"),
                "--assessment-core", str(receiver.parent / "vendor" / "assessment-core"),
                "--username", self.args.username, "--password-env", self.args.password_env])
            reopened = Commands.json_output(receipt)
            expected = {row["id"]: row for row in original["govhub"]["operations"]}
            actual = {row["id"]: row for row in reopened["operations"]}
            if original.get("workspace") != reopened.get("workspace") or expected != actual:
                raise ValueError("Independent receiving changed the original workspace or native operation population.")
            handover.update(phase="complete", reopened=reopened, cold_command=receipt,
                            receiving_state=self.state, completed_at=utc())
            save(path, handover)
            return {"state": "RECEIVED", "workspace": reopened["workspace"],
                    "operation_count": len(actual), "destination": str(target),
                    "receiver": str(receiver), "result": identity(path)}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    commands = parser.add_subparsers(dest="command", required=True)
    for name in ("run", "status", "handover"):
        item = commands.add_parser(name)
        item.add_argument("--request", required=True)
        item.add_argument("--continuation")
        if name == "handover":
            item.add_argument("--selection", required=True)
    inspect = commands.add_parser("inspect")
    add_workspace(inspect)
    args = parser.parse_args()
    os.umask(0o077)
    try:
        if args.command == "inspect":
            workspace, actor = opened(args)
            snapshot = workspace.snapshot()
            result = {"workspace": snapshot.get("workspace"),
                "actor": {"name": actor["name"], "role": actor["role"]},
                "operations": snapshot["govhub"]["operations"],
                "summary": snapshot["govhub"]["summary"]}
        else:
            receiving = Receiving(args.request, args.continuation)
            if args.command == "run":
                result = receiving.run()
            elif args.command == "status":
                result = receiving.status()
            else:
                selection, _ = request_payload(args.selection)
                result = receiving.handover(selection)
        print(json.dumps(result, ensure_ascii=False, allow_nan=False), flush=True)
        return 2 if result.get("state") == "attention" else 0
    except Exception as exc:
        print(json.dumps({"ok": False, "type": type(exc).__name__, "message": str(exc)}), file=sys.stderr)
        return 1


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
# SPDX-License-Identifier: Apache-2.0
"""Complete native Upsun source capture and independent private receiving.

Provider mutations remain owned by upsun_adapter and the original Session.
This module only reads native Git, the selected environment, SQL and mounts.
"""
from __future__ import annotations

import argparse
from datetime import datetime, timezone
import hashlib
import json
import os
from pathlib import Path, PurePosixPath
import re
import shutil
import stat
import subprocess
import sys
import tarfile
import tempfile
import zipfile

SCHEMA = "govhub.upsun.source.v1"
CLI_VERSION = "5.13.0"
CLI_COMMIT = "b23a9b1ba51afe1ab18ff7f8283ead4998aa80ed"
CHUNK = 1024 * 1024


def _now():
    return datetime.now(timezone.utc).isoformat().replace("+00:00", "Z")


def _bytes(value):
    return (json.dumps(value, ensure_ascii=False, sort_keys=True, indent=2) + "\n").encode("utf-8")


def _digest(value):
    return hashlib.sha256(value).hexdigest()


def _atomic(path, value):
    path = Path(path)
    path.parent.mkdir(mode=0o700, parents=True, exist_ok=True)
    if path.is_symlink():
        raise ValueError("A native source journal cannot be a link.")
    fd, name = tempfile.mkstemp(prefix=path.name + ".part-", dir=path.parent)
    try:
        with os.fdopen(fd, "wb") as stream:
            os.fchmod(stream.fileno(), 0o600)
            stream.write(_bytes(value))
            stream.flush()
            os.fsync(stream.fileno())
        os.replace(name, path)
    finally:
        if os.path.exists(name):
            os.unlink(name)


def _file(path):
    path = Path(path)
    if path.is_symlink() or not path.is_file():
        raise ValueError("The original ordinary source file is unavailable: " + str(path))
    a = path.stat()
    digest = hashlib.sha256()
    size = 0
    with path.open("rb") as stream:
        for data in iter(lambda: stream.read(CHUNK), b""):
            digest.update(data)
            size += len(data)
    b = path.stat()
    if (a.st_dev, a.st_ino, a.st_size, a.st_mtime_ns) != (
            b.st_dev, b.st_ino, b.st_size, b.st_mtime_ns) or size != a.st_size:
        raise ValueError("A native source file changed while it was being retained.")
    return {"bytes": size, "sha256": digest.hexdigest()}


def _relative(value):
    if (not isinstance(value, str) or not value or "\\" in value or "\0" in value
            or value.startswith("/") or any(x in ("", ".", "..") for x in value.split("/"))):
        raise ValueError("Use an ordinary package-relative native path.")
    value.encode("utf-8", errors="strict")
    return value


def _selector(value, name):
    if (not isinstance(value, str) or not value or "\0" in value or "\n" in value
            or value.startswith("-")):
        raise ValueError("Select the actual native " + name + ".")
    return value


def _executable(value):
    value = _selector(value, "executable")
    selected = shutil.which(value)
    if not selected or not os.access(selected, os.X_OK):
        raise ValueError("The selected original native executable is unavailable: " + value)
    return str(Path(selected).resolve())


def _load(path):
    return json.loads(Path(path).read_bytes().decode("utf-8"))


def _stable_file(path, content):
    path = Path(path)
    if path.exists():
        if path.read_bytes() != content:
            raise ValueError("The retained original source input differs: " + str(path))
    else:
        path.parent.mkdir(mode=0o700, parents=True, exist_ok=True)
        with path.open("xb") as stream:
            os.chmod(path, 0o600)
            stream.write(content)
            stream.flush()
            os.fsync(stream.fileno())


def _http_json(raw):
    """Keep native curl output complete, including all original response headers."""
    cursor = 0
    while raw[cursor:].startswith(b"HTTP/"):
        end = raw.find(b"\r\n\r\n", cursor)
        sep = 4
        if end < 0:
            end = raw.find(b"\n\n", cursor)
            sep = 2
        if end < 0:
            raise ValueError("Incomplete native response header.")
        lines = raw[cursor:end].replace(b"\r\n", b"\n").split(b"\n")
        status = int(lines[0].split()[1])
        headers = {}
        for line in lines[1:]:
            if b":" in line:
                key, value = line.split(b":", 1)
                headers.setdefault(key.decode("ascii").lower(), []).append(value.strip().decode("latin1"))
        cursor = end + sep
        if status < 200 or raw[cursor:].startswith(b"HTTP/"):
            continue
        if not 200 <= status < 300:
            raise ValueError("Native source GET returned HTTP " + str(status))
        body = raw[cursor:]
        lengths = headers.get("content-length")
        if lengths and "transfer-encoding" not in headers:
            if len(set(lengths)) != 1 or not lengths[0].isdigit() or int(lengths[0]) != len(body):
                raise ValueError("Native source GET returned an incomplete declared body.")
        return json.loads(body.decode("utf-8"))
    raise ValueError("The original complete native response headers are missing.")


def _cli_exec():
    """One exec within Session's admitted process group; no new controller."""
    request = json.load(sys.stdin)
    if request.get("schema") != "govhub.upsun.cli-request.v1":
        raise ValueError("Select the original retained native CLI request.")
    env = dict(os.environ)
    env["UPSUN_CLI_DEBUG"] = "0"
    env["UPSUN_CLI_DISABLE_CACHE"] = "1"
    env["NO_COLOR"] = "1"
    token_name = request.get("api_token_env")
    if token_name:
        if not re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", token_name):
            raise ValueError("Use the original API credential environment name.")
        token = os.environ.get(token_name)
        if not token:
            raise ValueError("The selected native API credential is unavailable on this host.")
        env["UPSUN_CLI_TOKEN"] = token
    # Existing CLI HOME/session and SSH agent remain native host configuration.
    # No access-token value is misrepresented as an Upsun API token.
    current_directory = str(Path(sys.argv[2]).resolve(strict=True))
    original_directory = request["capture_directory"].rstrip("/")
    def relocated(value):
        if isinstance(value, str) and (value == original_directory
                or value.startswith(original_directory + "/")):
            return current_directory + value[len(original_directory):]
        return value
    env["PATH"] = relocated(request["bin_directory"]) + os.pathsep + env.get("PATH", "")
    argv = [relocated(value) for value in request["argv"]]
    os.execve(argv[0], argv, env)


def _tar_files(path, base, names):
    """Capture exact selected worktree nodes; links remain links, never followed."""
    path, base = Path(path), Path(base)
    staging = path.with_suffix(path.suffix + ".partial")
    if staging.exists():
        staging.unlink()
    entries = []
    with tarfile.open(staging, "w", format=tarfile.PAX_FORMAT, dereference=False) as archive:
        for name in sorted(set(names)):
            _relative(name)
            node = base / name
            if not node.exists() and not node.is_symlink():
                entries.append({"path": name, "kind": "deleted"})
                continue
            info = archive.gettarinfo(str(node), arcname=name)
            if not (info.isfile() or info.isdir() or info.issym()):
                raise ValueError("A selected source node needs explicit native handling: " + name)
            row = {"path": name, "mode": info.mode, "kind": "symlink" if info.issym()
                   else "directory" if info.isdir() else "file"}
            if info.issym():
                row["link_target"] = info.linkname
                archive.addfile(info)
            elif info.isfile():
                before = _file(node)
                if info.size != before["bytes"]:
                    raise ValueError("A native file changed before its archive read: " + name)
                with node.open("rb") as stream:
                    archive.addfile(info, stream)
                if _file(node) != before:
                    raise ValueError("The native source changed during its capture: " + name)
                row.update(before)
            else:
                archive.addfile(info)
            entries.append(row)
    os.chmod(staging, 0o600)
    os.replace(staging, path)
    return entries


def _tree_names(root):
    names = []
    for parent, directories, files in os.walk(root, followlinks=False):
        for name in list(directories):
            path = Path(parent) / name
            names.append(path.relative_to(root).as_posix())
            if path.is_symlink():
                directories.remove(name)
        names.extend((Path(parent) / name).relative_to(root).as_posix() for name in files)
    return names


def capture_source(session, provider_inventory, selection):
    """Return one complete, retained native source package through Session.add.

    selection is the provider profile. Runtime paths may be relocated using the
    Session's original workspace mapping. Native target IDs never relocate.
    """
    s, p = session, selection
    root = Path(s.private_path(p["site_root"])).resolve(strict=True)
    if not root.is_dir():
        raise ValueError("Use the existing selected Git source directory.")
    project = _selector(p["project_id"], "project ID")
    environment = _selector(p["native_environment_id"], "environment ID")
    app = _selector(p.get("source_app"), "application")
    relation = _selector(p.get("source_database"), "database relationship")
    schema = _selector(p.get("source_database_schema"), "database schema")
    revision = p.get("source_revision", "")
    if not re.fullmatch(r"[0-9a-f]{40}|[0-9a-f]{64}", revision):
        raise ValueError("Select the complete original source revision.")
    mounts = p.get("source_mounts_json") or "[]"
    if isinstance(mounts, str):
        mounts = json.loads(mounts)
    if not isinstance(mounts, list) or any(not isinstance(x, str) for x in mounts):
        raise ValueError("source_mounts_json must be the original mount-path array.")
    mounts = [_relative(x.strip("/")) for x in mounts]
    if len(set(mounts)) != len(mounts):
        raise ValueError("Select each native mount once.")
    target = {"project_id": project, "environment_id": environment, "application": app,
              "database_relationship": relation, "database_schema": schema,
              "mount_selection": mounts, "source_revision": revision}
    key = _digest(_bytes(target))[:24]
    directory = s.out / ("upsun-source-" + key)
    directory.mkdir(mode=0o700, parents=True, exist_ok=True)
    if root == directory or root in directory.parents:
        raise ValueError("Keep native source capture outside the selected Git worktree.")
    state_path = directory / "capture.json"
    if state_path.exists():
        state = _load(state_path)
        if state.get("target") != target:
            raise ValueError("Continue the exact original source target.")
    else:
        state = {"schema": SCHEMA, "target": target, "started_at": _now(),
                 "state": "RUNNING", "commands": {}, "parts": {}}
        _atomic(state_path, state)

    def save():
        state["updated_at"] = _now()
        _atomic(state_path, state)
        s.state.setdefault("upsun_source", {})[key] = {
            "state": state["state"], "directory": str(directory), "target": target}
        s.save_state()

    if state["state"] == "COMPLETE":
        for name, identity in state["published"].items():
            if _file(directory / name) != identity:
                raise ValueError("A complete original source artifact changed.")
        archive = directory / "upsun-source.zip"
        manifest = directory / "MANIFEST.json"
        s.add(archive, "upsun_complete_source", source_revision=revision)
        s.add(manifest, "upsun_source_manifest", source_revision=revision)
        return {**state["result"], "archive": str(archive), "manifest": str(manifest)}

    inventory_path = directory / "provider-inventory.json"
    if not inventory_path.exists():
        _atomic(inventory_path, provider_inventory)
    inventory = _load(inventory_path)
    native_env = inventory.get("environment")
    deployment = inventory.get("current_deployment")
    if (not isinstance(native_env, dict) or native_env.get("id") != environment
            or not isinstance(deployment, dict) or not deployment.get("id")
            or app not in deployment.get("webapps", {})):
        raise ValueError("Inventory must retain the selected actual environment and deployed application.")
    if native_env.get("head_commit") != revision:
        raise ValueError("Reviewed native environment head differs from the selected original revision.")
    tools = {name: _executable(p.get(field) or default) for name, field, default in (
        ("git", "git_path", "git"), ("upsun", "upsun_path", "upsun"),
        ("ssh", "ssh_path", "ssh"), ("rsync", "rsync_path", "rsync"))}
    bin_dir = directory / "native-bin"
    bin_dir.mkdir(mode=0o700, exist_ok=True)
    for name in ("ssh", "rsync"):
        alias = bin_dir / name
        if alias.is_symlink():
            if str(alias.resolve()) != tools[name]:
                raise ValueError("The original capture executable binding changed.")
        elif alias.exists():
            raise ValueError("Unexpected native executable alias.")
        else:
            alias.symlink_to(tools[name])
    token_env = p.get("api_token_env")
    if token_env and not re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", token_env):
        raise ValueError("Use a native credential environment name, never its value.")

    def run(name, argv, cli=False):
        label = "upsun-source-" + key + "-" + name
        if cli:
            request_path = directory / "requests" / (name + ".json")
            request = {"schema": "govhub.upsun.cli-request.v1", "argv": argv,
                       "api_token_env": token_env, "bin_directory": str(bin_dir),
                       "capture_directory": str(directory)}
            if request_path.exists():
                if s.resolve_private(_load(request_path)) != request:
                    raise ValueError("The original native CLI selection or runtime binding changed.")
            else:
                _stable_file(request_path, _bytes(request))
            record = s.command(label, [sys.executable, str(Path(__file__).resolve()), "_cli", str(directory)],
                               stdin_path=str(request_path))
        else:
            record = s.command(label, argv)
        stored = directory / "commands"
        stored.mkdir(mode=0o700, exist_ok=True)
        paths = {}
        for field in ("stdout", "stderr"):
            original = Path(s.private_path(record[field]["path"]))
            destination = stored / (name + "." + field)
            if destination.exists():
                if _file(destination) != _file(original):
                    raise ValueError("The retained native command bytes differ.")
            else:
                shutil.copyfile(original, destination)
                os.chmod(destination, 0o600)
            paths[field] = destination.relative_to(directory).as_posix()
        command_path = stored / (name + ".json")
        if command_path.exists():
            if s.resolve_private(_load(command_path)) != record:
                raise ValueError("The original command outcome changed after source relocation.")
        else:
            _stable_file(command_path, _bytes(record))
        state["commands"][name] = {"argv": argv, "record": command_path.relative_to(directory).as_posix(),
                                    **paths}
        save()
        return (directory / paths["stdout"]).read_bytes()

    def cli(name, args):
        return run(name, [tools["upsun"], "--no-interaction", "--yes", "--no-ansi", *args], cli=True)

    def selected(command):
        return [command, "--project", project, "--environment", environment]

    def current(name):
        data = _http_json(cli(name, [*selected("environment:curl"), "deployments/current",
                         "--request", "GET", "--include", "--no-retry-401", "--disable-compression"]))
        if not isinstance(data, dict) or not data.get("id") or app not in data.get("webapps", {}):
            raise ValueError("Native current deployment does not contain the selected application.")
        return data

    def git(name, where, args):
        return run(name, [tools["git"], "-C", str(where), *args])

    try:
        version = cli("cli-version", ["--version"]).decode("utf-8").strip()
        if not re.search(r"\b5\.13\.0\b", version) or "upsun" not in version.lower():
            raise ValueError("This source contract requires the released Upsun CLI 5.13.0.")
        before = current("deployment-before")
        if before["id"] != deployment["id"]:
            raise ValueError("Native deployment changed since the retained provider review.")
        head_before = cli("head-before", [*selected("environment:info"), "head_commit", "--refresh"]).decode().strip()
        if head_before != revision:
            raise ValueError("Native head changed before source capture.")
        app_config = before["webapps"][app]
        native_mounts = app_config.get("mounts", {})
        if not isinstance(native_mounts, dict):
            raise ValueError("The actual application mount configuration is invalid.")
        normalized_mounts = {k.strip("/"): v for k, v in native_mounts.items()}
        if len(normalized_mounts) != len(native_mounts):
            raise ValueError("The native application repeats a normalized mount path.")
        all_mounts = sorted(_relative(name) for name in normalized_mounts)
        observed_mounts = cli("mount-list", [*selected("mount:list"), "--app", app, "--paths", "--refresh"])
        observed_mounts = sorted(x.strip("/") for x in observed_mounts.decode().splitlines() if x.strip())
        if observed_mounts != all_mounts:
            raise ValueError("Native CLI and deployment disagree on the complete mount selection.")
        selected_mounts = sorted(mounts or all_mounts)
        if any(name not in all_mounts for name in selected_mounts):
            raise ValueError("A selected mount does not exist on the original application.")
        # App YAML is an unchanged original source artifact, not a reconstructed JSON config.
        cli("app-config", [*selected("app:config-get"), "--app", app, "--refresh"])

        repos = state.get("repositories")
        if repos is None:
            repos = [{"path": "", "parent": None, "gitlink": None}]
            state["repositories"] = repos
            save()
        index = 0
        while index < len(repos):
            s.check()
            repository = repos[index]
            where = root / repository["path"]
            tag = "git-" + str(index)
            repo_dir = directory / "repositories" / str(index)
            repo_dir.mkdir(mode=0o700, parents=True, exist_ok=True)
            actual_root = git(tag + "-root", where, ["rev-parse", "--show-toplevel"]).decode().strip()
            if Path(actual_root).resolve() != where.resolve():
                raise ValueError("A native submodule is uninitialized or the selected Git root differs.")
            head = git(tag + "-head", where, ["rev-parse", "--verify", "HEAD"]).decode().strip()
            if index == 0 and head != revision:
                raise ValueError("Local Git HEAD differs from the reviewed Upsun revision.")
            if repository["gitlink"] and head != repository["gitlink"]:
                raise ValueError("A submodule checkout differs from its reviewed parent index.")
            repository["head"] = head
            listing = git(tag + "-index", where, ["ls-files", "--stage", "-z"])
            selected_files, gitlinks = [], []
            for row in listing.split(b"\0"):
                if not row:
                    continue
                metadata, raw_name = row.split(b"\t", 1)
                mode, object_id, stage = metadata.decode("ascii").split()
                name = _relative(os.fsdecode(raw_name))
                if stage != "0":
                    raise ValueError("Resolve native Git index conflicts before source capture.")
                if mode == "160000":
                    gitlinks.append((name, object_id))
                else:
                    selected_files.append(name)
            # Include HEAD files removed from the current index, so staged
            # deletions also remove their original working copy on reopening.
            head_tree = git(tag + "-head-tree", where, ["ls-tree", "-r", "-z", "--full-tree", head])
            for row in head_tree.split(b"\0"):
                if not row:
                    continue
                metadata, raw_name = row.split(b"\t", 1)
                mode, object_type, object_id = metadata.decode("ascii").split()
                if object_type == "blob":
                    selected_files.append(_relative(os.fsdecode(raw_name)))
            untracked = git(tag + "-untracked", where, ["ls-files", "--others", "--exclude-standard", "-z"])
            selected_files += [os.fsdecode(x) for x in untracked.split(b"\0") if x]
            git(tag + "-ignored", where, ["ls-files", "--others", "--ignored", "--exclude-standard", "-z"])
            staged = git(tag + "-staged", where, ["diff", "--cached", "--binary", "--full-index", "--no-ext-diff"])
            unstaged = git(tag + "-unstaged", where, ["diff", "--binary", "--full-index", "--no-ext-diff"])
            git(tag + "-status", where, ["status", "--porcelain=v1", "-z", "--untracked-files=all"])
            for filename, content in (("staged.patch", staged), ("unstaged.patch", unstaged)):
                _stable_file(repo_dir / filename, content)
            bundle = repo_dir / "repository.bundle"
            git(tag + "-bundle", where, ["bundle", "create", str(bundle), "--all", "HEAD"])
            git(tag + "-verify", where, ["bundle", "verify", str(bundle)])
            git(tag + "-archive", where, ["archive", "--format=tar", "--output", str(repo_dir / "tracked.tar"), head])
            git(tag + "-refs", where, ["show-ref", "--head"])
            entries_path = repo_dir / "worktree.json"
            if entries_path.exists():
                entries = _load(entries_path)
            else:
                entries = _tar_files(repo_dir / "worktree.tar", where, selected_files)
                _atomic(entries_path, entries)
            # Compare native working patches again after the complete byte capture.
            if git(tag + "-staged-after", where, ["diff", "--cached", "--binary", "--full-index", "--no-ext-diff"]) != staged:
                raise ValueError("Native staged changes changed during source capture.")
            if git(tag + "-unstaged-after", where, ["diff", "--binary", "--full-index", "--no-ext-diff"]) != unstaged:
                raise ValueError("Native worktree changed during source capture.")
            if git(tag + "-head-after", where, ["rev-parse", "--verify", "HEAD"]).decode().strip() != head:
                raise ValueError("Native Git HEAD changed during its complete source capture.")
            if git(tag + "-index-after", where, ["ls-files", "--stage", "-z"]) != listing:
                raise ValueError("Native Git index changed during its complete source capture.")
            repository["directory"] = repo_dir.relative_to(directory).as_posix()
            repository["worktree_entries"] = len(entries)
            for name, oid in gitlinks:
                relative = (PurePosixPath(repository["path"]) / name).as_posix()
                if not any(row["path"] == relative for row in repos):
                    repos.append({"path": relative, "parent": index, "gitlink": oid})
            save()
            index += 1

        db = directory / "database.sql"
        cli("database", [*selected("db:dump"), "--app", app, "--relationship", relation,
                         "--schema", schema, "--file", str(db)])
        if not db.is_file() or db.stat().st_size == 0:
            raise ValueError("The original native SQL dump is empty or unavailable.")
        state["parts"]["database"] = {"path": "database.sql", **_file(db),
                                      "relationship": relation, "schema": schema}

        mount_rows = []
        for index, name in enumerate(selected_mounts):
            s.check()
            destination = directory / "mount-staging" / str(index)
            destination.mkdir(mode=0o700, parents=True, exist_ok=True)
            # --delete affects only our private original download staging directory.
            cli("mount-" + str(index), [*selected("mount:download"), "--app", app,
                "--mount", name, "--target", str(destination), "--refresh", "--delete"])
            archive = directory / ("mount-" + str(index) + ".tar")
            entries_path = directory / ("mount-" + str(index) + ".json")
            if entries_path.exists():
                entries = _load(entries_path)
            else:
                entries = _tar_files(archive, destination, _tree_names(destination))
                _atomic(entries_path, entries)
            mount_rows.append({"mount": name, "definition": normalized_mounts[name],
                               "archive": archive.name, "entries": entries_path.name,
                               "nodes": len(entries), **_file(archive)})
        state["parts"]["mounts"] = mount_rows
        after = current("deployment-after")
        head_after = cli("head-after", [*selected("environment:info"), "head_commit", "--refresh"]).decode().strip()
        if before["id"] != after["id"] or head_after != head_before:
            raise ValueError("Native deployment/head changed across the retained source capture.")
        # Keep independent acquisition times and original deployment objects. SQL
        # and mount downloads do not constitute an atomic provider snapshot.
        state["state"] = "PACKAGING"
        save()
        members = []
        for path in sorted(directory.rglob("*")):
            if not path.is_file() or path.is_symlink():
                continue
            relative = path.relative_to(directory).as_posix()
            if relative in ("capture.json", "MANIFEST.json", "upsun-source.zip") or relative.startswith(
                    ("mount-staging/", "native-bin/")) or relative.endswith(".partial"):
                continue
            members.append({"path": relative, **_file(path)})
        total = sum(row["bytes"] for row in members)
        if total > p["max_artifact_bytes"]:
            raise ValueError("Complete native source exceeds max_artifact_bytes; increase the original intake limit.")
        manifest = {"schema": SCHEMA, "target": target, "source_revision": revision,
                    "cli_version": version, "cli_source_commit": CLI_COMMIT,
                    "started_at": state["started_at"], "completed_at": _now(),
                    "capture_consistency": "independently_acquired_native_parts",
                    "deployment_before": before, "deployment_after": after,
                    "environment_head_before": head_before, "environment_head_after": head_after,
                    "repositories": repos, "parts": state["parts"], "commands": state["commands"],
                    "ignored_source_policy": "Git-ignored paths are listed in original command output; host credentials and ignored build caches are not silently copied.",
                    "members": members, "member_bytes": total}
        _atomic(directory / "MANIFEST.json", manifest)
        archive_path = directory / "upsun-source.zip"
        temporary = directory / "upsun-source.zip.partial"
        with zipfile.ZipFile(temporary, "w", compression=zipfile.ZIP_STORED, allowZip64=True) as archive:
            archive.write(directory / "MANIFEST.json", "MANIFEST.json")
            for member in members:
                archive.write(directory / member["path"], member["path"])
        verify_source(temporary, p["max_artifact_bytes"])
        if temporary.stat().st_size > p["max_artifact_bytes"]:
            raise ValueError("The complete source ZIP including its manifest exceeds max_artifact_bytes.")
        os.chmod(temporary, 0o600)
        os.replace(temporary, archive_path)
        result = {"schema": SCHEMA, "state": "COMPLETE", "source_revision": revision,
                  "target": target, "deployment_id": before["id"],
                  "capture_consistency": manifest["capture_consistency"],
                  "repositories": repos, "parts": state["parts"],
                  "archive": str(archive_path), "manifest": str(directory / "MANIFEST.json"),
                  "archive_identity": _file(archive_path)}
        state["result"] = result
        state["published"] = {name: _file(directory / name) for name in ("upsun-source.zip", "MANIFEST.json")}
        state["state"] = "COMPLETE"
        save()
        s.add(archive_path, "upsun_complete_source", source_revision=revision)
        s.add(directory / "MANIFEST.json", "upsun_source_manifest", source_revision=revision)
        return result
    except BaseException as error:
        state["state"] = "ATTENTION"
        state["error"] = {"type": type(error).__name__, "message": str(error), "at": _now()}
        save()
        raise


def verify_source(archive_path, max_bytes=8 * 1024**3):
    """Verify every complete package member without extracting any filesystem node."""
    with zipfile.ZipFile(archive_path) as archive:
        infos = archive.infolist()
        names = [info.filename for info in infos]
        if len(names) != len(set(names)) or "MANIFEST.json" not in names:
            raise ValueError("The complete original source archive has duplicate or missing members.")
        if sum(info.file_size for info in infos) > max_bytes + 16 * CHUNK:
            raise ValueError("The complete native package exceeds the selected receiving limit.")
        manifest_info = archive.getinfo("MANIFEST.json")
        if manifest_info.file_size > 16 * CHUNK:
            raise ValueError("The original native source manifest exceeds its receiving limit.")
        manifest = json.loads(archive.read("MANIFEST.json").decode("utf-8"))
        if manifest.get("schema") != SCHEMA or not isinstance(manifest.get("members"), list):
            raise ValueError("Use the original complete Upsun source package.")
        expected = {}
        for member in manifest["members"]:
            name = _relative(member["path"])
            if name in expected or name == "MANIFEST.json":
                raise ValueError("The original manifest repeats a source member.")
            expected[name] = member
        if set(names) != set(expected) | {"MANIFEST.json"}:
            raise ValueError("The archive differs from its complete original source manifest.")
        for info in infos:
            _relative(info.filename)
            if info.is_dir() or stat.S_ISLNK(info.external_attr >> 16) or info.flag_bits & 1:
                raise ValueError("The outer source package requires ordinary unencrypted files.")
            if info.filename == "MANIFEST.json":
                continue
            digest = hashlib.sha256()
            size = 0
            with archive.open(info) as stream:
                for data in iter(lambda: stream.read(CHUNK), b""):
                    digest.update(data)
                    size += len(data)
            if {"bytes": size, "sha256": digest.hexdigest()} != {
                    key: expected[info.filename][key] for key in ("bytes", "sha256")}:
                raise ValueError("A complete original source member differs: " + info.filename)
        return manifest


def receive_source(archive_path, destination, max_bytes=8 * 1024**3):
    """Resume private exact-byte receipt; never overwrite another receiving identity."""
    archive_path = Path(archive_path).resolve(strict=True)
    destination = Path(destination).absolute()
    identity = _file(archive_path)
    manifest = verify_source(archive_path, max_bytes)
    if destination.is_symlink() or any(parent.is_symlink() for parent in destination.parents):
        raise ValueError("Use an ordinary original private receiving directory.")
    destination.mkdir(mode=0o700, parents=True, exist_ok=True)
    state_path = destination / "RECEIVING.json"
    if state_path.exists():
        state = _load(state_path)
        if state.get("archive") != identity:
            raise ValueError("Continue the same original complete source package.")
    else:
        if any(destination.iterdir()):
            raise ValueError("Start source receipt in an empty original private directory.")
        state = {"schema": "govhub.upsun.source-receiving.v1", "archive": identity,
                 "state": "RECEIVING", "started_at": _now()}
        _atomic(state_path, state)
    with zipfile.ZipFile(archive_path) as archive:
        for name in archive.namelist():
            path = destination / _relative(name)
            path.parent.mkdir(mode=0o700, parents=True, exist_ok=True)
            if any(parent.is_symlink() for parent in path.parents) or path.is_symlink():
                raise ValueError("The native receiving path contains a link.")
            member = next((x for x in manifest["members"] if x["path"] == name), None)
            expected = ({"bytes": len(archive.read(name)), "sha256": _digest(archive.read(name))}
                        if name == "MANIFEST.json" else {k: member[k] for k in ("bytes", "sha256")})
            if path.exists():
                if _file(path) != expected:
                    raise ValueError("A received original source member changed: " + name)
                continue
            temporary = path.with_name(path.name + ".receiving-partial")
            with archive.open(name) as source, temporary.open("wb") as output:
                os.chmod(temporary, 0o600)
                shutil.copyfileobj(source, output, CHUNK)
                output.flush()
                os.fsync(output.fileno())
            if _file(temporary) != expected:
                raise ValueError("Incomplete native receiving member.")
            os.replace(temporary, path)
    state.update(state="COMPLETE", completed_at=_now(), source_revision=manifest["source_revision"],
                 target=manifest["target"], destination=str(destination))
    _atomic(state_path, state)
    return state



def _restore_worktree(archive_path, destination, entries):
    """Restore only reviewed native members, preserving literal symlink targets."""
    destination = Path(destination)
    expected = {entry["path"]: entry for entry in entries}
    with tarfile.open(archive_path, "r:") as archive:
        names = archive.getnames()
        retained = {name for name, item in expected.items() if item["kind"] != "deleted"}
        if len(names) != len(set(names)) or set(names) != retained:
            raise ValueError("The original worktree archive differs from its node manifest.")
        # No member may traverse a retained symlink, regardless of archive order.
        links = {name for name, item in expected.items() if item["kind"] == "symlink"}
        for name in expected:
            _relative(name)
            if any(parent.as_posix() in links for parent in PurePosixPath(name).parents):
                raise ValueError("A native archive writes through a link; retain it for explicit review.")
        for name, entry in expected.items():
            target = destination / name
            for parent in target.parents:
                if parent == destination:
                    break
                if parent.is_symlink():
                    raise ValueError("The receiving tree has an unexpected linked parent.")
            if entry["kind"] == "deleted":
                if target.is_symlink() or target.is_file():
                    target.unlink()
                elif target.exists():
                    raise ValueError("A deleted native file was replaced by a local directory.")
                continue
            info = archive.getmember(name)
            target.parent.mkdir(mode=0o700, parents=True, exist_ok=True)
            if entry["kind"] == "directory":
                if not info.isdir() or target.is_symlink():
                    raise ValueError("Native directory type differs.")
                target.mkdir(mode=0o700, exist_ok=True)
                continue
            if entry["kind"] == "symlink":
                if not info.issym() or info.linkname != entry["link_target"]:
                    raise ValueError("Native link identity differs.")
                if target.is_symlink():
                    if os.readlink(target) == info.linkname:
                        continue
                    target.unlink()
                elif target.is_file():
                    target.unlink()
                elif target.exists():
                    raise ValueError("The native link destination contains a directory.")
                target.symlink_to(info.linkname)
                continue
            if not info.isfile() or info.size != entry["bytes"]:
                raise ValueError("Native file type or length differs.")
            if target.is_symlink():
                target.unlink()
            if target.exists() and not target.is_file():
                raise ValueError("The native file destination is not an ordinary file.")
            fd, temporary = tempfile.mkstemp(prefix=target.name + ".source-", dir=target.parent)
            try:
                with os.fdopen(fd, "wb") as output, archive.extractfile(info) as source:
                    os.fchmod(output.fileno(), 0o600)
                    shutil.copyfileobj(source, output, CHUNK)
                    output.flush()
                    os.fsync(output.fileno())
                if _file(temporary) != {key: entry[key] for key in ("bytes", "sha256")}:
                    raise ValueError("The original worktree bytes differ.")
                os.chmod(temporary, entry["mode"] & 0o777)
                os.replace(temporary, target)
                os.utime(target, (info.mtime, info.mtime))
            finally:
                if os.path.exists(temporary):
                    os.unlink(temporary)
        for name, entry in sorted(expected.items(), key=lambda row: row[0].count("/"), reverse=True):
            if entry["kind"] == "directory":
                os.chmod(destination / name, entry["mode"] & 0o777)


def reopen_source(session, received_directory, checkout_directory):
    """Reopen original Git/index/local work in an independently received project.

    The caller supplies its existing Session and original operation lock. Local
    Git writes use that same retained native command admission. Missing mutation
    outcomes stay on Session's original uncertain-command recovery path.
    SQL/mount bytes remain private original inputs; this never overwrites a live
    database or writes files into a deployed Upsun environment.
    """
    s = session
    received = Path(s.private_path(str(received_directory))).resolve(strict=True)
    manifest = _load(received / "MANIFEST.json")
    if manifest.get("schema") != SCHEMA:
        raise ValueError("Select the complete original received source.")
    for member in manifest["members"]:
        path = received / _relative(member["path"])
        if _file(path) != {key: member[key] for key in ("bytes", "sha256")}:
            raise ValueError("A retained original source member changed.")
    destination = Path(s.private_path(str(checkout_directory))).absolute()
    if destination.is_symlink() or any(parent.is_symlink() for parent in destination.parents):
        raise ValueError("Select an ordinary new private source checkout.")
    control = s.out / "upsun-source-reopen.json"
    binding = {"manifest_sha256": _file(received / "MANIFEST.json")["sha256"],
               "destination": str(destination)}
    if control.exists():
        state = s.read_private_json(control)
        if state.get("binding") != binding:
            raise ValueError("Continue the original source reopening destination.")
    else:
        if destination.exists() and any(destination.iterdir()):
            raise ValueError("Initial source reopening requires an empty private destination.")
        state = {"schema": "govhub.upsun.source-reopen.v1", "binding": binding,
                 "state": "RUNNING", "repositories": [], "started_at": _now()}
        _atomic(control, state)
    if state["state"] == "COMPLETE":
        # The receiving engineer's later edits remain theirs. Do not overwrite.
        return {**state, "reused": True}
    destination.mkdir(mode=0o700, parents=True, exist_ok=True)
    git = _executable(s.p.get("git_path") or "git")
    for index, repository in enumerate(manifest["repositories"]):
        relative = repository["path"]
        if relative:
            _relative(relative)
        where = destination / relative
        where.mkdir(mode=0o700, parents=True, exist_ok=True)
        data = received / _relative(repository["directory"])
        label = "upsun-reopen-" + str(index)

        def command(name, args, mutating=False):
            result = s.command(label + "-" + name, [git, "-C", str(where), *args], mutating=mutating)
            return Path(s.private_path(result["stdout"]["path"])).read_bytes()

        command("init", ["init"], True)
        command("bundle-verify", ["bundle", "verify", str(data / "repository.bundle")])
        command("head-fetch", ["fetch", str(data / "repository.bundle"), "HEAD"], True)
        command("checkout", ["checkout", "--detach", "--force", repository["head"]], True)
        # Fetch original heads only after leaving init's current branch.
        command("refs-after-detach", ["fetch", "--force", str(data / "repository.bundle"), "+refs/*:refs/*"], True)
        if (data / "staged.patch").stat().st_size:
            command("index", ["apply", "--cached", "--binary", str(data / "staged.patch")], True)
        entries = _load(data / "worktree.json")
        _restore_worktree(data / "worktree.tar", where, entries)
        row = {"path": relative, "head": repository["head"], "state": "RECONSTRUCTED"}
        if row not in state["repositories"]:
            state["repositories"].append(row)
        _atomic(control, state)
    # Parent diffs include native submodule working status. Reopen every original
    # child before comparing any parent's final index, patches and untracked set.
    for index, repository in enumerate(manifest["repositories"]):
        where = destination / repository["path"]
        data = received / repository["directory"]
        checks = [
            ("index", ["ls-files", "--stage", "-z"], received / manifest["commands"]["git-" + str(index) + "-index"]["stdout"]),
            ("status", ["status", "--porcelain=v1", "-z", "--untracked-files=all"], received / manifest["commands"]["git-" + str(index) + "-status"]["stdout"]),
            ("staged", ["diff", "--cached", "--binary", "--full-index", "--no-ext-diff"], data / "staged.patch"),
            ("unstaged", ["diff", "--binary", "--full-index", "--no-ext-diff"], data / "unstaged.patch"),
        ]
        for name, arguments, original in checks:
            record = s.command("upsun-reopen-final-" + str(index) + "-" + name,
                               [git, "-C", str(where), *arguments])
            observed = Path(s.private_path(record["stdout"]["path"])).read_bytes()
            if observed != original.read_bytes():
                raise ValueError("Independent native Git " + name + " differs from the original.")
    state.update(state="COMPLETE", completed_at=_now(), source_revision=manifest["source_revision"],
                 original_target=manifest["target"], database=manifest["parts"]["database"],
                 mounts=manifest["parts"]["mounts"], received_directory=str(received))
    _atomic(control, state)
    s.add(control, "upsun_source_reopen")
    return state


def _main():
    if len(sys.argv) == 3 and sys.argv[1] == "_cli":
        _cli_exec()
        return
    parser = argparse.ArgumentParser(description=__doc__)
    sub = parser.add_subparsers(dest="action", required=True)
    verify = sub.add_parser("verify")
    verify.add_argument("--archive", required=True)
    verify.add_argument("--max-bytes", type=int, default=8 * 1024**3)
    receive = sub.add_parser("receive")
    receive.add_argument("--archive", required=True)
    receive.add_argument("--destination", required=True)
    receive.add_argument("--max-bytes", type=int, default=8 * 1024**3)
    args = parser.parse_args()
    if args.action == "verify":
        value = verify_source(args.archive, args.max_bytes)
    else:
        value = receive_source(args.archive, args.destination, args.max_bytes)
    print(json.dumps(value, ensure_ascii=False, indent=2))


if __name__ == "__main__":
    _main()

