  const boxes=list=>`<div class="download-grid">${list.map(f=>`<div class="download-box"><strong><a href="/api/${enc(domain)}/${enc(id)}/${enc(f.name)}">${esc(f.name)}</a></strong><small>${esc(size(f.size))}</small></div>`).join('')}</div>`;
